const String kNgmyDefaultLogoUrl = 'https://i.ibb.co/LhbMvz9/ngmy-logo.png';
const String kNgmyUserLoggedOutKey = 'ngmy_user_logged_out';

Future<bool> ngmyReadUserLoggedOutFlag([SharedPreferences? prefs]) async {
  final p = prefs ?? await SharedPreferences.getInstance();
  return p.getBool(kNgmyUserLoggedOutKey) == true;
}

Future<void> ngmyWriteUserLoggedOutFlag(bool loggedOut, [SharedPreferences? prefs]) async {
  final p = prefs ?? await SharedPreferences.getInstance();
  if (loggedOut) {
    await p.setBool(kNgmyUserLoggedOutKey, true);
  } else {
    await p.remove(kNgmyUserLoggedOutKey);
  }
}

/// Stale `forceLogout` in prefs/cloud was kicking people to login on reopen.
/// Always clear it when establishing a session so only a live admin kick applies.
void ngmyClearStaleForceLogout(UserData? user) {
  if (user == null) return;
  user.forceLogout = false;
}

const _kNgmyDefaultThemeMode = ThemeMode.dark;

ThemeMode _ngmyInitialThemeMode = _kNgmyDefaultThemeMode;

ThemeMode _ngmyResolveThemeMode(ThemeMode mode) {
  if (mode != ThemeMode.system) return mode;
  final now = DateTime.now();
  final mins = now.hour * 60 + now.minute;
  const startLight = 9 * 60;
  const startDark = 20 * 60;
  return (mins >= startLight && mins < startDark) ? ThemeMode.light : ThemeMode.dark;
}

void _ngmyApplySystemChromeForThemeMode(ThemeMode mode) {
  final dark = _ngmyResolveThemeMode(mode) == ThemeMode.dark;
  if (kIsWeb) {
    ngmyApplyWebStatusBarStyle(lightMode: !dark);
  }
  SystemChrome.setSystemUIOverlayStyle(
    dark
        ? const SystemUiOverlayStyle(
            statusBarColor: Color(0xFF121212),
            statusBarIconBrightness: Brightness.light,
            statusBarBrightness: Brightness.dark,
            systemNavigationBarColor: Color(0xFF121212),
            systemNavigationBarIconBrightness: Brightness.light,
          )
        : const SystemUiOverlayStyle(
            statusBarColor: Colors.white,
            statusBarIconBrightness: Brightness.dark,
            statusBarBrightness: Brightness.light,
            systemNavigationBarColor: Colors.white,
            systemNavigationBarIconBrightness: Brightness.dark,
          ),
  );
}

/// Session restored from disk before the first Flutter frame (prevents home swap flash).
class NgmyLaunchBootstrap {
  const NgmyLaunchBootstrap({
    required this.themeMode,
    this.currentUser,
    this.users = const [],
    this.transactions = const [],
    this.media = const [],
    this.announcements = const [],
    this.config,
    this.plans = const [],
  });

  final ThemeMode themeMode;
  final UserData? currentUser;
  final List<UserData> users;
  final List<AppTransaction> transactions;
  final List<MediaPost> media;
  final List<Announcement> announcements;
  final AppConfig? config;
  final List<InvestmentPlan> plans;

  static const empty = NgmyLaunchBootstrap(themeMode: _kNgmyDefaultThemeMode);
}

String? _ngmyPrefsJson(SharedPreferences prefs, String key) {
  try {
    final val = prefs.getString(key);
    if (val == null || val.trim().isEmpty || val == 'null') return null;
    final trimmed = val.trim();
    if (trimmed.contains('\u0000')) {
      prefs.remove(key);
      return null;
    }
    if (!trimmed.startsWith('{') && !trimmed.startsWith('[')) return null;
    return trimmed;
  } catch (_) {
    return null;
  }
}

Future<NgmyLaunchBootstrap> ngmyLoadLaunchBootstrap() async {
  try {
    final prefs = await SharedPreferences.getInstance();
    var themeMode = _kNgmyDefaultThemeMode;
    final savedTheme = (prefs.getString('theme_mode') ?? '').trim();
    if (savedTheme == 'light') themeMode = ThemeMode.light;
    if (savedTheme == 'dark') themeMode = ThemeMode.dark;
    if (savedTheme == 'system') themeMode = ThemeMode.system;

    final plans = _bundledInvestmentPlans();

    AppConfig? config;
    final configJson = _ngmyPrefsJson(prefs, 'app_config');
    if (configJson != null) {
      try {
        final map = jsonDecode(configJson);
        if (map is Map<String, dynamic>) {
          config = AppConfig.fromJson(map);
          await _hydrateCivicCitiesAndRoomsFromLocalBackup(config);
        }
      } catch (_) {}
    }

    var media = <MediaPost>[];
    final mediaJson = _ngmyPrefsJson(prefs, 'all_media');
    if (mediaJson != null) {
      try {
        media = (jsonDecode(mediaJson) as List).map((e) => MediaPost.fromJson(e)).toList();
      } catch (_) {}
    }

    var users = <UserData>[];
    final usersJson = _ngmyPrefsJson(prefs, 'all_users');
    if (usersJson != null) {
      try {
        users = (jsonDecode(usersJson) as List).map((e) => UserData.fromJson(e)).toList();
      } catch (_) {}
    }

    var transactions = <AppTransaction>[];
    final txnJson = _ngmyPrefsJson(prefs, 'all_transactions');
    if (txnJson != null) {
      try {
        transactions = (jsonDecode(txnJson) as List).map((e) => AppTransaction.fromJson(e)).toList();
      } catch (_) {}
    }

    var announcements = <Announcement>[];
    final annJson = _ngmyPrefsJson(prefs, 'all_announcements');
    if (annJson != null) {
      try {
        announcements = (jsonDecode(annJson) as List).map((e) => Announcement.fromJson(e)).toList();
      } catch (_) {}
    }

    UserData? currentUser;
    final loggedOut = prefs.getBool(kNgmyUserLoggedOutKey) == true;
    final userJson = _ngmyPrefsJson(prefs, 'current_user');
    final lastEmail = (prefs.getString('ngmy_last_session_email') ?? '').toLowerCase().trim();
    // If the sticky logged-out flag is set but a session snapshot still exists,
    // prefer restoring the session — the flag was often left behind by a stale
    // forceLogout kick, not an intentional Profile → Log out.
    final hasSessionSnapshot = userJson != null || lastEmail.isNotEmpty;
    if (!loggedOut || hasSessionSnapshot) {
      if (loggedOut && hasSessionSnapshot) {
        await ngmyWriteUserLoggedOutFlag(false, prefs);
      }
      if (userJson != null) {
        try {
          final map = jsonDecode(userJson);
          if (map is Map<String, dynamic>) {
            final localUser = UserData.fromJson(map);
            final index = users.indexWhere((u) => u.email.toLowerCase().trim() == localUser.email.toLowerCase().trim());
            currentUser = index != -1 ? users[index] : localUser;
          }
        } catch (_) {}
      }
      if (currentUser == null && lastEmail.isNotEmpty) {
        final index = users.indexWhere((u) => u.email.toLowerCase().trim() == lastEmail);
        if (index != -1) {
          currentUser = users[index];
        } else {
          // Keep a minimal session even if all_users failed to decode.
          currentUser = UserData(email: lastEmail, username: lastEmail.split('@').first);
        }
      }
    }
    ngmyClearStaleForceLogout(currentUser);

    for (final u in users) {
      ngmyReconcileUserAccountBalance(u, transactions);
    }
    if (currentUser != null) {
      final key = currentUser!.email.toLowerCase().trim();
      final idx = users.indexWhere((u) => u.email.toLowerCase().trim() == key);
      if (idx >= 0) currentUser = users[idx];
    }

    if (config != null) {
      unawaited(ngmyHydrateCommunicateSettingsFromAllBackups(config));
      unawaited(ngmyHydrateHelpCenterHubFromAllBackups(config));
    } else {
      unawaited(NgmyCommunicateAvatarCache.hydrateRamFromDisk());
    }

    return NgmyLaunchBootstrap(
      themeMode: themeMode,
      currentUser: currentUser,
      users: users,
      transactions: transactions,
      media: media,
      announcements: announcements,
      config: config,
      plans: plans,
    );
  } catch (e) {
    debugPrint('[ngmy] launch bootstrap: $e');
    // Never wipe a good session on a partial prefs decode failure — try a
    // minimal salvage so reopen still lands inside the app.
    try {
      final prefs = await SharedPreferences.getInstance();
      final lastEmail = (prefs.getString('ngmy_last_session_email') ?? '').toLowerCase().trim();
      final userJson = _ngmyPrefsJson(prefs, 'current_user');
      UserData? salvage;
      if (userJson != null) {
        final map = jsonDecode(userJson);
        if (map is Map<String, dynamic>) salvage = UserData.fromJson(map);
      }
      salvage ??= lastEmail.isEmpty
          ? null
          : UserData(email: lastEmail, username: lastEmail.split('@').first);
      if (salvage != null) {
        ngmyClearStaleForceLogout(salvage);
        return NgmyLaunchBootstrap(themeMode: _kNgmyDefaultThemeMode, currentUser: salvage);
      }
    } catch (_) {}
    return NgmyLaunchBootstrap.empty;
  }
}

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  ngmyInitCrispRendering();
  FlutterError.onError = (details) {
    FlutterError.presentError(details);
    debugPrint('[flutter] ${details.exceptionAsString()}\n${details.stack}');
  };
  PlatformDispatcher.instance.onError = (error, stack) {
    debugPrint('[platform] $error\n$stack');
    return true;
  };

  final oauthReturn = kIsWeb && ngmyUriHasOAuthCallback();

  // Public /bio, /menu, civic enroll, etc. links should not wait on full local bootstrap.
  if (kIsWeb) ngmyCaptureCivicEnrollLaunchIntent();
  final isGuestCivicEnroll = kIsWeb && ngmyIsGuestCivicEnrollLaunch();
  final guestAppSlug = kIsWeb && !isGuestCivicEnroll ? ngmyPublishedAppSlugFromLaunch() : null;
  final isGuestPublishedApp = guestAppSlug != null && guestAppSlug.trim().isNotEmpty;
  final guestInvoiceSlug = kIsWeb && !isGuestCivicEnroll && !isGuestPublishedApp ? ngmyPublishedInvoiceSlugFromLaunch() : null;
  final isGuestPublishedInvoice = guestInvoiceSlug != null && guestInvoiceSlug.trim().isNotEmpty;
  final guestMenuSlug =
      kIsWeb && !isGuestCivicEnroll && !isGuestPublishedApp && !isGuestPublishedInvoice ? ngmyPublishedMenuSlugFromLaunch() : null;
  final isGuestPublishedMenu = guestMenuSlug != null && guestMenuSlug.trim().isNotEmpty;
  final guestBioSlug = kIsWeb &&
          !isGuestCivicEnroll &&
          !isGuestPublishedApp &&
          !isGuestPublishedInvoice &&
          !isGuestPublishedMenu
      ? ngmyPublishedBioSlugFromLaunch()
      : null;
  final isGuestPublishedBio = guestBioSlug != null && guestBioSlug.trim().isNotEmpty;
  final guestLocalMenuSlug = kIsWeb &&
          !isGuestCivicEnroll &&
          !isGuestPublishedApp &&
          !isGuestPublishedInvoice &&
          !isGuestPublishedMenu &&
          !isGuestPublishedBio
      ? ngmyPublishedLocalMenuSlugFromLaunch()
      : null;
  final isGuestLocalPublishedMenu = guestLocalMenuSlug != null && guestLocalMenuSlug.trim().isNotEmpty;
  final guestLocalBioSlug = kIsWeb &&
          !isGuestCivicEnroll &&
          !isGuestPublishedApp &&
          !isGuestPublishedInvoice &&
          !isGuestPublishedMenu &&
          !isGuestPublishedBio &&
          !isGuestLocalPublishedMenu
      ? ngmyPublishedLocalBioSlugFromLaunch()
      : null;
  final isGuestLocalPublishedBio = guestLocalBioSlug != null && guestLocalBioSlug.trim().isNotEmpty;
  final isGuestLink = isGuestCivicEnroll ||
      isGuestPublishedApp ||
      isGuestPublishedInvoice ||
      isGuestPublishedMenu ||
      isGuestPublishedBio ||
      isGuestLocalPublishedMenu ||
      isGuestLocalPublishedBio;

  var launchBootstrap = NgmyLaunchBootstrap.empty;
  const deferBootstrapLoad = false;
  if (!isGuestLink) {
    if (oauthReturn) {
      await ngmyIgnoreTimeout(ngmyEnsureSupabaseAuthInitialized, timeout: const Duration(seconds: 15));
      await ngmyRecoverOAuthSessionIfNeeded();
    }
    launchBootstrap = await ngmyLoadLaunchBootstrap();

    final launchLoggedOut = await ngmyReadUserLoggedOutFlag();
    if (launchLoggedOut) {
      try {
        await ngmyEnsureSupabaseAuthInitialized();
        await Supabase.instance.client.auth.signOut();
      } catch (_) {}
    }
    if (oauthReturn && !launchLoggedOut) {
      try {
        final authUser = Supabase.instance.client.auth.currentUser;
        final email = authUser?.email?.toLowerCase().trim() ?? '';
        if (email.isNotEmpty) {
          final fullName = (authUser?.userMetadata?['full_name'] ?? authUser?.userMetadata?['name'] ?? '').toString().trim();
          final admins = ['kbpabloqr@gmail.com', 'ngumoyaking@gmail.com', 'appbusiness321@gmail.com', 'appbusiness84@gmail.com'];
          final users = List<UserData>.from(launchBootstrap.users);
          final idx = users.indexWhere((u) => u.email.toLowerCase().trim() == email);
          if (idx == -1) {
            users.add(UserData(
              email: email,
              username: fullName.isNotEmpty ? fullName : email.split('@').first,
              isAdmin: admins.contains(email),
              passwordHash: '',
            ));
          } else if (fullName.isNotEmpty) {
            users[idx].username = fullName;
          }
          final currentIdx = users.indexWhere((u) => u.email.toLowerCase().trim() == email);
          launchBootstrap = NgmyLaunchBootstrap(
            themeMode: launchBootstrap.themeMode,
            currentUser: users[currentIdx],
            users: users,
            transactions: launchBootstrap.transactions,
            media: launchBootstrap.media,
            announcements: launchBootstrap.announcements,
            config: launchBootstrap.config,
            plans: launchBootstrap.plans,
          );
        }
      } catch (e) {
        debugPrint('[ngmy_oauth] bootstrap session merge: $e');
      }
      if (launchBootstrap.currentUser != null) {
        try {
          final prefs = await SharedPreferences.getInstance();
          final u = launchBootstrap.currentUser!;
          await prefs.setString('current_user', jsonEncode(u.toJson()));
          await prefs.setString('ngmy_last_session_email', u.email.toLowerCase().trim());
          await prefs.setString('all_users', jsonEncode(launchBootstrap.users.map((e) => e.toJson()).toList()));
        } catch (e) {
          debugPrint('[ngmy_oauth] session persist: $e');
        }
      }
      ngmyMarkSupabaseReady();
    }

    _ngmyInitialThemeMode = launchBootstrap.themeMode;
    _ngmyApplySystemChromeForThemeMode(_ngmyInitialThemeMode);

    ngmyCaptureMediaPostLaunchIntent();
    ngmyCaptureReferralLaunchIntent();
  }

  Future<void> initSupabase() async {
    try {
      await ngmyEnsureSupabaseAuthInitialized();
      await ngmyRecoverOAuthSessionIfNeeded();
    } catch (e) {
      debugPrint('Supabase init failed (app still starts): $e');
    } finally {
      ngmyMarkSupabaseReady();
    }
  }

  if (isGuestPublishedBio || isGuestLocalPublishedMenu || isGuestLocalPublishedBio) {
    // Device-local and bio guests load without blocking on Supabase.
    unawaited(ngmyIgnoreTimeout(initSupabase, timeout: const Duration(seconds: 8)));
  } else if (isGuestLink) {
    await ngmyIgnoreTimeout(initSupabase, timeout: const Duration(seconds: 12));
  }

  runZonedGuarded(() {
    if (isGuestCivicEnroll) {
      runApp(const NgmyGuestCivicEnrollApp());
      return;
    }
    if (isGuestPublishedApp) {
      runApp(NgmyGuestPublishedApp(slug: guestAppSlug.trim().toLowerCase()));
      return;
    }
    if (isGuestPublishedInvoice) {
      runApp(NgmyGuestPublishedInvoice(slug: guestInvoiceSlug.trim().toLowerCase()));
      return;
    }
    if (isGuestPublishedMenu) {
      runApp(NgmyGuestPublishedMenu(slug: guestMenuSlug.trim().toLowerCase()));
      return;
    }
    if (isGuestPublishedBio) {
      runApp(NgmyGuestPublishedBio(slug: guestBioSlug.trim().toLowerCase()));
      return;
    }
    if (isGuestLocalPublishedMenu) {
      runApp(NgmyGuestLocalPublishedMenu(slug: guestLocalMenuSlug.trim().toLowerCase()));
      return;
    }
    if (isGuestLocalPublishedBio) {
      runApp(NgmyGuestLocalPublishedBio(slug: guestLocalBioSlug.trim().toLowerCase()));
      return;
    }
    final app = NGMYApp(launchBootstrap: launchBootstrap, deferBootstrapLoad: deferBootstrapLoad);
    runApp(NgmyWebViewportGuard(child: app));
  }, (e, st) {
    debugPrint('[zone] $e\n$st');
  });

  if (!isGuestLink) {
    // Never block first frame on cloud — cold start offline must show cached home immediately.
    unawaited(ngmyIgnoreTimeout(initSupabase, timeout: const Duration(seconds: 12)));
  }
}

// --- DATA MODELS ---

String _hashPassword(String password) {
  final bytes = utf8.encode(password);
  return sha256.convert(bytes).toString();
}

/// Long-press to copy — avoids SelectionArea/Overlay issues on desktop.
class CopyOnHoldText extends StatelessWidget {
  final String data;
  final TextStyle? style;
  final TextAlign? textAlign;
  final int? maxLines;
  final TextOverflow? overflow;

  const CopyOnHoldText(
    this.data, {
    super.key,
    this.style,
    this.textAlign,
    this.maxLines,
    this.overflow,
  });

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onLongPress: () {
        Clipboard.setData(ClipboardData(text: data));
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Copied to clipboard'),
            duration: Duration(seconds: 2),
            behavior: SnackBarBehavior.floating,
          ),
        );
      },
      child: Text(
        data,
        style: style,
        textAlign: textAlign,
        maxLines: maxLines,
        overflow: overflow,
      ),
    );
  }
}

class DateSlashFormatter extends TextInputFormatter {
  @override
  TextEditingValue formatEditUpdate(TextEditingValue oldValue, TextEditingValue newValue) {
    final digits = newValue.text.replaceAll(RegExp(r'[^0-9]'), '');
    final buf = StringBuffer();
    for (int i = 0; i < digits.length && i < 8; i++) {
      if (i == 2 || i == 4) buf.write('/');
      buf.write(digits[i]);
    }
    final text = buf.toString();
    return TextEditingValue(
      text: text,
      selection: TextSelection.collapsed(offset: text.length),
    );
  }
}

/// Formats phone as 123-456-7890 (dashes after 3 and 6 digits).
class PhoneDashFormatter extends TextInputFormatter {
  @override
  TextEditingValue formatEditUpdate(TextEditingValue oldValue, TextEditingValue newValue) {
    final digits = newValue.text.replaceAll(RegExp(r'\D'), '');
    if (digits.length > 15) {
      return oldValue;
    }
    final buf = StringBuffer();
    for (var i = 0; i < digits.length; i++) {
      if (i == 3 || i == 6) buf.write('-');
      buf.write(digits[i]);
    }
    final text = buf.toString();
    return TextEditingValue(
      text: text,
      selection: TextSelection.collapsed(offset: text.length),
    );
  }
}

String ngmyFormatPhoneDisplay(String raw) {
  final digits = raw.replaceAll(RegExp(r'\D'), '');
  if (digits.isEmpty) return '';
  final buf = StringBuffer();
  for (var i = 0; i < digits.length; i++) {
    if (i == 3 || i == 6) buf.write('-');
    buf.write(digits[i]);
  }
  return buf.toString();
}

String formatCurrency(double amount) {
  String str = amount.toStringAsFixed(2);
  List<String> parts = str.split('.');
  RegExp reg = RegExp(r'(\d{1,3})(?=(\d{3})+(?!\d))');
  parts[0] = parts[0].replaceAllMapped(reg, (Match m) => '${m[1]},');
  return parts.join('.');
}

String ngmyNormalizeEmail(String email) => email.toLowerCase().trim();

/// Strip leading `$` so the field can use a visual prefix without fighting the controller.
String ngmyCashAppTagInputText(String raw) {
  var t = raw.trim();
  while (t.startsWith('\$')) {
    t = t.substring(1).trim();
  }
  return t;
}

/// Ensure one leading `$` when saving or submitting a Cash App tag.
String ngmyNormalizeCashAppTagForSubmit(String raw) {
  final bare = ngmyCashAppTagInputText(raw);
  if (bare.isEmpty) return '';
  return '\$$bare';
}

/// Emails that signed up or signed in on the login page (users table / session).
final Set<String> ngmyAppLoginUserEmails = <String>{};
const _kNgmyAppLoginEmailsKey = 'ngmy_app_login_emails_v1';

Future<void> ngmyLoadAppLoginUserRegistry() async {
  try {
    final prefs = await SharedPreferences.getInstance();
    final raw = prefs.getString(_kNgmyAppLoginEmailsKey);
    if (raw == null || raw.trim().isEmpty) return;
    final decoded = jsonDecode(raw);
    if (decoded is! List) return;
    for (final e in decoded) {
      final key = ngmyNormalizeEmail(e.toString());
      if (key.isNotEmpty) ngmyAppLoginUserEmails.add(key);
    }
  } catch (e) {
    debugPrint('[login registry] load: $e');
  }
}

Future<void> ngmyPersistAppLoginUserRegistry() async {
  try {
    final prefs = await SharedPreferences.getInstance();
    final sorted = ngmyAppLoginUserEmails.toList()..sort();
    await prefs.setString(_kNgmyAppLoginEmailsKey, jsonEncode(sorted));
  } catch (e) {
    debugPrint('[login registry] persist: $e');
  }
}

void ngmyRegisterAppLoginUser(String email) {
  final key = ngmyNormalizeEmail(email);
  if (key.isEmpty) return;
  if (ngmyAppLoginUserEmails.add(key)) {
    unawaited(ngmyPersistAppLoginUserRegistry());
  }
}

void ngmyRegisterAppLoginUsers(Iterable<UserData> users) {
  for (final u in users) {
    ngmyRegisterAppLoginUser(u.email);
  }
}

void ngmyMarkUserAsAppLoginAccount(UserData u) {
  u.isAppLoginAccount = true;
  ngmyRegisterAppLoginUser(u.email);
}

void ngmyHydrateAppLoginUserRegistry(Iterable<UserData> users) {
  for (final u in users) {
    if (u.isAppLoginAccount || ngmyLooksLikeAppLoginUser(u)) {
      u.isAppLoginAccount = true;
      ngmyRegisterAppLoginUser(u.email);
    }
  }
}

bool ngmyIsRegisteredAppLoginUser(UserData u) {
  if (u.email.trim().isEmpty) return false;
  return ngmyAppLoginUserEmails.contains(ngmyNormalizeEmail(u.email));
}

const int kNgmyUserTxnFetchMax = 5000;

bool _ngmyTxnIncreasesBalance(AppTransaction t) {
  return t.type == TransactionType.deposit ||
      t.type == TransactionType.adminAdd ||
      t.type == TransactionType.reimbursement ||
      t.type == TransactionType.claim;
}

double ngmyBalanceFromApprovedTransactions(String email, List<AppTransaction> transactions) {
  final key = ngmyNormalizeEmail(email);
  var balance = 0.0;
  for (final t in transactions) {
    if (ngmyNormalizeEmail(t.userEmail) != key) continue;
    if (t.status == TransactionStatus.pending && t.type == TransactionType.withdrawal) {
      balance -= t.amount;
      continue;
    }
    if (t.status != TransactionStatus.approved) continue;
    if (_ngmyTxnIncreasesBalance(t)) {
      balance += t.amount;
    } else {
      balance -= t.amount;
    }
  }
  return balance.clamp(0.0, double.infinity);
}

double ngmyPendingWithdrawalTotal(String email, List<AppTransaction> transactions) {
  final key = email.toLowerCase().trim();
  var total = 0.0;
  for (final t in transactions) {
    if (t.userEmail.toLowerCase().trim() != key) continue;
    if (t.status != TransactionStatus.pending || t.type != TransactionType.withdrawal) continue;
    total += t.amount;
  }
  return total;
}

/// Authoritative balance from the transaction ledger once this device has
/// any history for the person — a bet/win/purchase lands as a local
/// AppTransaction row immediately, and it must win over a stale cloud
/// echo of the pre-bet balance so a spend visibly drops (and a payout
/// visibly lands) right away instead of getting silently reverted by the
/// next sync. Only falls back to the stored/cloud balance when this
/// device has no transaction history at all for the person (e.g. a
/// just-arrived realtime row for someone not loaded locally yet).
double ngmyResolveAccountBalance(
  String email,
  double storedBalance,
  List<AppTransaction> transactions,
) {
  final key = ngmyNormalizeEmail(email);
  if (key.isEmpty) return 0.0;
  final stored = storedBalance.clamp(0.0, double.infinity);
  final txnCount = transactions.where((t) => ngmyNormalizeEmail(t.userEmail) == key).length;
  if (txnCount == 0) return stored;
  return ngmyBalanceFromApprovedTransactions(email, transactions);
}

void ngmyReconcileUserAccountBalance(UserData user, List<AppTransaction> transactions) {
  user.accountBalance = ngmyResolveAccountBalance(
    user.email,
    user.accountBalance,
    transactions,
  );
}

/// Admin dashboard balance — cloud [accountBalance] is synced after every wallet change; the admin
/// txn cache is only a recent global slice so ledger alone is often incomplete.
double ngmyAdminDisplayBalance(UserData u, List<AppTransaction> transactions) {
  final key = ngmyNormalizeEmail(u.email);
  if (key.isEmpty) return 0;
  final stored = u.accountBalance;
  final userTxns = transactions.where((t) => ngmyNormalizeEmail(t.userEmail) == key).toList();
  if (userTxns.isEmpty) return stored.clamp(0.0, double.infinity);
  final ledger = ngmyBalanceFromApprovedTransactions(u.email, userTxns);
  if (stored > ledger + 0.01) return stored.clamp(0.0, double.infinity);
  return ledger;
}

bool ngmyIsGameLedgerTransaction(AppTransaction t) {
  final d = (t.sourceDetails ?? '').toLowerCase();
  if (d.contains('game bet:') || d.contains('game payout:') || d.contains('game partial:')) return true;
  if (d.contains('multiplayer payout:')) return true;
  if (d.contains('dice') && t.method == PaymentMethod.system) return true;
  return false;
}

Future<void> ngmyBackfillGameWinNotificationsFromLedger(
  String email,
  List<AppTransaction> transactions,
) async {
  final key = ngmyNormalizeEmail(email);
  if (key.isEmpty) return;
  final cutoff = DateTime.now().subtract(kNgmyGameNotificationRetention);
  for (final t in transactions) {
    if (ngmyNormalizeEmail(t.userEmail) != key) continue;
    if (t.timestamp.isBefore(cutoff)) continue;
    if (t.status != TransactionStatus.approved) continue;
    if (t.type != TransactionType.reimbursement) continue;
    final d = t.sourceDetails ?? '';
    final lower = d.toLowerCase();
    final isGameWin = lower.contains('game payout:') ||
        lower.contains('game partial:') ||
        lower.contains('multiplayer payout:') ||
        (lower.contains('dice') && t.method == PaymentMethod.system);
    if (!isGameWin) continue;
    String title = 'Game';
    if (lower.contains('game payout:')) {
      title = d.substring(lower.indexOf('game payout:') + 'game payout:'.length).trim();
    } else if (lower.contains('game partial:')) {
      title = d.substring(lower.indexOf('game partial:') + 'game partial:'.length).trim();
      final paren = title.indexOf('(');
      if (paren > 0) title = title.substring(0, paren).trim();
    } else if (lower.contains('multiplayer payout:')) {
      title = d.substring(lower.indexOf('multiplayer payout:') + 'multiplayer payout:'.length).trim();
      final paren = title.indexOf('(');
      if (paren > 0) title = title.substring(0, paren).trim();
    } else if (lower.contains('dice')) {
      title = 'Dice Roll';
    }
    await NgmyGameNotifications.record(
      email: email,
      gameTitle: title.isEmpty ? 'Game' : title,
      won: true,
      amount: t.amount,
      detail: d,
      txnId: t.id,
      at: t.timestamp,
    );
  }
}

bool ngmyIsStoreLedgerTransaction(AppTransaction t) {
  final d = (t.sourceDetails ?? '').toLowerCase();
  return d.contains('ngmy store sale') || d.contains('ngmy store purchase');
}

/// Game Center bets / wagers — no browser push (in-game alerts only).
bool ngmyIsGameSpendTransaction(AppTransaction t) {
  if (!ngmyIsGameLedgerTransaction(t)) return false;
  if (t.status != TransactionStatus.approved) return false;
  return t.type == TransactionType.adminRemove;
}

enum NgmyPushSoundKind { incomeCash, spendDefault }

void ngmyDeliverTransactionAlerts(AppTransaction t, {bool forceIncomeSound = true}) {
  if (t.status != TransactionStatus.approved) return;
  if (ngmyTransactionCountsAsIncome(t)) {
    ngmyPlayIncomeSoundForTransaction(t, force: forceIncomeSound);
  }
}

void ngmyApplyPendingWithdrawalHold(UserData user, AppTransaction t, Set<String> appliedHoldIds) {
  if (t.type != TransactionType.withdrawal || t.status != TransactionStatus.pending) return;
  if (t.id.isEmpty || appliedHoldIds.contains(t.id)) return;
  appliedHoldIds.add(t.id);
  user.accountBalance = (user.accountBalance - t.amount).clamp(0.0, double.infinity);
}

void ngmyReleasePendingWithdrawalHold(UserData user, AppTransaction t, Set<String> appliedHoldIds) {
  if (t.type != TransactionType.withdrawal) return;
  if (t.id.isEmpty || !appliedHoldIds.contains(t.id)) return;
  appliedHoldIds.remove(t.id);
  user.accountBalance += t.amount;
}

/// After admin approves/rejects a wallet txn, sync user balance strictly from the ledger.
void ngmySyncUserBalanceAfterWalletDecision(
  UserData user,
  List<AppTransaction> transactions, {
  AppTransaction? justDecided,
  TransactionStatus? previousStatus,
}) {
  user.accountBalance = ngmyResolveAccountBalance(
    user.email,
    user.accountBalance,
    transactions,
  );
  if (justDecided != null &&
      previousStatus == TransactionStatus.pending &&
      justDecided.status == TransactionStatus.approved &&
      ngmyTransactionCountsAsIncome(justDecided)) {
    ngmyPlayIncomeSoundForTransaction(justDecided, force: true);
  }
}

bool ngmyTransactionCountsAsIncome(AppTransaction t) {
  if (t.status != TransactionStatus.approved) return false;
  if (!_ngmyTxnIncreasesBalance(t)) return false;
  if (t.type == TransactionType.deposit && isInvestmentRequestDetails(t.sourceDetails)) {
    return false;
  }
  return t.amount >= 0.01;
}

void ngmyPlayIncomeSoundForTransaction(AppTransaction t, {bool force = true}) {
  if (!ngmyTransactionCountsAsIncome(t)) return;
  unawaited(NgmyIncomeSound.playForUser(
    beneficiaryEmail: t.userEmail,
    amount: t.amount,
    dedupeKey: 'txn_${t.id}',
    force: force,
  ));
}

void ngmyPlayIncomeSoundForAmount({
  required String beneficiaryEmail,
  required double amount,
  String? dedupeKey,
  bool force = true,
}) {
  unawaited(NgmyIncomeSound.playForUser(
    beneficiaryEmail: beneficiaryEmail,
    amount: amount,
    dedupeKey: dedupeKey,
    force: force,
  ));
}

void ngmyApplyApprovedTransactionToBalance(UserData user, AppTransaction t, {bool playSound = false}) {
  if (t.status != TransactionStatus.approved) return;
  if (_ngmyTxnIncreasesBalance(t)) {
    user.accountBalance += t.amount;
    if (playSound) ngmyPlayIncomeSoundForTransaction(t);
  } else {
    user.accountBalance -= t.amount;
  }
}

int _ngmyTransactionStatusRank(TransactionStatus status) {
  switch (status) {
    case TransactionStatus.approved:
      return 2;
    case TransactionStatus.rejected:
      return 1;
    case TransactionStatus.pending:
      return 0;
  }
}

AppTransaction _pickPreferredTransaction(AppTransaction local, AppTransaction remote) {
  // Civic contribution/claim rejects are terminal — never resurrect approved over rejected.
  final civicType = local.type == TransactionType.contribution ||
      remote.type == TransactionType.contribution ||
      local.type == TransactionType.claim ||
      remote.type == TransactionType.claim;
  if (civicType) {
    if (local.status == TransactionStatus.rejected && remote.status != TransactionStatus.rejected) {
      return local;
    }
    if (remote.status == TransactionStatus.rejected && local.status != TransactionStatus.rejected) {
      return remote;
    }
  }
  final localRank = _ngmyTransactionStatusRank(local.status);
  final remoteRank = _ngmyTransactionStatusRank(remote.status);
  late AppTransaction pick;
  if (localRank != remoteRank) {
    pick = localRank > remoteRank ? local : remote;
  } else if (ngmyIsWalletDepositOrWithdraw(local) || ngmyIsWalletDepositOrWithdraw(remote)) {
    pick = local.timestamp.isAfter(remote.timestamp) ? local : remote;
  } else {
    pick = local.timestamp.isAfter(remote.timestamp) ? local : remote;
  }
  final localProof = (local.screenshotPath ?? '').trim();
  final remoteProof = (remote.screenshotPath ?? '').trim();
  final pickProof = (pick.screenshotPath ?? '').trim();
  if (pickProof.isNotEmpty) return pick;
  final bestProof = localProof.isNotEmpty ? localProof : remoteProof;
  if (bestProof.isEmpty) return pick;
  return AppTransaction(
    id: pick.id,
    userEmail: pick.userEmail,
    amount: pick.amount,
    type: pick.type,
    method: pick.method,
    sourceDetails: pick.sourceDetails ?? local.sourceDetails ?? remote.sourceDetails,
    screenshotPath: bestProof,
    verificationCode: pick.verificationCode ?? local.verificationCode ?? remote.verificationCode,
    status: pick.status,
    timestamp: pick.timestamp,
  );
}

/// Replace all of a user's transaction rows with cloud truth, keeping only unsynced
/// local pending rows so balances cannot drift between devices.
List<AppTransaction> ngmyReplaceUserTransactionsFromCloud(
  List<AppTransaction> all,
  String email,
  List<AppTransaction> cloudTxns, {
  Set<String>? dirtyTransactionIds,
}) {
  final key = ngmyNormalizeEmail(email);
  if (key.isEmpty) return all;
  final dirty = dirtyTransactionIds ?? const {};
  final cloudOwn = cloudTxns.where((t) => ngmyNormalizeEmail(t.userEmail) == key).toList();
  final cloudIds = cloudOwn.map((t) => t.id).where((id) => id.isNotEmpty).toSet();
  final localPendingOnly = all.where((t) {
    if (ngmyNormalizeEmail(t.userEmail) != key) return false;
    if (t.id.isEmpty) return false;
    if (cloudIds.contains(t.id)) return false;
    // Only keep rows this device created and has not finished syncing yet.
    return dirty.contains(t.id);
  }).toList();
  final preserved = all.where((t) => ngmyNormalizeEmail(t.userEmail) != key).toList();
  return [...preserved, ...cloudOwn, ...localPendingOnly]
    ..sort((a, b) => b.timestamp.compareTo(a.timestamp));
}

List<AppTransaction> _mergeTransactionsWithRemote(
  List<AppTransaction> local,
  List<AppTransaction> remote, {
  Map<String, int>? walletDecisionLedger,
}) {
  final merged = <String, AppTransaction>{};
  for (final t in remote) {
    if (t.id.isEmpty) continue;
    merged[t.id] = t;
  }
  for (final t in local) {
    if (t.id.isEmpty) continue;
    final existing = merged[t.id];
    merged[t.id] = existing == null ? t : _pickPreferredTransaction(t, existing);
  }
  final ledger = walletDecisionLedger;
  if (ledger != null && ledger.isNotEmpty) {
    for (final entry in merged.entries) {
      final decided = ledger[entry.key];
      if (decided == null || decided <= 0 || decided > 2) continue;
      final ledgerStatus = TransactionStatus.values[decided];
      final txn = entry.value;
      // Keep cloud-pending wallet requests visible in Admin → Wallet until they
      // are actually approved/rejected in the transactions table.
      if (ngmyIsWalletDepositOrWithdraw(txn) &&
          txn.status == TransactionStatus.pending &&
          ledgerStatus != TransactionStatus.pending) {
        continue;
      }
      txn.status = ledgerStatus;
    }
  }
  return merged.values.toList()..sort((a, b) => b.timestamp.compareTo(a.timestamp));
}

/// Apply balance when a transaction becomes approved (avoids double-deduct on withdrawals).
void _ngmyApplyApprovedTransitionToBalance(
  UserData user,
  AppTransaction tx, {
  required TransactionStatus? previousStatus,
}) {
  if (tx.status != TransactionStatus.approved) return;
  if (tx.type == TransactionType.withdrawal && previousStatus == TransactionStatus.pending) {
    return;
  }
  ngmyApplyApprovedTransactionToBalance(user, tx);
  if (previousStatus == TransactionStatus.pending && ngmyTransactionCountsAsIncome(tx)) {
    ngmyPlayIncomeSoundForTransaction(tx, force: true);
  }
}

enum TransactionType { deposit, withdrawal, adminAdd, adminRemove, reimbursement, contribution, claim }
enum TransactionStatus { pending, approved, rejected }
enum PaymentMethod { cashApp, bitcoin, system }

/// Wallet deposit/withdraw receipts (with screenshots) auto-delete after 5 days.
const int kNgmyWalletReceiptRetentionDays = 5;
const int kNgmyWalletHistoryDisplayMax = 500;

/// Civic help-mode / contribution campaigns may run this long before the app
/// auto-deactivates once (and records missed). Registrars can still end earlier.
const int kNgmyHelpCampaignMaxMonths = 2;

/// After a campaign is closed, contribution receipts stay visible this long.
const int kNgmyContributionReceiptAfterCloseDays = 5;

/// True when [startedAt] has reached the 2-month help-campaign limit.
bool ngmyHelpCampaignReachedMaxDuration(DateTime startedAt, [DateTime? now]) {
  final n = now ?? DateTime.now();
  final localStart = startedAt.toLocal();
  final limit = DateTime(
    localStart.year,
    localStart.month + kNgmyHelpCampaignMaxMonths,
    localStart.day,
    localStart.hour,
    localStart.minute,
    localStart.second,
    localStart.millisecond,
    localStart.microsecond,
  );
  return !n.toLocal().isBefore(limit);
}

/// Civic Registry claims a registrar has resolved (rejected/deleted) stay
/// visible as history for this long, then auto-disappear and get purged.
const int kNgmyCivicClaimRetentionDays = 60;

bool ngmyIsWalletReceiptTransaction(AppTransaction t) {
  if (t.status == TransactionStatus.pending) return false;
  return t.type == TransactionType.deposit ||
      t.type == TransactionType.withdrawal ||
      t.type == TransactionType.adminAdd;
}

bool ngmyWalletReceiptExpired(AppTransaction t, DateTime cutoff, Map<String, DateTime> decisionTimes) {
  if (!ngmyIsWalletReceiptTransaction(t)) return false;
  final decidedAt = decisionTimes[t.id] ?? t.timestamp;
  return decidedAt.isBefore(cutoff);
}

bool ngmyIsWalletDepositOrWithdraw(AppTransaction t) =>
    t.type == TransactionType.deposit || t.type == TransactionType.withdrawal;

bool _ngmyIsClockInSessionStartTransaction(AppTransaction t) {
  if (t.type != TransactionType.reimbursement) return false;
  return (t.sourceDetails ?? '').toLowerCase().contains('clock-in session started');
}

bool ngmyIsClockInHistoryTransaction(AppTransaction t) {
  if (t.type != TransactionType.reimbursement) return false;
  if (_ngmyIsClockInSessionStartTransaction(t)) return false;
  return (t.sourceDetails ?? '').toLowerCase().contains('clock-in');
}

bool ngmyIsWalletHistoryTransaction(AppTransaction t) {
  if (ngmyIsGameLedgerTransaction(t)) return false;
  if (_ngmyIsClockInSessionStartTransaction(t)) return false;
  if (t.type == TransactionType.contribution) return false;
  if (t.status == TransactionStatus.rejected) return false;
  if (t.status == TransactionStatus.pending) {
    return t.type == TransactionType.deposit || t.type == TransactionType.withdrawal;
  }
  return t.type == TransactionType.deposit ||
      t.type == TransactionType.withdrawal ||
      t.type == TransactionType.adminAdd ||
      t.type == TransactionType.adminRemove ||
      t.type == TransactionType.reimbursement ||
      t.type == TransactionType.claim;
}

List<AppTransaction> ngmyUserWalletHistoryTransactions(
  List<AppTransaction> all,
  String email, {
  int max = kNgmyWalletHistoryDisplayMax,
}) {
  final key = email.toLowerCase().trim();
  final list = all
      .where((t) => t.userEmail.toLowerCase().trim() == key)
      .where(ngmyIsWalletHistoryTransaction)
      .toList()
    ..sort((a, b) => b.timestamp.compareTo(a.timestamp));
  if (list.length <= max) return list;
  return list.take(max).toList();
}

/// Wallet-only balance from deposit/withdraw rows (matches history math, not clock-in earnings).
double ngmyWalletHistoryBalance(List<AppTransaction> walletTxns, String email) {
  final key = email.toLowerCase().trim();
  var balance = 0.0;
  for (final t in walletTxns) {
    if (t.userEmail.toLowerCase().trim() != key) continue;
    if (t.status == TransactionStatus.pending && t.type == TransactionType.withdrawal) {
      balance -= t.amount;
      continue;
    }
    if (t.status != TransactionStatus.approved) continue;
    if (t.type == TransactionType.deposit) {
      balance += t.amount;
    } else if (t.type == TransactionType.withdrawal) {
      balance -= t.amount;
    }
  }
  return balance.clamp(0.0, double.infinity);
}

double ngmyWalletHistoryDelta(AppTransaction t) {
  if (t.status != TransactionStatus.approved) return 0;
  if (t.type == TransactionType.deposit) return t.amount;
  if (t.type == TransactionType.withdrawal) return -t.amount;
  return 0;
}

/// Signed balance change when a transaction is applied (matches [ngmyBalanceFromApprovedTransactions]).
double ngmyTransactionLedgerEffect(AppTransaction t) {
  if (t.status == TransactionStatus.pending && t.type == TransactionType.withdrawal) {
    return -t.amount;
  }
  if (t.status != TransactionStatus.approved) return 0;
  if (_ngmyTxnIncreasesBalance(t)) return t.amount;
  if (t.type == TransactionType.withdrawal ||
      t.type == TransactionType.adminRemove ||
      t.type == TransactionType.contribution) {
    return -t.amount;
  }
  return 0;
}

/// Balance immediately after each transaction (newest row matches [currentBalance] when it is the latest affecting txn).
Map<String, double> ngmyBalanceAfterTransactionById({
  required String email,
  required List<AppTransaction> allTransactions,
  required double currentBalance,
}) {
  final key = ngmyNormalizeEmail(email);
  final chronological = allTransactions
      .where((t) => ngmyNormalizeEmail(t.userEmail) == key)
      .toList()
    ..sort((a, b) => b.timestamp.compareTo(a.timestamp));

  var rolling = currentBalance;
  final map = <String, double>{};
  for (final t in chronological) {
    if (t.id.isNotEmpty) map[t.id] = rolling;
    rolling -= ngmyTransactionLedgerEffect(t);
  }
  return map;
}

const String _investmentRequestPrefix = 'INVEST_REQUEST|';

bool isInvestmentRequestDetails(String? details) {
  return details != null && details.startsWith(_investmentRequestPrefix);
}

Map<String, String> parseInvestmentRequestDetails(String? details) {
  final out = <String, String>{};
  if (!isInvestmentRequestDetails(details)) return out;
  final parts = details!.split('|');
  for (final p in parts.skip(1)) {
    final idx = p.indexOf(':');
    if (idx <= 0 || idx >= p.length - 1) continue;
    out[p.substring(0, idx)] = p.substring(idx + 1);
  }
  return out;
}

String buildInvestmentRequestDetails({
  required String plan,
  required double amount,
  required double roi,
  required String payer,
}) {
  return '$_investmentRequestPrefix'
      'plan:$plan|'
      'amount:${amount.toStringAsFixed(2)}|'
      'roi:${roi.toStringAsFixed(6)}|'
      'payer:$payer';
}

/// Stable id so repeat taps cannot create duplicate investment charges.
String ngmyInvestPurchaseTxnId(String email, String planName, double planAmount) {
  final e = email.toLowerCase().trim();
  final slug = planName.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '_');
  return 'invest_buy_${e}_${slug}_${planAmount.toStringAsFixed(2)}';
}

bool ngmyUserHasActivePlan(UserData user, {required String planName, required double planAmount}) {
  final inv = user.activeInvestment;
  if (inv == null || inv.daysLeft <= 0) return false;
  return inv.name == planName && (inv.amount - planAmount).abs() < 0.0001;
}

bool ngmyHasApprovedInvestPurchase(
  String email,
  List<AppTransaction> transactions,
  String txnId,
) {
  final key = email.toLowerCase().trim();
  return transactions.any(
    (t) =>
        t.id == txnId &&
        t.userEmail.toLowerCase().trim() == key &&
        t.status == TransactionStatus.approved,
  );
}

class AppTransaction {
  final String id;
  final String userEmail;
  final double amount;
  final TransactionType type;
  final PaymentMethod method;
  final String? sourceDetails;
  final String? screenshotPath;
  final String? verificationCode;
  TransactionStatus status;
  final DateTime timestamp;

  AppTransaction({
    required this.id, required this.userEmail, required this.amount,
    required this.type, required this.method, this.sourceDetails,
    this.screenshotPath, this.verificationCode, this.status = TransactionStatus.pending,
    required this.timestamp,
  });

  Map<String, dynamic> toJson() => _transactionRowForCloud(this);

  factory AppTransaction.fromJson(Map<String, dynamic> json) {
    DateTime parseDate(dynamic v) {
      if (v == null || v == "null" || v.toString().isEmpty) return DateTime.now();
      try {
        final d = DateTime.parse(v.toString());
        return d.isUtc ? d.toLocal() : d;
      } catch (_) { return DateTime.now(); }
    }
    int parseIndex(dynamic v, int max) {
      if (v == null) return 0;
      if (v is int) return v.clamp(0, max);
      if (v is num) return v.toInt().clamp(0, max);
      final n = int.tryParse(v.toString());
      if (n != null) return n.clamp(0, max);
      final lower = v.toString().toLowerCase();
      if (lower == 'pending') return 0;
      if (lower == 'approved') return 1;
      if (lower == 'rejected') return 2;
      return 0;
    }
    return AppTransaction(
      id: (json['id'] ?? '').toString(),
      userEmail: ngmyNormalizeEmail((json['userEmail'] ?? json['user_email'] ?? '').toString()),
      amount: (json['amount'] ?? 0.0).toDouble(),
      type: TransactionType.values[parseIndex(json['type'], TransactionType.values.length - 1)],
      method: PaymentMethod.values[parseIndex(json['method'], PaymentMethod.values.length - 1)],
      sourceDetails: (json['sourceDetails'] ?? json['source_details'])?.toString(),
      screenshotPath: (json['screenshotPath'] ?? json['screenshot_path'])?.toString(),
      verificationCode: (json['verificationCode'] ?? json['verification_code'])?.toString(),
      status: TransactionStatus.values[parseIndex(json['status'], TransactionStatus.values.length - 1)],
      timestamp: parseDate(json['timestamp']),
    );
  }
}

Map<String, dynamic> _transactionRowForCloud(AppTransaction t) {
  // Only camelCase keys — live Supabase rejects snake_case duplicates (PGRST204).
  return {
    'id': t.id,
    'userEmail': ngmyNormalizeEmail(t.userEmail),
    'amount': t.amount,
    'type': t.type.index,
    'method': t.method.index,
    'sourceDetails': t.sourceDetails,
    'screenshotPath': t.screenshotPath,
    'verificationCode': t.verificationCode,
    'status': t.status.index,
    'timestamp': t.timestamp.toUtc().toIso8601String(),
  };
}

Map<String, dynamic> _transactionRowSnakeForCloud(AppTransaction t) {
  return {
    'id': t.id,
    'user_email': t.userEmail,
    'amount': t.amount,
    'type': t.type.index,
    'method': t.method.index,
    'source_details': t.sourceDetails,
    'screenshot_path': t.screenshotPath,
    'verification_code': t.verificationCode,
    'status': t.status.index,
    'timestamp': t.timestamp.toUtc().toIso8601String(),
  };
}

/// Wallet deposit screenshots are picked as base64 data URLs. Posting that inline
/// to Supabase often fails (payload too large), so admins never see the request.
Future<String?> _uploadWalletPaymentProofIfNeeded(AppTransaction t) async {
  final path = (t.screenshotPath ?? '').trim();
  if (path.isEmpty) return null;
  if (path.startsWith('supabase://')) return path;
  if (!path.startsWith('data:')) return path;

  final comma = path.indexOf(',');
  if (comma < 0) return null;
  final header = path.substring(0, comma);
  final b64 = path.substring(comma + 1);
  Uint8List bytes;
  try {
    bytes = base64Decode(b64);
  } catch (_) {
    return null;
  }
  if (bytes.isEmpty) return null;

  var mime = 'image/jpeg';
  if (header.contains(':')) {
    final typePart = header.split(';').first.split(':');
    if (typePart.length > 1 && typePart[1].trim().isNotEmpty) {
      mime = typePart[1].trim();
    }
  }
  final ext = mime.contains('png') ? 'png' : 'jpg';
  final emailSafe = ngmyNormalizeEmail(t.userEmail).replaceAll(RegExp(r'[^a-z0-9@._-]'), '_');
  final txnSafe = t.id.replaceAll(RegExp(r'[^a-zA-Z0-9._-]'), '_');
  final storagePath = 'wallet-proofs/$emailSafe/$txnSafe.$ext';
  final uploaded = await _uploadNgmyMediaBytes(bytes: bytes, storagePath: storagePath, contentType: mime);
  return uploaded.ref;
}

Future<Map<String, dynamic>> _transactionRowForCloudPrepared(AppTransaction t) async {
  final row = _transactionRowForCloud(t);
  if (!ngmyIsWalletDepositOrWithdraw(t)) return row;
  final proof = await _uploadWalletPaymentProofIfNeeded(t);
  if (proof != null && proof.isNotEmpty) {
    row['screenshotPath'] = proof;
  } else if ((t.screenshotPath ?? '').startsWith('data:')) {
    // Still sync the pending request — admin can ask user to resend proof if upload failed.
    row['screenshotPath'] = 'proof_upload_failed';
  }
  return row;
}

Future<bool> _patchTransactionStatusInCloud(AppTransaction t) async {
  final patches = <Map<String, dynamic>>[
    {'status': t.status.index},
    {'status': t.status.name},
  ];
  for (final patch in patches) {
    try {
      await Supabase.instance.client
          .from('transactions')
          .update(patch)
          .eq('id', t.id)
          .timeout(kNgmyCloudWriteTimeout);
      if (await _verifyTransactionStatusInCloud(t)) return true;
    } catch (e) {
      debugPrint('[txn] status patch: $e');
    }
  }
  return false;
}

Future<bool> _verifyTransactionStatusInCloud(AppTransaction t) async {
  try {
    final row = await Supabase.instance.client
        .from('transactions')
        .select('status')
        .eq('id', t.id)
        .maybeSingle()
        .timeout(kNgmyCloudWriteTimeout);
    if (row == null) return false;
    final remote = row['status'];
    final remoteIdx = remote is num ? remote.toInt() : int.tryParse(remote?.toString() ?? '');
    if (remoteIdx == t.status.index) return true;
    final remoteName = remote?.toString().toLowerCase().trim();
    return remoteName == t.status.name;
  } catch (e) {
    debugPrint('[txn] verify status: $e');
    return false;
  }
}

Future<bool> _pushTransactionDecisionToCloud(AppTransaction t, {int attempts = 6}) async {
  if (!await ngmyCanReachCloud()) return false;
  if (t.status == TransactionStatus.pending) return false;
  for (var i = 0; i < attempts; i++) {
    if (await _patchTransactionStatusInCloud(t)) return true;
    final camel = await _transactionRowForCloudPrepared(t);
    final snake = _transactionRowSnakeForCloud(t);
    if ((snake['screenshot_path'] ?? '').toString().startsWith('data:')) {
      snake['screenshot_path'] = camel['screenshotPath'];
    }
    for (final row in [camel, snake]) {
      final ok = await _safeUpsertTransactionRows([row], requireStatus: true);
      if (ok && await _verifyTransactionStatusInCloud(t)) return true;
    }
    await Future.delayed(Duration(milliseconds: 400 * (i + 1)));
  }
  return false;
}

Future<bool> _safeUpsertTransactionRows(
  List<Map<String, dynamic>> rows, {
  bool requireStatus = false,
}) async {
  if (!NgmyCloudPolicy.persistTransactionsToCloud) return true;
  if (rows.isEmpty) return true;
  var working = rows.map((e) => Map<String, dynamic>.from(e)).toList();
  for (var i = 0; i < 12; i++) {
    try {
      await Supabase.instance.client.from('transactions').upsert(working).timeout(kNgmyCloudWriteTimeout);
      if (requireStatus && working.every((r) => !r.containsKey('status'))) {
        debugPrint('[transactions] upsert rejected: status column missing in Supabase schema');
        return false;
      }
      return true;
    } catch (e) {
      final missing = _missingColumnFromPostgrestError(e);
      if (missing != null && missing.isNotEmpty) {
        if (requireStatus && missing == 'status') {
          debugPrint('[transactions] cannot save approval: status column missing in Supabase');
          return false;
        }
        for (final row in working) {
          row.remove(missing);
        }
        continue;
      }
      debugPrint('[transactions] upsert error: $e');
      return false;
    }
  }
  return false;
}

Future<bool> _safeUpsertUserRow(Map<String, dynamic> row) async {
  if (row.isEmpty) return true;
  var working = NgmyCloudPolicy.filterUserRowForCloud(row);
  if (working.isEmpty || !working.containsKey('email')) return true;
  for (var i = 0; i < 12; i++) {
    try {
      // users.id is the table's primary key, but every row here is keyed by
      // email (a separate unique index) and never includes id — without
      // onConflict, PostgREST's default upsert targets the primary key,
      // tries to INSERT a brand-new row, and silently fails on the email
      // unique-constraint violation, so existing rows never actually update.
      await Supabase.instance.client.from('users').upsert(working, onConflict: 'email').timeout(kNgmyCloudWriteTimeout);
      return true;
    } catch (e) {
      final missing = _missingColumnFromPostgrestError(e) ?? _missingColumnFromError(e);
      if (missing != null && missing.isNotEmpty) {
        working.remove(missing);
        continue;
      }
      debugPrint('[users] upsert error: $e');
      return false;
    }
  }
  return false;
}

