Map<String, String> _adminUserCrownBadgeFromJson(dynamic raw) {
  final out = <String, String>{};
  if (raw is Map) {
    raw.forEach((k, v) {
      final key = ngmyNormalizeEmail(k.toString());
      final crown = v.toString().trim().toLowerCase();
      if (key.isEmpty) return;
      if (crown == 'king' || crown == 'queen') {
        out[key] = crown;
      }
    });
  }
  return out;
}

Map<String, String> _adminUserAccountStatusFromJson(dynamic raw) {
  final out = <String, String>{};
  if (raw is Map) {
    raw.forEach((k, v) {
      final key = ngmyNormalizeEmail(k.toString());
      final status = v.toString().trim().toLowerCase();
      if (key.isNotEmpty && status.isNotEmpty && status != 'active') out[key] = status;
    });
  }
  return out;
}

Map<String, String> _familyTreePhotoAccessFromJson(dynamic raw) {
  final out = <String, String>{};
  if (raw is Map) {
    raw.forEach((k, v) {
      final key = k.toString().toLowerCase().trim();
      final val = v.toString().trim();
      if (key.isNotEmpty && val.isNotEmpty) out[key] = val;
    });
  }
  return out;
}

List<String> _emailListFromJson(dynamic raw) {
  if (raw is! List) return [];
  return raw.map((e) => e.toString().toLowerCase().trim()).where((e) => e.isNotEmpty).toList();
}

bool ngmyChargeUserWallet({
  required UserData user,
  required List<UserData> allUsers,
  required double amount,
  required String description,
  required void Function(AppTransaction) onAddTransaction,
  List<AppTransaction>? transactions,
}) {
  if (amount <= 0) return true;
  if (!ngmyUserWalletLedgerSettled) return false;
  final key = user.email.toLowerCase().trim();
  final idx = allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
  final target = idx >= 0 ? allUsers[idx] : user;
  final spendable = transactions != null
      ? ngmyResolveAccountBalance(target.email, target.accountBalance, transactions)
      : target.accountBalance;
  if (spendable + 0.001 < amount) return false;
  onAddTransaction(
    AppTransaction(
      id: 'ngmy-ft-${DateTime.now().microsecondsSinceEpoch}',
      userEmail: target.email,
      amount: amount,
      type: TransactionType.withdrawal,
      method: PaymentMethod.system,
      sourceDetails: description,
      status: TransactionStatus.approved,
      timestamp: DateTime.now(),
    ),
  );
  return true;
}

Map<String, String> _civicRegistryPinsFromJson(dynamic raw) {
  if (raw is Map) {
    return raw.map((k, v) => MapEntry(k.toString().trim(), v.toString().trim()));
  }
  return {};
}

Map<String, Map<String, dynamic>> _mshauriSettingsFromJson(dynamic raw) {
  if (raw is! Map) return {};
  final out = <String, Map<String, dynamic>>{};
  raw.forEach((k, v) {
    final state = k.toString().trim();
    if (state.isEmpty || v is! Map) return;
    out[state] = Map<String, dynamic>.from(v);
  });
  return out;
}

/// Admin cloud timers always win so every player uses the same seconds.
Map<String, int> _mergeGameTimeLimitsPreferCustom(Map<String, int> local, Map<String, int> remote) {
  final defaults = ngmyDefaultGameTimeLimits();
  final out = <String, int>{};
  for (final id in defaults.keys) {
    final def = defaults[id]!;
    final l = local[id] ?? def;
    final r = remote[id] ?? def;
    final remoteCustom = r != def;
    if (remoteCustom) {
      out[id] = r;
    } else if (l != def) {
      out[id] = l;
    } else {
      out[id] = def;
    }
  }
  return out;
}

int _pickCustomInt(int local, int remote, int def) {
  final localCustom = local != def;
  final remoteCustom = remote != def;
  if (remoteCustom) return remote;
  if (localCustom) return local;
  return def;
}

Map<String, dynamic> _mergeDiceSettingsPreferCustom(Map<String, dynamic> localJson, Map<String, dynamic> remoteJson) {
  final local = NgmyDiceSettings.fromJson(localJson);
  final remote = NgmyDiceSettings.fromJson(remoteJson);
  final defaults = NgmyDiceSettings();
  final weights = <String, int>{};
  for (final key in ngmyDefaultDiceWeights().keys) {
    final def = defaults.weights[key] ?? 1;
    weights[key] = _pickCustomInt(local.weights[key] ?? def, remote.weights[key] ?? def, def);
  }
  final merged = NgmyDiceSettings(
    weights: weights,
    winPercent: _pickCustomInt(local.winPercent, remote.winPercent, defaults.winPercent),
    maxWinStreak: _pickCustomInt(local.maxWinStreak, remote.maxWinStreak, defaults.maxWinStreak),
    maxLoseStreak: _pickCustomInt(local.maxLoseStreak, remote.maxLoseStreak, defaults.maxLoseStreak),
    plus3DailyLimit: _pickCustomInt(local.plus3DailyLimit, remote.plus3DailyLimit, defaults.plus3DailyLimit),
    plus3UsedToday: local.plus3Date.compareTo(remote.plus3Date) >= 0 ? local.plus3UsedToday : remote.plus3UsedToday,
    plus3Date: local.plus3Date.compareTo(remote.plus3Date) >= 0 ? local.plus3Date : remote.plus3Date,
    userGrants: local.userGrants.isNotEmpty ? local.userGrants : remote.userGrants,
    playerState: local.playerState.isNotEmpty ? local.playerState : remote.playerState,
  );
  return merged.toJson();
}

int _registrarStatusRank(String status) {
  switch (status.toLowerCase()) {
    case 'revoked':
      return 4;
    case 'approved':
      return 3;
    case 'rejected':
      return 2;
    case 'pending':
      return 1;
    default:
      return 0;
  }
}

/// Recency decides which of two application records for the same person
/// is current. Every reviewer decision writes [updatedAt]. For legacy rows
/// with the same decision timestamp, a revoke wins over an older approval;
/// a deliberate Restore Access always has a later [updatedAt] and wins.
Map<String, dynamic> _pickRegistrarApplicationRow(
  Map<String, dynamic> a,
  Map<String, dynamic> b,
) {
  DateTime? ts(Map<String, dynamic> m) {
    final raw = (m['updatedAt'] ?? m['revokedAt'] ?? m['reviewedAt'] ?? m['createdAt'] ?? '').toString();
    if (raw.trim().isEmpty) return null;
    return DateTime.tryParse(raw)?.toUtc();
  }

  final at = ts(a);
  final bt = ts(b);
  if (at != null && bt != null) {
    if (bt.isAfter(at)) return b;
    if (at.isAfter(bt)) return a;
    final ar = _registrarStatusRank((a['status'] ?? 'pending').toString());
    final br = _registrarStatusRank((b['status'] ?? 'pending').toString());
    return ar >= br ? a : b;
  }
  if (at != null) return a;
  if (bt != null) return b;
  // Neither row has a usable timestamp — revoked/rejected must beat a
  // stale approval until an administrator explicitly restores the record.
  final ar = _registrarStatusRank((a['status'] ?? 'pending').toString());
  final br = _registrarStatusRank((b['status'] ?? 'pending').toString());
  return ar >= br ? a : b;
}

void _stampJobWorkerApplicationDecision(
  Map<String, dynamic> app, {
  required bool approve,
  required String reviewerEmail,
  String? rejectionReason,
}) {
  final now = DateTime.now().toUtc().toIso8601String();
  app['status'] = approve ? 'approved' : 'rejected';
  app['reviewedAt'] = now;
  app['updatedAt'] = now;
  app['reviewedBy'] = reviewerEmail;
  if (approve) {
    app.remove('rejectionReason');
  } else {
    app['rejectionReason'] = (rejectionReason ?? '').trim();
  }
}

List<Map<String, dynamic>> _replaceJobWorkerApplicationInList(
  List<Map<String, dynamic>> apps,
  Map<String, dynamic> updated,
) {
  final id = (updated['id'] ?? '').toString();
  if (id.isEmpty) return apps.map((e) => Map<String, dynamic>.from(e)).toList();
  var found = false;
  final next = apps.map((e) {
    if ((e['id'] ?? '').toString() != id) return Map<String, dynamic>.from(e);
    found = true;
    return Map<String, dynamic>.from({...Map<String, dynamic>.from(e), ...updated});
  }).toList();
  if (!found) next.add(Map<String, dynamic>.from(updated));
  return next;
}

Map<String, dynamic>? _jobWorkerApplicationForEmail(
  List<Map<String, dynamic>> apps,
  String email,
) {
  final key = email.toLowerCase().trim();
  if (key.isEmpty) return null;
  Map<String, dynamic>? best;
  for (final raw in apps) {
    if ((raw['userEmail'] ?? '').toString().toLowerCase().trim() != key) continue;
    final row = Map<String, dynamic>.from(raw);
    best = best == null ? row : _pickRegistrarApplicationRow(best, row);
  }
  return best;
}

List<Map<String, dynamic>> _mergeCivicRegistrarApplications(
  List<Map<String, dynamic>> local,
  List<Map<String, dynamic>> remote,
) {
  final byId = <String, Map<String, dynamic>>{};
  for (final a in local) {
    final id = (a['id'] ?? '').toString();
    if (id.isNotEmpty) byId[id] = Map<String, dynamic>.from(a);
  }
  for (final a in remote) {
    final id = (a['id'] ?? '').toString();
    if (id.isEmpty) continue;
    final r = Map<String, dynamic>.from(a);
    final existing = byId[id];
    if (existing == null) {
      byId[id] = r;
      continue;
    }
    byId[id] = _pickRegistrarApplicationRow(existing, r);
  }
  final byEmail = <String, Map<String, dynamic>>{};
  final noEmail = <Map<String, dynamic>>[];
  for (final a in byId.values) {
    final email = (a['userEmail'] ?? '').toString().toLowerCase().trim();
    if (email.isEmpty) {
      noEmail.add(a);
      continue;
    }
    final existing = byEmail[email];
    byEmail[email] = existing == null ? a : _pickRegistrarApplicationRow(existing, a);
  }
  return [...byEmail.values, ...noEmail]
    ..sort((a, b) => (b['createdAt'] ?? '').toString().compareTo((a['createdAt'] ?? '').toString()));
}

String? _registrarApplicationStatusForEmail(AppConfig config, String email) {
  final key = email.toLowerCase().trim();
  if (key.isEmpty) return null;
  Map<String, dynamic>? best;
  for (final a in config.civicRegistrarApplications) {
    if ((a['userEmail'] ?? '').toString().toLowerCase().trim() != key) continue;
    final row = Map<String, dynamic>.from(a);
    best = best == null ? row : _pickRegistrarApplicationRow(best, row);
  }
  return best == null ? null : (best['status'] ?? 'pending').toString().toLowerCase();
}

void _applyRegistrarGrantsFromConfig(
  AppConfig config,
  List<UserData> users, {
  UserData? currentUser,
}) {
  for (final u in users) {
    u.isAuthorizedRegistrar = _hasEffectiveRegistrarAccess(config, u);
  }
  if (currentUser != null) {
    currentUser.isAuthorizedRegistrar = _hasEffectiveRegistrarAccess(config, currentUser);
  }
}

/// Registrar controls are granted only by an approved application, never by
/// the cached flag stored on a user record. Explicit Registry King/Admin
/// assignments remain valid only when they have no application record; an
/// explicit revoke or rejection always overrides every registrar grant.
bool _hasEffectiveRegistrarAccess(AppConfig config, UserData user) {
  final status = _registrarApplicationStatusForEmail(config, user.email);
  if (status == 'approved') return true;
  if (status == null) return user.isCivicRegistryKing || user.isCivicRegistryAdmin;
  return false;
}

List<Map<String, dynamic>> _civicRegistrarApplicationsFromConfigValue(dynamic raw) {
  if (raw is List) {
    return raw.map((e) => Map<String, dynamic>.from(e as Map)).toList();
  }
  if (raw is String && raw.trim().isNotEmpty) {
    try {
      final decoded = jsonDecode(raw);
      if (decoded is List) {
        return decoded.map((e) => Map<String, dynamic>.from(e as Map)).toList();
      }
    } catch (_) {}
  }
  return const [];
}

Future<List<Map<String, dynamic>>> _fetchRemoteCivicRegistrarApplications() async {
  try {
    final row = await _fetchNgmyConfigRow(columns: 'civicRegistrarApplications');
    if (row == null) return const [];
    return _civicRegistrarApplicationsFromConfigValue(row['civicRegistrarApplications']);
  } catch (e) {
    debugPrint('[config] fetch civicRegistrarApplications: $e');
    return const [];
  }
}

Future<({String global, Map<String, String> byState})> _fetchRemoteCivicRegistryPins() async {
  try {
    final row = await _fetchNgmyConfigRow(columns: 'civicRegistryPin,civicRegistryPinsByState');
    if (row == null) return (global: '', byState: <String, String>{});
    return (
      global: (row['civicRegistryPin'] ?? '').toString().trim(),
      byState: _civicRegistryPinsFromJson(row['civicRegistryPinsByState']),
    );
  } catch (e) {
    debugPrint('[config] fetch civic registry pins: $e');
    return (global: '', byState: <String, String>{});
  }
}

Future<void> _mergeCivicRegistryPinsIntoConfig(AppConfig config) async {
  final remote = await _fetchRemoteCivicRegistryPins();
  final backup = await NgmyCivicRegistryPins.loadLocalBackup();
  if (remote.global.isNotEmpty) {
    config.civicRegistryPin = remote.global;
  } else if (config.civicRegistryPin.trim().isEmpty && backup.global.trim().isNotEmpty) {
    config.civicRegistryPin = backup.global.trim();
  }
  config.civicRegistryPinsByState = NgmyCivicRegistryPins.mergeMaps(
    NgmyCivicRegistryPins.mergeMaps(backup.byState, config.civicRegistryPinsByState),
    remote.byState,
  );
  await NgmyCivicRegistryPins.saveLocalBackup(
    globalPin: config.civicRegistryPin,
    pinsByState: config.civicRegistryPinsByState,
  );
}

/// Cities/rooms added by a registrar were disappearing intermittently:
/// _persistCriticalConfigFields pushed config.civicCitiesByState/rooms
/// straight from this device's local state with no fetch-merge step
/// first — unlike civicRegistrarApplications and the registry pins just
/// above, which both fetch remote and merge before writing. Two
/// registrars (or a registrar and an admin) each adding a different city
/// around the same time raced: whichever device's throttled push landed
/// last silently overwrote the whole civicCitiesByState/rooms value with
/// its own local copy, discarding whatever the other device had just
/// added. Union-merging local with remote before every write closes
/// that gap — an addition can never be lost to a later write from a
/// device that didn't know about it yet.
Future<void> _mergeCivicCitiesAndRoomsIntoConfig(AppConfig config) async {
  try {
    final row = await _fetchNgmyConfigRow(columns: 'civicCitiesByState,rooms');
    if (row == null) return;
    final remoteByState = NgmyCivicRegistryStats.parseCivicCitiesByState(row['civicCitiesByState']);
    if (remoteByState.isNotEmpty) {
      config.civicCitiesByState =
          NgmyCivicRegistryStats.mergeCitiesByState(config.civicCitiesByState, remoteByState);
      config.cities = NgmyCivicRegistryStats.allCitiesUnion(config.civicCitiesByState);
    }
    final remoteRooms = row['rooms'];
    if (remoteRooms is List && remoteRooms.isNotEmpty) {
      config.rooms = NgmyCivicRegistryStats.mergeRooms(
        config.rooms,
        remoteRooms.map((e) => e.toString()).toList(),
      );
    }
  } catch (e) {
    debugPrint('[config] merge cities/rooms: $e');
  }
}

Future<void> _hydrateCivicCitiesAndRoomsFromLocalBackup(AppConfig config) async {
  final backup = await NgmyCivicRegistryStats.loadCitiesRoomsLocalBackup();
  if (backup.byState.isNotEmpty) {
    config.civicCitiesByState =
        NgmyCivicRegistryStats.mergeCitiesByState(config.civicCitiesByState, backup.byState);
    config.cities = NgmyCivicRegistryStats.allCitiesUnion(config.civicCitiesByState);
  }
  if (backup.rooms.isNotEmpty) {
    config.rooms = NgmyCivicRegistryStats.mergeRooms(config.rooms, backup.rooms);
  }
}

/// Immediate save for Manage Cities & Rooms — local backup + app_config + cloud.
Future<void> _persistCivicCitiesAndRoomsNow(AppConfig config) async {
  config.cities = NgmyCivicRegistryStats.allCitiesUnion(config.civicCitiesByState);
  await NgmyCivicRegistryStats.saveCitiesRoomsLocalBackup(
    civicCitiesByState: config.civicCitiesByState,
    rooms: config.rooms,
  );
  try {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('app_config', jsonEncode(config.toJson()));
  } catch (e) {
    debugPrint('[config] civic cities/rooms local save: $e');
  }
  if (!await ngmyCanReachCloud()) return;
  final client = Supabase.instance.client;
  final combined = NgmyCloudPolicy.filterConfigForCloud(<String, dynamic>{
    'id': kNgmyConfigRowId,
    'civicCitiesByState': config.civicCitiesByState.map((k, v) => MapEntry(k, v)),
    'cities': config.cities,
    'rooms': config.rooms,
  });
  try {
    await client.from('config').upsert(combined);
  } catch (e) {
    debugPrint('[config] civic cities/rooms upsert: $e');
  }
}

Future<void> _persistCivicRegistryPins(
  AppConfig config, {
  required String state,
  required String pin,
  String? globalPin,
}) async {
  final st = state.trim();
  final p = pin.trim();
  if (st.isNotEmpty && p.isNotEmpty) {
    config.civicRegistryPinsByState = Map<String, String>.from(config.civicRegistryPinsByState)..[st] = p;
  }
  if (globalPin != null && globalPin.trim().isNotEmpty) {
    config.civicRegistryPin = globalPin.trim();
  }
  await NgmyCivicRegistryPins.saveLocalBackup(
    globalPin: config.civicRegistryPin,
    pinsByState: config.civicRegistryPinsByState,
  );
  await _mergeCivicRegistryPinsIntoConfig(config);
  try {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('app_config', jsonEncode(config.toJson()));
  } catch (e) {
    debugPrint('[config] local civic pins save: $e');
  }
  if (await ngmyCanReachCloud()) {
    await _persistCriticalConfigFields(config);
  }
}

/// Civic Registry King — crowned by admin; may approve registrars and change states in their state.
bool _isCivicRegistryKing(UserData user) => user.isCivicRegistryKing;

String _reviewerCivicStateScope(UserData reviewer, AppConfig config) {
  if (reviewer.isAdmin) return '';
  if (!_hasCivicRegistrarReviewAccess(reviewer, config)) return '';
  final serving = NgmyCivicRegistryStats.registrarStateForUser(
    email: reviewer.email,
    userState: reviewer.state,
    applications: config.civicRegistrarApplications,
  );
  if (serving.trim().isNotEmpty) return serving.trim();
  return reviewer.state.trim();
}

bool _reviewerCanActOnRegistrarApp(UserData reviewer, Map<String, dynamic> app, AppConfig config) {
  if (reviewer.isAdmin) return true;
  if (!_hasCivicRegistrarReviewAccess(reviewer, config)) return false;
  final scope = _reviewerCivicStateScope(reviewer, config).trim().toLowerCase();
  if (scope.isEmpty) return false;
  return (app['state'] ?? '').toString().trim().toLowerCase() == scope;
}

/// App admin, Civic Registry King, or an Authorized Registrar may review
/// applications — ARs/Kings only for their own state (see scope helpers).
bool _hasCivicRegistrarReviewAccess(UserData reviewer, AppConfig config) {
  if (reviewer.isAdmin) return true;
  if (_isCivicRegistryKing(reviewer)) return true;
  return _hasEffectiveRegistrarAccess(config, reviewer);
}

void _openCivicRegistryPinSheet(
  BuildContext context, {
  required AppConfig config,
  required UserData reviewer,
  required VoidCallback onDataChanged,
  String? initialState,
}) {
  final isDark = Theme.of(context).brightness == Brightness.dark;
  const usStates = [
    'Alabama', 'Alaska', 'Arizona', 'Arkansas', 'California', 'Colorado', 'Connecticut', 'Delaware', 'Florida', 'Georgia',
    'Hawaii', 'Idaho', 'Illinois', 'Indiana', 'Iowa', 'Kansas', 'Kentucky', 'Louisiana', 'Maine', 'Maryland',
    'Massachusetts', 'Michigan', 'Minnesota', 'Mississippi', 'Missouri', 'Montana', 'Nebraska', 'Nevada', 'New Hampshire', 'New Jersey',
    'New Mexico', 'New York', 'North Carolina', 'North Dakota', 'Ohio', 'Oklahoma', 'Oregon', 'Pennsylvania', 'Rhode Island', 'South Carolina',
    'South Dakota', 'Tennessee', 'Texas', 'Utah', 'Vermont', 'Virginia', 'Washington', 'West Virginia', 'Wisconsin', 'Wyoming',
  ];
  final scope = _reviewerCivicStateScope(reviewer, config);
  showNgmyCivicRegistryPinSheet(
    context,
    isDark: isDark,
    usStates: usStates,
    globalPin: config.civicRegistryPin,
    pinsByState: config.civicRegistryPinsByState,
    initialState: initialState ?? (scope.isNotEmpty ? scope : reviewer.state),
    canEditAnyState: reviewer.isAdmin,
    reviewerAssignedState: reviewer.isAdmin ? '' : (_isCivicRegistryKing(reviewer) ? scope : ''),
    onSave: (state, pin, globalPin) => _persistCivicRegistryPins(
      config,
      state: state,
      pin: pin,
      globalPin: reviewer.isAdmin ? globalPin : null,
    ).then((_) => onDataChanged()),
  );
}

void _mergeRegistrarApplicationsIntoConfig(AppConfig config, List<Map<String, dynamic>> remote) {
  config.civicRegistrarApplications = _mergeCivicRegistrarApplications(
    config.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)).toList(),
    remote,
  );
}

Future<bool> _persistCivicRegistrarApplications(AppConfig config) async {
  try {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('app_config', jsonEncode(config.toJson()));
  } catch (e) {
    debugPrint('[registrar] local config save: $e');
  }
  await _persistManagementOperationalListsLocal(config);
  if (!await ngmyCanReachCloud()) return false;
  _operationalConfigCloudDebounce?.cancel();
  _mergeRegistrarApplicationsIntoConfig(config, await _fetchRemoteCivicRegistrarApplications());
  return await _persistManagementOperationalListsAuthoritative(config);
}

Future<void> _pushUserAuthorizedRegistrar(UserData u) async {
  final email = u.email.trim();
  if (email.isEmpty || !await ngmyCanReachCloud()) return;
  await _safeUpsertUserRow({
    'email': email,
    'isAuthorizedRegistrar': u.isAuthorizedRegistrar,
    'state': u.state,
    'civicRegistryStateSwitchesUsed': u.civicRegistryStateSwitchesUsed,
    'civicRegistryAnchorState': u.civicRegistryAnchorState,
  });
}

Map<String, dynamic> _userRowForRegistryEnrollmentFlag(UserData u) => {
      'email': u.email.trim(),
      'isEnrolledInRegistry': u.isEnrolledInRegistry,
    };

bool _userIsCivicRegistryEnrolled(AppConfig config, UserData user) =>
    user.isEnrolledInRegistry || NgmyCivicRegistryMembers.isEnrolled(config, user.email);

UserData _civicMemberRecordToDisplayUser(Map<String, dynamic> m, List<UserData> allUsers) {
  final email = NgmyCivicRegistryMembers.emailKey((m['email'] ?? '').toString());
  final registryId = (m['registryId'] ?? '').toString().trim();
  final fullName = (m['fullName'] ?? '').toString().trim();
  final idx = email.isEmpty
      ? -1
      : allUsers.indexWhere((u) => NgmyCivicRegistryMembers.emailKey(u.email) == email);
  final u = idx >= 0
      ? UserData.fromJson(allUsers[idx].toJson())
      : UserData(
          email: email,
          username: fullName.isNotEmpty ? fullName : (registryId.isNotEmpty ? registryId : 'Member'),
        );
  u.isEnrolledInRegistry = true;
  u.fullName = fullName.isNotEmpty ? fullName : (u.fullName ?? u.username);
  u.dob = (m['dob'] ?? u.dob ?? '').toString();
  u.idType = (m['idType'] ?? u.idType ?? '').toString();
  u.registryId = registryId.isNotEmpty ? registryId : (u.registryId ?? '').toString();
  u.homeAddress = (m['homeAddress'] ?? u.homeAddress ?? '').toString();
  u.phone = (m['phone'] ?? u.phone).toString();
  u.city = (m['city'] ?? '').toString();
  u.room = (m['room'] ?? '').toString();
  u.state = (m['state'] ?? u.state).toString();
  u.helps = m['helps'] is num ? (m['helps'] as num).toInt() : u.helps;
  u.missed = m['missed'] is num ? (m['missed'] as num).toInt() : u.missed;
  return u;
}

List<UserData> _civicRegistryMembersForDisplay(AppConfig config, List<UserData> allUsers) {
  NgmyCivicRegistryMembers.pruneIncompleteEnrollments(config);
  NgmyCivicRegistryMembers.migrateFromLegacyUsers(config, allUsers);
  return NgmyCivicRegistryMembers.listFrom(config).map((m) => _civicMemberRecordToDisplayUser(m, allUsers)).toList();
}

UserData _civicDeceasedRecordToDisplayUser(Map<String, dynamic> deceasedRow, List<UserData> allUsers) {
  final snap = NgmyCivicRegistryMembers.deceasedMemberSnapshot(deceasedRow) ?? deceasedRow;
  return _civicMemberRecordToDisplayUser(snap, allUsers);
}

List<UserData> _civicDeceasedMembersForDisplay(AppConfig config, List<UserData> allUsers, {String? state}) {
  final st = (state ?? '').trim().toLowerCase();
  final rows = st.isEmpty
      ? NgmyCivicRegistryMembers.deceasedFrom(config)
      : NgmyCivicRegistryMembers.deceasedSnapshotsForState(config, state!);
  return rows.map((r) => _civicDeceasedRecordToDisplayUser(r, allUsers)).toList();
}

Map<String, dynamic>? _civicMemberOrDeceasedRaw(AppConfig config, UserData u) {
  final active = NgmyCivicRegistryMembers.findByEmail(config, u.email) ??
      NgmyCivicRegistryMembers.findByRegistryId(config, u.registryId ?? '');
  if (active != null) return active;
  final deceased = NgmyCivicRegistryMembers.findDeceasedByEmail(config, u.email) ??
      NgmyCivicRegistryMembers.findDeceasedByRegistryId(config, u.registryId ?? '');
  if (deceased == null) return null;
  return NgmyCivicRegistryMembers.deceasedMemberSnapshot(deceased);
}

bool _civicMemberIsDeceased(AppConfig config, UserData u) =>
    NgmyCivicRegistryMembers.isDeceased(config, email: u.email, registryId: u.registryId ?? '');

Set<String> _civicDeceasedContributorKeys(AppConfig config) {
  final keys = <String>{};
  for (final row in NgmyCivicRegistryMembers.deceasedFrom(config)) {
    final email = NgmyCivicRegistryMembers.emailKey((row['email'] ?? '').toString());
    if (email.isNotEmpty) keys.add('em:$email');
    final rid = (row['registryId'] ?? '').toString().trim().toUpperCase();
    if (rid.isNotEmpty) keys.add('rid:$rid');
    final snap = NgmyCivicRegistryMembers.deceasedMemberSnapshot(row);
    if (snap != null) {
      final snapEmail = NgmyCivicRegistryMembers.emailKey((snap['email'] ?? '').toString());
      if (snapEmail.isNotEmpty) keys.add('em:$snapEmail');
      final snapRid = (snap['registryId'] ?? '').toString().trim().toUpperCase();
      if (snapRid.isNotEmpty) keys.add('rid:$snapRid');
      final linked = NgmyCivicRegistryMembers.emailKey((snap['linkedAppEmail'] ?? '').toString());
      if (linked.isNotEmpty) keys.add('em:$linked');
    }
  }
  return keys;
}

bool _civicContributionFromDeceased(AppTransaction t, Set<String> deceasedKeys, Map<String, dynamic> meta) {
  if (deceasedKeys.isEmpty) return false;
  final txEmail = NgmyCivicRegistryMembers.emailKey(t.userEmail);
  if (txEmail.isNotEmpty && deceasedKeys.contains('em:$txEmail')) return true;
  final metaEmail = NgmyCivicRegistryMembers.emailKey((meta['memberEmail'] ?? '').toString());
  if (metaEmail.isNotEmpty && deceasedKeys.contains('em:$metaEmail')) return true;
  final metaRid = (meta['registryId'] ?? '').toString().trim().toUpperCase();
  if (metaRid.isNotEmpty && deceasedKeys.contains('rid:$metaRid')) return true;
  return false;
}

void _syncCivicMemberRecordFromUser(AppConfig config, UserData u) {
  // Never enroll from account/profile edits — only update people already in the registry.
  final already =
      NgmyCivicRegistryMembers.findByEmail(config, u.email) != null ||
      ((u.registryId ?? '').trim().isNotEmpty &&
          NgmyCivicRegistryMembers.findByRegistryId(config, u.registryId!) != null);
  if (!already) return;
  NgmyCivicRegistryMembers.syncFromFields(
    config,
    email: u.email,
    fullName: u.fullName ?? u.username,
    dob: u.dob ?? '',
    idType: u.idType ?? '',
    homeAddress: u.homeAddress ?? '',
    phone: u.phone,
    city: u.city ?? '',
    room: u.room ?? '',
    state: u.state,
    registryId: u.registryId ?? '',
    helps: u.helps,
    missed: u.missed,
  );
}

void _setCivicEnrollmentFlagForAccount(List<UserData> allUsers, String email, bool enrolled) {
  final key = NgmyCivicRegistryMembers.emailKey(email);
  if (key.isEmpty) return;
  final idx = allUsers.indexWhere((u) => NgmyCivicRegistryMembers.emailKey(u.email) == key);
  if (idx >= 0) allUsers[idx].isEnrolledInRegistry = enrolled;
}

void _preserveRegistryEnrollmentFromLocal(UserData local, UserData remote) {
  if (!local.isEnrolledInRegistry) return;
  remote.isEnrolledInRegistry = true;
  if ((local.fullName ?? '').trim().isNotEmpty) remote.fullName = local.fullName;
  if ((local.dob ?? '').trim().isNotEmpty) remote.dob = local.dob;
  if ((local.idType ?? '').trim().isNotEmpty) remote.idType = local.idType;
  if ((local.registryId ?? '').trim().isNotEmpty) remote.registryId = local.registryId;
  if ((local.homeAddress ?? '').trim().isNotEmpty) remote.homeAddress = local.homeAddress;
  if ((local.city ?? '').trim().isNotEmpty) remote.city = local.city;
  if ((local.room ?? '').trim().isNotEmpty) remote.room = local.room;
  if (local.state.trim().isNotEmpty) remote.state = local.state;
  remote.phone = ngmyMergeAccountPhone(local: local.phone, remote: remote.phone);
  remote.helps = local.helps;
  remote.missed = local.missed;
}

NgmyCivicRegistryUserRow _civicRegistryUserRow(UserData u) => NgmyCivicRegistryUserRow(
      email: u.email,
      username: u.username,
      state: u.state,
      isAuthorizedRegistrar: u.isAuthorizedRegistrar,
      isCivicRegistryKing: u.isCivicRegistryKing,
      isCivicRegistryAdmin: u.isCivicRegistryAdmin,
      stateSwitchesUsed: u.civicRegistryStateSwitchesUsed,
      anchorState: u.civicRegistryAnchorState,
      isEnrolledInRegistry: u.isEnrolledInRegistry,
    );

Future<void> _syncRegistrarStateAfterConfigChange(
  AppConfig config,
  List<UserData> users, {
  UserData? currentUser,
}) async {
  // Revoke/approve only updates registrar access — civicRegistryMembers, spendings, and cities stay.
  _applyRegistrarGrantsFromConfig(config, users, currentUser: currentUser);
  // Include every known account. A deleted application has no status, so it
  // must be pushed as false just like an explicit revoke.
  final targets = <UserData>[...users];
  if (currentUser != null) targets.add(currentUser);
  final seen = <String>{};
  for (final u in targets) {
    final key = u.email.toLowerCase().trim();
    if (key.isEmpty || seen.contains(key)) continue;
    seen.add(key);
    await _pushUserAuthorizedRegistrar(u);
  }
}

List<Map<String, dynamic>> _mergeJobPostsLists(
  List<Map<String, dynamic>> local,
  List<Map<String, dynamic>> remote,
) {
  if (remote.isEmpty) return local.map((e) => Map<String, dynamic>.from(e)).toList();
  if (local.isEmpty) return remote.map((e) => Map<String, dynamic>.from(e)).toList();
  final byId = <String, Map<String, dynamic>>{};
  for (final a in local) {
    final id = (a['id'] ?? '').toString();
    if (id.isNotEmpty) byId[id] = Map<String, dynamic>.from(a);
  }
  for (final a in remote) {
    final id = (a['id'] ?? '').toString();
    if (id.isEmpty) continue;
    final r = Map<String, dynamic>.from(a);
    final existing = byId[id];
    if (existing == null) {
      byId[id] = r;
      continue;
    }
    final rc = (r['createdAt'] ?? r['completedAt'] ?? '').toString();
    final ec = (existing['createdAt'] ?? existing['completedAt'] ?? '').toString();
    byId[id] = rc.compareTo(ec) >= 0 ? r : existing;
  }
  return byId.values.toList()
    ..sort((a, b) => (b['createdAt'] ?? '').toString().compareTo((a['createdAt'] ?? '').toString()));
}

List<Map<String, dynamic>> _mergeJobWorkerApplicationsLists(
  List<Map<String, dynamic>> local,
  List<Map<String, dynamic>> remote,
) {
  return _mergeCivicRegistrarApplications(local, remote);
}

List<Map<String, dynamic>> _mergeLoanApplicationsLists(
  List<Map<String, dynamic>> local,
  List<Map<String, dynamic>> remote,
) {
  if (remote.isEmpty) return local.map((e) => Map<String, dynamic>.from(e)).toList();
  if (local.isEmpty) return remote.map((e) => Map<String, dynamic>.from(e)).toList();
  final byId = <String, Map<String, dynamic>>{};
  for (final a in local) {
    final id = (a['id'] ?? '').toString();
    if (id.isNotEmpty) byId[id] = Map<String, dynamic>.from(a);
  }
  for (final a in remote) {
    final id = (a['id'] ?? '').toString();
    if (id.isEmpty) continue;
    final r = Map<String, dynamic>.from(a);
    final existing = byId[id];
    if (existing == null) {
      byId[id] = r;
    } else {
      final lu = (existing['updatedAt'] ?? '').toString();
      final ru = (r['updatedAt'] ?? '').toString();
      final es = (existing['status'] ?? 'pending').toString();
      final rs = (r['status'] ?? 'pending').toString();
      final existingFinal = es == 'approved' || es == 'rejected';
      final remoteFinal = rs == 'approved' || rs == 'rejected';
      if (existingFinal && !remoteFinal) {
        ngmyLoanMergePaymentsIntoApp(existing, r);
        ngmyLoanMergePhotoRefsIntoApp(existing, r);
        byId[id] = existing;
      } else if (!existingFinal && remoteFinal) {
        ngmyLoanMergePaymentsIntoApp(r, existing);
        ngmyLoanMergePhotoRefsIntoApp(r, existing);
        byId[id] = r;
      } else {
        final winner = ru.compareTo(lu) >= 0 ? r : existing;
        final loser = identical(winner, r) ? existing : r;
        ngmyLoanMergePaymentsIntoApp(winner, loser);
        ngmyLoanMergePhotoRefsIntoApp(winner, loser);
        byId[id] = winner;
      }
    }
  }
  return byId.values.toList()
    ..sort((a, b) => (b['createdAt'] ?? '').toString().compareTo((a['createdAt'] ?? '').toString()));
}

/// Never drop local admin decisions when cloud config poll/bootstrap is stale.
void _mergeOperationalManagementListsIntoConfig(AppConfig next, AppConfig keep) {
  final keepLoans = keep.loanApplications.map((e) => Map<String, dynamic>.from(e)).toList();
  final keepJobPosts = keep.jobPosts.map((e) => Map<String, dynamic>.from(e)).toList();
  final keepJobWorkerApps = keep.jobWorkerApplications.map((e) => Map<String, dynamic>.from(e)).toList();
  final keepHelpApps = keep.helpHelperApplications.map((e) => Map<String, dynamic>.from(e)).toList();
  final keepHelpReqs = keep.helpRequests.map((e) => Map<String, dynamic>.from(e)).toList();
  final keepHelpBiz = keep.helpBusinesses.map((e) => Map<String, dynamic>.from(e)).toList();

  if (next.loanApplications.isEmpty && keepLoans.isNotEmpty) {
    next.loanApplications = keepLoans;
  } else {
    next.loanApplications = _mergeLoanApplicationsLists(keepLoans, next.loanApplications);
  }
  if (next.jobPosts.isEmpty && keepJobPosts.isNotEmpty) {
    next.jobPosts = keepJobPosts;
  } else {
    next.jobPosts = _mergeJobPostsLists(keepJobPosts, next.jobPosts);
  }
  if (next.jobWorkerApplications.isEmpty && keepJobWorkerApps.isNotEmpty) {
    next.jobWorkerApplications = keepJobWorkerApps;
  } else {
    next.jobWorkerApplications = _mergeJobWorkerApplicationsLists(keepJobWorkerApps, next.jobWorkerApplications);
  }
  if (next.helpHelperApplications.isEmpty && keepHelpApps.isNotEmpty) {
    next.helpHelperApplications = keepHelpApps;
  } else if (keepHelpApps.isNotEmpty || next.helpHelperApplications.isNotEmpty) {
    next.helpHelperApplications = _mergeJobWorkerApplicationsLists(keepHelpApps, next.helpHelperApplications);
  }
  if (next.helpRequests.isEmpty && keepHelpReqs.isNotEmpty) {
    next.helpRequests = keepHelpReqs;
  } else if (keepHelpReqs.isNotEmpty || next.helpRequests.isNotEmpty) {
    next.helpRequests = _mergeJobWorkerApplicationsLists(keepHelpReqs, next.helpRequests);
  }
  if (next.helpBusinesses.isEmpty && keepHelpBiz.isNotEmpty) {
    next.helpBusinesses = keepHelpBiz;
  } else if (keepHelpBiz.isNotEmpty || next.helpBusinesses.isNotEmpty) {
    next.helpBusinesses = _mergeJobWorkerApplicationsLists(keepHelpBiz, next.helpBusinesses);
  }
  final keepSpendings = keep.helpCampaignSpendings.map((e) => Map<String, dynamic>.from(e)).toList();
  if (next.helpCampaignSpendings.isEmpty && keepSpendings.isNotEmpty) {
    next.helpCampaignSpendings = keepSpendings;
  } else if (keepSpendings.isNotEmpty || next.helpCampaignSpendings.isNotEmpty) {
    next.helpCampaignSpendings = _mergeHelpCampaignSpendingsLists(keepSpendings, next.helpCampaignSpendings);
  }
}

List<Map<String, dynamic>> _mergeHelpCampaignSpendingsLists(
  List<Map<String, dynamic>> local,
  List<Map<String, dynamic>> remote,
) {
  final byId = <String, Map<String, dynamic>>{};
  for (final raw in [...local, ...remote]) {
    final row = Map<String, dynamic>.from(raw);
    final id = (row['id'] ?? '').toString();
    if (id.isEmpty) continue;
    byId[id] = row;
  }
  return byId.values.toList()
    ..sort((a, b) {
      final at = DateTime.tryParse((a['recordedAt'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
      final bt = DateTime.tryParse((b['recordedAt'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
      return bt.compareTo(at);
    });
}

/// Closures are the missed-count idempotency key. Never replace — union by campaignId.
List<Map<String, dynamic>> _mergeHelpCampaignClosuresLists(
  List<Map<String, dynamic>> local,
  List<Map<String, dynamic>> remote,
) {
  final byId = <String, Map<String, dynamic>>{};
  void take(Map<String, dynamic> raw) {
    final row = Map<String, dynamic>.from(raw);
    final id = (row['campaignId'] ?? '').toString().trim();
    if (id.isEmpty) return;
    final prev = byId[id];
    if (prev == null) {
      byId[id] = row;
      return;
    }
    final prevAt = DateTime.tryParse((prev['closedAt'] ?? '').toString());
    final nextAt = DateTime.tryParse((row['closedAt'] ?? '').toString());
    if (prevAt == null || (nextAt != null && nextAt.isBefore(prevAt))) {
      byId[id] = row;
    }
  }
  for (final raw in [...local, ...remote]) {
    take(Map<String, dynamic>.from(raw));
  }
  return byId.values.toList();
}

/// Prefer inactive when either side already closed that campaign — stops cloud
/// from resurrecting an auto-expired / deactivated help mode and re-blinking it.
Map<String, dynamic> _mergeHelpModeByStateMaps(
  Map<String, dynamic> local,
  Map<String, dynamic> remote, {
  List<Map<String, dynamic>> closures = const [],
}) {
  final closedIds = <String>{
    for (final c in closures)
      if ((c['campaignId'] ?? '').toString().trim().isNotEmpty) (c['campaignId'] ?? '').toString().trim(),
  };

  Map<String, Map<String, dynamic>> normalize(Map<String, dynamic> src) {
    final out = <String, Map<String, dynamic>>{};
    src.forEach((k, v) {
      final key = k.toString().trim().toLowerCase();
      if (key.isEmpty || v is! Map) return;
      out[key] = Map<String, dynamic>.from(v);
    });
    return out;
  }

  final localNorm = normalize(local);
  final remoteNorm = normalize(remote);
  final keys = <String>{...localNorm.keys, ...remoteNorm.keys};
  final out = <String, dynamic>{};

  for (final key in keys) {
    final l = localNorm[key];
    final r = remoteNorm[key];
    if (l == null && r == null) continue;
    if (l == null) {
      final campaign = Map<String, dynamic>.from(r!);
      final cid = (campaign['campaignId'] ?? '').toString().trim();
      if (cid.isNotEmpty && closedIds.contains(cid)) campaign['active'] = false;
      out[key] = campaign;
      continue;
    }
    if (r == null) {
      out[key] = Map<String, dynamic>.from(l);
      continue;
    }

    final localId = (l['campaignId'] ?? '').toString().trim();
    final remoteId = (r['campaignId'] ?? '').toString().trim();
    final localActive = l['active'] == true;
    final remoteActive = r['active'] == true;
    final sameCampaign = localId.isNotEmpty && localId == remoteId;

    late final Map<String, dynamic> chosen;
    if (sameCampaign) {
      chosen = Map<String, dynamic>.from(remoteActive ? r : l);
      if (!localActive || !remoteActive) chosen['active'] = false;
      if ((chosen['campaignId'] ?? '').toString().trim().isEmpty && localId.isNotEmpty) {
        chosen['campaignId'] = localId;
      }
      if ((chosen['campaignStartedAt'] ?? '').toString().trim().isEmpty &&
          (l['campaignStartedAt'] ?? '').toString().trim().isNotEmpty) {
        chosen['campaignStartedAt'] = l['campaignStartedAt'];
      }
    } else if (localActive && !remoteActive) {
      chosen = Map<String, dynamic>.from(l);
    } else if (remoteActive && !localActive) {
      chosen = Map<String, dynamic>.from(r);
    } else if (localActive && remoteActive) {
      final lt = DateTime.tryParse((l['campaignStartedAt'] ?? '').toString());
      final rt = DateTime.tryParse((r['campaignStartedAt'] ?? '').toString());
      chosen = Map<String, dynamic>.from(
        (rt != null && (lt == null || rt.isAfter(lt))) ? r : l,
      );
    } else {
      chosen = Map<String, dynamic>.from(l);
      chosen['active'] = false;
    }

    final cid = (chosen['campaignId'] ?? '').toString().trim();
    if (cid.isNotEmpty && closedIds.contains(cid)) chosen['active'] = false;
    out[key] = chosen;
  }
  return out;
}
/// Keeps local civic/game admin settings when Supabase row is missing jsonb columns.
void _applyRemoteConfigMerge(AppConfig next, Map<String, dynamic> record, AppConfig keep) {
  if (record.containsKey('gameTimeLimits') && record['gameTimeLimits'] is Map) {
    final remote = ngmyParseGameTimeLimits(record['gameTimeLimits']);
    next.gameTimeLimits = _mergeGameTimeLimitsPreferCustom(keep.gameTimeLimits, remote);
  } else {
    next.gameTimeLimits = Map<String, int>.from(keep.gameTimeLimits);
  }

  if (record.containsKey('diceSettings') && record['diceSettings'] is Map) {
    final remote = Map<String, dynamic>.from(record['diceSettings'] as Map);
    if (remote.isNotEmpty) {
      next.diceSettings = _mergeDiceSettingsPreferCustom(keep.diceSettings, remote);
    } else {
      next.diceSettings = Map<String, dynamic>.from(keep.diceSettings);
    }
  } else {
    next.diceSettings = Map<String, dynamic>.from(keep.diceSettings);
  }

  if (record.containsKey('gameInvites') && record['gameInvites'] is List) {
    final remote = (record['gameInvites'] as List).map((e) => Map<String, dynamic>.from(e as Map)).toList();
    next.gameInvites = mergeGameInvites(keep.gameInvites, remote);
  } else if (keep.gameInvites.isNotEmpty) {
    next.gameInvites = keep.gameInvites.map((e) => Map<String, dynamic>.from(e)).toList();
  }

  if (record.containsKey('civicRegistryPin')) {
    final remotePin = (record['civicRegistryPin'] ?? '').toString().trim();
    if (remotePin.isNotEmpty) {
      next.civicRegistryPin = remotePin;
    } else if (keep.civicRegistryPin.trim().isNotEmpty) {
      next.civicRegistryPin = keep.civicRegistryPin;
    }
  } else if (keep.civicRegistryPin.trim().isNotEmpty) {
    next.civicRegistryPin = keep.civicRegistryPin;
  }

  if (record.containsKey('civicRegistryPinsByState') && record['civicRegistryPinsByState'] is Map) {
    final remotePins = _civicRegistryPinsFromJson(record['civicRegistryPinsByState']);
    next.civicRegistryPinsByState = NgmyCivicRegistryPins.mergeMaps(keep.civicRegistryPinsByState, remotePins);
  } else if (keep.civicRegistryPinsByState.isNotEmpty) {
    next.civicRegistryPinsByState = Map<String, String>.from(keep.civicRegistryPinsByState);
  }

  if (record.containsKey('civicCitiesByState') && record['civicCitiesByState'] is Map) {
    final remoteByState = NgmyCivicRegistryStats.parseCivicCitiesByState(record['civicCitiesByState']);
    next.civicCitiesByState =
        NgmyCivicRegistryStats.mergeCitiesByState(keep.civicCitiesByState, remoteByState);
    next.cities = NgmyCivicRegistryStats.allCitiesUnion(next.civicCitiesByState);
  } else if (keep.civicCitiesByState.isNotEmpty) {
    next.civicCitiesByState = Map<String, List<String>>.from(keep.civicCitiesByState);
    next.cities = NgmyCivicRegistryStats.allCitiesUnion(next.civicCitiesByState);
  }

  if (record.containsKey('rooms') && record['rooms'] is List) {
    final remoteRooms = (record['rooms'] as List).map((e) => e.toString()).toList();
    next.rooms = NgmyCivicRegistryStats.mergeRooms(keep.rooms, remoteRooms);
  } else if (keep.rooms.isNotEmpty) {
    next.rooms = List<String>.from(keep.rooms);
  }

  if (record.containsKey('civicRegistrarApplications')) {
    final remoteApps = _civicRegistrarApplicationsFromConfigValue(record['civicRegistrarApplications']);
    next.civicRegistrarApplications = _mergeCivicRegistrarApplications(
      keep.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)).toList(),
      remoteApps,
    );
  } else if (keep.civicRegistrarApplications.isNotEmpty) {
    next.civicRegistrarApplications =
        keep.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)).toList();
  }

  // Prefer cloud config column when present; ngmy_settings hydrate still wins afterward.
  if (record.containsKey('civicSelfEnrollmentEnabled')) {
    next.civicSelfEnrollmentEnabled = record['civicSelfEnrollmentEnabled'] == true;
  } else {
    next.civicSelfEnrollmentEnabled = keep.civicSelfEnrollmentEnabled;
  }

  if (record.containsKey('officialCashApp') || record.containsKey('official_cash_app')) {
    final remote = (record['officialCashApp'] ?? record['official_cash_app'] ?? '').toString().trim();
    if (remote.isNotEmpty) {
      next.officialCashApp = remote;
    } else if (keep.officialCashApp.trim().isNotEmpty) {
      next.officialCashApp = keep.officialCashApp;
    }
  } else if (keep.officialCashApp.trim().isNotEmpty) {
    next.officialCashApp = keep.officialCashApp;
  }

  if (record.containsKey('officialBitcoin') || record.containsKey('official_bitcoin')) {
    final remote = (record['officialBitcoin'] ?? record['official_bitcoin'] ?? '').toString().trim();
    if (remote.isNotEmpty) {
      next.officialBitcoin = remote;
    } else if (keep.officialBitcoin.trim().isNotEmpty) {
      next.officialBitcoin = keep.officialBitcoin;
    }
  } else if (keep.officialBitcoin.trim().isNotEmpty) {
    next.officialBitcoin = keep.officialBitcoin;
  }

  if (record.containsKey('familyTreeCreateFee')) {
    if (ngmyShouldDeferRemoteConfigOverwrite()) {
      next.familyTreeCreateFee = keep.familyTreeCreateFee;
    } else {
      final v = record['familyTreeCreateFee'];
      if (v is num && v >= 0) next.familyTreeCreateFee = v.toDouble();
    }
  } else {
    next.familyTreeCreateFee = keep.familyTreeCreateFee;
  }
  if (record.containsKey('familyTreePhotoMonthlyFee')) {
    if (ngmyShouldDeferRemoteConfigOverwrite()) {
      next.familyTreePhotoMonthlyFee = keep.familyTreePhotoMonthlyFee;
    } else {
      final v = record['familyTreePhotoMonthlyFee'];
      if (v is num && v >= 0) next.familyTreePhotoMonthlyFee = v.toDouble();
    }
  } else {
    next.familyTreePhotoMonthlyFee = keep.familyTreePhotoMonthlyFee;
  }
  if (record.containsKey('musicStudioPerSongFee')) {
    if (ngmyShouldDeferRemoteConfigOverwrite()) {
      next.musicStudioPerSongFee = keep.musicStudioPerSongFee;
    } else {
      final v = record['musicStudioPerSongFee'];
      if (v is num && v >= 0) next.musicStudioPerSongFee = v.toDouble();
    }
  } else {
    next.musicStudioPerSongFee = keep.musicStudioPerSongFee;
  }
  if (record.containsKey('appStudioCloudSaveFee')) {
    if (ngmyShouldDeferRemoteConfigOverwrite()) {
      next.appStudioCloudSaveFee = keep.appStudioCloudSaveFee;
    } else {
      final v = record['appStudioCloudSaveFee'];
      if (v is num && v >= 0) next.appStudioCloudSaveFee = v.toDouble();
    }
  } else {
    next.appStudioCloudSaveFee = keep.appStudioCloudSaveFee;
  }
  if (record.containsKey('communicateEnabled')) {
    next.communicateEnabled = record['communicateEnabled'] == true;
  } else {
    next.communicateEnabled = keep.communicateEnabled;
  }
  if (record.containsKey('appBuilderEnabled')) {
    next.appBuilderEnabled = record['appBuilderEnabled'] == true;
  } else {
    next.appBuilderEnabled = keep.appBuilderEnabled;
  }
  if (record.containsKey('appBuilderPublished') && record['appBuilderPublished'] is List) {
    next.appBuilderPublished = List<Map<String, dynamic>>.from(
      (record['appBuilderPublished'] as List).map((e) => Map<String, dynamic>.from(e as Map)),
    );
  } else if (keep.appBuilderPublished.isNotEmpty) {
    next.appBuilderPublished = List<Map<String, dynamic>>.from(keep.appBuilderPublished.map((e) => Map<String, dynamic>.from(e)));
  }
  if (record.containsKey('appBuilderReviewQueue') && record['appBuilderReviewQueue'] is List) {
    next.appBuilderReviewQueue = List<Map<String, dynamic>>.from(
      (record['appBuilderReviewQueue'] as List).map((e) => Map<String, dynamic>.from(e as Map)),
    );
  } else if (keep.appBuilderReviewQueue.isNotEmpty) {
    next.appBuilderReviewQueue = List<Map<String, dynamic>>.from(keep.appBuilderReviewQueue.map((e) => Map<String, dynamic>.from(e)));
  }
  if (record.containsKey('communicateFeeAmount') && !ngmyShouldDeferRemoteConfigOverwrite()) {
    final v = record['communicateFeeAmount'];
    if (v is num && v >= 0) next.communicateFeeAmount = v.toDouble();
  } else {
    next.communicateFeeAmount = keep.communicateFeeAmount;
