Future<bool> _pushUserProfilePictureToCloud(UserData u) async {
  if (!await ngmyCanReachCloud()) return false;
  final email = u.email.trim();
  if (email.isEmpty) return false;
  final photo = (u.profilePicturePath ?? '').trim();
  if (photo.isEmpty || photo.startsWith('data:image')) return false;
  for (var attempt = 0; attempt < 3; attempt++) {
    final ok = await _safeUpsertUserRow({
      'email': email,
      'profilePicturePath': photo,
    });
    if (ok) return true;
    await Future.delayed(Duration(milliseconds: 400 * (attempt + 1)));
  }
  return false;
}

Future<void> _hydrateUserCrownBadgeFromCloud(UserData u) async {
  if (!await ngmyCanReachCloud()) return;
  final email = u.email.trim();
  if (email.isEmpty) return;
  try {
    final row = await Supabase.instance.client
        .from('users')
        .select(NgmySupabaseColumns.userCrownBadge)
        .eq('email', email)
        .maybeSingle()
        .timeout(kNgmyCloudLoadTimeout);
    if (row == null) return;
    final crown = (row[NgmySupabaseColumns.userCrownBadge] ?? '').toString().trim().toLowerCase();
    if (crown == 'king' || crown == 'queen') {
      u.crownBadge = crown;
    } else if (crown.isEmpty) {
      u.crownBadge = '';
    }
  } catch (e) {
    if (_missingColumnFromError(e) != null) return;
    debugPrint('[user] crown fetch: $e');
  }
}

Future<bool> _pushUserAdminAccountFieldsToCloud(UserData u) async {
  return true;
}

Future<bool> _deleteUserFromCloud(String email) async {
  final key = email.trim();
  if (key.isEmpty || !await ngmyCanReachCloud()) return false;
  try {
    await Supabase.instance.client.from('users').delete().eq('email', key).timeout(kNgmyCloudWriteTimeout);
    return true;
  } catch (e) {
    debugPrint('[admin] delete user cloud: $e');
    return false;
  }
}

Map<String, dynamic> _userSignupRowForCloud(UserData u) {
  final username = u.username.trim().isEmpty ? u.email.split('@').first : u.username.trim();
  final row = <String, dynamic>{
    'email': ngmyNormalizeEmail(u.email),
    'username': username,
    'phone': u.phone.trim(),
    'status': u.status.trim().isEmpty ? 'active' : u.status,
    'isAdmin': u.isAdmin,
  };
  // Never overwrite an existing cloud password with an empty hash (OAuth / partial sync).
  if (u.passwordHash.trim().isNotEmpty) {
    row['passwordHash'] = u.passwordHash;
  }
  return row;
}

/// Saves a new or returning account to Supabase so admin can see app signups.
Future<bool> _pushSignupUserToCloudReliable(UserData u, {bool includeFreeTrial = false}) async {
  if (u.email.trim().isEmpty) return false;
  ngmyMarkUserAsAppLoginAccount(u);
  for (var i = 0; i < 8; i++) {
    if (!await ngmyCanReachCloud()) {
      await Future.delayed(Duration(milliseconds: 400 * (i + 1)));
      continue;
    }
    if (await _safeUpsertUserRow(_userSignupRowForCloud(u))) break;
    if (i == 7) return false;
    await Future.delayed(Duration(milliseconds: 400 * (i + 1)));
  }
  final photo = (u.profilePicturePath ?? '').trim();
  if (photo.isNotEmpty && !photo.startsWith('data:image')) {
    await _pushUserProfilePictureToCloud(u);
  }
  return true;
}

Future<bool> _pushUserToCloudFast(UserData u, {bool includeFreeTrial = false, bool includeBalance = false}) async {
  return _pushUserProfilePictureToCloud(u);
}

Future<bool> _pushUserMediaProfileFast(UserData u) async {
  return true;
}

void _mergeUserMediaProfileFields(UserData local, UserData remote) {
  remote.mediaFollowers = <String>{...remote.mediaFollowers, ...local.mediaFollowers}.toList();
  remote.mediaFollowing = <String>{...remote.mediaFollowing, ...local.mediaFollowing}.toList();
  remote.readAnnouncementIds = NgmyAnnouncementReads.mergeReadSets(local.readAnnouncementIds, remote.readAnnouncementIds).toList();
  remote.openedContributionReceiptKeys = NgmyCivicReadState.mergeSets(
    local.openedContributionReceiptKeys,
    remote.openedContributionReceiptKeys,
  ).toList();
  remote.dismissedContributionReceiptKeys = NgmyCivicReadState.mergeSets(
    local.dismissedContributionReceiptKeys,
    remote.dismissedContributionReceiptKeys,
  ).toList();
  if ((local.mediaBio ?? '').trim().isNotEmpty && (remote.mediaBio ?? '').trim().isEmpty) {
    remote.mediaBio = local.mediaBio;
  }
  if (local.mediaHighlights.isNotEmpty && remote.mediaHighlights.isEmpty) {
    remote.mediaHighlights = local.mediaHighlights.map((e) => Map<String, dynamic>.from(e)).toList();
  }
  if (local.mediaStories.isNotEmpty && remote.mediaStories.isEmpty) {
    remote.mediaStories = local.mediaStories.map((e) => Map<String, dynamic>.from(e)).toList();
  }
}

void showNgmyCivicRegistrarApplicationsSheet(
  BuildContext context, {
  required AppConfig config,
  required List<UserData> allUsers,
  required UserData reviewer,
  required VoidCallback onDataChanged,
  VoidCallback? onParentSetState,
}) {
  showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    backgroundColor: Colors.transparent,
    builder: (ctx) => StatefulBuilder(
      builder: (ctx, setST) {
        final isDark = Theme.of(ctx).brightness == Brightness.dark;
        final scope = _reviewerCivicStateScope(reviewer, config).trim().toLowerCase();
        final apps = List<Map<String, dynamic>>.from(
          config.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)),
        )
          ..retainWhere((a) {
            if (scope.isEmpty) return true;
            return (a['state'] ?? '').toString().trim().toLowerCase() == scope;
          })
          ..sort((a, b) => (b['createdAt'] ?? '').toString().compareTo((a['createdAt'] ?? '').toString()));
        final pendingApps = apps.where((a) => (a['status'] ?? 'pending').toString() == 'pending').toList();

        String fmt(String raw) {
          if (raw.trim().isEmpty) return 'N/A';
          try {
            final d = DateTime.parse(raw).toLocal();
            return '${d.month}/${d.day}/${d.year} ${d.hour}:${d.minute.toString().padLeft(2, '0')}';
          } catch (_) {
            return raw;
          }
        }

        return Align(
          alignment: Alignment.bottomCenter,
          child: Container(
            constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(ctx).height * 0.88),
            margin: const EdgeInsets.fromLTRB(14, 14, 14, 18),
            decoration: BoxDecoration(
              color: isDark ? const Color(0xFF0F111A) : Colors.white,
              borderRadius: BorderRadius.circular(26),
              border: Border.all(color: isDark ? Colors.white10 : const Color(0xFFE2E8F0)),
            ),
            padding: const EdgeInsets.fromLTRB(18, 10, 18, 18),
            child: Column(
              children: [
                Container(width: 40, height: 4, decoration: BoxDecoration(color: Colors.grey.withOpacity(0.3), borderRadius: BorderRadius.circular(10))),
                const SizedBox(height: 12),
                Row(
                  children: [
                    const Icon(Icons.verified_user_rounded, color: Color(0xFF6200EE)),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        scope.isEmpty
                            ? 'Authorized Registrar Requests'
                            : 'Registrar Requests — ${_reviewerCivicStateScope(reviewer, config)}',
                        style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 18),
                      ),
                    ),
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 4),
                      decoration: BoxDecoration(color: Colors.orange.withOpacity(0.12), borderRadius: BorderRadius.circular(9)),
                      child: Text('${pendingApps.length} pending', style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 11)),
                    ),
                  ],
                ),
                const SizedBox(height: 12),
                Expanded(
                  child: apps.isEmpty
                      ? Center(child: Text('No registrar applications yet.', style: TextStyle(color: isDark ? Colors.white54 : Colors.black54)))
                      : ListView.builder(
                          itemCount: apps.length,
                          itemBuilder: (context, i) {
                            final app = apps[i];
                            final status = (app['status'] ?? 'pending').toString();
                            final statusColor = status == 'approved'
                                ? Colors.green
                                : status == 'revoked' || status == 'rejected'
                                    ? Colors.red
                                    : Colors.orange;
                            final email = (app['userEmail'] ?? '').toString().toLowerCase().trim();
                            final userIndex = allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
                            return Container(
                              margin: const EdgeInsets.only(bottom: 10),
                              padding: const EdgeInsets.all(12),
                              decoration: BoxDecoration(
                                color: isDark ? const Color(0xFF1C1F2E) : const Color(0xFFF8FAFC),
                                borderRadius: BorderRadius.circular(12),
                                border: Border.all(color: statusColor.withOpacity(0.28)),
                              ),
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Row(
                                    children: [
                                      Expanded(
                                        child: Text(
                                          (app['fullName'] ?? app['username'] ?? 'Applicant').toString(),
                                          style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 15),
                                        ),
                                      ),
                                      Container(
                                        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                                        decoration: BoxDecoration(color: statusColor.withOpacity(0.12), borderRadius: BorderRadius.circular(8)),
                                        child: Text(status.toUpperCase(), style: TextStyle(color: statusColor, fontSize: 10, fontWeight: FontWeight.bold)),
                                      ),
                                    ],
                                  ),
                                  const SizedBox(height: 5),
                                  Text('Email: ${app['userEmail'] ?? ''}'),
                                  if ((app['state'] ?? '').toString().trim().isNotEmpty) Text('State: ${app['state']}'),
                                  if ((app['phone'] ?? '').toString().trim().isNotEmpty) Text('Phone: ${app['phone']}'),
                                  if ((app['reason'] ?? '').toString().trim().isNotEmpty)
                                    Padding(
                                      padding: const EdgeInsets.only(top: 4),
                                      child: Text('Reason: ${app['reason']}', style: const TextStyle(height: 1.35)),
                                    ),
                                  if ((app['experience'] ?? '').toString().trim().isNotEmpty)
                                    Text('Experience: ${app['experience']}', style: TextStyle(color: isDark ? Colors.white54 : Colors.black54, fontSize: 12)),
                                  Text('Submitted: ${fmt((app['createdAt'] ?? '').toString())}', style: TextStyle(color: isDark ? Colors.white54 : Colors.black54, fontSize: 11)),
                                  if (status == 'pending' && _reviewerCanActOnRegistrarApp(reviewer, app, config)) ...[
                                    const SizedBox(height: 8),
                                    Row(
                                      children: [
                                        Expanded(
                                          child: OutlinedButton(
                                            onPressed: () async {
                                              final decidedAt = DateTime.now().toUtc().toIso8601String();
                                              app['status'] = 'rejected';
                                              app['reviewedAt'] = decidedAt;
                                              app['updatedAt'] = decidedAt;
                                              app['reviewedBy'] = reviewer.email;
                                              // Write the update back into the FULL config list, not
                                              // `apps` — `apps` is scope-filtered to this reviewer's own
                                              // state (see its construction above), so assigning it
                                              // straight to config.civicRegistrarApplications silently
                                              // dropped every other state's applications whenever a
                                              // King (not Admin) reviewer actioned one of their own.
                                              config.civicRegistrarApplications = NgmyCivicRegistrarApplication.upsertInList(
                                                config.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)).toList(),
                                                app,
                                              );
                                              await NgmyCivicRegistrarApplication.save(email, Map<String, dynamic>.from(app));
                                              await _persistCivicRegistrarApplications(config);
                                              if (userIndex != -1) {
                                                allUsers[userIndex].isAuthorizedRegistrar = false;
                                                await _pushUserAuthorizedRegistrar(allUsers[userIndex]);
                                              }
                                              await _syncRegistrarStateAfterConfigChange(config, allUsers);
                                              onDataChanged();
                                              onParentSetState?.call();
                                              setST(() {});
                                            },
                                            child: const Text('Reject'),
                                          ),
                                        ),
                                        const SizedBox(width: 8),
                                        Expanded(
                                          child: ElevatedButton(
                                            onPressed: () async {
                                              final appState = (app['state'] ?? '').toString().trim();
                                              if (appState.isNotEmpty &&
                                                  !NgmyCivicRegistryStats.canApproveRegistrarForState(
                                                    state: appState,
                                                    applications: apps,
                                                    users: allUsers,
                                                  )) {
                                                ScaffoldMessenger.of(ctx).showSnackBar(
                                                  SnackBar(
                                                    content: Text(
                                                      '$appState already has $kNgmyMaxRegistrarsPerState authorized registrars. Revoke one or set Civic Registry Admin.',
                                                    ),
                                                  ),
                                                );
                                                return;
                                              }
                                              final decidedAt = DateTime.now().toUtc().toIso8601String();
                                              app['status'] = 'approved';
                                              app['reviewedAt'] = decidedAt;
                                              app['updatedAt'] = decidedAt;
                                              app['reviewedBy'] = reviewer.email;
                                              config.civicRegistrarApplications = NgmyCivicRegistrarApplication.upsertInList(
                                                config.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)).toList(),
                                                app,
                                              );
                                              if (userIndex != -1) {
                                                allUsers[userIndex].isAuthorizedRegistrar = true;
                                                allUsers[userIndex].state = appState.isNotEmpty ? appState : allUsers[userIndex].state;
                                                await _pushUserAuthorizedRegistrar(allUsers[userIndex]);
                                              }
                                              await NgmyCivicRegistrarApplication.save(email, Map<String, dynamic>.from(app));
                                              await _persistCivicRegistrarApplications(config);
                                              await _syncRegistrarStateAfterConfigChange(config, allUsers);
                                              onDataChanged();
                                              onParentSetState?.call();
                                              setST(() {});
                                            },
                                            child: const Text('Approve'),
                                          ),
                                        ),
                                      ],
                                    ),
                                  ] else if (status == 'approved' && _reviewerCanActOnRegistrarApp(reviewer, app, config)) ...[
                                    const SizedBox(height: 8),
                                    SizedBox(
                                      width: double.infinity,
                                      child: OutlinedButton(
                                        style: OutlinedButton.styleFrom(foregroundColor: Colors.red),
                                        onPressed: () async {
                                          final revokedAt = DateTime.now().toUtc().toIso8601String();
                                          app['status'] = 'revoked';
                                          app['revokedAt'] = revokedAt;
                                          app['updatedAt'] = revokedAt;
                                          app['revokedBy'] = reviewer.email;
                                          config.civicRegistrarApplications = NgmyCivicRegistrarApplication.upsertInList(
                                            config.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)).toList(),
                                            app,
                                          );
                                          if (userIndex != -1) {
                                            allUsers[userIndex].isAuthorizedRegistrar = false;
                                            await _pushUserAuthorizedRegistrar(allUsers[userIndex]);
                                          }
                                          await NgmyCivicRegistrarApplication.save(email, Map<String, dynamic>.from(app));
                                          await _persistCivicRegistrarApplications(config);
                                          await _syncRegistrarStateAfterConfigChange(config, allUsers);
                                          onDataChanged();
                                          onParentSetState?.call();
                                          setST(() {});
                                          if (context.mounted) {
                                            ScaffoldMessenger.of(context).showSnackBar(
                                              const SnackBar(
                                                content: Text(
                                                  'Registrar access removed. All enrolled members and civic records are preserved.',
                                                ),
                                              ),
                                            );
                                          }
                                        },
                                        child: const Text('Revoke Registrar Access'),
                                      ),
                                    ),
                                  ] else if ((status == 'revoked' || status == 'rejected') && _reviewerCanActOnRegistrarApp(reviewer, app, config)) ...[
                                    const SizedBox(height: 8),
                                    Row(
                                      children: [
                                        Expanded(
                                          child: OutlinedButton(
                                            style: OutlinedButton.styleFrom(
                                              foregroundColor: Colors.green,
                                              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 10),
                                            ),
                                            onPressed: () async {
                                              final appState = (app['state'] ?? '').toString().trim();
                                              if (appState.isNotEmpty &&
                                                  !NgmyCivicRegistryStats.canApproveRegistrarForState(
                                                    state: appState,
                                                    applications: apps,
                                                    users: allUsers,
                                                  )) {
                                                ScaffoldMessenger.of(ctx).showSnackBar(
                                                  SnackBar(
                                                    content: Text(
                                                      '$appState already has $kNgmyMaxRegistrarsPerState authorized registrars. Revoke one first.',
                                                    ),
                                                  ),
                                                );
                                                return;
                                              }
                                              final restoredAt = DateTime.now().toUtc().toIso8601String();
                                              app['status'] = 'approved';
                                              app['reviewedAt'] = restoredAt;
                                              app['updatedAt'] = restoredAt;
                                              app['reviewedBy'] = reviewer.email;
                                              config.civicRegistrarApplications = NgmyCivicRegistrarApplication.upsertInList(
                                                config.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)).toList(),
                                                app,
                                              );
                                              if (userIndex != -1) {
                                                allUsers[userIndex].isAuthorizedRegistrar = true;
                                                allUsers[userIndex].state = appState.isNotEmpty ? appState : allUsers[userIndex].state;
                                                await _pushUserAuthorizedRegistrar(allUsers[userIndex]);
                                              }
                                              await NgmyCivicRegistrarApplication.save(email, Map<String, dynamic>.from(app));
                                              await _persistCivicRegistrarApplications(config);
                                              await _syncRegistrarStateAfterConfigChange(config, allUsers);
                                              onDataChanged();
                                              onParentSetState?.call();
                                              setST(() {});
                                              if (context.mounted) {
                                                ScaffoldMessenger.of(context).showSnackBar(
                                                  const SnackBar(content: Text('Registrar access restored.')),
                                                );
                                              }
                                            },
                                            child: const Text(
                                              'Restore Access',
                                              maxLines: 1,
                                              softWrap: false,
                                              overflow: TextOverflow.visible,
                                              style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700),
                                            ),
                                          ),
                                        ),
                                        const SizedBox(width: 8),
                                        Expanded(
                                          child: OutlinedButton(
                                            style: OutlinedButton.styleFrom(
                                              foregroundColor: Colors.red,
                                              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 10),
                                            ),
                                            onPressed: () async {
                                              final confirmed = await showDialog<bool>(
                                                context: ctx,
                                                builder: (dctx) => AlertDialog(
                                                  title: const Text('Delete application?'),
                                                  content: Text(
                                                    'This removes ${(app['fullName'] ?? app['username'] ?? email).toString()}\'s registrar application history entirely, letting them submit a brand new application.',
                                                  ),
                                                  actions: [
                                                    TextButton(onPressed: () => Navigator.pop(dctx, false), child: const Text('Cancel')),
                                                    TextButton(
                                                      onPressed: () => Navigator.pop(dctx, true),
                                                      child: const Text('Delete', style: TextStyle(color: Colors.red)),
                                                    ),
                                                  ],
                                                ),
                                              );
                                              if (confirmed != true) return;
                                              // Remove every record for this email from the FULL
                                              // config list (not just this one status entry) — the
                                              // applicant can have separate rows per status
                                              // transition (see upsertInList), and any leftover row
                                              // would keep _registrarApplicationStatusForEmail
                                              // reporting revoked/rejected and blocking reapplication.
                                              config.civicRegistrarApplications = config.civicRegistrarApplications
                                                  .where((a) => (a['userEmail'] ?? '').toString().toLowerCase().trim() != email)
                                                  .map((e) => Map<String, dynamic>.from(e))
                                                  .toList();
                                              if (userIndex != -1) {
                                                // Deleting the request also removes its registrar
                                                // grant; their regular civic membership remains.
                                                allUsers[userIndex].isAuthorizedRegistrar = false;
                                                await _pushUserAuthorizedRegistrar(allUsers[userIndex]);
                                              }
                                              await NgmyCivicRegistrarApplication.clear(email);
                                              await _persistCivicRegistrarApplications(config);
                                              await _syncRegistrarStateAfterConfigChange(config, allUsers);
                                              onDataChanged();
                                              onParentSetState?.call();
                                              setST(() {});
                                              if (context.mounted) {
                                                ScaffoldMessenger.of(context).showSnackBar(
                                                  const SnackBar(content: Text('Application deleted — they can reapply.')),
                                                );
                                              }
                                            },
                                            child: const Text(
                                              'Delete Application',
                                              maxLines: 1,
                                              softWrap: false,
                                              overflow: TextOverflow.visible,
                                              style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700),
                                            ),
                                          ),
                                        ),
                                      ],
                                    ),
                                  ],
                                ],
                              ),
                            );
                          },
                        ),
                ),
              ],
            ),
          ),
        );
      },
    ),
  );
}

NgmyLoanConfigBridge ngmyLoanConfigBridge(AppConfig config) => NgmyLoanConfigBridge(
      loanApplications: config.loanApplications,
      loanPhone: config.loanPhone,
      loanHowItWorks: config.loanHowItWorks,
      officialCashApp: config.officialCashApp,
      loanCompanyZelle: config.loanCompanyZelle.trim().isNotEmpty ? config.loanCompanyZelle : config.helpZelle,
