List<InvestmentPlan> _investmentPlansFromMaps(List<Map<String, dynamic>> maps) {
  final plans = maps.map((e) => InvestmentPlan.fromJson(e)).toList();
  for (final pl in plans) {
    pl.applyFixedRoi();
  }
  plans.sort((a, b) => a.price.compareTo(b.price));
  return plans;
}

List<Map<String, dynamic>> _investmentPlansToMaps(List<InvestmentPlan> plans) =>
    plans.map((e) => e.toJson()).toList();

void _applyBundledInvestmentPlansToConfig(AppConfig config) {
  config.investmentPlans = kNgmyInvestmentPlansMaps.map((e) => Map<String, dynamic>.from(e)).toList();
}

List<InvestmentPlan> _bundledInvestmentPlans() => _investmentPlansFromMaps(kNgmyInvestmentPlansMaps);

Future<List<Map<String, dynamic>>> _fetchRemoteInvestmentPlans() async {
  try {
    final cfg = await _fetchNgmyConfigRow(columns: 'investmentPlans');
    if (cfg == null) return [];
    final raw = cfg['investmentPlans'];
    if (raw is! List) return [];
    return raw.map((e) => Map<String, dynamic>.from(e as Map)).toList();
  } catch (e) {
    debugPrint('[investmentPlans] fetch error: $e');
    return [];
  }
}

class InvestmentPlan {
  static const double fixedRoi = 0.0286; // 2.86% daily ROI for all plans
  static const int workDays = 261;

  String name;
  double price;
  double roi;

  InvestmentPlan({required this.name, required this.price, double? roi})
      : roi = fixedRoi;

  double get dailyIncome => price * fixedRoi;
  double get totalReturn => dailyIncome * workDays;

  void applyFixedRoi() => roi = fixedRoi;

  Map<String, dynamic> toJson() => {'name': name, 'price': price, 'roi': fixedRoi};
  factory InvestmentPlan.fromJson(Map<String, dynamic> json) => InvestmentPlan(
        name: (json['name'] ?? '').toString(),
        price: (json['price'] ?? 0.0).toDouble(),
      );
}

class MediaPost {
  final String id;
  final String userEmail;
  final String username;
  final String videoUrl;
  final String contentType; // video | image
  final String caption;
  final DateTime timestamp;
  int likes;
  int shareCount;
  List<String> likedBy;
  List<String> savedBy;
  List<String> sharedBy;
  List<Map<String, dynamic>> comments;
  List<String> taggedUsers;
  double? mediaAspectRatio;
  String externalLink;
  int previewSeconds;
  double continuePrice;
  double watchReward;
  int watchRequiredSeconds;
  List<String> rewardedViewers;

  MediaPost({
    required this.id,
    required this.userEmail,
    required this.username,
    required this.videoUrl,
    required this.caption,
    required this.timestamp,
    this.contentType = 'video',
    this.likes = 0,
    this.shareCount = 0,
    this.likedBy = const <String>[],
    this.savedBy = const <String>[],
    this.sharedBy = const <String>[],
    this.comments = const <Map<String, dynamic>>[],
    this.taggedUsers = const <String>[],
    this.mediaAspectRatio,
    this.externalLink = '',
    this.previewSeconds = 0,
    this.continuePrice = 0,
    this.watchReward = 0,
    this.watchRequiredSeconds = 0,
    List<String>? rewardedViewers,
  }) : rewardedViewers = rewardedViewers ?? <String>[];

  NgmyMediaMonetization get monetization => NgmyMediaMonetization(
        externalLink: externalLink,
        previewSeconds: previewSeconds,
        continuePrice: continuePrice,
        watchReward: watchReward,
        watchRequiredSeconds: watchRequiredSeconds,
        rewardedViewers: rewardedViewers,
      );

  void applyMonetization(NgmyMediaMonetization m) {
    externalLink = m.externalLink;
    previewSeconds = m.previewSeconds;
    continuePrice = m.continuePrice;
    watchReward = m.watchReward;
    watchRequiredSeconds = m.watchRequiredSeconds;
    rewardedViewers = List<String>.from(m.rewardedViewers);
  }

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{
      'id': id,
      'userEmail': userEmail,
      'username': username,
      'videoUrl': videoUrl,
      'url': videoUrl,
      'contentType': contentType,
      'type': contentType,
      'caption': caption,
      'timestamp': timestamp.toUtc().toIso8601String(),
      'likes': likedBy.length,
      'shareCount': shareCount,
      'likedBy': likedBy,
      'savedBy': savedBy,
      'sharedBy': sharedBy,
      'comments': comments,
      'taggedUsers': taggedUsers,
      if (mediaAspectRatio != null) 'mediaAspectRatio': mediaAspectRatio,
    };
    monetization.applyTo(map);
    return map;
  }

  factory MediaPost.fromJson(Map<String, dynamic> json) {
    json = ngmyMediaJsonWithData(json);
    final likedBy = _jsonStringList(json['likedBy'] ?? json['liked_by']);
    final savedBy = _jsonStringList(json['savedBy'] ?? json['saved_by']);
    final sharedBy = _jsonStringList(json['sharedBy'] ?? json['shared_by']);
    final comments = _jsonMapList(json['comments'] ?? json['media_comments']);
    final taggedUsers = _jsonStringList(json['taggedUsers'] ?? json['tagged_users']);
    final mon = NgmyMediaMonetization.fromJson(json);
    return MediaPost(
      id: json['id'] ?? '',
      userEmail: json['userEmail'] ?? json['user_email'] ?? '',
      username: json['username'] ?? (json['data'] is Map ? (json['data'] as Map)['username'] : null) ?? 'User',
      videoUrl: json['videoUrl'] ?? json['video_url'] ?? json['url'] ?? '',
      contentType: (json['contentType'] ?? json['content_type'] ?? json['type'] ?? 'video').toString(),
      caption: json['caption'] ?? json['description'] ?? '',
      timestamp: DateTime.parse(json['timestamp'] ?? json['created_at'] ?? DateTime.now().toIso8601String()).toLocal(),
      likedBy: likedBy,
      savedBy: savedBy,
      sharedBy: sharedBy,
      comments: comments,
      taggedUsers: taggedUsers,
      likes: likedBy.isNotEmpty ? likedBy.length : (json['likes'] ?? 0),
      shareCount: (json['shareCount'] as num?)?.toInt() ?? 0,
      mediaAspectRatio: (json['mediaAspectRatio'] as num?)?.toDouble(),
      externalLink: mon.externalLink,
      previewSeconds: mon.previewSeconds,
      continuePrice: mon.continuePrice,
      watchReward: mon.watchReward,
      watchRequiredSeconds: mon.watchRequiredSeconds,
      rewardedViewers: List<String>.from(mon.rewardedViewers),
    );
  }
}

double _clampMediaAspectRatio(double ratio) => ratio.clamp(0.45, 2.35);

/// Display name for media posts — never show generic "User" when we can resolve the account.
String _mediaAuthorName(UserData user) {
  final full = user.fullName?.trim();
  if (full != null && full.isNotEmpty) return full;
  final un = user.username.trim();
  if (un.isNotEmpty && un != 'User') return un;
  final email = user.email.trim().toLowerCase();
  if (email.contains('@')) return email.split('@').first;
  return un.isNotEmpty ? un : 'Member';
}

String _mediaPostDisplayName(MediaPost post, List<UserData> allUsers) {
  final stored = post.username.trim();
  if (stored.isNotEmpty && stored != 'User') return stored;
  final email = post.userEmail.toLowerCase().trim();
  if (email.isNotEmpty) {
    final user = allUsers.firstWhere(
      (x) => x.email.toLowerCase().trim() == email,
      orElse: () => UserData(email: post.userEmail),
    );
    return _mediaAuthorName(user);
  }
  return stored.isNotEmpty ? stored : 'Member';
}

String _pickMediaUsername(String remote, String local) {
  bool good(String s) => s.trim().isNotEmpty && s.trim() != 'User';
  if (good(remote)) return remote.trim();
  if (good(local)) return local.trim();
  return remote.trim().isNotEmpty ? remote.trim() : local.trim();
}

double _mediaFrameHeightForWidth(double width, double aspectRatio, double maxScreenFraction) {
  final safeRatio = _clampMediaAspectRatio(aspectRatio);
  final maxH = width / safeRatio;
  return maxH;
}

Future<double?> _aspectRatioFromImageBytes(Uint8List bytes) async {
  try {
    final codec = await ui.instantiateImageCodec(bytes);
    final frame = await codec.getNextFrame();
    final w = frame.image.width;
    final h = frame.image.height;
    if (w <= 0 || h <= 0) return null;
    return _clampMediaAspectRatio(w / h);
  } catch (e) {
    debugPrint('[media] aspect ratio decode: $e');
    return null;
  }
}

String? _missingColumnFromPostgrestError(Object error) {
  final text = error.toString();
  final m = RegExp("Could not find the '([^']+)' column").firstMatch(text);
  return m?.group(1);
}

bool _isMissingTablePostgrestError(Object error, String table) {
  return error.toString().contains("Could not find the table 'public.$table'");
}

const _userMediaProfileCloudKeys = {
  'mediaFollowers',
  'mediaFollowing',
  'mediaBio',
  'mediaHighlights',
  'mediaStories',
  'readAnnouncementIds',
};

void _stripUserMediaProfileFieldsFromBulkRow(Map<String, dynamic> row) {
  for (final key in _userMediaProfileCloudKeys) {
    row.remove(key);
  }
}

Map<String, dynamic> _userRowForBulkSync(UserData u, {bool includeFreeTrial = false, bool includeBalance = false}) {
  final row = Map<String, dynamic>.from(u.toJson());
  _stripUserMediaProfileFieldsFromBulkRow(row);
  row['referralCode'] = ngmyReferralCodeForEmail(u.email);
  if (!includeFreeTrial) {
    row.remove('freeTrialActive');
    row.remove('freeTrialDailyAmount');
  }
  if (!includeBalance) {
    row.remove('accountBalance');
  }
  // Username is pushed only via _pushUserProfileBasicsToCloud (self-edit) or
  // _pushUserAdminAccountFieldsToCloud (admin) — never routine bulk sync, so
  // admin renames are not overwritten by another device's stale local copy.
  row.remove('username');
  // Admin-set identity fields — never wipe cloud via routine profile sync.
  row.remove('crownBadge');
  row.remove('status');
  row.remove('forceLogout');
  final photo = (row['profilePicturePath'] ?? '').toString().trim();
  if (photo.isEmpty || photo.startsWith('data:image')) {
    row.remove('profilePicturePath');
  }
  return row;
}

String _ngmyMergeAccountStatus(String local, String remote) {
  const rank = {'disabled': 4, 'suspended': 3, 'verified': 2, 'active': 1};
  final l = local.trim().toLowerCase();
  final r = remote.trim().toLowerCase();
  final lr = rank[l] ?? 1;
  final rr = rank[r] ?? 1;
  return lr >= rr ? l : r;
}

void _mergeCloudProfileIdentityFields(UserData local, UserData remote) {
  final remotePhoto = (remote.profilePicturePath ?? '').trim();
  if (_ngmyIsCloudProfilePhoto(remotePhoto)) {
    remote.profilePicturePath = remotePhoto;
  }

  final remoteCrown = remote.crownBadge.trim().toLowerCase();
  if (remoteCrown == 'king' || remoteCrown == 'queen') {
    remote.crownBadge = remoteCrown;
  }

  remote.status = _ngmyMergeAccountStatus(local.status, remote.status);

  final remoteUsername = remote.username.trim();
  if (remoteUsername.isNotEmpty) {
    remote.username = remoteUsername;
  }
}

Future<UserData?> _fetchCloudUserRow(String email) async {
  final key = ngmyNormalizeEmail(email);
  if (key.isEmpty || !await ngmyCanReachCloud()) return null;
  try {
    var row = await Supabase.instance.client
        .from('users')
        .select()
        .eq('email', key)
        .maybeSingle()
        .timeout(kNgmyCloudLoadTimeout);
    row ??= await Supabase.instance.client
        .from('users')
        .select()
        .ilike('email', key)
        .maybeSingle()
        .timeout(kNgmyCloudLoadTimeout);
    if (row == null) return null;
    return UserData.fromJson(Map<String, dynamic>.from(row));
  } catch (e) {
    debugPrint('[user] full row fetch: $e');
    try {
      final row = await ngmyFetchUserLoginRow(Supabase.instance.client, key);
      if (row == null) return null;
      return UserData.fromJson(row);
    } catch (e2) {
      debugPrint('[user] login row fetch: $e2');
      return null;
    }
  }
}

Future<bool> _pushUserBalanceToCloud(
  UserData u, {
  bool allowDecrease = false,
  List<AppTransaction>? ledgerTransactions,
}) async {
  if (!await ngmyCanReachCloud()) return false;
  final email = u.email.trim();
  if (email.isEmpty) return false;
  final local = u.accountBalance.clamp(0.0, double.infinity);
  try {
    // A caller with ledger history for this person already knows `local`
    // is authoritative (it's what ngmyResolveAccountBalance/
    // ngmyReconcileUserAccountBalance just computed from their own
    // AppTransaction rows — e.g. right after a bet was deducted or a win
    // credited). Checking cloud and adopting it whenever it happens to
    // still show the pre-bet/pre-payout number — because this push raced
    // ahead of that number actually landing in Supabase — silently
    // reverted the spend/credit and skipped writing the correct value.
    // Only fall back to "trust cloud when it's higher" when the caller
    // has no ledger to vouch for `local` at all.
    final hasLedgerHistory = ledgerTransactions != null &&
        ledgerTransactions.any((t) => ngmyNormalizeEmail(t.userEmail) == ngmyNormalizeEmail(email));
    if (!allowDecrease && !hasLedgerHistory) {
      final row = await Supabase.instance.client
          .from('users')
          .select('accountBalance')
          .eq('email', email)
          .maybeSingle()
          .timeout(kNgmyCloudLoadTimeout);
      if (row != null) {
        final cloud = (row['accountBalance'] ?? 0.0).toDouble();
        if (cloud > local + 0.01) {
          u.accountBalance = cloud;
          return true;
        }
      }
    }
    await Supabase.instance.client.from('users').upsert({
      'email': email,
      'accountBalance': local,
    }, onConflict: 'email').timeout(kNgmyCloudWriteTimeout);
    return true;
  } catch (e) {
    debugPrint('[user] balance upsert: $e');
    return false;
  }
}

