Future<bool> _upsertMediaRowSafe(Map<String, dynamic> row) async {
  if (!NgmyCloudPolicy.persistMediaPostsToCloud) return true;
  if (!await ngmyCanReachCloud()) return false;
  var working = ngmyMediaRowForCloud(row);
  final url = (working['videoUrl'] ?? '').toString();
  if (url.isEmpty) return false;
  if (url.startsWith('data:') && url.length > 120000) {
    debugPrint('[media] skipped upsert: inline media too large for database.');
    return false;
  }
  const protected = {'id', 'userEmail', 'videoUrl', 'url'};
  for (int pass = 0; pass < 2; pass++) {
    for (int i = 0; i < 12; i++) {
      try {
        await Supabase.instance.client.from('media').upsert(working).timeout(kNgmyCloudWriteTimeout);
        if (await _verifyMediaRowInCloud(working)) return true;
      } catch (e) {
        if (_isMissingTablePostgrestError(e, 'media')) {
          debugPrint('[media] table missing in Supabase.');
          return false;
        }
        final missing = _missingColumnFromPostgrestError(e);
        if (missing != null && missing.isNotEmpty) {
          if (protected.contains(missing)) {
            debugPrint('[media] required column missing in Supabase: $missing');
            return false;
          }
          working.remove(missing);
          if (working['data'] is Map) {
            (working['data'] as Map).remove(missing);
          }
          continue;
        }
        debugPrint('[media] upsert error: $e');
        break;
      }
    }
    if (pass == 0) {
      working = ngmyMediaRowMinimalForCloud(row);
      debugPrint('[media] retrying upsert with minimal columns');
    }
  }
  return false;
}

