const _kNgmySettingsTermsKey = 'terms_and_conditions';
const _kNgmySettingsPrivacyKey = 'privacy_policy';
const _kNgmySettingsPlansKey = 'investment_plans';
const _kNgmySettingsPopupsKey = 'ngmy_popups';
const _kNgmySettingsChatClosedKey = 'ngmy_chat_closed';
const _kStoreSystemTermsId = 'ngmy:system:terms';
const _kStoreSystemPrivacyId = 'ngmy:system:privacy';
const _kStoreSystemPlansId = 'ngmy:system:investment_plans';

Object? _ngmyLastSupabasePersistError;

void _rememberSupabasePersistError(Object? error) {
  if (error != null) _ngmyLastSupabasePersistError = error;
}

Future<bool> _upsertConfigAdminLegalAndPlans({
  String? terms,
  String? privacy,
  List<Map<String, dynamic>>? plans,
}) async {
  final row = <String, dynamic>{'id': kNgmyConfigRowId};
  if (terms != null) row['termsAndConditions'] = terms;
  if (privacy != null) row['privacyPolicy'] = privacy;
  if (plans != null) row['investmentPlans'] = plans;
  if (row.length <= 1) return false;
  for (int i = 0; i < 8; i++) {
    try {
      await Supabase.instance.client.from('config').upsert(row, onConflict: 'id');
      return true;
    } catch (e) {
      _rememberSupabasePersistError(e);
      final missing = _missingColumnFromPostgrestError(e);
      if (missing != null && missing.isNotEmpty) {
        row.remove(missing);
        if (row.length <= 1) return false;
        continue;
      }
      debugPrint('[config] admin legal/plans upsert error: $e');
      return false;
    }
  }
  return false;
}

bool _isNgmySystemStoreListingId(String id) => id.startsWith('ngmy:system:');

DateTime? _parseSettingUpdatedAt(Object? raw) => DateTime.tryParse((raw ?? '').toString());

Future<bool> _upsertNgmySettingSafe(String key, Map<String, dynamic> value) async {
  if (!NgmyCloudPolicy.allowNgmySettingsKey(key)) return true;
  final row = <String, dynamic>{
    'key': key,
    'value': value,
    'updated_at': DateTime.now().toUtc().toIso8601String(),
  };
  for (int i = 0; i < 8; i++) {
    try {
      // Without a timeout, a stalled (not failed — a request that never
      // resolves at all) connection blocks this await forever. That's
      // fatal for a caller like the Deactivate Help Mode button, which
      // awaits this before closing its dialog: no exception ever fires,
      // so the retry/error handling below never runs either — the button
      // just looks permanently stuck instead of failing visibly.
      await Supabase.instance.client.from('ngmy_settings').upsert([row], onConflict: 'key').timeout(kNgmyCloudWriteTimeout);
      return true;
    } catch (e) {
      _rememberSupabasePersistError(e);
      if (_isMissingTablePostgrestError(e, 'ngmy_settings')) {
        debugPrint('[ngmy_settings] table missing — run supabase/ngmy_settings_table.sql');
        return false;
      }
      final missing = _missingColumnFromPostgrestError(e);
      if (missing != null && missing.isNotEmpty) {
        row.remove(missing);
        continue;
      }
      debugPrint('[ngmy_settings] upsert error: $e');
      return false;
    }
  }
  return false;
}

Future<Map<String, dynamic>?> _fetchNgmySettingSafe(String key) async {
  try {
    final row = await Supabase.instance.client.from('ngmy_settings').select().eq('key', key).maybeSingle().timeout(kNgmyCloudLoadTimeout);
    if (row == null) return null;
    final value = row['value'];
    if (value is Map) return Map<String, dynamic>.from(value);
    return null;
  } catch (e) {
    if (!_isMissingTablePostgrestError(e, 'ngmy_settings')) {
      debugPrint('[ngmy_settings] fetch error: $e');
    }
    return null;
  }
}

