/// Frosted pill frame — matches bottom nav / menu bar styling.
Widget _ngmyMenuPillFrame(BuildContext context, {required bool isDark, required Widget child}) {
  final fillColor = Theme.of(context).cardColor;
  return ngmyClipBackdrop(
    borderRadius: BorderRadius.circular(30),
    sigma: 16,
    child: Container(
      width: double.infinity,
      padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 16),
      decoration: BoxDecoration(
        color: fillColor,
        borderRadius: BorderRadius.circular(30),
        border: Border.all(
          color: isDark ? Colors.white.withValues(alpha: 0.12) : Colors.black.withValues(alpha: 0.06),
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: isDark ? 0.28 : 0.07),
            blurRadius: 15,
            offset: const Offset(0, 5),
          ),
        ],
      ),
      child: child,
    ),
  );
}

/// Animated glassy green frame — clock-in tag style, reusable on home stats.
Widget _ngmyGlassGreenShell({
  required Widget child,
  required double shimmer,
  BorderRadius borderRadius = const BorderRadius.all(Radius.circular(16)),
  EdgeInsets padding = const EdgeInsets.all(2),
  bool useBlur = true,
}) {
  Widget core(double s) {
    final inner = Container(
      decoration: BoxDecoration(
        borderRadius: borderRadius,
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            Color.lerp(const Color(0xFF6EE7B7), const Color(0xFF34D399), s)!.withValues(alpha: 0.72),
            const Color(0xFF059669).withValues(alpha: 0.58),
            const Color(0xFF047857).withValues(alpha: 0.68),
          ],
          stops: const [0, 0.55, 1],
        ),
        border: Border.all(color: Colors.white.withValues(alpha: 0.40 + s * 0.30), width: 1.2),
        boxShadow: [
          BoxShadow(color: const Color(0xFF22C55E).withValues(alpha: 0.26 + s * 0.20), blurRadius: 16, offset: const Offset(0, 5)),
          BoxShadow(color: Colors.white.withValues(alpha: 0.16), blurRadius: 4, offset: const Offset(-1, -1)),
          BoxShadow(color: const Color(0xFF064E3B).withValues(alpha: 0.22), blurRadius: 8, offset: const Offset(0, 3)),
        ],
      ),
      alignment: Alignment.center,
      child: Stack(
        clipBehavior: Clip.none,
        alignment: Alignment.center,
        children: [
          Positioned(
            left: 4,
            right: 4,
            top: 0,
            height: 14,
            child: DecoratedBox(
              decoration: BoxDecoration(
                borderRadius: BorderRadius.vertical(top: Radius.circular(borderRadius.topLeft.x - 2)),
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [Colors.white.withValues(alpha: 0.38 + s * 0.16), Colors.white.withValues(alpha: 0)],
                ),
              ),
            ),
          ),
          child,
        ],
      ),
    );
    if (!useBlur || ngmyPreferLightGraphics) return inner;
    return ngmyClipBackdrop(borderRadius: borderRadius, sigma: 12, child: inner);
  }

  return Container(
    padding: padding,
    decoration: BoxDecoration(
      borderRadius: borderRadius,
      gradient: SweepGradient(
        colors: [
          const Color(0xFF86EFAC).withValues(alpha: 0.06),
          const Color(0xFFBBF7D0).withValues(alpha: 0.50 + shimmer * 0.28),
          const Color(0xFF22C55E).withValues(alpha: 0.78),
          const Color(0xFF6EE7B7).withValues(alpha: 0.38 + shimmer * 0.18),
          const Color(0xFF86EFAC).withValues(alpha: 0.06),
        ],
        transform: GradientRotation(shimmer * math.pi * 2),
      ),
      boxShadow: [
        BoxShadow(color: const Color(0xFF34D399).withValues(alpha: 0.16 + shimmer * 0.14), blurRadius: 12, spreadRadius: 0.5),
      ],
    ),
    child: core(shimmer),
  );
}

class Announcement {
  final String id;
  final String title;
  final String message;
  final String? imageUrl;
  final String? videoUrl;
  final DateTime timestamp;
  final bool isAi;
  final String authorEmail;
  final String authorUsername;
  final String postType; // official | community

  Announcement({
    required this.id,
    required this.title,
    required this.message,
    this.imageUrl,
    this.videoUrl,
    required this.timestamp,
    this.isAi = false,
    this.authorEmail = '',
    this.authorUsername = 'NGMY',
    this.postType = 'official',
  });

  bool get isOfficial => postType == 'official';

  Map<String, dynamic> toJson() => {
    'id': id,
    'title': title,
    'message': message,
    'imageUrl': imageUrl,
    'videoUrl': videoUrl,
    'timestamp': timestamp.toUtc().toIso8601String(),
    'isAi': isAi,
    'authorEmail': authorEmail,
    'authorUsername': authorUsername,
    'postType': postType,
  };

  factory Announcement.fromJson(Map<String, dynamic> json) {
    return Announcement(
      id: json['id'] ?? '',
      title: json['title'] ?? '',
      message: json['message'] ?? '',
      imageUrl: json['imageUrl'],
      videoUrl: json['videoUrl'],
      timestamp: DateTime.parse(json['timestamp'] ?? DateTime.now().toIso8601String()).toLocal(),
      isAi: json['isAi'] ?? false,
      authorEmail: (json['authorEmail'] ?? json['author_email'] ?? '').toString(),
      authorUsername: (json['authorUsername'] ?? json['author_username'] ?? 'NGMY').toString(),
      postType: (json['postType'] ?? json['post_type'] ?? 'official').toString(),
    );
  }
}

String _geminiKeyFromMap(Map<String, dynamic> json) {
  for (final field in [
    'aiApiKey',
    'ai_api_key',
    'geminiApiKey',
    'gemini_api_key',
    'geminiapikey',
  ]) {
    final v = json[field]?.toString().trim();
    if (v != null && v.isNotEmpty) return v;
  }
  return '';
}

/// Supabase config row id (TEXT column in NGMY — must be '1', not integer 1).
const String kNgmyConfigRowId = '1';

Future<Map<String, dynamic>?> _fetchNgmyConfigRow({String columns = '*'}) async {
  final client = Supabase.instance.client;
  Future<Map<String, dynamic>?> trySelect(String cols) async {
    for (final id in [kNgmyConfigRowId, 1]) {
      try {
        final row = await client.from('config').select(cols).eq('id', id).maybeSingle();
        if (row != null) return Map<String, dynamic>.from(row);
      } catch (e) {
        debugPrint('[config] fetch id=$id cols=$cols: $e');
      }
    }
    try {
      final row = await client.from('config').select(cols).limit(1).maybeSingle();
      if (row != null) return Map<String, dynamic>.from(row);
    } catch (e) {
      debugPrint('[config] fetch any row cols=$cols: $e');
    }
    return null;
  }

  if (columns != '*') {
    final partial = await trySelect(columns);
    if (partial != null) return partial;
    return trySelect('*');
  }
  return trySelect('*');
}

dynamic _ngmyConfigRowIdValue(Map<String, dynamic>? row) {
  if (row == null) return kNgmyConfigRowId;
  final id = row['id'];
  if (id == null) return kNgmyConfigRowId;
  return id is String ? id : id.toString();
}

String? _missingColumnFromError(Object error) {
  final text = error.toString();
  final m = RegExp("Could not find the '([^']+)' column").firstMatch(text);
  return m?.group(1);
}

Future<String> _fetchRemoteGeminiApiKey() async {
  try {
    final row = await _fetchNgmyConfigRow(columns: NgmySupabaseColumns.geminiOnly);
    if (row == null) return '';
    return _geminiKeyFromMap(row);
  } catch (e) {
    debugPrint('[config] fetch gemini key error: $e');
    return '';
  }
}

Future<bool> _persistGeminiApiKeyToSupabase(String key) async {
  final k = key.trim();
  if (k.isEmpty) return false;
  final client = Supabase.instance.client;

  final existing = await _fetchNgmyConfigRow();
  final idValue = _ngmyConfigRowIdValue(existing);
  Map<String, dynamic> row = existing != null
      ? Map<String, dynamic>.from(existing)
      : <String, dynamic>{'id': idValue};
  row['id'] = idValue;
  row['geminiApiKey'] = k;
  row['gemini_api_key'] = k;
  row['aiApiKey'] = k;
  row['ai_api_key'] = k;

  var working = Map<String, dynamic>.from(row);
  for (var attempt = 0; attempt < 16; attempt++) {
    try {
      await client.from('config').upsert(working);
      final verify = await _fetchRemoteGeminiApiKey();
      if (verify.isNotEmpty) {
        debugPrint('[config] AI API key synced for all users.');
        return true;
      }
    } catch (e) {
      final missing = _missingColumnFromError(e);
      if (missing != null && missing.isNotEmpty && working.containsKey(missing)) {
        working = Map<String, dynamic>.from(working)..remove(missing);
        continue;
      }
      debugPrint('[config] AI key upsert failed: $e');
    }

    for (final field in ['geminiApiKey', 'gemini_api_key', 'aiApiKey', 'ai_api_key']) {
      if (!working.containsKey(field)) continue;
      try {
        await client.from('config').upsert({'id': idValue, field: k});
        if ((await _fetchRemoteGeminiApiKey()).isNotEmpty) {
          debugPrint('[config] AI API key saved via $field.');
          return true;
        }
      } catch (e) {
        debugPrint('[config] AI key save via $field failed: $e');
      }
      try {
        await client.from('config').update({field: k}).eq('id', idValue);
        if ((await _fetchRemoteGeminiApiKey()).isNotEmpty) {
          debugPrint('[config] AI API key updated via $field.');
          return true;
        }
      } catch (e) {
        debugPrint('[config] AI key update via $field failed: $e');
      }
    }
    break;
  }
  return false;
}

Future<Map<String, dynamic>> _configRowForSupabaseUpsert({
  required AppConfig config,
  required bool isAdmin,
}) async {
  await _mergeCivicRegistryPinsIntoConfig(config);
  final row = <String, dynamic>{'id': kNgmyConfigRowId, ...config.toJson()};
  final localKey = config.geminiApiKey.trim();
  final remoteKey = await _fetchRemoteGeminiApiKey();
  if (isAdmin && localKey.isNotEmpty) {
    row['geminiApiKey'] = localKey;
    row['gemini_api_key'] = localKey;
    row['aiApiKey'] = localKey;
    row['ai_api_key'] = localKey;
  } else if (remoteKey.isNotEmpty) {
    row['geminiApiKey'] = remoteKey;
    row['gemini_api_key'] = remoteKey;
    row['aiApiKey'] = remoteKey;
    row['ai_api_key'] = remoteKey;
    config.geminiApiKey = remoteKey;
  } else {
    row.remove('geminiApiKey');
    row.remove('gemini_api_key');
    row.remove('aiApiKey');
    row.remove('ai_api_key');
  }
  final remoteLegal = await _fetchRemoteLegalContent();
  final remoteTerms = (remoteLegal['terms'] ?? '').trim();
  final remotePrivacy = (remoteLegal['privacy'] ?? '').trim();
  row['gameTimeLimits'] = config.gameTimeLimits;
  row['diceSettings'] = config.diceSettings;
  row['gameInvites'] = config.gameInvites;
  row['civicRegistryPin'] = config.civicRegistryPin;
  row['civicRegistryPinsByState'] = config.civicRegistryPinsByState;
  if (isAdmin) {
    _mergeRegistrarApplicationsIntoConfig(config, await _fetchRemoteCivicRegistrarApplications());
    row['civicRegistrarApplications'] = config.civicRegistrarApplications;
  } else {
    row.remove('civicRegistrarApplications');
  }
  row['jobPosts'] = config.jobPosts;
  row['jobWorkerApplications'] = config.jobWorkerApplications;
  if (isAdmin) {
    row['termsAndConditions'] = config.termsAndConditions;
    row['privacyPolicy'] = config.privacyPolicy;
    row['investmentPlans'] = config.investmentPlans;
  } else {
    if (remoteTerms.isNotEmpty) {
      row['termsAndConditions'] = remoteTerms;
      config.termsAndConditions = remoteTerms;
    } else {
      row.remove('termsAndConditions');
    }
    if (remotePrivacy.isNotEmpty) {
      row['privacyPolicy'] = remotePrivacy;
      config.privacyPolicy = remotePrivacy;
    } else {
      row.remove('privacyPolicy');
    }
    final remotePlans = await _fetchRemoteInvestmentPlans();
    if (remotePlans.isNotEmpty) {
      row['investmentPlans'] = remotePlans;
      config.investmentPlans = remotePlans;
    } else {
      row.remove('investmentPlans');
    }
  }
  return row;
}

/// Persists News open/closed for all users (ngmy_settings + config column).
Future<bool> ngmyPersistNgmyChatClosed(AppConfig config, bool closed) async {
  config.ngmyChatClosed = closed;
  try {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('app_config', jsonEncode(config.toJson()));
  } catch (e) {
    debugPrint('[ngmyChatClosed] local save: $e');
  }
  if (!await ngmyCanReachCloud()) return true;
  var saved = await _upsertNgmySettingSafe(_kNgmySettingsChatClosedKey, {'closed': closed});
  try {
    final existing = await _fetchNgmyConfigRow(columns: 'id');
    final idValue = _ngmyConfigRowIdValue(existing);
    await Supabase.instance.client.from('config').update({'ngmyChatClosed': closed}).eq('id', idValue);
    saved = true;
  } catch (e) {
    final missing = _missingColumnFromError(e);
    if (missing != 'ngmyChatClosed') {
      try {
        final existing = await _fetchNgmyConfigRow(columns: 'id');
        final idValue = _ngmyConfigRowIdValue(existing);
        await Supabase.instance.client.from('config').upsert({'id': idValue, 'ngmyChatClosed': closed});
        saved = true;
      } catch (e2) {
        debugPrint('[ngmyChatClosed] config save: $e2');
      }
    }
  }
  return saved;
}

Future<bool?> ngmyFetchRemoteNgmyChatClosed() async {
  final settings = await _fetchNgmySettingSafe(_kNgmySettingsChatClosedKey);
  if (settings != null && settings.containsKey('closed')) {
    return settings['closed'] == true;
  }
  try {
    final row = await _fetchNgmyConfigRow(columns: 'ngmyChatClosed');
    if (row != null && row.containsKey('ngmyChatClosed')) {
      return row['ngmyChatClosed'] == true;
    }
  } catch (e) {
    debugPrint('[ngmyChatClosed] fetch: $e');
  }
  return null;
}

void _applyNgmyChatClosedFromRemote(AppConfig next, Map<String, dynamic> record, {required bool localClosed}) {
  if (record.containsKey('ngmyChatClosed')) {
    next.ngmyChatClosed = record['ngmyChatClosed'] == true;
  } else {
    // Remote row may omit the column — keep the last known local state.
    next.ngmyChatClosed = localClosed;
  }
}

