class ActiveInvestment {
  String name; double amount; double dailyROI; final DateTime purchaseDate;
  double totalEarned; int daysClockedIn;
  ActiveInvestment({required this.name, required this.amount, required this.dailyROI, required this.purchaseDate, this.totalEarned = 0.0, this.daysClockedIn = 0});
  Map<String, dynamic> toJson() => {'name': name, 'amount': amount, 'dailyROI': dailyROI, 'purchaseDate': purchaseDate.toUtc().toIso8601String(), 'totalEarned': totalEarned, 'daysClockedIn': daysClockedIn};
  factory ActiveInvestment.fromJson(Map<String, dynamic> json) {
    DateTime parseDate(dynamic v) {
      if (v == null || v == "null" || v.toString().isEmpty) return DateTime.now();
      try {
        final d = DateTime.parse(v.toString());
        return d.isUtc ? d.toLocal() : d;
      } catch (_) { return DateTime.now(); }
    }
    return ActiveInvestment(
      name: json['name'],
      amount: (json['amount'] ?? 0.0).toDouble(),
      dailyROI: (json['dailyROI'] ?? 0.0).toDouble(),
      purchaseDate: parseDate(json['purchaseDate']),
      totalEarned: (json['totalEarned'] ?? 0.0).toDouble(),
      daysClockedIn: json['daysClockedIn'] ?? 0
    );
  }
  double get dailyAmount => amount * dailyROI;
  int get daysLeft => 261 - daysClockedIn;
}

class UserData {
  String email; String phone; String username; double accountBalance; double totalProfit;
  bool isClockedIn; DateTime? clockInStartTime; bool isAdmin; ActiveInvestment? activeInvestment;
  String status; // active, suspended, verified, disabled
  bool forceLogout; int referralCount; int points;
  String? profilePicturePath;
  bool isAuthorizedRegistrar;
  /// Civic Registry King — approve registrar requests in their state; may change states there.
  bool isCivicRegistryKing;
  /// Civic Registry Admin — may serve any state; does not count toward per-state registrar cap.
  bool isCivicRegistryAdmin;
  int civicRegistryStateSwitchesUsed;
  String civicRegistryAnchorState;
  bool isApprovedWorker;
  bool isApprovedHelper;
  bool canSellOnStore;
  DateTime? lastClockInDate;
  DateTime? lastClockInEarningsDate;
  /// Amount earned today — stays on the Today tile after payout until midnight.
  double todayClockInEarned;
  String passwordHash;
  String state;
  int helps;
  int missed;
  bool isEnrolledInRegistry;
  String? fullName;
  String? dob;
  String? idType;
  String? registryId;
  String? homeAddress;
  String? city;
  String? room;
  String referredByCode;
  double clockInPenaltyPercent;
  String? pendingInvestmentName;
  double? pendingInvestmentAmount;
  double? pendingInvestmentRoi;
  String savedCashAppTag;
  String savedZelleInfo;
  String savedBitcoinAddress;
  String crownBadge;
  double freeFixCredit;
  bool freeTrialActive;
  double freeTrialDailyAmount;
  String mediaBio;
  List<String> mediaFollowers;
  List<String> mediaFollowing;
  List<Map<String, dynamic>> mediaHighlights;
  List<Map<String, dynamic>> mediaStories;
  List<String> readAnnouncementIds;
  List<String> openedContributionReceiptKeys;
  List<String> dismissedContributionReceiptKeys;
  /// Calendar month key e.g. 2026-06 — weekday check-in misses in this month.
  String clockInMissMonth;
  int clockInMissCount;
  List<String> clockInMissedDays;
  /// True when this row was created via the login/sign-up page (not civic-only manual enroll).
  bool isAppLoginAccount;

  UserData({this.email = '', this.phone = '', this.username = 'User', this.accountBalance = 0.0, this.totalProfit = 0.0, this.isClockedIn = false, this.clockInStartTime, this.isAdmin = false, this.activeInvestment, this.status = 'active', this.forceLogout = false, this.referralCount = 0, this.points = 0, this.profilePicturePath, this.isAuthorizedRegistrar = false, this.isCivicRegistryKing = false, this.isCivicRegistryAdmin = false, this.civicRegistryStateSwitchesUsed = 0, this.civicRegistryAnchorState = '', this.isApprovedWorker = false, this.isApprovedHelper = false, this.canSellOnStore = false, this.lastClockInDate, this.lastClockInEarningsDate, this.todayClockInEarned = 0.0, this.passwordHash = '', this.state = 'Georgia', this.helps = 0, this.missed = 0, this.isEnrolledInRegistry = false, this.fullName, this.dob, this.idType, this.registryId, this.homeAddress, this.city, this.room, this.referredByCode = '', this.clockInPenaltyPercent = 0.0, this.pendingInvestmentName, this.pendingInvestmentAmount, this.pendingInvestmentRoi, this.savedCashAppTag = '', this.savedZelleInfo = '', this.savedBitcoinAddress = '', this.crownBadge = '', this.freeFixCredit = 0.0, this.freeTrialActive = false, this.freeTrialDailyAmount = 0.0, this.mediaBio = '', this.isAppLoginAccount = false, List<String>? mediaFollowers, List<String>? mediaFollowing, List<Map<String, dynamic>>? mediaHighlights, List<Map<String, dynamic>>? mediaStories, List<String>? readAnnouncementIds,
    List<String>? openedContributionReceiptKeys,
    List<String>? dismissedContributionReceiptKeys,
    this.clockInMissMonth = '',
    this.clockInMissCount = 0,
    List<String>? clockInMissedDays}) : mediaFollowers = mediaFollowers ?? <String>[], mediaFollowing = mediaFollowing ?? <String>[], mediaHighlights = mediaHighlights ?? <Map<String, dynamic>>[], mediaStories = mediaStories ?? <Map<String, dynamic>>[], readAnnouncementIds = readAnnouncementIds ?? <String>[], openedContributionReceiptKeys = openedContributionReceiptKeys ?? <String>[], dismissedContributionReceiptKeys = dismissedContributionReceiptKeys ?? <String>[], clockInMissedDays = clockInMissedDays ?? <String>[];
  bool get isOnFreeTrial => freeTrialActive && freeTrialDailyAmount > 0;
  double get totalInvestmentAmount {
    if (activeInvestment == null) return 0.0;
    if (activeInvestment!.daysLeft <= 0) return 0.0;
    return activeInvestment!.amount;
  }
  bool get alreadyClockedInToday {
    final now = DateTime.now();
    if (_ngmySameCalendarDay(lastClockInEarningsDate, now)) return true;
    if (_ngmySameCalendarDay(lastClockInDate, now) && !isClockedIn) return true;
    return false;
  }
  double get currentTodayEarnings {
    if (!isClockedIn || clockInStartTime == null) return 0.0;
    final goal = todayDailyGoal;
    if (goal <= 0) return 0.0;
    final progress = isOnFreeTrial
        ? _ngmyClockInProgressOneMinute(clockInStartTime)
        : _ngmyClockInProgressToNoon(clockInStartTime);
    final earnings = goal * progress;
    return earnings > goal ? goal : earnings;
  }

  /// Balance sheet invested/pending amount for admin user detail.
  double get adminDisplayInvestedAmount {
    if (activeInvestment != null && activeInvestment!.daysLeft > 0) {
      return activeInvestment!.amount;
    }
    final pending = pendingInvestmentAmount ?? 0;
    if (pending > 0) return pending;
    return 0.0;
  }

  String get adminDisplayInvestedLabel {
    if (activeInvestment != null && activeInvestment!.daysLeft > 0) return 'Invested';
    if ((pendingInvestmentAmount ?? 0) > 0) return 'Pending invest.';
    return 'Invested';
  }

  /// Today tile: live earnings while clocked in; after deposit keeps today's total until midnight.
  double get displayedTodayEarnings {
    final now = DateTime.now();
    if (isClockedIn && clockInStartTime != null && _ngmySameCalendarDay(clockInStartTime!, now)) {
      return currentTodayEarnings;
    }
    if (todayClockInEarned > 0 && _ngmySameCalendarDay(lastClockInEarningsDate, now)) {
      return todayClockInEarned;
    }
    return 0.0;
  }

  /// Unpaid clock-in accrual only (for total profit while session is active).
  double get unpaidTodayEarnings =>
      isClockedIn && clockInStartTime != null ? currentTodayEarnings : 0.0;
  /// Full daily clock-in amount before any late penalty (e.g. \$5.72).
  double get fullDailyEarningsBeforePenalty {
    if (isOnFreeTrial) return freeTrialDailyAmount;
    if (activeInvestment == null) return 0.0;
    return activeInvestment!.dailyAmount;
  }

  /// Maximum the user can earn today after late clock-in penalty (15% or 20% off full daily).
  double get todayDailyGoal {
    final full = fullDailyEarningsBeforePenalty;
    if (full <= 0) return 0.0;
    return full * (1 - (clockInPenaltyPercent.clamp(0.0, 100.0) / 100));
  }
  Map<String, dynamic> toJson() => {'email': email, 'phone': phone, 'username': username, 'accountBalance': accountBalance, 'totalProfit': totalProfit, 'isClockedIn': isClockedIn, 'clockInStartTime': clockInStartTime?.toUtc().toIso8601String(), 'isAdmin': isAdmin, 'activeInvestment': activeInvestment?.toJson(), 'status': status, 'forceLogout': forceLogout, 'referralCount': referralCount, 'points': points, 'profilePicturePath': profilePicturePath, 'isAuthorizedRegistrar': isAuthorizedRegistrar, 'isCivicRegistryKing': isCivicRegistryKing, 'isCivicRegistryAdmin': isCivicRegistryAdmin, 'civicRegistryStateSwitchesUsed': civicRegistryStateSwitchesUsed, 'civicRegistryAnchorState': civicRegistryAnchorState, 'isApprovedWorker': isApprovedWorker, 'isApprovedHelper': isApprovedHelper, 'canSellOnStore': canSellOnStore, 'lastClockInDate': lastClockInDate?.toUtc().toIso8601String(), 'lastClockInEarningsDate': lastClockInEarningsDate?.toUtc().toIso8601String(), 'todayClockInEarned': todayClockInEarned, 'passwordHash': passwordHash, 'state': state, 'helps': helps, 'missed': missed, 'isEnrolledInRegistry': isEnrolledInRegistry, 'fullName': fullName, 'dob': dob, 'idType': idType, 'registryId': registryId, 'homeAddress': homeAddress, 'city': city, 'room': room, 'referredByCode': referredByCode, 'clockInPenaltyPercent': clockInPenaltyPercent, 'pendingInvestmentName': pendingInvestmentName, 'pendingInvestmentAmount': pendingInvestmentAmount, 'pendingInvestmentRoi': pendingInvestmentRoi, 'savedCashAppTag': savedCashAppTag, 'savedZelleInfo': savedZelleInfo, 'savedBitcoinAddress': savedBitcoinAddress, 'crownBadge': crownBadge, 'freeFixCredit': freeFixCredit, 'freeTrialActive': freeTrialActive, 'freeTrialDailyAmount': freeTrialDailyAmount, 'mediaBio': mediaBio, 'isAppLoginAccount': isAppLoginAccount, 'mediaFollowers': mediaFollowers, 'mediaFollowing': mediaFollowing, 'mediaHighlights': mediaHighlights, 'mediaStories': mediaStories, 'readAnnouncementIds': readAnnouncementIds, 'openedContributionReceiptKeys': openedContributionReceiptKeys, 'dismissedContributionReceiptKeys': dismissedContributionReceiptKeys, 'clockInMissMonth': clockInMissMonth, 'clockInMissCount': clockInMissCount, 'clockInMissedDays': clockInMissedDays};
  factory UserData.fromJson(Map<String, dynamic> json) {
    DateTime? parseDate(dynamic v) {
      if (v == null || v == "null" || v.toString().isEmpty) return null;
      try {
        final d = DateTime.parse(v.toString());
        return d.isUtc ? d.toLocal() : d;
      } catch (_) { return null; }
    }
    ActiveInvestment? parseActiveInvestment(dynamic raw) {
      if (raw == null) return null;
      try {
        if (raw is Map<String, dynamic>) return ActiveInvestment.fromJson(raw);
        if (raw is Map) return ActiveInvestment.fromJson(Map<String, dynamic>.from(raw));
        if (raw is String && raw.trim().isNotEmpty) {
          final decoded = jsonDecode(raw);
          if (decoded is Map<String, dynamic>) return ActiveInvestment.fromJson(decoded);
          if (decoded is Map) return ActiveInvestment.fromJson(Map<String, dynamic>.from(decoded));
        }
      } catch (_) {}
      return null;
    }
    return UserData(
      email: json['email'] ?? '',
      phone: json['phone'] ?? '',
      username: json['username'] ?? 'User',
      accountBalance: (json['accountBalance'] ?? 0.0).toDouble(),
      totalProfit: (json['totalProfit'] ?? 0.0).toDouble(),
      isClockedIn: json['isClockedIn'] ?? false,
      clockInStartTime: parseDate(json['clockInStartTime']),
      isAdmin: json['isAdmin'] ?? false,
      activeInvestment: parseActiveInvestment(json['activeInvestment']),
      status: json['status'] ?? 'active',
      forceLogout: json['forceLogout'] ?? false,
      referralCount: json['referralCount'] ?? 0,
      points: json['points'] ?? 0,
      profilePicturePath: json['profilePicturePath'],
      isAuthorizedRegistrar: json['isAuthorizedRegistrar'] ?? false,
      isCivicRegistryKing: json['isCivicRegistryKing'] == true,
      isCivicRegistryAdmin: json['isCivicRegistryAdmin'] ?? false,
      civicRegistryStateSwitchesUsed: (json['civicRegistryStateSwitchesUsed'] ?? 0) is int
          ? json['civicRegistryStateSwitchesUsed'] as int
          : int.tryParse('${json['civicRegistryStateSwitchesUsed']}') ?? 0,
      civicRegistryAnchorState: (json['civicRegistryAnchorState'] ?? '').toString(),
      isApprovedWorker: json['isApprovedWorker'] ?? false,
      isApprovedHelper: json['isApprovedHelper'] ?? false,
      canSellOnStore: json['canSellOnStore'] == true || json['can_sell_on_store'] == true,
      lastClockInDate: parseDate(json['lastClockInDate']),
      lastClockInEarningsDate: parseDate(json['lastClockInEarningsDate']),
      todayClockInEarned: (json['todayClockInEarned'] ?? 0.0).toDouble(),
      passwordHash: (json['passwordHash'] ?? json['password_hash'] ?? '').toString(),
      state: json['state'] ?? 'Georgia',
      helps: json['helps'] ?? 0,
      missed: json['missed'] ?? 0,
      isEnrolledInRegistry: json['isEnrolledInRegistry'] ?? false,
      fullName: json['fullName'],
      dob: json['dob'],
      idType: json['idType'],
      registryId: json['registryId'],
      homeAddress: json['homeAddress'],
      city: json['city'],
      room: json['room'],
      referredByCode: (json['referredByCode'] ?? '').toString(),
      clockInPenaltyPercent: (json['clockInPenaltyPercent'] ?? 0.0).toDouble(),
      pendingInvestmentName: json['pendingInvestmentName'] as String?,
      pendingInvestmentAmount: json['pendingInvestmentAmount'] == null ? null : (json['pendingInvestmentAmount'] as num).toDouble(),
      pendingInvestmentRoi: json['pendingInvestmentRoi'] == null ? null : (json['pendingInvestmentRoi'] as num).toDouble(),
      savedCashAppTag: (json['savedCashAppTag'] ?? json['saved_cash_app_tag'] ?? '').toString(),
      savedZelleInfo: (json['savedZelleInfo'] ?? '').toString(),
      savedBitcoinAddress: (json['savedBitcoinAddress'] ?? json['saved_bitcoin_address'] ?? '').toString(),
      crownBadge: (json['crownBadge'] ?? '').toString(),
      freeFixCredit: (json['freeFixCredit'] ?? 0.0).toDouble(),
      freeTrialActive: json['freeTrialActive'] == true,
      freeTrialDailyAmount: (json['freeTrialDailyAmount'] ?? 0.0).toDouble(),
      mediaBio: (json['mediaBio'] ?? '').toString(),
      isAppLoginAccount: json['isAppLoginAccount'] == true || json['is_app_login_account'] == true,
      mediaFollowers: _jsonStringList(json['mediaFollowers']),
      mediaFollowing: _jsonStringList(json['mediaFollowing']),
      mediaHighlights: _jsonMapList(json['mediaHighlights']),
      mediaStories: _jsonMapList(json['mediaStories']),
      readAnnouncementIds: _jsonStringList(json['readAnnouncementIds']),
      openedContributionReceiptKeys: _jsonStringList(json['openedContributionReceiptKeys']),
      dismissedContributionReceiptKeys: _jsonStringList(json['dismissedContributionReceiptKeys']),
      clockInMissMonth: (json['clockInMissMonth'] ?? '').toString(),
      clockInMissCount: (json['clockInMissCount'] ?? 0) is int
          ? json['clockInMissCount'] as int
          : int.tryParse('${json['clockInMissCount']}') ?? 0,
      clockInMissedDays: _jsonStringList(json['clockInMissedDays']),
    );
  }
}

List<String> _jsonStringList(dynamic raw) {
  if (raw == null) return <String>[];
  if (raw is String && raw.trim().isNotEmpty) {
    try {
      final decoded = jsonDecode(raw);
      if (decoded is List) raw = decoded;
    } catch (_) {}
  }
  if (raw is List) return raw.map((e) => e.toString()).toList();
  return <String>[];
}

List<Map<String, dynamic>> _jsonMapList(dynamic raw) {
  if (raw == null) return <Map<String, dynamic>>[];
  if (raw is String && raw.trim().isNotEmpty) {
    try {
      final decoded = jsonDecode(raw);
      if (decoded is List) raw = decoded;
    } catch (_) {}
  }
  if (raw is List) {
    return raw
        .map((e) => e is Map ? Map<String, dynamic>.from(e) : <String, dynamic>{})
        .where((m) => m.isNotEmpty)
        .toList();
  }
  return <Map<String, dynamic>>[];
}

