    return '${_currentUser?.email ?? ''}|${_allUsers.length}|${_allTransactions.length}|${_allMedia.length}|$annSig|${_config.ngmyChatClosed}';
  }

  bool _ngmySessionIsAdmin(UserData? user) {
    if (user == null) return false;
    final key = user.email.toLowerCase().trim();
    return user.isAdmin || ngmyEmailIsAdmin(key);
  }

  /// Admin dashboard + Civic Registry reviewers who must see new applications instantly.
  bool _ngmyReceivesAdminDashboardAlerts(UserData? user) {
    if (user == null) return false;
    if (_ngmySessionIsAdmin(user)) return true;
    return user.isCivicRegistryKing || user.isCivicRegistryAdmin;
  }

  List<UserData> _mergeAllUsersWithRemote(
    Map<String, UserData> localByEmail,
    List<UserData> remote,
  ) {
    final merged = Map<String, UserData>.from(localByEmail);
    for (final remoteUser in remote) {
      final key = remoteUser.email.toLowerCase().trim();
      if (key.isEmpty) continue;
      final local = merged[key];
      if (local == null) {
        merged[key] = remoteUser;
        if (ngmyEmailIsAdmin(key)) merged[key]!.isAdmin = true;
        continue;
      }
      _preserveLocalSessionState(local, remoteUser);
      _mergeUserMediaProfileFields(local, remoteUser);
      if (local.isAppLoginAccount) remoteUser.isAppLoginAccount = true;
      merged[key] = remoteUser;
      if (local.passwordHash.trim().isNotEmpty && merged[key]!.passwordHash.trim().isEmpty) {
        merged[key]!.passwordHash = local.passwordHash;
      }
      _preserveLocalSessionState(local, merged[key]!);
      if (ngmyEmailIsAdmin(key)) merged[key]!.isAdmin = true;
    }
    return ngmyApplyAdminAccountActionsToUsers(_config, merged.values.toList());
  }

  void _registerCloudUsersAsAppLogins(Iterable<UserData> users) {
    for (final u in users) {
      if (u.email.trim().isEmpty) continue;
      u.isAppLoginAccount = true;
      ngmyRegisterAppLoginUser(u.email);
    }
  }

  Future<List<UserData>> _fetchAllUsersFromCloudPage({
    required int from,
    required int to,
    String? columns,
  }) async {
    dynamic query = supabase.from('users').select(columns ?? '*').order('email');
    final chunk = await query.range(from, to).timeout(kNgmyCloudLoadTimeout);
    if (chunk == null) return const [];
    return (chunk as List)
        .map((e) => UserData.fromJson(Map<String, dynamic>.from(e as Map)))
        .toList();
  }

  Future<List<UserData>> _fetchAllUsersFromCloud() async {
    const columnSets = <String?>[
      null,
      NgmySupabaseColumns.adminUsersList,
      NgmySupabaseColumns.userLogin,
      'email,username,phone,passwordHash,accountBalance,status,isAdmin',
      'email,username,phone,passwordHash',
      'email',
    ];
    Object? lastError;
    for (final columns in columnSets) {
      final all = <UserData>[];
      try {
        var from = 0;
        const pageSize = 1000;
        while (from < 50000) {
          final to = from + pageSize - 1;
          final page = await _fetchAllUsersFromCloudPage(from: from, to: to, columns: columns);
          if (page.isEmpty) break;
          all.addAll(page);
          if (page.length < pageSize) break;
          from += pageSize;
        }
        if (all.isNotEmpty) {
          _registerCloudUsersAsAppLogins(all);
          return all;
        }
      } catch (e) {
        lastError = e;
        debugPrint('[admin] users fetch columns=${columns ?? '*'}: $e');
      }
    }
    if (lastError != null) {
      debugPrint('[admin] users fetch failed: $lastError');
    }
    return const [];
  }

  void _mergeUsersDiscoveredFromTransactions(List<UserData> users, List<AppTransaction> txns) {
    final keys = <String>{for (final u in users) ngmyNormalizeEmail(u.email)};
    for (final t in txns) {
      final key = ngmyNormalizeEmail(t.userEmail);
      if (key.isEmpty || keys.contains(key) || ngmyIsAdminDeletedUser(_config, key)) continue;
      final discovered = UserData(email: key, username: key.split('@').first, isAppLoginAccount: true);
      users.add(discovered);
      ngmyRegisterAppLoginUser(key);
      keys.add(key);
    }
  }

  Future<Set<String>> _fetchDistinctUserEmailsFromCloudTransactions() async {
    final emails = <String>{};
    var from = 0;
    const pageSize = 1000;
    while (from < 100000) {
      final to = from + pageSize - 1;
      final rows = await supabase
          .from('transactions')
          .select('userEmail')
          .order('timestamp', ascending: false)
          .range(from, to)
          .timeout(kNgmyCloudLoadTimeout);
      if (rows == null || (rows as List).isEmpty) break;
      for (final raw in rows) {
        final key = ngmyNormalizeEmail((raw['userEmail'] ?? '').toString());
        if (key.isNotEmpty) emails.add(key);
      }
      if (rows.length < pageSize) break;
      from += pageSize;
    }
    return emails;
  }

  Future<void> _discoverUsersFromCloudActivityIntoAllUsers() async {
    final keys = <String>{for (final u in _allUsers) ngmyNormalizeEmail(u.email)};
    final discovered = <String>[];

    try {
      final txEmails = await _fetchDistinctUserEmailsFromCloudTransactions();
      discovered.addAll(txEmails);
    } catch (e) {
      debugPrint('[admin] discover users from cloud tx: $e');
    }

    try {
      final mediaRows = await supabase
          .from('media')
          .select('userEmail')
          .limit(5000)
          .timeout(kNgmyCloudLoadTimeout);
      if (mediaRows != null) {
        for (final raw in mediaRows as List) {
          final key = ngmyNormalizeEmail((raw['userEmail'] ?? '').toString());
          if (key.isNotEmpty) discovered.add(key);
        }
      }
    } catch (e) {
      debugPrint('[admin] discover users from media: $e');
    }

    for (final key in discovered) {
      if (key.isEmpty || keys.contains(key) || ngmyIsAdminDeletedUser(_config, key)) continue;
      final user = UserData(email: key, username: key.split('@').first, isAppLoginAccount: true);
      _allUsers.add(user);
      ngmyRegisterAppLoginUser(key);
      keys.add(key);
      unawaited(_safeUpsertUserRow(_userSignupRowForCloud(user)));
    }
  }

  Future<List<AppTransaction>> _fetchAdminTransactionsFromCloud({int limit = 10000}) async {
    final transData = await supabase
        .from('transactions')
        .select()
        .order('timestamp', ascending: false)
        .limit(limit)
        .timeout(kNgmyCloudLoadTimeout);
    if (transData == null) return const [];
    return (transData as List).map((e) => AppTransaction.fromJson(e)).toList();
  }

  /// Pending deposits/withdrawals only — not capped by the general 10k history window.
  Future<List<AppTransaction>> _fetchAdminPendingWalletFromCloud({int limit = 500}) async {
    try {
      final rows = await supabase
          .from('transactions')
          .select()
          .eq('status', TransactionStatus.pending.index)
          .inFilter('type', [TransactionType.deposit.index, TransactionType.withdrawal.index])
          .order('timestamp', ascending: false)
          .limit(limit)
          .timeout(kNgmyCloudLoadTimeout);
      if (rows == null) return const [];
      return (rows as List)
          .map((e) => AppTransaction.fromJson(Map<String, dynamic>.from(e as Map)))
          .where((t) => t.status == TransactionStatus.pending && ngmyIsWalletDepositOrWithdraw(t))
          .toList();
    } catch (e) {
      debugPrint('[admin] pending wallet fetch: $e');
      return const [];
    }
  }

  void _mergePendingWalletRequestsFromCloud(List<AppTransaction> pending) {
    if (pending.isEmpty) return;
    var added = 0;
    final newPendingForAdmin = <AppTransaction>[];
    for (final tx in pending) {
      if (tx.id.isEmpty || tx.status != TransactionStatus.pending) continue;
      final decided = _walletDecisionLedger[tx.id];
      if (decided != null && decided > 0 && decided <= 2) continue;
      final idx = _allTransactions.indexWhere((t) => t.id == tx.id);
      if (idx != -1) {
        final local = _allTransactions[idx];
        if (local.status != TransactionStatus.pending) continue;
        _allTransactions[idx] = _pickPreferredTransaction(local, tx);
        continue;
      }
      _allTransactions.add(tx);
      added++;
      newPendingForAdmin.add(tx);
    }
    if (newPendingForAdmin.isNotEmpty) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        for (final tx in newPendingForAdmin) {
          unawaited(_notifyAdminAboutPendingTransaction(tx));
        }
      });
    }
    if (added > 0) {
      NgmyAdminLiveRefresh.notify();
      unawaited(_persistLocalOnly());
    }
  }

  /// Flush debounced saves immediately — call on pause/close and after login.
  Future<void> _persistSessionImmediately() async {
    _saveDebounceTimer?.cancel();
    _heavySaveTimer?.cancel();
    _pendingHeavySave = false;
    await _persistLocalOnly();
  }

  Future<void> _clearLoggedOutFlag() async {
    _userExplicitlyLoggedOut = false;
    await ngmyWriteUserLoggedOutFlag(false);
  }

  Future<void> _performForceLogoutFromCloud(String email) async {
    _userExplicitlyLoggedOut = true;
    _resetWalletLedgerSyncState();
    _pauseBackgroundSync(disableRealtimeLoop: true);
    await ngmyWriteUserLoggedOutFlag(true);
    try {
      final p = await SharedPreferences.getInstance();
      await p.remove('current_user');
      await p.remove('ngmy_last_session_email');
    } catch (_) {}
    try {
      await supabase.auth.signOut();
    } catch (e) {
      debugPrint('[logout] force supabase signOut: $e');
    }
    if (!mounted) return;
    _cloudUserRowEnsuredForEmail = null;
    _cloudUserRowResyncTimer?.cancel();
    setState(() => _currentUser = null);
  }

  Future<void> _performLogout() async {
    _userExplicitlyLoggedOut = true;
    _resetWalletLedgerSyncState();
    _pauseBackgroundSync(disableRealtimeLoop: true);
    await ngmyWriteUserLoggedOutFlag(true);
    try {
      final p = await SharedPreferences.getInstance();
      await p.remove('current_user');
      await p.remove('ngmy_last_session_email');
    } catch (_) {}
    try {
      await supabase.auth.signOut();
    } catch (e) {
      debugPrint('[logout] supabase signOut: $e');
    }
    if (!mounted) return;
    _cloudUserRowEnsuredForEmail = null;
    _cloudUserRowResyncTimer?.cancel();
    setState(() => _currentUser = null);
  }

  Future<void> _ensureCurrentUserRegisteredInCloud({bool force = false}) async {
    if (_currentUser == null) return;
    final key = ngmyNormalizeEmail(_currentUser!.email);
    if (key.isEmpty) return;
    if (!force && _cloudUserRowEnsuredForEmail == key) return;
    _cloudUserRowEnsuredForEmail = key;
    await _pushSignupUserToCloudReliable(_currentUser!, includeFreeTrial: true);
  }

  /// Restores paid Stripe features from Supabase for whoever is signed in, so
  /// buying on one device unlocks the feature everywhere that account logs in.
  Future<void> _syncStripeAccessForCurrentUser({bool force = false}) async {
    final email = ngmyNormalizeEmail(_currentUser?.email ?? '');
    if (email.isEmpty) return;
    if (!force && _stripeAccessSyncedForEmail == email) return;
    _stripeAccessSyncedForEmail = email;
    await NgmyStripePayments.syncAllAccessFromCloud(email);
  }

  void _startCloudUserRowResyncLoop() {
    _cloudUserRowResyncTimer?.cancel();
    if (_currentUser == null) return;
    unawaited(_ensureCurrentUserRegisteredInCloud(force: true));
    unawaited(_syncStripeAccessForCurrentUser(force: true));
    _cloudUserRowResyncTimer = Timer.periodic(const Duration(minutes: 5), (_) async {
      if (!mounted || _currentUser == null || _backgroundSyncPaused || _userExplicitlyLoggedOut) return;
      // Pull-merge before push — otherwise a device whose local copy missed a
      // realtime update (clock-in earnings, activeInvestment, totalProfit set by
      // another device on this same account) would blindly stomp the cloud row
      // with its own stale snapshot every 5 minutes, blanking those fields on
      // every other device.
      await _refreshCurrentUserFromCloud();
      if (!mounted || _currentUser == null || _backgroundSyncPaused || _userExplicitlyLoggedOut) return;
      unawaited(_pushSignupUserToCloudReliable(_currentUser!, includeFreeTrial: true));
      unawaited(_syncStripeAccessForCurrentUser(force: true));
    });
  }

  Future<void> _restoreSessionFromLocalCache({SharedPreferences? prefs}) async {
    if (_currentUser != null || _userExplicitlyLoggedOut) {
      ngmyClearStaleForceLogout(_currentUser);
      return;
    }
    final p = prefs ?? await SharedPreferences.getInstance();
    final loggedOutFlag = p.getBool(kNgmyUserLoggedOutKey) == true;
    final userJson = _ngmyPrefsJson(p, 'current_user');
    final lastEmail = (p.getString('ngmy_last_session_email') ?? '').toLowerCase().trim();
    // Sticky logged-out flag with a surviving session snapshot is inconsistent —
    // recover into the app instead of trapping on Auth forever.
    if (loggedOutFlag && userJson == null && lastEmail.isEmpty) {
      _userExplicitlyLoggedOut = true;
      return;
    }
    if (loggedOutFlag) {
      await ngmyWriteUserLoggedOutFlag(false, p);
      _userExplicitlyLoggedOut = false;
    }
    if (userJson != null) {
      try {
        final map = jsonDecode(userJson);
        if (map is Map<String, dynamic>) {
          final localUser = UserData.fromJson(map);
          ngmyClearStaleForceLogout(localUser);
          final index = _allUsers.indexWhere(
            (u) => u.email.toLowerCase().trim() == localUser.email.toLowerCase().trim(),
          );
          if (index != -1) {
            ngmyClearStaleForceLogout(_allUsers[index]);
            _currentUser = _allUsers[index];
          } else {
            _currentUser = localUser;
          }
          if (mounted) setState(() {});
          unawaited(_persistSessionImmediately());
          return;
        }
      } catch (_) {}
    }
    if (lastEmail.isEmpty) return;
    final index = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == lastEmail);
    if (index == -1) {
      _currentUser = UserData(email: lastEmail, username: lastEmail.split('@').first);
      if (mounted) setState(() {});
      unawaited(_persistSessionImmediately());
      return;
    }
    ngmyClearStaleForceLogout(_allUsers[index]);
    _currentUser = _allUsers[index];
    if (mounted) setState(() {});
    unawaited(_persistSessionImmediately());
  }

  Future<void> _tryRestoreSessionFromSupabaseAuth() async {
    if (_currentUser != null || _userExplicitlyLoggedOut) return;
    if (await ngmyReadUserLoggedOutFlag()) {
      _userExplicitlyLoggedOut = true;
      try {
        if (supabase.auth.currentSession != null) await supabase.auth.signOut();
      } catch (_) {}
      return;
    }
    try {
      final authUser = supabase.auth.currentUser;
      final email = authUser?.email?.toLowerCase().trim();
      if (email == null || email.isEmpty) return;
      final fullName = (authUser?.userMetadata?['full_name'] ?? authUser?.userMetadata?['name'] ?? '').toString().trim();
      await _signInOrCreateFromOAuth(email, fullName: fullName);
      await _persistSessionImmediately();
    } catch (e) {
      debugPrint('[session] supabase auth restore: $e');
    }
  }

  void _restartSyncLoopsForCurrentUser() {
    if (_currentUser == null) return;
    _realtimePaused = false;
    _backgroundSyncPaused = false;
    if (!_realtimeStarted) {
      unawaited(_startBackgroundServicesWhenReady());
      return;
    }
    _subscribeToRealtime();
    // Wallet / Growth Income polls only while those screens are open (see NgmyFeatureSyncSession).
    if (NgmyFeatureSyncSession.anyGrowthIncomeActive) {
      _startUserTransactionSync();
      _startAdminPendingTransactionPoll();
    }
    _startAdminOperationalRequestsPoll();
    _startAdminUsersPoll();
    _startCloudUserRowResyncLoop();
    _startCurrentUserPullLoop();
    unawaited(_ensureCurrentUserRegisteredInCloud(force: true));
    if (_ngmySessionIsAdmin(_currentUser) && NgmyFeatureSyncSession.growthIncomeAdminActive) {
      unawaited(_refreshAdminDashboardFromCloud());
      unawaited(_refreshPendingTransactionsFromCloud());
    }
  }

  /// Pull latest wallet requests for admin (never wipe local cache on empty cloud).
  /// [lightweight] skips heavy user fetch + bulk flush — use when opening admin or polling.
  Future<void> _refreshAdminCloudSnapshot({bool lightweight = false}) async {
    if (!_ngmySessionIsAdmin(_currentUser)) return;
    if (!await ngmyCanReachCloud()) return;
    final localUsersBeforeFetch = <String, UserData>{
      for (final u in _allUsers) u.email.toLowerCase().trim(): u,
    };
    try {
      await _refreshWalletDecisionLedger();
      _applyWalletDecisionLedgerToTransactions();

      if (!lightweight) {
        final remote = await _fetchAllUsersFromCloud();
        if (remote.isNotEmpty) {
          _allUsers = _mergeAllUsersWithRemote(localUsersBeforeFetch, remote);
          _reconcileAllUserBalances();
          unawaited(ngmyRegisterReferralCodesForUsers(remote));
        } else {
          debugPrint('[admin] cloud users empty — keeping ${_allUsers.length} local users');
        }
      }

      final remoteTransactions = await _fetchAdminTransactionsFromCloud(
        limit: lightweight ? 800 : 10000,
      );
      if (remoteTransactions.isNotEmpty || !lightweight) {
        _allTransactions = _mergeTransactionsWithRemote(
          _allTransactions,
          remoteTransactions,
          walletDecisionLedger: _walletDecisionLedger,
        );
        _applyWalletDecisionLedgerToTransactions();
      }
      final pendingWallet = NgmyFeatureSyncSession.growthIncomeAdminActive
          ? await _fetchAdminPendingWalletFromCloud()
          : const <AppTransaction>[];
      if (pendingWallet.isNotEmpty) {
        _mergePendingWalletRequestsFromCloud(pendingWallet);
      }
      _applyWalletDecisionLedgerToTransactions();
      _mergeUsersDiscoveredFromTransactions(_allUsers, _allTransactions);
      if (!lightweight) {
        await _discoverUsersFromCloudActivityIntoAllUsers();
      }
      _allUsers = ngmyApplyAdminAccountActionsToUsers(_config, _allUsers);
      ngmyHydrateAppLoginUserRegistry(_allUsers);
      _reconcileAllUserBalances(ledgerSettled: true);
      _applyStoreSellAccessEmailsToUsers(_config, _allUsers, currentUser: _currentUser);
      for (final email in kNgmyAdminEmails) {
        final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
        if (idx >= 0) _allUsers[idx].isAdmin = true;
      }
      if (_currentUser != null && _ngmySessionIsAdmin(_currentUser)) {
        _currentUser!.isAdmin = true;
      }
      await _persistLocalOnly();
      if (mounted) setState(() {});
      if (lightweight) {
        unawaited(_flushLocalWalletDecisionsToCloud());
      } else {
        await _flushLocalWalletDecisionsToCloud();
      }
    } catch (e) {
      debugPrint('[admin] cloud snapshot refresh: $e');
    }
  }

  Future<bool> _syncWalletApprovalInBackground(AppTransaction t, UserData? user) async {
    if (t.status == TransactionStatus.pending) return false;
    await _pushTransactionToCloudFast(t);
    var synced = await _pushTransactionDecisionToCloud(t, attempts: 3);
    if (!synced && _ngmySessionIsAdmin(_currentUser)) {
      synced = await _pushTransactionDecisionToCloud(t, attempts: 2);
    }
    if (user != null) {
      await _pushUserToCloudFast(user, includeFreeTrial: true);
      _markUserDirty(user.email);
    }
    _markTransactionDirty(t.id);
    await _persistLocalOnly();
    if (mounted) setState(() {});
    return synced;
  }

