  @override
  Future<void> _refreshGameCenterSettingsFromCloud() async {
    if (!mounted || !await ngmyCanReachCloud()) return;
    await ngmyApplyGameCenterSettingsBackup(
      apply: (limits, dice, invites) {
        if (!mounted) return;
        final nextLimits = _mergeGameTimeLimitsPreferCustom(_config.gameTimeLimits, limits);
        final nextDice = dice.isNotEmpty
            ? _mergeDiceSettingsPreferCustom(_config.diceSettings, dice)
            : _config.diceSettings;
        final nextInvites = invites.isNotEmpty
            ? mergeGameInvites(_config.gameInvites, invites)
            : _config.gameInvites;
        final limitsSig = jsonEncode(nextLimits);
        final oldLimitsSig = jsonEncode(_config.gameTimeLimits);
        final diceSig = jsonEncode(nextDice);
        final oldDiceSig = jsonEncode(_config.diceSettings);
        if (limitsSig == oldLimitsSig && diceSig == oldDiceSig) return;
        setState(() {
          _config.gameTimeLimits = nextLimits;
          _config.diceSettings = nextDice;
          _config.gameInvites = nextInvites;
        });
        unawaited(_persistLocalOnly());
      },
    );
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused ||
        state == AppLifecycleState.hidden ||
        state == AppLifecycleState.detached) {
      unawaited(_persistSessionImmediately());
      _pauseBackgroundSync();
    }
    if (state == AppLifecycleState.resumed) {
      // Do not force a viewport resettle on every resume — returning from the
      // image picker was making Menu/Bio feel like the app was refreshing/crashing.
      unawaited(() async {
        final paid = await NgmyStripePayments.processPaymentReturnFromUrl();
        if (paid) {
          await _syncStripeAccessForCurrentUser(force: true);
          NgmyStripePayments.forceWebViewportResettle();
        }
      }());
      unawaited(_restoreSessionOnAppVisible());
      unawaited(_probeOfflineAtLaunch());
      _resumeBackgroundSync();
      if (_currentUser != null) {
        _ngmyReconcileClockInSession(_currentUser!, _allTransactions);
      }
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        unawaited(_refreshGameCenterSettingsFromCloud());
        unawaited(_refreshSessionFromCloudOnResume());
        unawaited(_catchUpCloudDataAfterConnect());
      });
      if (_ngmySessionIsAdmin(_currentUser)) {
        if (NgmyFeatureSyncSession.growthIncomeAdminActive) {
          unawaited(_refreshPendingTransactionsFromCloud());
          unawaited(_archiveAndPurgeOldApprovedWalletRequests(online: true));
        }
        unawaited(_refreshAdminOperationalRequestsFromCloud());
        unawaited(_refreshAdminUsersFromCloud());
        unawaited(_refreshAdminCloudSnapshot(lightweight: true));
      }
      if (_allowConfigDiffNotifications) {
        unawaited(_notifyStoreMarketDayListings());
      }
    }
  }

  /// Transactions first, then user row — avoids balance flashing stale cloud amounts.
  Future<void> _refreshSessionFromCloudOnResume() async {
    if (NgmyFeatureSyncSession.growthIncomeUserActive) {
      await _refreshUserTransactionsFromCloud(force: true);
    }
    await _refreshCurrentUserFromCloud();
    if (!mounted) return;
    setState(() {
      _reconcileAllUserBalances(ledgerSettled: true);
    });
    if (_currentUser != null) {
      unawaited(NgmyGameNotifications.syncFromCloud(_currentUser!.email));
    }
    unawaited(_archiveAndPurgeOldApprovedWalletRequests(online: await ngmyCanReachCloud()));
    unawaited(_persistLocalOnly());
  }

  Future<void> _refreshCurrentUserFromCloud() async {
    if (_currentUser == null || !await ngmyCanReachCloud()) return;
    if (NgmyGameSession.suppressExternalNotifications) return;
    final now = DateTime.now();
    if (_lastCurrentUserCloudRefresh != null &&
        now.difference(_lastCurrentUserCloudRefresh!) < const Duration(seconds: 8)) {
      return;
    }
    _lastCurrentUserCloudRefresh = now;
    try {
      final email = _currentUser!.email.trim();
      if (email.isEmpty) return;
      await _maybeUploadLocalProfilePhotoToCloud(_currentUser!);
      final photoRow = await supabase
          .from('users')
          .select('profilePicturePath')
          .eq('email', email)
          .maybeSingle()
          .timeout(kNgmyCloudLoadTimeout);
      // Re-check any logged-in member with a registrar application so both
      // revokes and restores take effect while the Civic Registry is open.
      final localRegistrarStatus = _registrarApplicationStatusForEmail(_config, email);
      if (_currentUser!.isAuthorizedRegistrar || localRegistrarStatus != null) {
        final remoteApps = await _fetchRemoteCivicRegistrarApplications();
        final remoteConfig = AppConfig();
        remoteConfig.civicRegistrarApplications = remoteApps;
        final remoteRegistrarStatus = _registrarApplicationStatusForEmail(remoteConfig, email);
        if (mounted && remoteRegistrarStatus != localRegistrarStatus) {
          setState(() {
            _mergeRegistrarApplicationsIntoConfig(_config, remoteApps);
            _applyRegistrarGrantsFromConfig(_config, _allUsers, currentUser: _currentUser);
          });
          NgmyAdminLiveRefresh.notify();
          if (remoteRegistrarStatus == 'revoked' || remoteRegistrarStatus == 'rejected') {
            unawaited(_pushInAppNotification(
              title: 'Registrar access removed',
              body: 'Your Authorized Registrar access was revoked by an admin.',
              tag: 'registrar_revoked_$email',
              cooldown: const Duration(minutes: 10),
            ));
          }
        }
      }
      if (photoRow == null || !mounted) return;
      final cloudPhoto = (photoRow['profilePicturePath'] ?? '').toString().trim();
      if (!_ngmyIsCloudProfilePhoto(cloudPhoto)) return;
      setState(() {
        _currentUser!.profilePicturePath = cloudPhoto;
        final key = email.toLowerCase().trim();
        final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
        if (idx >= 0) _allUsers[idx].profilePicturePath = cloudPhoto;
      });
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
      await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
    } catch (e) {
      debugPrint('[user] profile refresh from cloud: $e');
    }
  }

  @override void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    if (kIsWeb) {
      ngmyUnregisterPageVisibleHandler(_restoreSessionOnAppVisible);
    }
    ngmyOnGameWinNotify = null;
    ngmyInAppNotify = null;
    ngmyOnStoreOrdersChanged = null;
    _pauseBackgroundSync(disableRealtimeLoop: true);
    try { _startupRebuildDebounce?.cancel(); } catch (_) {}
    try { _autoThemeTimer?.cancel(); } catch (_) {}
    try { _mediaDeliveryTimer?.cancel(); } catch (_) {}
    try { _inAppNoticeEntry?.remove(); } catch (_) {}
    try { _saveDebounceTimer?.cancel(); } catch (_) {}
    try { _heavySaveTimer?.cancel(); } catch (_) {}
    try { _dataChangedUiDebounce?.cancel(); } catch (_) {}
    NgmySupabaseSyncThrottle.reset();
    try { _legalPlansRefreshDebounce?.cancel(); } catch (_) {}
    try { _authSub?.cancel(); } catch (_) {}
    super.dispose();
  }

  final supabase = Supabase.instance.client;

  ThemeMode get _effectiveThemeMode => _ngmyResolveThemeMode(_themeMode);

  void _applySystemUiForMode(ThemeMode mode) {
    final isDarkMode = mode == ThemeMode.dark;
    final style = isDarkMode
        ? const SystemUiOverlayStyle(
            statusBarColor: Color(0xFF121212),
            statusBarIconBrightness: Brightness.light,
            statusBarBrightness: Brightness.dark,
            systemNavigationBarColor: Color(0xFF121212),
            systemNavigationBarIconBrightness: Brightness.light,
          )
        : const SystemUiOverlayStyle(
            // Keep light mode top area bright and never black.
            statusBarColor: Colors.white,
            statusBarIconBrightness: Brightness.dark,
            statusBarBrightness: Brightness.light,
            systemNavigationBarColor: Colors.white,
            systemNavigationBarIconBrightness: Brightness.dark,
          );
    SystemChrome.setSystemUIOverlayStyle(style);
    if (kIsWeb) {
      ngmyApplyWebStatusBarStyle(lightMode: !isDarkMode);
    }
  }

  Future<void> _setThemeMode(ThemeMode mode) async {
    if (!mounted) return;
    setState(() => _themeMode = mode);
    _applySystemUiForMode(_effectiveThemeMode);
    final p = await SharedPreferences.getInstance();
    await p.setString('theme_mode', mode.name);
    _scheduleAutoThemeTick();
  }

  String? _oauthRedirectTo() => ngmyOAuthRedirectUrl();

  Future<String?> _startDesktopOAuthSignIn(OAuthProvider provider) async {
    HttpServer? server;
    try {
      server = await HttpServer.bind(InternetAddress.loopbackIPv4, 53682);
      final redirectTo = 'http://127.0.0.1:53682/auth-callback';
      final oauthUrl = await supabase.auth.getOAuthSignInUrl(
        provider: provider,
        redirectTo: redirectTo,
      );
      final launched = await launchUrl(
        Uri.parse(oauthUrl.url),
        mode: LaunchMode.externalApplication,
      );
      if (!launched) {
        await server.close(force: true);
        return 'Could not open ${provider.name} login screen.';
      }

      final req = await server.first.timeout(const Duration(minutes: 2));
      final callbackUri = Uri.parse('$redirectTo?${req.uri.query}');
      final hasError = callbackUri.queryParameters['error'] != null;
      final errorDescription = callbackUri.queryParameters['error_description'];

      const html = '''
<!doctype html>
<html><head><meta charset="utf-8"><title>NGMY Login</title></head>
<body style="font-family:Arial,sans-serif;padding:24px;background:#0f172a;color:#e2e8f0;">
<h2>Login Completed</h2>
<p>You can close this browser tab and return to NGMY.</p>
</body></html>
''';
      req.response.headers.contentType = ContentType.html;
      req.response.write(html);
      await req.response.close();

      if (hasError) {
        await server.close(force: true);
        return '${provider.name.toUpperCase()} login failed: ${errorDescription ?? "OAuth callback error"}';
      }
      await supabase.auth.getSessionFromUrl(callbackUri);
      await server.close(force: true);
      return null;
    } on SocketException {
      await server?.close(force: true);
      return 'Desktop login callback port is busy. Close other apps using port 53682 and try again.';
    } on TimeoutException {
      await server?.close(force: true);
      return '${provider.name.toUpperCase()} login timed out. Please try again.';
    } catch (e) {
      await server?.close(force: true);
      return '${provider.name.toUpperCase()} login failed. Add this redirect URL in Supabase Auth settings: http://127.0.0.1:53682/auth-callback. Error: $e';
    }
  }

  Future<String?> _startOAuthSignIn(OAuthProvider provider, {String? emailHint}) async {
    await _clearLoggedOutFlag();
    if (!kIsWeb && (Platform.isWindows || Platform.isLinux || Platform.isMacOS)) {
      return _startDesktopOAuthSignIn(provider);
    }
    return ngmyStartOAuthSignIn(provider, emailHint: emailHint);
  }

  String _appConfigSig(AppConfig c) => jsonEncode(c.toJson());

  void _markUserDirty(String? email) {
    final key = email?.toLowerCase().trim() ?? '';
    if (key.isNotEmpty) _dirtyUserEmails.add(key);
  }

  void _markTransactionDirty(String? id) {
    final key = id?.trim() ?? '';
    if (key.isNotEmpty) _dirtyTransactionIds.add(key);
  }

  Future<void> _refreshWalletDecisionLedger() async {
    _walletDecisionLedger = await NgmyWalletDecisionLedger.loadMerged();
    _applyWalletDecisionLedgerToTransactions();
  }

  void _applyWalletDecisionLedgerToTransactions() {
    if (_walletDecisionLedger.isEmpty) return;
    for (final t in _allTransactions) {
      final decided = _walletDecisionLedger[t.id];
      if (decided == null || decided <= 0 || decided > 2) continue;
      final newStatus = TransactionStatus.values[decided];
      if (t.status == newStatus) continue;
      if (!ngmyIsWalletDepositOrWithdraw(t)) {
        t.status = newStatus;
        continue;
      }
      final previousStatus = t.status;
      t.status = newStatus;
      final userKey = t.userEmail.toLowerCase().trim();
      final userIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == userKey);
      if (userIdx < 0) continue;
      if (previousStatus == TransactionStatus.pending) {
        if (newStatus == TransactionStatus.rejected && t.type == TransactionType.withdrawal) {
          ngmyReleasePendingWithdrawalHold(_allUsers[userIdx], t, _withdrawalHoldTxnIds);
        } else {
          ngmySyncUserBalanceAfterWalletDecision(
            _allUsers[userIdx],
            _allTransactions,
            justDecided: t,
            previousStatus: previousStatus,
          );
        }
        if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == userKey) {
          _currentUser = _allUsers[userIdx];
        }
        unawaited(_pushUserBalanceToCloud(_allUsers[userIdx], ledgerTransactions: _allTransactions));
      }
    }
  }

  Future<bool> _pushTransactionToCloudReliable(AppTransaction t, {int attempts = 3}) async {
    if (t.status != TransactionStatus.pending) {
      return _pushTransactionDecisionToCloud(t, attempts: attempts);
    }
    for (var i = 0; i < attempts; i++) {
      if (!await ngmyCanReachCloud()) {
        await Future.delayed(Duration(milliseconds: 400 * (i + 1)));
        continue;
      }
      final row = await _transactionRowForCloudPrepared(t);
      final ok = await _safeUpsertTransactionRows([row]);
      if (ok) return true;
      await Future.delayed(Duration(milliseconds: 400 * (i + 1)));
    }
    return false;
  }

  Future<void> _flushLocalWalletDecisionsToCloud() async {
    if (!_ngmySessionIsAdmin(_currentUser)) return;
    await _refreshWalletDecisionLedger();
    _applyWalletDecisionLedgerToTransactions();
    if (!await ngmyCanReachCloud()) return;
    const walletTypes = {TransactionType.deposit, TransactionType.withdrawal};
    for (final t in _allTransactions) {
      if (!walletTypes.contains(t.type)) continue;
      if (t.status == TransactionStatus.pending) continue;
      if (t.id.isEmpty) continue;
      final ok = await _pushTransactionDecisionToCloud(t, attempts: 4);
      if (!ok) {
        _markTransactionDirty(t.id);
        debugPrint('[txn] wallet decision still not in cloud: ${t.id} (${t.status.name})');
      }
    }
  }

