  void _startAdminUsersPoll() {
    _adminUsersPoll?.cancel();
    if (!_ngmySessionIsAdmin(_currentUser)) return;
    unawaited(_refreshAdminUsersFromCloud());
    _adminUsersPoll = Timer.periodic(const Duration(seconds: 15), (_) {
      if (!mounted || _backgroundSyncPaused || !_ngmySessionIsAdmin(_currentUser)) return;
      unawaited(_refreshAdminUsersFromCloud());
    });
  }

  Future<void> _refreshAdminUsersFromCloud() async {
    if (!_ngmySessionIsAdmin(_currentUser)) return;
    if (!await ngmyCanReachCloud()) return;
    final localUsersBeforeFetch = <String, UserData>{
      for (final u in _allUsers) u.email.toLowerCase().trim(): u,
    };
    try {
      final remote = await _fetchAllUsersFromCloud();
      if (remote.isNotEmpty) {
        _allUsers = _mergeAllUsersWithRemote(localUsersBeforeFetch, remote);
      } else {
        _allUsers = ngmyApplyAdminAccountActionsToUsers(_config, localUsersBeforeFetch.values.toList());
      }
      await _discoverUsersFromCloudActivityIntoAllUsers();
      _mergeUsersDiscoveredFromTransactions(_allUsers, _allTransactions);
      _allUsers = ngmyApplyAdminAccountActionsToUsers(_config, _allUsers);
      ngmyHydrateAppLoginUserRegistry(_allUsers);
      _reconcileAllUserBalances();
      await _persistLocalOnly();
      if (mounted) setState(() {});
      NgmyAdminLiveRefresh.notify();
    } catch (e) {
      debugPrint('[admin] users poll: $e');
    }
  }

  void _startAdminPendingTransactionPoll() {
    _adminPendingTxnPoll?.cancel();
    if (!_ngmySessionIsAdmin(_currentUser)) return;
    if (!NgmyFeatureSyncSession.growthIncomeAdminActive) return;
    unawaited(_refreshPendingTransactionsFromCloud());
    _adminPendingTxnPoll = Timer.periodic(const Duration(seconds: 12), (_) {
      if (!mounted || _backgroundSyncPaused || !_ngmySessionIsAdmin(_currentUser)) return;
      if (!NgmyFeatureSyncSession.growthIncomeAdminActive) {
        _adminPendingTxnPoll?.cancel();
        return;
      }
      unawaited(_refreshPendingTransactionsFromCloud());
    });
  }

  void _startAdminOperationalRequestsPoll() {
    _adminOperationalRequestsPoll?.cancel();
    if (!_ngmyReceivesAdminDashboardAlerts(_currentUser)) return;
    unawaited(_refreshAdminOperationalRequestsFromCloud());
    _adminOperationalRequestsPoll = Timer.periodic(const Duration(seconds: 45), (_) {
      if (!mounted || _backgroundSyncPaused || !_ngmyReceivesAdminDashboardAlerts(_currentUser)) return;
      unawaited(_refreshAdminOperationalRequestsFromCloud());
    });
  }

  Future<void> _refreshAdminOperationalRequestsFromCloud() async {
    if (!_ngmyReceivesAdminDashboardAlerts(_currentUser)) return;
    if (!await ngmyCanReachCloud()) return;
    if (_shouldDeferRemoteConfigOverwrite()) return;
    try {
      final prev = AppConfig.fromJson(_config.toJson());
      await ngmyAdminRefreshManagementConfig(_config);
      if (!mounted) return;
      if (_appConfigSig(prev) == _appConfigSig(_config)) return;
      if (_allowConfigDiffNotifications) {
        _notifyAdminOnNewPendingRegistrarApps(prev, _config);
      }
      setState(() {});
      NgmyAdminLiveRefresh.notify();
      unawaited(_persistLocalOnly());
    } catch (e) {
      debugPrint('[admin] operational requests poll: $e');
    }
  }

  Future<void> _refreshPendingTransactionsFromCloud() async {
    if (!_ngmySessionIsAdmin(_currentUser)) return;
    if (!await ngmyCanReachCloud()) return;
    try {
      await _refreshWalletDecisionLedger();
      _applyWalletDecisionLedgerToTransactions();
      final pendingWallet = await _fetchAdminPendingWalletFromCloud();
      if (mounted) {
        setState(() => _mergePendingWalletRequestsFromCloud(pendingWallet));
      } else {
        _mergePendingWalletRequestsFromCloud(pendingWallet);
      }
      _applyWalletDecisionLedgerToTransactions();
    } catch (e) {
      debugPrint('[admin] pending txn poll: $e');
    }
  }

  /// [_config.storeOrders] may be an unmodifiable view from bootstrap/json — copy before mutating.
  bool _maintainConfigStoreOrders() {
    final orders = _mutableStoreOrdersCopy(_config.storeOrders);
    final changed = _maintainStoreOrders(orders);
    _config.storeOrders = orders;
    return changed;
  }

  /// Local disk only — use after targeted cloud upserts (approve/deny, fast push).
  Future<void> _persistLocalOnly() async {
    _maintainConfigStoreOrders();
    try {
      final prefs = await SharedPreferences.getInstance();
      _allUsers.removeWhere((u) => u.email.trim().isEmpty);
      if (_currentUser != null) {
        final email = _currentUser!.email.toLowerCase().trim();
        if (email.isNotEmpty) {
          await prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
          await prefs.setString('ngmy_last_session_email', email);
        }
      }
      await prefs.setString('all_transactions', jsonEncode(_allTransactions.map((e) => e.toJson()).toList()));
      await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
      await prefs.setString('investment_plans', jsonEncode(_globalPlans.map((e) => e.toJson()).toList()));
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
      await prefs.setString('all_media', jsonEncode(_allMedia.map((e) => e.toJson()).toList()));
      await prefs.setString('all_announcements', jsonEncode(_allAnnouncements.map((e) => e.toJson()).toList()));
      await _persistLocalSnapshot();
    } catch (e) {
      debugPrint('[ngmy] local persist: $e');
    }
  }

  bool _userNeedsAdminCloudSync(UserData u) {
    final email = u.email.toLowerCase().trim();
    if (email.isEmpty) return false;
    if (_dirtyUserEmails.contains(email)) return true;
    return _allTransactions.any(
      (t) => t.userEmail.toLowerCase().trim() == email && t.status == TransactionStatus.pending,
    );
  }

  List<Map<String, dynamic>> _transactionsForAdminCloudSync() {
    final cutoff = DateTime.now().subtract(const Duration(days: 2));
    final seen = <String>{};
    final rows = <Map<String, dynamic>>[];
    for (final t in _allTransactions) {
      if (t.id.isEmpty || !seen.add(t.id)) continue;
      final pending = t.status == TransactionStatus.pending;
      final recent = t.timestamp.isAfter(cutoff);
      final dirty = _dirtyTransactionIds.contains(t.id);
      if (pending || recent || dirty) {
        rows.add(Map<String, dynamic>.from(t.toJson()));
      }
    }
    return rows;
  }

  /// Admin sync — finalized wallet decisions first, then pending requests.
  Future<void> _syncAdminOperationalToCloud() async {
    if (_currentUser?.isAdmin != true) return;
    if (!await ngmyCanReachCloud()) return;
    _isSyncing = true;
    final syncedTxnIds = <String>{};
    try {
      await _persistLocalOnly();
      const walletTypes = {TransactionType.deposit, TransactionType.withdrawal};
      final finalized = _allTransactions
          .where((t) => walletTypes.contains(t.type) && t.status != TransactionStatus.pending)
          .toList();
      for (final t in finalized) {
        if (t.id.isEmpty) continue;
        final dirty = _dirtyTransactionIds.contains(t.id);
        final recent = t.timestamp.isAfter(DateTime.now().subtract(const Duration(days: 7)));
        if (!dirty && !recent) continue;
        if (await _pushTransactionDecisionToCloud(t)) {
          syncedTxnIds.add(t.id);
        }
      }
      final txRows = <Map<String, dynamic>>[];
      for (final e in _transactionsForAdminCloudSync()) {
        final t = AppTransaction.fromJson(e);
        txRows.add(await _transactionRowForCloudPrepared(t));
      }
      if (txRows.isNotEmpty) {
        final ok = await _safeUpsertTransactionRows(
          txRows.map((e) => Map<String, dynamic>.from(e)).toList(),
        );
        if (ok) {
          syncedTxnIds.addAll(txRows.map((e) => (e['id'] ?? '').toString()).where((e) => e.isNotEmpty));
        }
      }
      final pendingEmails = _allTransactions
          .where((t) => t.status == TransactionStatus.pending)
          .map((t) => t.userEmail.toLowerCase().trim())
          .where((e) => e.isNotEmpty)
          .toSet();
      final emails = <String>{..._dirtyUserEmails, ...pendingEmails};
      final usersToSync = emails.isEmpty
          ? _allUsers.where(_userNeedsAdminCloudSync).toList()
          : _allUsers.where((u) => emails.contains(u.email.toLowerCase().trim())).toList();
      if (usersToSync.isNotEmpty) {
        await _safeUpsertRows(
          'users',
          usersToSync.map((u) => _userRowForBulkSync(u, includeFreeTrial: true)).toList(),
          onConflict: 'email',
        );
      }
      await _persistOperationalConfigToCloud(_config);
      _dirtyUserEmails.clear();
      _dirtyTransactionIds.removeWhere(syncedTxnIds.contains);
      await ngmyPersistGameCenterConfigNow(_config);
    } catch (e) {
      debugPrint('[ngmy] admin operational sync: $e');
    } finally {
      Future.delayed(const Duration(milliseconds: 200), () => _isSyncing = false);
    }
  }

  Future<void> _onReferralLinked(String code) async {
    if (_currentUser == null) return;
    final normalized = ngmyNormalizeReferralCode(code);
    if (normalized.isEmpty) return;
    final key = _currentUser!.email.toLowerCase().trim();
    setState(() {
      _currentUser!.referredByCode = normalized;
      final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
      if (idx >= 0) {
        _allUsers[idx].referredByCode = normalized;
      } else {
        _allUsers.add(_currentUser!);
      }
    });
    _markUserDirty(_currentUser!.email);
    await _persistSessionImmediately();
    unawaited(_pushUserToCloudFast(_currentUser!));
  }

  void _onDataChanged({String? dirtyUserEmail, String? dirtyTransactionId}) {
    _markUserDirty(dirtyUserEmail ?? _currentUser?.email);
    _markTransactionDirty(dirtyTransactionId);
    _dataChangedUiDebounce?.cancel();
    _dataChangedUiDebounce = Timer(const Duration(milliseconds: 150), () {
    if (mounted) setState(() {});
    });
    final isAdmin = _ngmySessionIsAdmin(_currentUser);
    if (isAdmin) {
      unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: true));
      _scheduleAdminConfigPersist();
    } else {
      unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
    }
    _pendingHeavySave = true;
    _saveDebounceTimer?.cancel();
    _saveDebounceTimer = Timer(const Duration(seconds: 1), () {
      if (!mounted) return;
      unawaited(_persistLocalOnly());
      if (_currentUser?.isAdmin == true) {
        unawaited(_syncAdminOperationalToCloud());
      } else {
        unawaited(_saveData(heavy: false, fullCloud: false));
      }
    });
    _heavySaveTimer?.cancel();
    _heavySaveTimer = Timer(const Duration(minutes: 10), () {
      if (!mounted || !_pendingHeavySave) return;
      _pendingHeavySave = false;
      if (_currentUser?.isAdmin == true) {
        unawaited(_syncAdminOperationalToCloud());
      } else {
        unawaited(_saveData(heavy: true, fullCloud: false));
      }
    });
  }

