  Future<void> _notifyTransactionEvent(AppTransaction t, {bool statusChanged = false}) async {
    if (_ngmyIsClockInSessionStartTransaction(t)) return;
    if (ngmyIsGameSpendTransaction(t)) return;
    if (kNgmySuppressClockInPopups) {
      final sd = (t.sourceDetails ?? '').toLowerCase();
      if (sd.contains('clock-in')) return;
    }
    final currentEmail = _currentUser?.email.toLowerCase().trim();
    if (currentEmail == null || currentEmail.isEmpty) return;
    if (t.userEmail.toLowerCase().trim() != currentEmail) return;
    if (!_tryClaimTransactionNotification(t, statusChanged: statusChanged)) return;
    final isIncome = ngmyTransactionCountsAsIncome(t);
    await _pushUserPushAlert(
      title: _notificationTitleForTransaction(t, statusChanged: statusChanged),
      body: _notificationBodyForTransaction(t, statusChanged: statusChanged),
      tag: statusChanged ? 'txn_${t.id}_${t.status.name}' : 'txn_${t.id}',
      sound: isIncome ? NgmyPushSoundKind.incomeCash : NgmyPushSoundKind.spendDefault,
      incomeTransaction: isIncome ? t : null,
    );
  }

  void _scheduleAutoThemeTick() {
    _autoThemeTimer?.cancel();
    if (_themeMode != ThemeMode.system) return;

    final now = DateTime.now();
    final morning = DateTime(now.year, now.month, now.day, 9, 0);
    final evening = DateTime(now.year, now.month, now.day, 20, 0);
    DateTime next;
    if (now.isBefore(morning)) {
      next = morning;
    } else if (now.isBefore(evening)) {
      next = evening;
    } else {
      next = morning.add(const Duration(days: 1));
    }
    final delay = next.difference(now) + const Duration(seconds: 1);
    _autoThemeTimer = Timer(delay, () {
      if (!mounted) return;
      setState(() {});
      _scheduleAutoThemeTick();
    });
  }

  void _subscribeToAuthState() {
    _authSub = supabase.auth.onAuthStateChange.listen((data) {
      unawaited(_handleSupabaseAuthStateChange(data));
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      unawaited(_handleSupabaseAuthStateChange(null));
    });
  }

  Future<void> _handleSupabaseAuthStateChange(AuthState? data) async {
    if (_userExplicitlyLoggedOut || await ngmyReadUserLoggedOutFlag()) {
      _userExplicitlyLoggedOut = true;
      try {
        if (supabase.auth.currentSession != null) await supabase.auth.signOut();
      } catch (_) {}
      return;
    }
    final authUser = data?.session?.user ?? supabase.auth.currentUser;
    final email = authUser?.email?.toLowerCase().trim();
    if (email == null || email.isEmpty) return;
    final fullName = (authUser?.userMetadata?['full_name'] ?? authUser?.userMetadata?['name'] ?? '').toString().trim();
    await _signInOrCreateFromOAuth(email, fullName: fullName);
  }

  Future<void> _signInOrCreateFromOAuth(String email, {String fullName = ''}) async {
    final emailNorm = email.toLowerCase().trim();
    if (emailNorm.isEmpty) return;
    if (_userExplicitlyLoggedOut || await ngmyReadUserLoggedOutFlag()) {
      _userExplicitlyLoggedOut = true;
      try {
        if (supabase.auth.currentSession != null) await supabase.auth.signOut();
      } catch (_) {}
      return;
    }
    if (_currentUser?.email.toLowerCase().trim() == emailNorm) return;
    final admins = ['kbpabloqr@gmail.com', 'ngumoyaking@gmail.com', 'appbusiness321@gmail.com', 'appbusiness84@gmail.com'];
    var idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == emailNorm);
    if (!mounted) return;
    setState(() {
      if (idx == -1) {
        final user = UserData(
          email: emailNorm,
          username: fullName.isNotEmpty ? fullName : emailNorm.split('@').first,
          isAdmin: admins.contains(emailNorm),
          passwordHash: '',
          isAppLoginAccount: true,
        );
        _allUsers.add(user);
        _currentUser = user;
      } else {
        if (fullName.isNotEmpty) {
          _allUsers[idx].username = fullName;
        }
        _currentUser = _allUsers[idx];
      }
      ngmyMarkUserAsAppLoginAccount(_currentUser!);
      if (ngmyRestoreAdminDeletedUserOnLogin(_config, emailNorm)) {
        unawaited(ngmyAdminPersistManagementConfig(_config));
      }
    });
    NgmyIncomeSound.bindSession(emailNorm);
    unawaited(NgmyIncomeSound.unlockForWebUserGesture());
    if (_currentUser != null && _currentUser!.passwordHash.trim().isEmpty) {
      try {
        final cloud = await _fetchCloudUserRow(emailNorm);
        if (cloud != null && cloud.passwordHash.trim().isNotEmpty) {
          _currentUser!.passwordHash = cloud.passwordHash;
          final uIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == emailNorm);
          if (uIdx >= 0) _allUsers[uIdx].passwordHash = cloud.passwordHash;
        }
      } catch (e) {
        debugPrint('[oauth] preserve cloud password hash: $e');
      }
    }
    await _saveData();
    await _persistSessionImmediately();
    if (_currentUser != null) {
      await _applyPendingReferralLink(_currentUser!);
      unawaited(_pushSignupUserToCloudReliable(_currentUser!, includeFreeTrial: true));
    }
    _restartSyncLoopsForCurrentUser();
    unawaited(_refreshCurrentUserFromCloud());
    unawaited(_maybeUploadLocalProfilePhotoToCloud(_currentUser!));
    unawaited(_refreshUserTransactionsFromCloud(force: true));
  }

  void _subscribeToRealtime() {
    if (_realtimePaused || _currentUser == null || _userExplicitlyLoggedOut) {
      try {
        _appSyncChannel?.unsubscribe();
      } catch (_) {}
      _appSyncChannel = null;
      return;
    }
    try {
      _appSyncChannel?.unsubscribe();
      final sessionEmail = (_currentUser?.email ?? '').trim();
      if (sessionEmail.isEmpty) {
        _appSyncChannel = null;
        return;
      }
      if (!NgmyCloudPolicy.realtimeForRegularUsers && !_ngmySessionIsAdmin(_currentUser)) {
        _appSyncChannel = null;
        debugPrint('Realtime: disabled for regular users (local-first)');
        return;
      }
      if (!_ngmySessionIsAdmin(_currentUser)) {
        _appSyncChannel = null;
        return;
      }

      final channelName = 'ngmy-admin-scoped-${sessionEmail.toLowerCase().hashCode}';
      _appSyncChannel = supabase
          .channel(channelName)
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'config',
            callback: (payload) => _onConfigChange(payload),
          )
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'store_listings',
            callback: (payload) => _onStoreListingsChange(payload),
          )
          .subscribe();
      debugPrint('Realtime: admin civic + store + popups ($channelName)');
    } catch (e) {
      debugPrint('Realtime subscribe error: $e');
    }
  }

  void _onStoreListingsChange(PostgresChangePayload payload) {
    if (!_ngmySessionIsAdmin(_currentUser)) return;
    unawaited(_reloadStoreFromSupabase().then((_) {
      if (mounted) {
        setState(() {});
        NgmyAdminLiveRefresh.notify();
      }
    }));
  }

  void _onAnnouncementsChange(PostgresChangePayload payload) {
    try {
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        setState(() => _allAnnouncements.removeWhere((a) => a.id == id));
        NgmyAdminLiveRefresh.notify();
      } else {
        final ann = Announcement.fromJson(payload.newRecord);
        bool isNew = false;
        setState(() {
          final idx = _allAnnouncements.indexWhere((a) => a.id == ann.id);
          if (idx == -1) {
            _allAnnouncements.add(ann);
            isNew = true;
          } else {
            _allAnnouncements[idx] = ann;
          }
        });
        unawaited(_persistAnnouncementsLocally());
        if (isNew && !_seenRealtimeAnnouncementIds.contains(ann.id)) {
          _seenRealtimeAnnouncementIds.add(ann.id);
          unawaited(_pushInAppNotification(
            title: 'New announcement',
            body: ann.title.trim().isNotEmpty ? ann.title : ann.message,
            tag: 'announcement_${ann.id}',
          ));
        }
        NgmyAdminLiveRefresh.notify();
      }
    } catch (e) {
      debugPrint('Announcements realtime apply error: $e');
    }
  }

