    final me = user.email.toLowerCase().trim();
    if (me.isEmpty) return;
    final prevIds = prev.jobPosts
        .map((j) => (j['id'] ?? '').toString())
        .where((id) => id.isNotEmpty)
        .toSet();
    for (final raw in next.jobPosts) {
      final job = Map<String, dynamic>.from(raw);
      final id = (job['id'] ?? '').toString();
      if (id.isEmpty || prevIds.contains(id) || _seenJobPostIds.contains(id)) continue;
      if ((job['status'] ?? 'open').toString() != 'open') continue;
      final owner = (job['ownerEmail'] ?? '').toString().toLowerCase().trim();
      if (owner == me) continue;
      _seenJobPostIds.add(id);
      final title = (job['title'] ?? 'New job').toString().trim();
      unawaited(_pushInAppNotification(
        title: 'New job in marketplace',
        body: title.isEmpty ? 'A new job was posted. Open Job Marketplace to view.' : title,
        tag: 'job_new_$id',
      ));
    }
  }

  void _notifyBuyersOfNewStoreListing(Map<String, dynamic> listing) {
    final id = (listing['id'] ?? '').toString();
    if (id.isEmpty || _seenStoreListingNotifyIds.contains(id)) return;
    if (_isNgmySystemStoreListingId(id)) return;
    if ((listing['status'] ?? 'active').toString() != 'active') return;
    _seenStoreListingNotifyIds.add(id);
    final me = _currentUser?.email.toLowerCase().trim();
    final seller = (listing['sellerEmail'] ?? '').toString().toLowerCase().trim();
    if (me != null && me.isNotEmpty && me == seller) return;
    final title = (listing['title'] ?? 'New item').toString().trim();
    unawaited(_pushInAppNotification(
      title: 'New in NGMY Store',
      body: title.isEmpty ? 'A seller posted a new listing.' : title,
      tag: 'store_new_$id',
    ));
  }

  Future<void> _notifyStoreMarketDayListings() async {
    if (_currentUser == null) return;
    if (NgmyGameSession.suppressExternalNotifications) return;
    final me = _currentUser!.email.toLowerCase().trim();
    if (me.isEmpty) return;
    for (final listing in ngmyStoreListingsOnMarketToday(_config.storeListings)) {
      final id = (listing['id'] ?? '').toString();
      if (id.isEmpty) continue;
      final seller = (listing['sellerEmail'] ?? '').toString().toLowerCase().trim();
      if (seller == me) continue;
      if (await ngmyWasStoreMarketNotifiedToday(id)) continue;
      await ngmyMarkStoreMarketNotifiedToday(id);
      final title = (listing['title'] ?? 'Store item').toString().trim();
      final schedule = NgmyStoreListingExtras.scheduleLabel(listing);
      unawaited(_pushInAppNotification(
        title: 'On the market today',
        body: title.isEmpty ? 'An item you follow is available today ($schedule).' : '$title — $schedule',
        tag: 'store_market_day_$id',
        cooldown: const Duration(hours: 20),
      ));
    }
  }

  void _onConfigChange(PostgresChangePayload payload) {
    try {
      if (!_ngmySessionIsAdmin(_currentUser)) return;
      if (payload.eventType != PostgresChangeEvent.delete) {
        if (_shouldDeferRemoteConfigOverwrite()) return;
        final fullRecord = Map<String, dynamic>.from(payload.newRecord);
        final record = NgmyCloudPolicy.filterConfigFromRemote(fullRecord);
        if (record.isEmpty) return;
        final keepListings = List<Map<String, dynamic>>.from(_config.storeListings.map((e) => Map<String, dynamic>.from(e)));
        final keepInquiries = List<Map<String, dynamic>>.from(_config.storeInquiries.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpApps = List<Map<String, dynamic>>.from(_config.helpHelperApplications.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpReqs = List<Map<String, dynamic>>.from(_config.helpRequests.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpBiz = List<Map<String, dynamic>>.from(_config.helpBusinesses.map((e) => Map<String, dynamic>.from(e)));
        final keepOrders = List<Map<String, dynamic>>.from(_config.storeOrders.map((e) => Map<String, dynamic>.from(e)));
        final keepPlans = List<Map<String, dynamic>>.from(_config.investmentPlans.map((e) => Map<String, dynamic>.from(e)));
        final keepRegistrarApps = List<Map<String, dynamic>>.from(
          _config.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)),
        );
        final keepConfig = AppConfig.fromJson(_config.toJson());
        final next = AppConfig.fromJson({..._config.toJson(), ...record});
        _applyRemoteConfigMerge(next, record, keepConfig);
        if (next.storeOrders.isEmpty && keepOrders.isNotEmpty) next.storeOrders = keepOrders;
        else next.storeOrders = _mergeStoreOrdersLists(keepOrders, next.storeOrders);
        next.storeOrders = _mutableStoreOrdersCopy(next.storeOrders);
        _maintainStoreOrders(next.storeOrders);
        if (next.storeListings.isEmpty && keepListings.isNotEmpty) next.storeListings = keepListings;
        if (next.storeInquiries.isEmpty && keepInquiries.isNotEmpty) {
          next.storeInquiries = keepInquiries;
        } else if (keepInquiries.isNotEmpty || next.storeInquiries.isNotEmpty) {
          next.storeInquiries = _mergeStoreInquiriesLists(keepInquiries, next.storeInquiries);
        }
        if (next.helpHelperApplications.isEmpty && keepHelpApps.isNotEmpty) next.helpHelperApplications = keepHelpApps;
        if (next.helpRequests.isEmpty && keepHelpReqs.isNotEmpty) next.helpRequests = keepHelpReqs;
        if (next.helpBusinesses.isEmpty && keepHelpBiz.isNotEmpty) next.helpBusinesses = keepHelpBiz;
        if (next.civicRegistrarApplications.isEmpty && keepRegistrarApps.isNotEmpty) {
          next.civicRegistrarApplications = keepRegistrarApps;
        } else {
          next.civicRegistrarApplications = _mergeCivicRegistrarApplications(
            keepRegistrarApps,
            next.civicRegistrarApplications,
          );
        }
        final keepPopups = List<Map<String, dynamic>>.from(_config.ngmyPopups.map((e) => Map<String, dynamic>.from(e)));
        final keepVideoPopups = List<Map<String, dynamic>>.from(_config.ngmyVideoPopups.map((e) => Map<String, dynamic>.from(e)));
        final remotePopups = (record['ngmyPopups'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)).toList();
        final remoteVideoPopups = (record['ngmyVideoPopups'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)).toList();
        next.ngmyPopups = _mergeNgmyPopupsFromRemote(keepPopups, remotePopups, NgmyPopupDefaults.ensurePopups);
        next.ngmyVideoPopups = _mergeNgmyPopupsFromRemote(keepVideoPopups, remoteVideoPopups, NgmyPopupDefaults.ensureVideoPopups);
        unawaited(_finishRemoteConfigChangeApply(next));
      }
    } catch (e) {
      debugPrint('Config realtime apply error: $e');
    }
  }

  Future<void> _finishRemoteConfigChangeApply(AppConfig next) async {
    await ngmyHydrateCivicSelfEnrollmentFromAllBackups(next);
    if (!mounted) return;
    if (_appConfigSig(_config) != _appConfigSig(next)) {
      if (_allowConfigDiffNotifications) {
        _notifySellerOfNewStoreOrders(_config, next);
        _notifyPendingGameInvites(_config, next);
        _notifyApprovedWorkersOfNewJobs(_config, next);
        _notifyAdminOnNewPendingRegistrarApps(_config, next);
      }
      setState(() {
        _config = next;
        _applyStoreSellAccessEmailsToUsers(_config, _allUsers, currentUser: _currentUser);
        _applyRegistrarGrantsFromConfig(_config, _allUsers, currentUser: _currentUser);
      });
      NgmyAdminLiveRefresh.notify();
      SharedPreferences.getInstance().then((prefs) {
        prefs.setString('app_config', jsonEncode(_config.toJson()));
        prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
        prefs.setString('investment_plans', jsonEncode(_globalPlans.map((e) => e.toJson()).toList()));
        if (_currentUser != null) {
          prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
        }
      }).catchError((_) {});
      unawaited(_processMediaDeliveryQueue());
    }
    _scheduleLegalPlansRefreshFromCloud();
  }

  void _onNgmySettingsChange(PostgresChangePayload payload) {
    if (_isSyncing && _shouldDeferRemoteConfigOverwrite()) return;
    try {
      final key = (payload.newRecord['key'] ?? '').toString();
      if (key == 'management_operational_lists') {
        final value = payload.newRecord['value'];
        if (value is Map) {
          if (_shouldDeferRemoteConfigOverwrite()) return;
          final keep = AppConfig.fromJson(_config.toJson());
          _applyManagementOperationalListsPayload(_config, Map<String, dynamic>.from(value));
          _mergeOperationalManagementListsIntoConfig(_config, keep);
          if (_allowConfigDiffNotifications) {
            _notifyAdminOnNewPendingRegistrarApps(keep, _config);
          }
          setState(() {});
          NgmyAdminLiveRefresh.notify();
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
        }
        return;
      }
      if (key == _kNgmyDeletedMediaSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          _applyDeletedMediaIdsPayload(_tombstonedMediaIds, Map<String, dynamic>.from(value));
          if (!mounted) return;
          setState(() => _allMedia.removeWhere((m) => _tombstonedMediaIds.contains(m.id)));
          unawaited(_persistTombstonedMediaIds(_tombstonedMediaIds));
          unawaited(_persistAllMediaLocally());
        }
        return;
      }
      if (key == _kNgmySettingsTermsKey || key == _kNgmySettingsPrivacyKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          final content = (value['content'] ?? '').toString();
          if (content.isNotEmpty) {
            setState(() {
              if (key == _kNgmySettingsTermsKey) {
                _config.termsAndConditions = content;
              } else {
                _config.privacyPolicy = content;
              }
            });
            unawaited(_persistLocalOnly());
          }
        }
        return;
      }
      if (key == _kNgmySettingsPlansKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          final raw = value['plans'];
          if (raw is List) {
            final plans = raw.map((e) => Map<String, dynamic>.from(e as Map)).toList();
            _applyRemoteInvestmentPlansToApp(plans);
            setState(() {});
            unawaited(_persistLocalOnly());
          }
        }
        return;
      }
      if (key == _kNgmyStoreSellAccessSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          final raw = value['emails'];
          if (raw is List) {
            _config.storeSellAccessEmails = raw
                .map((e) => e.toString().toLowerCase().trim())
                .where((e) => e.isNotEmpty)
                .toSet()
                .toList()
              ..sort();
            _applyStoreSellAccessEmailsToUsers(_config, _allUsers, currentUser: _currentUser);
            setState(() {});
            unawaited(_persistLocalOnly());
          }
        }
        return;
      }
      if (key == _kNgmyFamilyTreePaymentSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          if (ngmyShouldDeferRemoteConfigOverwrite()) return;
          setState(() => _applyFamilyTreePaymentPayload(_config, Map<String, dynamic>.from(value)));
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
          NgmyAdminLiveRefresh.notify();
        }
        return;
      }
      if (key == _kNgmyInvoicePaymentSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          if (ngmyShouldDeferRemoteConfigOverwrite()) return;
          setState(() => _applyInvoicePaymentPayload(_config, Map<String, dynamic>.from(value)));
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
          NgmyAdminLiveRefresh.notify();
        }
        return;
      }
      if (key == _kNgmyWalletPaymentSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          setState(() => _applyWalletPaymentPayload(_config, Map<String, dynamic>.from(value)));
          unawaited(_persistWalletPaymentSettingsLocal(_config));
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
          NgmyAdminLiveRefresh.notify();
        }
        return;
      }
      if (key == _kNgmySettingsChatClosedKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          final closed = value['closed'] == true;
          if (_config.ngmyChatClosed != closed) {
            setState(() => _config.ngmyChatClosed = closed);
            SharedPreferences.getInstance().then((prefs) {
              prefs.setString('app_config', jsonEncode(_config.toJson()));
            }).catchError((_) {});
          }
        }
        return;
      }
      if (key == _kNgmyAppBrandingSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          if (ngmyShouldDeferRemoteConfigOverwrite()) return;
          setState(() => _applyAppBrandingPayload(_config, Map<String, dynamic>.from(value)));
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
          NgmyAdminLiveRefresh.notify();
        }
        return;
      }
      if (key == _kNgmyCivicSelfEnrollmentSettingsKey) {
        final value = payload.newRecord['value'];
        if (value is Map) {
          setState(() => NgmyCivicSelfEnrollment.applyPayload(_config, Map<String, dynamic>.from(value), force: true));
          unawaited(NgmyCivicSelfEnrollment.saveLocalBackup(_config));
          unawaited(ngmyFlushCriticalConfigLocalAndCloud(_config, cloud: false));
          NgmyAdminLiveRefresh.notify();
        }
        return;
      }
      if (key.isNotEmpty) {
        _scheduleLegalPlansRefreshFromCloud();
      }
    } catch (e) {
      debugPrint('[ngmy_settings] news closed realtime: $e');
    }
  }

  void _onStoreInquiryChange(PostgresChangePayload payload) {
    if (_isSyncing) return;
    try {
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        setState(() => _config.storeInquiries.removeWhere((m) => (m['id'] ?? '').toString() == id));
        return;
      }
      final inquiry = _storeInquiryFromRow(Map<String, dynamic>.from(payload.newRecord));
      final id = (inquiry['id'] ?? '').toString();
      if (id.isEmpty) return;
      setState(() {
        final idx = _config.storeInquiries.indexWhere((m) => (m['id'] ?? '').toString() == id);
        if (idx == -1) {
          _config.storeInquiries.add(inquiry);
        } else {
          final local = Map<String, dynamic>.from(_config.storeInquiries[idx]);
          final mergedReplies = _mergeInquiryReplyLists(_storeInquiryReplies(local), _storeInquiryReplies(inquiry));
          final pickLocal = _storeInquiryLastAt(local).compareTo(_storeInquiryLastAt(inquiry)) >= 0;
          final picked = Map<String, dynamic>.from(pickLocal ? local : inquiry);
          picked['replies'] = mergedReplies;
          picked['read'] = local['read'] == true || inquiry['read'] == true;
          picked['buyerRead'] = local['buyerRead'] == true || inquiry['buyerRead'] == true;
          _config.storeInquiries[idx] = picked;
        }
      });
      SharedPreferences.getInstance().then((prefs) {
        prefs.setString('app_config', jsonEncode(_config.toJson()));
      }).catchError((_) {});
    } catch (e) {
      debugPrint('Store inquiry realtime apply error: $e');
    }
  }

  void _onStoreListingChange(PostgresChangePayload payload) {
    if (_isSyncing) return;
    try {
      final recordId = (payload.newRecord['id'] ?? payload.oldRecord['id'] ?? '').toString();
      if (_isNgmySystemStoreListingId(recordId)) {
        _scheduleLegalPlansRefreshFromCloud();
        return;
      }
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        setState(() => _config.storeListings.removeWhere((l) => (l['id'] ?? '').toString() == id));
        return;
      }
      final listing = _normalizeStoreListing(_storeListingFromRow(Map<String, dynamic>.from(payload.newRecord)));
      final id = (listing['id'] ?? '').toString();
      if (id.isEmpty) return;
      final idx = _config.storeListings.indexWhere((l) => (l['id'] ?? '').toString() == id);
      final merged = idx == -1
          ? listing
          : _pickNewerListing(_config.storeListings[idx], listing);
      final oldSig = _storeListingsSignature(_config.storeListings);
      if (idx == -1) {
        _config.storeListings.add(merged);
        _notifyBuyersOfNewStoreListing(merged);
      } else if (_storeListingsSignature([_config.storeListings[idx]]) != _storeListingsSignature([merged])) {
        _config.storeListings[idx] = merged;
      }
      final newSig = _storeListingsSignature(_config.storeListings);
      if (newSig != oldSig && mounted) setState(() {});
    } catch (e) {
      debugPrint('Store listing realtime apply error: $e');
    }
  }

  void _onMediaChange(PostgresChangePayload payload) {
    try {
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? payload.newRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        if (!mounted) return;
        unawaited(_persistDeletedMediaIdAuthoritative(id, _tombstonedMediaIds));
        setState(() => _allMedia.removeWhere((m) => m.id == id));
        unawaited(_persistAllMediaLocally());
        NgmyAdminLiveRefresh.notify();
        return;
      }
      final incoming = MediaPost.fromJson(payload.newRecord);
      if (_tombstonedMediaIds.contains(incoming.id)) return;
      if (!mounted) return;
      setState(() {
        final idx = _allMedia.indexWhere((m) => m.id == incoming.id);
        if (idx == -1) {
          _allMedia.insert(0, incoming);
        } else {
          _allMedia[idx] = _combineMediaPosts(incoming, _allMedia[idx]);
        }
        _allMedia.sort((a, b) => b.timestamp.compareTo(a.timestamp));
      });
      unawaited(_persistAllMediaLocally());
      NgmyAdminLiveRefresh.notify();
    } catch (e) {
      debugPrint('Media realtime apply error: $e');
    }
  }

  void _onUsersChange(PostgresChangePayload payload) {
    try {
      // Profile row sync only — balance is NEVER read from the users table.
      if (payload.eventType == PostgresChangeEvent.delete) {
        final email = (payload.oldRecord['email'] ?? '').toString().toLowerCase().trim();
        if (email.isEmpty) return;
        setState(() => _allUsers.removeWhere((u) => u.email.toLowerCase().trim() == email));
        NgmyAdminLiveRefresh.notify();
        return;
      }
      final newRow = Map<String, dynamic>.from(payload.newRecord);
      final updatedUser = UserData.fromJson(newRow);
      final email = updatedUser.email.toLowerCase().trim();
      if (email.isEmpty) return;
      if (ngmyIsAdminDeletedUser(_config, email)) return;
      ngmyApplyAdminAccountStatusOverride(_config, updatedUser);
      ngmyApplyAdminCrownOverride(_config, updatedUser);
      ngmyRegisterAppLoginUser(email);
      final grant = _canSellOnStoreForEmail(_config, email);
      updatedUser.canSellOnStore = grant || updatedUser.canSellOnStore;
      setState(() {
        final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
        if (idx == -1) {
          updatedUser.accountBalance = ngmyResolveAccountBalance(
            updatedUser.email,
            updatedUser.accountBalance,
            _allTransactions,
          );
          _allUsers.add(updatedUser);
        } else {
          final local = _allUsers[idx];
          _preserveLocalSessionState(local, updatedUser);
          updatedUser.canSellOnStore = grant || updatedUser.canSellOnStore || local.canSellOnStore;
          _mergeUserMediaProfileFields(local, updatedUser);
          _ngmyReconcileClockInSession(updatedUser, _allTransactions);
          _allUsers[idx] = updatedUser;
        }
        if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == email) {
          if (updatedUser.forceLogout) {
            // Live admin kick only — ignore if we just remounted / restored.
            final shellAge = _sessionBecameLiveAt == null
                ? Duration.zero
                : DateTime.now().difference(_sessionBecameLiveAt!);
            updatedUser.forceLogout = false;
            final uIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
            if (uIdx >= 0) _allUsers[uIdx].forceLogout = false;
            unawaited(_pushUserToCloudFast(updatedUser));
            if (shellAge > const Duration(seconds: 4)) {
              unawaited(_performForceLogoutFromCloud(email));
            }
          } else {
            final localCurrent = _currentUser!;
            _preserveLocalSessionState(localCurrent, updatedUser);
            updatedUser.canSellOnStore = grant || updatedUser.canSellOnStore || localCurrent.canSellOnStore;
            _ngmyReconcileClockInSession(updatedUser, _allTransactions);
            final listIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
            if (listIdx >= 0) _allUsers[listIdx] = updatedUser;
            _currentUser = updatedUser;
            final remotePhoto = (updatedUser.profilePicturePath ?? '').trim();
            if (_ngmyIsCloudProfilePhoto(remotePhoto)) {
              _currentUser!.profilePicturePath = updatedUser.profilePicturePath;
            }
          }
        }
      });
      unawaited(NgmyAnnouncementReads.saveLocal(email, updatedUser.readAnnouncementIds.toSet()));
      SharedPreferences.getInstance().then((prefs) {
        prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
        if (_currentUser != null) {
          prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
        }
      }).catchError((_) {});
      NgmyAdminLiveRefresh.notify();
    } catch (e) {
      debugPrint('Users realtime apply error: $e');
    }
  }

  void _onTransactionsChange(PostgresChangePayload payload) {
    try {
      if (!_ngmySessionIsAdmin(_currentUser) && _currentUser != null) {
        if (payload.eventType != PostgresChangeEvent.delete) {
          final row = payload.newRecord;
          final type = row['type'];
          final status = row['status'];
          final isCommunityContribution = type == TransactionType.contribution.index &&
              status == TransactionStatus.approved.index;
          if (!isCommunityContribution) {
            final sessionKey = ngmyNormalizeEmail(_currentUser!.email);
            final txEmail = ngmyNormalizeEmail((row['userEmail'] ?? row['user_email'] ?? '').toString());
            if (txEmail.isNotEmpty && txEmail != sessionKey) return;
          }
        } else {
          final row = payload.oldRecord;
          final type = row['type'];
          final isCommunityContribution = type == TransactionType.contribution.index;
          if (!isCommunityContribution) {
            final sessionKey = ngmyNormalizeEmail(_currentUser!.email);
            final txEmail = ngmyNormalizeEmail((row['userEmail'] ?? row['user_email'] ?? '').toString());
            if (txEmail.isNotEmpty && txEmail != sessionKey) return;
          }
        }
      }
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        setState(() => _allTransactions.removeWhere((t) => t.id == id));
        NgmyAdminLiveRefresh.notify();
      } else {
        final incoming = AppTransaction.fromJson(payload.newRecord);
        AppTransaction? previous;
        late AppTransaction tx;
        setState(() {
          final idx = _allTransactions.indexWhere((t) => t.id == incoming.id);
          if (idx == -1) {
            _allTransactions.add(incoming);
            tx = incoming;
          } else {
            previous = _allTransactions[idx];
            tx = _pickPreferredTransaction(previous!, incoming);
            final decided = _walletDecisionLedger[tx.id];
            if (decided != null && decided > 0 && decided <= 2) {
              tx.status = TransactionStatus.values[decided];
            }
            _allTransactions[idx] = tx;
          }
        });
        final statusChanged = previous != null && previous!.status != tx.status;
        if (previous == null || statusChanged) {
          unawaited(_notifyTransactionEvent(tx, statusChanged: statusChanged));
        }
        final becameApproved = tx.status == TransactionStatus.approved &&
            (previous == null || previous!.status != TransactionStatus.approved);
        final ownDirtyTxn = _dirtyTransactionIds.contains(tx.id);
        final userKey = tx.userEmail.toLowerCase().trim();
        final userIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == userKey);
        if (userIdx >= 0 && ngmyIsWalletDepositOrWithdraw(tx)) {
          if (tx.type == TransactionType.withdrawal &&
              tx.status == TransactionStatus.rejected &&
              previous?.status == TransactionStatus.pending) {
            ngmyReleasePendingWithdrawalHold(_allUsers[userIdx], tx, _withdrawalHoldTxnIds);
          } else if (becameApproved && previous?.status == TransactionStatus.pending) {
            ngmySyncUserBalanceAfterWalletDecision(
              _allUsers[userIdx],
              _allTransactions,
              justDecided: tx,
              previousStatus: previous!.status,
            );
          }
          if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == userKey) {
            _currentUser = _allUsers[userIdx];
          }
        } else if (becameApproved && ngmyTransactionCountsAsIncome(tx)) {
          ngmyDeliverTransactionAlerts(tx);
        }
        if (userIdx >= 0 &&
            (_ngmyIsClockInSessionStartTransaction(tx) ||
                ((tx.sourceDetails ?? '').toLowerCase().contains('clock-in daily earnings')))) {
          _ngmyReconcileClockInSession(_allUsers[userIdx], _allTransactions);
          if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == userKey) {
            _currentUser = _allUsers[userIdx];
          }
        }
        _reconcileAllUserBalances(ledgerSettled: _userWalletLedgerSettled);
        if (_currentUser != null) {
          final userIdx = _allUsers.indexWhere(
            (u) => ngmyNormalizeEmail(u.email) == ngmyNormalizeEmail(_currentUser!.email),
          );
          if (userIdx >= 0 && (becameApproved || previous == null) && ngmyIsGameLedgerTransaction(tx)) {
            unawaited(_pushUserToCloudFast(_allUsers[userIdx], includeFreeTrial: true));
          }
          if (userIdx >= 0 &&
              (previous == null || statusChanged || becameApproved) &&
              ngmyNormalizeEmail(tx.userEmail) == ngmyNormalizeEmail(_currentUser!.email)) {
            unawaited(_pushUserBalanceToCloud(_allUsers[userIdx], ledgerTransactions: _allTransactions));
          }
        }
        if (tx.status == TransactionStatus.pending &&
            (tx.type == TransactionType.deposit || tx.type == TransactionType.withdrawal) &&
            (previous == null || previous!.status != TransactionStatus.pending)) {
          unawaited(_notifyAdminAboutPendingTransaction(tx));
        }
        unawaited(_persistLocalOnly());
        NgmyAdminLiveRefresh.notify();
      }
    } catch (e) {
      debugPrint('Transactions realtime apply error: $e');
    }
  }

  void _preserveLocalSessionState(UserData local, UserData remote) {
    if (local.passwordHash.trim().isNotEmpty && remote.passwordHash.trim().isEmpty) {
      remote.passwordHash = local.passwordHash;
    }
    if (local.lastClockInEarningsDate != null) {
      final remoteDate = remote.lastClockInEarningsDate;
      if (remoteDate == null || local.lastClockInEarningsDate!.isAfter(remoteDate)) {
        remote.lastClockInEarningsDate = local.lastClockInEarningsDate;
      }
    }
    if (local.todayClockInEarned > 0) {
      if (_ngmySameCalendarDay(local.lastClockInEarningsDate, DateTime.now())) {
        remote.todayClockInEarned = math.max(remote.todayClockInEarned, local.todayClockInEarned);
      }
    }
    if (local.lastClockInDate != null) {
      final remoteDate = remote.lastClockInDate;
      if (remoteDate == null || local.lastClockInDate!.isAfter(remoteDate)) {
        remote.lastClockInDate = local.lastClockInDate;
      }
    }
    _ngmyMergeClockInSessionAcrossDevices(local, remote, _allTransactions);
    if (local.activeInvestment != null) {
      if (remote.activeInvestment == null) {
        remote.activeInvestment = local.activeInvestment;
      } else {
        final localInv = local.activeInvestment!;
        final remoteInv = remote.activeInvestment!;
        final localNewer = localInv.purchaseDate.isAfter(remoteInv.purchaseDate);
        final localHigher = localInv.amount > remoteInv.amount + 0.001;
        if (localNewer || localHigher) {
          remote.activeInvestment = localInv;
        }
      }
    }
    // NGMY points are earned locally during games — never let stale cloud rows drop them.
    if (local.points > remote.points) {
      remote.points = local.points;
    }
    // A bet is deducted (and a win credited) locally the instant it happens
    // via an AppTransaction row — but this merge runs on every realtime
    // `users` row echo, and until that echo's own accountBalance catches up
    // with the txn that already landed, adopting it raw silently reverted
    // the spend/credit back to its pre-bet value. Once this device has any
    // transaction history for the person, the ledger is authoritative —
    // same rule ngmyResolveAccountBalance already applies elsewhere.
    remote.accountBalance = ngmyResolveAccountBalance(remote.email, remote.accountBalance, _allTransactions);
    _mergeCloudProfileIdentityFields(local, remote);
    _mergeUserMediaProfileFields(local, remote);
    if (local.savedCashAppTag.trim().isNotEmpty && remote.savedCashAppTag.trim().isEmpty) {
      remote.savedCashAppTag = local.savedCashAppTag;
    }
    if (local.savedBitcoinAddress.trim().isNotEmpty && remote.savedBitcoinAddress.trim().isEmpty) {
      remote.savedBitcoinAddress = local.savedBitcoinAddress;
    }
    remote.phone = ngmyMergeAccountPhone(local: local.phone, remote: remote.phone);
    if (local.isApprovedWorker && !remote.isApprovedWorker) remote.isApprovedWorker = true;
    if (local.isApprovedHelper && !remote.isApprovedHelper) remote.isApprovedHelper = true;
    // Never revive a registrar grant from stale local state. The approved
    // application list is authoritative for revoke, restore, and delete.
    remote.isAuthorizedRegistrar = _hasEffectiveRegistrarAccess(_config, remote);
    _preserveRegistryEnrollmentFromLocal(local, remote);
  }

  Future<void> _applyAuthoritativeCloudProfile(UserData user) async {
    await ngmyHydrateManagementListsFromAllBackups(_config);
    ngmyApplyAdminAccountStatusOverride(_config, user);
    ngmyApplyAdminCrownOverride(_config, user);
    await _hydrateUserCrownBadgeFromCloud(user);
    final crown = user.crownBadge.trim().toLowerCase();
    if (crown != 'king' && crown != 'queen') {
      ngmyApplyAdminCrownOverride(_config, user);
    }
  }

  /// After login: pull advisors, management lists, full user row, and transactions
  /// before showing balance — never push a lower balance to the cloud.
  Future<void> _syncSessionFromCloudAfterLogin(String emailKey) async {
    if (_currentUser == null || !await ngmyCanReachCloud()) return;
    try {
      await ngmyHydrateCommunicateSettingsFromAllBackups(_config);
      await ngmyHydrateManagementListsFromAllBackups(_config);

      double cloudStoredBalance = _currentUser!.accountBalance;
      final cloudUser = await _fetchCloudUserRow(_currentUser!.email);
      if (cloudUser != null) {
        cloudStoredBalance = cloudUser.accountBalance;
        final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == emailKey);
        final local = idx >= 0 ? _allUsers[idx] : _currentUser!;
        cloudUser.passwordHash = _currentUser!.passwordHash;
        cloudUser.forceLogout = false;
        if (ngmyEmailIsAdmin(emailKey)) cloudUser.isAdmin = true;
        _preserveLocalSessionState(local, cloudUser);
        _mergeUserMediaProfileFields(local, cloudUser);
        await _applyAuthoritativeCloudProfile(cloudUser);
        _currentUser = cloudUser;
        if (idx >= 0) _allUsers[idx] = cloudUser;
      }

      await _refreshUserTransactionsFromCloud(force: true);
      if (_currentUser == null || !mounted) return;

      ngmyReconcileUserAccountBalance(_currentUser!, _allTransactions);
      if (_currentUser!.accountBalance < cloudStoredBalance - 0.01) {
        _currentUser!.accountBalance = cloudStoredBalance;
      }
      final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == emailKey);
      if (idx >= 0) {
        _allUsers[idx].accountBalance = _currentUser!.accountBalance;
        _allUsers[idx].crownBadge = _currentUser!.crownBadge;
        _allUsers[idx].status = _currentUser!.status;
        if ((_currentUser!.profilePicturePath ?? '').trim().isNotEmpty) {
          _allUsers[idx].profilePicturePath = _currentUser!.profilePicturePath;
        }
      }

      _allUsers = ngmyApplyAdminAccountActionsToUsers(_config, _allUsers);
      if (mounted) setState(() {});
      await _persistLocalOnly();
    } catch (e, st) {
      debugPrint('[login] cloud session sync: $e\n$st');
    }
  }

  void _seedWithdrawalHoldTxnIds() {
    for (final t in _allTransactions) {
      if (t.type == TransactionType.withdrawal &&
          t.status == TransactionStatus.pending &&
          t.id.isNotEmpty) {
        _withdrawalHoldTxnIds.add(t.id);
      }
    }
  }

  String _walletLedgerSignatureForEmail(String email) {
    final key = ngmyNormalizeEmail(email);
    if (key.isEmpty) return '';
    final parts = <String>[];
    for (final t in _allTransactions) {
      if (ngmyNormalizeEmail(t.userEmail) != key) continue;
      parts.add('${t.id}:${t.status.index}:${t.type.index}:${t.amount.toStringAsFixed(2)}');
    }
    parts.sort();
    return parts.join('|');
  }

  void _reconcileAllUserBalances({bool ledgerSettled = false}) {
    if (ledgerSettled) {
      _userWalletLedgerSettled = true;
      ngmyUserWalletLedgerSettled = true;
    }
    for (final u in _allUsers) {
      ngmyReconcileUserAccountBalance(u, _allTransactions);
    }
    if (_currentUser != null) {
      final key = _currentUser!.email.toLowerCase().trim();
      final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
      if (idx >= 0) _currentUser = _allUsers[idx];
      final signature = _walletLedgerSignatureForEmail(_currentUser!.email);
      final ledgerChanged = signature != _lastWalletLedgerSignature;
      if (ledgerChanged) {
        _lastWalletLedgerSignature = signature;
        ngmySyncLiveBalanceFor(
          _currentUser!.email,
          _currentUser!.accountBalance,
          allowIncrease: true,
          force: true,
        );
      } else if (ledgerSettled) {
        ngmySyncLiveBalanceFor(
          _currentUser!.email,
          _currentUser!.accountBalance,
          allowIncrease: true,
          force: true,
        );
      }
    }
  }

  void _resetWalletLedgerSyncState() {
    _userWalletLedgerSettled = false;
    ngmyUserWalletLedgerSettled = false;
  }

  Future<void> _persistLocalSnapshot() async {
    await NgmyCommunicateAvatarCache.hydrateRamFromDisk();
    final configMap = _config.toJson();
    try {
      configMap['communicateProfiles'] =
          await NgmyCommunicateAvatarCache.profilesWithEmbeddedAvatars(_config.communicateProfiles);
    } catch (_) {}
    await NgmyLocalCache.persistSnapshot(
      users: _allUsers.map((e) => e.toJson()).toList(),
      transactions: _allTransactions.map((e) => e.toJson()).toList(),
      media: _allMedia.map((e) => e.toJson()).toList(),
      announcements: _allAnnouncements.map((e) => e.toJson()).toList(),
      config: configMap,
      investmentPlans: _globalPlans.map((e) => e.toJson()).toList(),
      currentUser: _currentUser?.toJson(),
    );
    await NgmyCommunicateAvatarCache.persistConfigProfilesLocally(_config);
  }

