          textSelectionTheme: TextSelectionThemeData(
            cursorColor: const Color(0xFFBB86FC),
            selectionColor: const Color(0xFFBB86FC).withValues(alpha: 0.35),
            selectionHandleColor: const Color(0xFFBB86FC),
          ),
        ),
        themeMode: _effectiveThemeMode,
        themeAnimationDuration: Duration.zero,
        builder: (context, child) {
          // Never cache [child] — reusing a stale navigator subtree caused black
          // blink loops on web/PWA after cloud sync or any parent rebuild.
          final bg = Theme.of(context).scaffoldBackgroundColor;
          final body = child ??
              ColoredBox(
                color: bg,
                child: Center(
                  child: CircularProgressIndicator(
                    color: Theme.of(context).colorScheme.primary,
                  ),
                ),
              );
          return ngmyCrispAppWrapper(context, body);
        },
        home: !_sessionBootstrapComplete
            ? Scaffold(
                backgroundColor: Theme.of(context).scaffoldBackgroundColor,
                body: const Center(child: CircularProgressIndicator()),
              )
            : _currentUser == null
            ? AuthScreen(
                allUsers: _allUsers,
                config: _config,
                onGoogleLogin: (emailHint) => _startOAuthSignIn(OAuthProvider.google, emailHint: emailHint),
                onGithubLogin: (emailHint) => _startOAuthSignIn(OAuthProvider.github, emailHint: emailHint),
                onResetPasswordByEmail: (email, newHash) async {
                  final emailNorm = email.toLowerCase().trim();
                  debugPrint('[ResetPW] Starting reset for $emailNorm');
                  _isSyncing = true;

                  try {
                    await ngmyWaitForSupabaseReady();
                    var result = await supabase
                        .from('users')
                        .update({'passwordHash': newHash})
                        .eq('email', emailNorm)
                        .select();

                    if (result.isEmpty) {
                      result = await supabase
                          .from('users')
                          .update({'passwordHash': newHash})
                          .ilike('email', emailNorm)
                          .select();
                    }

                    if (result.isEmpty) {
                      await supabase.from('users').upsert({
                        'email': emailNorm,
                        'passwordHash': newHash,
                        'username': emailNorm.split('@').first,
                      }, onConflict: 'email');
                    }

                    final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == emailNorm);
                    if (mounted) {
                      setState(() {
                        if (idx != -1) {
                          _allUsers[idx].passwordHash = newHash;
                        } else {
                          _allUsers.add(UserData(
                            email: emailNorm,
                            passwordHash: newHash,
                            username: emailNorm.split('@').first,
                            isAppLoginAccount: true,
                          ));
                        }
                      });
                    }

                    final prefs = await SharedPreferences.getInstance();
                    await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));

                    _isSyncing = false;
                    return true;
                  } catch (e) {
                    debugPrint('[ResetPW] failed: $e');
                    _isSyncing = false;
                    return false;
                  }
                },
                onAuthComplete: (e, p, u, passwordHash, isLogin) async {
                  final email = e.toLowerCase().trim();
                  if (isLogin) {
                    await _completePasswordLogin(email, passwordHash);
                    return;
                  }
                  await _clearLoggedOutFlag();
                  final user = UserData(
                    email: email,
                    phone: p,
                    username: u,
                    isAdmin: ngmyEmailIsAdmin(email),
                    passwordHash: passwordHash,
                    isAppLoginAccount: true,
                  );
                  ngmyMarkUserAsAppLoginAccount(user);
                  NgmyIncomeSound.bindSession(email);
                  unawaited(NgmyIncomeSound.unlockForWebUserGesture());

                  var synced = false;
                  for (var attempt = 0; attempt < 15; attempt++) {
                    synced = await _pushSignupUserToCloudReliable(user, includeFreeTrial: true);
                    if (synced) break;
                    await Future.delayed(Duration(milliseconds: 700 * (attempt + 1)));
                  }

                  if (!mounted) return;
                  setState(() {
                    _currentUser = user;
                    final idx = _allUsers.indexWhere((x) => x.email.toLowerCase().trim() == email);
                    if (idx >= 0) {
                      _allUsers[idx] = user;
                    } else {
                      _allUsers.add(user);
                    }
                  });
                  await _applyPendingReferralLink(user);
                  await _persistLocalOnly();
                  if (!synced && mounted) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(
                        content: Text('Account saved on this device. Still connecting to server — retrying in background.'),
                        duration: Duration(seconds: 6),
                      ),
                    );
                    unawaited(_pushSignupUserToCloudReliable(user, includeFreeTrial: true));
                  }
                  unawaited(_startBackgroundServicesWhenReady());
                },
              )
            : MainScreen(
                key: ValueKey('main_${_currentUser!.email.toLowerCase().trim()}'),
                user: _currentUser!, allTransactions: _allTransactions, allUsers: _allUsers, globalPlans: _globalPlans,
                allMedia: _allMedia,
                allAnnouncements: _allAnnouncements,
                config: _config,
                onThemeChanged: (m) => _setThemeMode(m), currentThemeMode: _themeMode,
                onLogout: _performLogout,
                onDataChanged: _onDataChanged,
                onReferralLinked: _onReferralLinked,
                onAddTransaction: (t) {
                  // Admin-deleted civic contributions must never be re-pushed / resurrected.
                  if (t.type == TransactionType.contribution &&
                      _config.civicDeletedContributionIds.contains(t.id.trim())) {
                    _allTransactions.removeWhere((x) => x.id == t.id);
                    unawaited(() async {
                      try {
                        if (await ngmyCanReachCloud()) {
                          await Supabase.instance.client
                              .from('transactions')
                              .delete()
                              .eq('id', t.id)
                              .timeout(kNgmyCloudWriteTimeout);
                        }
                      } catch (_) {}
                    }());
                    return;
                  }
                  final existingIdx = _allTransactions.indexWhere((x) => x.id == t.id);
                  final exists = existingIdx != -1;
                  UserData? syncedUser;
                  if (!exists) {
                  setState(() {
                    _allTransactions.add(t);
                    final userKey = ngmyNormalizeEmail(t.userEmail);
                    final userIdx = _allUsers.indexWhere((u) => ngmyNormalizeEmail(u.email) == userKey);
                    if (userIdx != -1) {
                      if (_ngmyIsClockInSessionStartTransaction(t)) {
                        _ngmyReconcileClockInSession(_allUsers[userIdx], _allTransactions);
                      } else if ((t.sourceDetails ?? '')
                          .toLowerCase()
                          .contains('clock-in daily earnings')) {
                        // Stack earnings into the wallet (+=). Never skip credit —
                        // skipping made each day's payout look like it replaced the balance.
                        if (t.status == TransactionStatus.approved && t.amount > 0) {
                          ngmyApplyApprovedTransactionToBalance(
                            _allUsers[userIdx],
                            t,
                            playSound: false,
                          );
                        }
                        _ngmyReconcileClockInSession(_allUsers[userIdx], _allTransactions);
                      } else if (t.status == TransactionStatus.approved) {
                        ngmyApplyApprovedTransactionToBalance(
                          _allUsers[userIdx],
                          t,
                          playSound: ngmyTransactionCountsAsIncome(t),
                        );
                      } else {
                        ngmyReconcileUserAccountBalance(_allUsers[userIdx], _allTransactions);
                      }
                      syncedUser = _allUsers[userIdx];
                      if (_currentUser != null && ngmyNormalizeEmail(_currentUser!.email) == userKey) {
                        _currentUser = _allUsers[userIdx];
                      }
                      _lastWalletLedgerSignature = _walletLedgerSignatureForEmail(userKey);
                    }
                  });
                  unawaited(_pushTransactionToCloudReliable(t));
                  unawaited(_pushTransactionToCloudFast(t));
                  _markTransactionDirty(t.id);
                  if (syncedUser != null) {
                    _markUserDirty(syncedUser!.email);
                    unawaited(_pushUserToCloudFast(syncedUser!, includeFreeTrial: true).then((ok) {
                      if (ok) _dirtyUserEmails.remove(ngmyNormalizeEmail(syncedUser!.email));
                    }));
                    unawaited(_pushUserBalanceToCloud(
                      syncedUser!,
                      allowDecrease: ngmyIsGameLedgerTransaction(t) ||
                          t.type == TransactionType.adminRemove ||
                          t.type == TransactionType.withdrawal,
                    ));
                    ngmyNotifyBalanceChanged(
                      email: syncedUser!.email,
                      balance: syncedUser!.accountBalance,
                      allowIncrease: true,
                    );
                  } else {
                    ngmyNotifyBalanceChanged();
                  }
                  unawaited(_persistLocalOnly());
                  } else {
                    // Update an existing row in place (status flips, contribution
                    // amount/note edits, etc.). Replace the list entry so final
                    // fields like amount/sourceDetails actually change.
                    _allTransactions[existingIdx] = t;
                    unawaited(_pushTransactionToCloudReliable(t));
                    unawaited(_pushTransactionToCloudFast(t));
                    _markTransactionDirty(t.id);
                    if (mounted) setState(() {});
                  }
                  if (t.status == TransactionStatus.approved && ngmyTransactionCountsAsIncome(t)) {
                    ngmyDeliverTransactionAlerts(t);
                  }
                  if (t.status == TransactionStatus.pending &&
                      (t.type == TransactionType.deposit || t.type == TransactionType.withdrawal)) {
                    unawaited(_notifyAdminAboutPendingTransaction(t));
                  }
                  if (!_ngmyIsClockInSessionStartTransaction(t)) {
                    unawaited(_notifyTransactionEvent(t));
                  }
                },
                onProcessTransaction: (t, approve) async {
                  UserData? syncedUser;
                  final previousStatus = t.status;
                  final newStatus = approve ? TransactionStatus.approved : TransactionStatus.rejected;
                  await NgmyWalletDecisionLedger.record(t.id, newStatus.index);
                  _walletDecisionLedger[t.id] = newStatus.index;
                  await NgmyWalletDecisionLedger.recordCloud(
                    transactionId: t.id,
                    statusIndex: newStatus.index,
                    userEmail: t.userEmail,
                    amount: t.amount,
                    typeIndex: t.type.index,
                  );
                  setState(() {
                    t.status = newStatus;
                    var targetIndex = _allUsers.indexWhere(
                      (u) => u.email.toLowerCase().trim() == t.userEmail.toLowerCase().trim(),
                    );
                    UserData targetUser;
                    if (targetIndex == -1) {
                      targetUser = UserData(
                        email: t.userEmail,
                        username: t.userEmail.split('@').first,
                      );
                      _allUsers.add(targetUser);
                      targetIndex = _allUsers.length - 1;
                    } else {
                      targetUser = _allUsers[targetIndex];
                    }
                    final details = t.sourceDetails ?? '';
                    final isInvestmentRequest = t.type == TransactionType.deposit && isInvestmentRequestDetails(details);
                    if (approve) {
                      if (isInvestmentRequest) {
                        final meta = parseInvestmentRequestDetails(details);
                        final planName = (meta['plan'] ?? '').trim();
                        final planAmount = double.tryParse(meta['amount'] ?? '');
                        final planRoi = double.tryParse(meta['roi'] ?? '');
                        if (planName.isNotEmpty && planAmount != null && planRoi != null) {
                          targetUser.activeInvestment = ActiveInvestment(
                            name: planName,
                            amount: planAmount,
                            dailyROI: InvestmentPlan.fixedRoi,
                            purchaseDate: DateTime.now(),
                            daysClockedIn: 0,
                            totalEarned: 0.0,
                          );
                          targetUser.pendingInvestmentName = null;
                          targetUser.pendingInvestmentAmount = null;
                          targetUser.pendingInvestmentRoi = null;
                          final investDebit = AppTransaction(
                            id: ngmyInvestPurchaseTxnId(t.userEmail, planName, planAmount),
                            userEmail: t.userEmail,
                            amount: t.amount,
                            type: TransactionType.adminRemove,
                            method: PaymentMethod.system,
                            sourceDetails: 'Investment plan purchase/upgrade: $planName',
                            status: TransactionStatus.approved,
                            timestamp: DateTime.now(),
                          );
                          if (!_allTransactions.any((x) => x.id == investDebit.id)) {
                            _allTransactions.add(investDebit);
                            unawaited(_pushTransactionToCloudReliable(investDebit));
                            unawaited(_pushTransactionToCloudFast(investDebit));
                            _markTransactionDirty(investDebit.id);
                          }
                        }
                      }
                    } else {
                      if (isInvestmentRequest) {
                        targetUser.pendingInvestmentName = null;
                        targetUser.pendingInvestmentAmount = null;
                        targetUser.pendingInvestmentRoi = null;
                      }
                    }
                    syncedUser = targetUser;
                    if (!approve && t.type == TransactionType.withdrawal) {
                      ngmyReleasePendingWithdrawalHold(targetUser, t, _withdrawalHoldTxnIds);
                    } else if (approve &&
                        t.type == TransactionType.deposit &&
                        !isInvestmentRequest &&
                        previousStatus == TransactionStatus.pending) {
                      // Explicit credit so approved deposits always arrive in the account.
                      targetUser.accountBalance =
                          (targetUser.accountBalance + t.amount).clamp(0.0, double.infinity);
                    } else if (approve && t.type == TransactionType.withdrawal) {
                      // Funds were already held when the withdrawal was submitted.
                      _withdrawalHoldTxnIds.remove(t.id);
                    } else {
                      ngmySyncUserBalanceAfterWalletDecision(
                        targetUser,
                        _allTransactions,
                        justDecided: t,
                        previousStatus: previousStatus,
                      );
                    }
                    if (_currentUser != null &&
                        _currentUser!.email.toLowerCase().trim() == t.userEmail.toLowerCase().trim()) {
                      _currentUser = targetUser;
                    }
                  });
                  NgmyAdminLiveRefresh.notify();
                  _markTransactionDirty(t.id);
                  if (syncedUser != null) {
                    _lastWalletLedgerSignature = _walletLedgerSignatureForEmail(syncedUser!.email);
                    // Always write approved deposit credits (and holds) to the database so money is not lost.
                    unawaited(_pushUserBalanceToCloud(
                      syncedUser!,
                      allowDecrease: t.type == TransactionType.withdrawal || !approve,
                    ));
                    ngmyNotifyBalanceChanged(
                      email: syncedUser!.email,
                      balance: syncedUser!.accountBalance,
                      allowIncrease: true,
                    );
                  } else {
                    ngmyNotifyBalanceChanged();
                  }
                  await _persistLocalOnly();
                  final syncedUserCopy = syncedUser;
                  final cloudSynced = await _syncWalletApprovalInBackground(t, syncedUserCopy);
                  if (mounted) {
                    final label = approve ? 'approved' : 'rejected';
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text(
                          cloudSynced
                              ? 'Deposit/withdrawal $label and saved to database.'
                              : 'Decision saved on this device — will sync when connection allows.',
                        ),
                        backgroundColor: cloudSynced ? const Color(0xFF00B25A) : Colors.orange,
                        duration: const Duration(seconds: 3),
                      ),
                    );
                  }
                  if (approve) {
                    ngmyDeliverTransactionAlerts(t, forceIncomeSound: true);
                  }
                  unawaited(_notifyTransactionEvent(t, statusChanged: true));
                },
                onAddPlan: (_) {
                  _applyBundledInvestmentPlansToConfig(_config);
                  setState(() => _globalPlans = _bundledInvestmentPlans());
                  unawaited(_persistLocalOnly());
                },
                onPostMedia: (post) {
                  _tombstonedMediaIds.remove(post.id);
                  setState(() {
                    _allMedia.removeWhere((m) => m.id == post.id);
                    _allMedia.insert(0, post);
                  });
                  NgmyAdminLiveRefresh.notify();
                  unawaited(() async {
                    var saved = await _upsertMediaRowSafe(Map<String, dynamic>.from(post.toJson()));
                    if (!saved) {
                      debugPrint('[media] onPostMedia cloud upsert failed for ${post.id} — retrying');
                      await Future.delayed(const Duration(seconds: 2));
                      saved = await _upsertMediaRowSafe(Map<String, dynamic>.from(post.toJson()));
                    }
                    if (!saved) {
                      debugPrint('[media] onPostMedia cloud upsert still failed for ${post.id}');
                    }
                    await _persistTombstonedMediaIds(_tombstonedMediaIds);
                    await _persistAllMediaLocally();
                  }());
                },
                onRefreshMediaFromCloud: _refreshMediaAndProfilesFromCloud,
                onDeleteMedia: _deleteMediaPostGlobally,
                onPruneMedia: _pruneDeletedMediaPost,
                onSavePopups: _savePopupsSettingsToCloud,
                onUploadPopupVideo: _uploadPopupVideoRef,
                onAddAnnouncement: (ann) {
                  setState(() => _allAnnouncements.add(ann));
                  NgmyAdminLiveRefresh.notify();
                  unawaited(_upsertAnnouncement(ann));
                  unawaited(_persistAnnouncementsLocally());
                  unawaited(_persistLocalOnly());
                },
              onDeleteAnnouncement: (id) {
                setState(() => _allAnnouncements.removeWhere((a) => a.id == id));
                NgmyAdminLiveRefresh.notify();
                _deleteAnnouncementById(id);
                unawaited(_persistLocalOnly());
              },
                onClearAllAnnouncements: () {
                setState(() => _allAnnouncements.clear());
                _clearAllAnnouncementsRemote();
                unawaited(_persistLocalOnly());
              },
                onSyncAdminMediaPost: _syncAdminMediaPost,
                onSyncAdminUserMedia: _syncAdminUserMediaProfile,
                onEnqueueMediaDelivery: _enqueueMediaDelivery,
                onPromptNotifications: (ctx) => _promptPushNotificationsForUser(ctx, _currentUser!.email),
                onMarkAnnouncementsRead: (ids) => _markAnnouncementsReadForUser(ids),
                onRefreshAdminData: _refreshAdminDashboardFromCloud,
                onPushUserToCloud: (u) => _pushUserToCloudFast(u, includeFreeTrial: true),
                onPushBalanceToCloud: (u, {bool allowDecrease = false}) => _pushUserBalanceToCloud(u, allowDecrease: allowDecrease),
                onPersistUserToCloud: (u) => _pushUserToCloudFast(u, includeFreeTrial: true),
                onRefreshLegalAndPlans: () => _refreshLegalAndPlansFromCloud(),
                onPersistManagementConfig: _saveAdminManagementConfigNow,
                onRefreshManagementData: _refreshAdminManagementFromCloud,
                onRefreshAdminMedia: _reloadMediaFromSupabase,
                onPurgeBrokenMedia: ({bool verifyUrls = false}) => _purgeGhostAndBrokenMedia(verifyUrls: verifyUrls),
            ),
      ),
    );
  }
}

// --- UI COMPONENTS ---

class FloatingTitle extends StatelessWidget {
  final String title; final Widget? leading; final Widget? trailing; final VoidCallback? onTap;
  /// Larger title chip — used for NGMY Hub so the header reads clearly.
  final bool large;
  const FloatingTitle({
    super.key,
    required this.title,
    this.leading,
    this.trailing,
    this.onTap,
    this.large = false,
  });
  @override
  Widget build(BuildContext context) {
    final h = large ? 76.0 : 60.0;
    final size = large ? 22.0 : 15.0;
    final isDark = Theme.of(context).brightness == Brightness.dark;
    return GestureDetector(
      onTap: onTap,
      child: Container(
        height: h,
        padding: EdgeInsets.symmetric(horizontal: large ? 14 : 10),
        decoration: BoxDecoration(
          color: Theme.of(context).cardColor,
          borderRadius: BorderRadius.circular(large ? 38 : 30),
          border: Border.all(
            color: isDark ? Colors.white.withValues(alpha: 0.12) : const Color(0xFF94A3B8),
            width: isDark ? 1 : 1.4,
          ),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(isDark ? 0.08 : 0.12),
              blurRadius: 15,
              offset: const Offset(0, 5),
            ),
          ],
        ),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            leading ?? SizedBox(width: large ? 48 : 40),
            Expanded(
              child: Center(
                child: Text(
                  title,
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    fontWeight: FontWeight.w900,
                    fontSize: size,
                    letterSpacing: large ? 1.6 : 1,
                    height: 1.05,
                    color: isDark ? null : const Color(0xFF0F172A),
                  ),
                ),
              ),
            ),
            trailing ?? SizedBox(width: large ? 48 : 40),
          ],
        ),
      ),
    );
  }
}

// --- SCREENS ---

class AuthScreen extends StatefulWidget {
  final List<UserData> allUsers;
  final AppConfig config;
  final Future<void> Function(String, String, String, String, bool) onAuthComplete;
  final Future<String?> Function(String emailHint) onGoogleLogin;
  final Future<String?> Function(String emailHint) onGithubLogin;
  final Future<bool> Function(String email, String newPasswordHash) onResetPasswordByEmail;
  const AuthScreen({super.key, required this.onAuthComplete, required this.allUsers, required this.onGoogleLogin, required this.onGithubLogin, required this.onResetPasswordByEmail, required this.config});
  @override State<AuthScreen> createState() => _AuthScreenState();
}
class _AuthScreenState extends State<AuthScreen> {
  bool _isLogin = true;
  bool _showPassword = false;
  bool _authBusy = false;
  bool _oauthBusy = false;
  final _e = TextEditingController();
  final _p = TextEditingController();
  final _s = TextEditingController();
  final _u = TextEditingController();

  Future<void> _submit() async {
    final email = _e.text.toLowerCase().trim();
    final phone = _p.text.trim();
    final username = _u.text.trim();

    if (email.isEmpty || !email.endsWith('@gmail.com')) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please enter a valid Gmail address')));
      return;
    }

    final password = _s.text;
    if (password.isEmpty || password.length < 6) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Password must be at least 6 characters')));
      return;
    }

    if (_isLogin) {
      if (_authBusy) return;
      final user = widget.allUsers.firstWhere(
        (u) => u.email.toLowerCase().trim() == email,
        orElse: () => UserData(email: ''),
      );

      final enteredHash = _hashPassword(password);

      if (user.email.isNotEmpty && user.passwordHash.isNotEmpty && user.passwordHash == enteredHash) {
        setState(() => _authBusy = true);
        try {
          await widget.onAuthComplete(email, '', '', enteredHash, true);
        } finally {
          if (mounted) setState(() => _authBusy = false);
        }
        return;
      }

      setState(() => _authBusy = true);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Checking credentials...')),
        );
      }

      try {
        await ngmyWaitForSupabaseReady();
        final fresh = await ngmyFetchUserLoginRow(
          Supabase.instance.client,
          email,
        );

        if (!mounted) return;

        if (fresh == null) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('Account not found. Please Sign Up first.')),
          );
          return;
        }

        final row = fresh;
        final dbHash = (row['passwordHash'] ?? row['password_hash'] ?? '').toString();
        if (dbHash.isNotEmpty && dbHash == enteredHash) {
          await widget.onAuthComplete(email, '', '', enteredHash, true);
        } else {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('Wrong password')),
          );
        }
      } catch (err) {
        debugPrint('[Login] cloud check failed: $err');
        if (!mounted) return;
        if (user.email.isNotEmpty && user.passwordHash.isNotEmpty && user.passwordHash == enteredHash) {
          await widget.onAuthComplete(email, '', '', enteredHash, true);
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('Signed in offline using data saved on this device.')),
          );
          return;
        }
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(ngmyAuthReachabilityMessage(err))),
        );
      } finally {
        if (mounted) setState(() => _authBusy = false);
      }
    } else {
      if (username.isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please enter a username')));
        return;
      }
      if (phone.isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please enter a phone number')));
        return;
      }

      final existsEmail = widget.allUsers.any((u) => u.email.toLowerCase().trim() == email);
      if (existsEmail) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('This email is already registered. Please Login.')));
        return;
      }
      final existsUser = widget.allUsers.any((u) => u.username.toLowerCase().trim() == username.toLowerCase().trim());
      if (existsUser) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Username already taken')));
        return;
      }
      final existsPhone = NgmyCivicRegistryMembers.isAppPhoneTaken(widget.allUsers, phone);
      if (existsPhone) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Phone number already registered')));
        return;
      }

      setState(() => _authBusy = true);
      try {
        await ngmyWaitForSupabaseReady();
        final existingCloud = await ngmyFetchUserLoginRow(Supabase.instance.client, email);
        if (!mounted) return;
        if (existingCloud != null) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('This email is already registered. Please log in instead.')),
          );
          setState(() => _isLogin = true);
          return;
        }
      } catch (e) {
        debugPrint('[signup] cloud duplicate check: $e');
      } finally {
        if (mounted) setState(() => _authBusy = false);
      }

      widget.onAuthComplete(email, phone, username, _hashPassword(password), false);
    }
  }

  Widget _buildAuthModeSwitchGlassCard(bool isDark) {
    final isLoginMode = _isLogin;
    final frameGradient = isDark
        ? [
            Colors.white.withOpacity(0.12),
            Colors.white.withOpacity(0.05),
          ]
        : [
            Colors.white.withOpacity(0.78),
