/// Compact 3D-styled logout confirmation (profile screen).
class _NgmyLogoutConfirmDialog extends StatefulWidget {
  const _NgmyLogoutConfirmDialog();

  @override
  State<_NgmyLogoutConfirmDialog> createState() => _NgmyLogoutConfirmDialogState();
}

class _NgmyLogoutConfirmDialogState extends State<_NgmyLogoutConfirmDialog>
    with SingleTickerProviderStateMixin {
  static const double _maxWidth = 300;

  late final AnimationController _ctrl;
  late final Animation<double> _glow;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 2200),
    )..repeat(reverse: true);
    _glow = Tween<double>(begin: 0.22, end: 0.42).animate(
      CurvedAnimation(parent: _ctrl, curve: Curves.easeInOut),
    );
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    const accent = Color(0xFFEF4444);

    return Dialog(
      backgroundColor: Colors.transparent,
      insetPadding: const EdgeInsets.symmetric(horizontal: 40, vertical: 24),
      child: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: _maxWidth),
          child: AnimatedBuilder(
            animation: _ctrl,
            builder: (context, _) {
              final glow = _glow.value;
              final tilt = math.sin(_ctrl.value * math.pi * 2) * 0.012;

              return Transform(
                transform: Matrix4.identity()
                  ..setEntry(3, 2, 0.001)
                  ..rotateX(tilt)
                  ..rotateY(tilt * 0.6),
                alignment: Alignment.center,
                child: DecoratedBox(
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(20),
                    boxShadow: [
                      BoxShadow(
                        color: accent.withOpacity(glow),
                        blurRadius: 16,
                        offset: const Offset(0, 6),
                      ),
                      BoxShadow(
                        color: Colors.black.withOpacity(0.35),
                        blurRadius: 12,
                        offset: const Offset(0, 8),
                      ),
                    ],
                  ),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(20),
                    child: Material(
                      color: Colors.transparent,
                      child: Container(
                        decoration: const BoxDecoration(
                          gradient: LinearGradient(
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                            colors: [
                              Color(0xFF5C1010),
                              Color(0xFF7F1D1D),
                              Color(0xFF292524),
                            ],
                          ),
                          border: Border.fromBorderSide(
                            BorderSide(color: Color(0x33FFFFFF), width: 1),
                          ),
                        ),
                        padding: const EdgeInsets.fromLTRB(16, 14, 16, 12),
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Row(
                              children: [
                                Container(
                                  width: 40,
                                  height: 40,
                                  decoration: BoxDecoration(
                                    shape: BoxShape.circle,
                                    gradient: RadialGradient(
                                      colors: [
                                        accent.withOpacity(0.45),
                                        Colors.transparent,
                                      ],
                                    ),
                                    border: Border.all(
                                      color: Colors.white.withOpacity(0.3),
                                      width: 1.5,
                                    ),
                                    boxShadow: [
                                      BoxShadow(
                                        color: accent.withOpacity(0.4),
                                        blurRadius: 8,
                                        offset: const Offset(0, 3),
                                      ),
                                    ],
                                  ),
                                  child: const Icon(
                                    Icons.logout_rounded,
                                    color: Colors.white,
                                    size: 20,
                                  ),
                                ),
                                const SizedBox(width: 12),
                                const Expanded(
                                  child: Text(
                                    'Log out?',
                                    style: TextStyle(
                                      color: Colors.white,
                                      fontSize: 17,
                                      fontWeight: FontWeight.w800,
                                    ),
                                  ),
                                ),
                              ],
                            ),
                            const SizedBox(height: 10),
                            Text(
                              'Are you sure you want to log out of your account?',
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                color: Colors.white.withOpacity(0.78),
                                fontSize: 12.5,
                                height: 1.35,
                              ),
                            ),
                            const SizedBox(height: 14),
                            Row(
                              children: [
                                Expanded(
                                  child: TextButton(
                                    onPressed: () => Navigator.pop(context, false),
                                    style: TextButton.styleFrom(
                                      foregroundColor: Colors.white70,
                                      padding: const EdgeInsets.symmetric(vertical: 8),
                                      shape: RoundedRectangleBorder(
                                        borderRadius: BorderRadius.circular(10),
                                        side: BorderSide(
                                          color: Colors.white.withOpacity(0.22),
                                        ),
                                      ),
                                      backgroundColor: Colors.white.withOpacity(0.08),
                                    ),
                                    child: const Text(
                                      'Cancel',
                                      style: TextStyle(
                                        fontWeight: FontWeight.w600,
                                        fontSize: 13,
                                      ),
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 8),
                                Expanded(
                                  child: FilledButton(
                                    onPressed: () => Navigator.pop(context, true),
                                    style: FilledButton.styleFrom(
                                      backgroundColor: accent,
                                      foregroundColor: Colors.white,
                                      padding: const EdgeInsets.symmetric(vertical: 8),
                                      elevation: 4,
                                      shadowColor: accent.withOpacity(0.6),
                                      shape: RoundedRectangleBorder(
                                        borderRadius: BorderRadius.circular(10),
                                      ),
                                    ),
                                    child: const Text(
                                      'Log out',
                                      style: TextStyle(
                                        fontWeight: FontWeight.w800,
                                        fontSize: 13,
                                      ),
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
        ),
      ),
    );
  }
}

class _LateClockInBanner extends StatefulWidget {
  final String message;
  final double penaltyPercent;
  final bool isBlocked;
  final bool compact;
  final bool goldFrame;

  const _LateClockInBanner({
    required this.message,
    required this.penaltyPercent,
    this.isBlocked = false,
    this.compact = false,
    this.goldFrame = false,
  });

  @override
  State<_LateClockInBanner> createState() => _LateClockInBannerState();
}

class _LateClockInBannerState extends State<_LateClockInBanner> with SingleTickerProviderStateMixin {
  late final AnimationController _ctrl;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 2200))..repeat(reverse: true);
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final blocked = widget.isBlocked;
    final penalty = widget.penaltyPercent;
    final accent = blocked
        ? const Color(0xFF64748B)
        : (penalty >= 20 ? const Color(0xFFEF4444) : const Color(0xFFF97316));
    return AnimatedBuilder(
      animation: _ctrl,
      builder: (context, _) {
        final pulse = 0.55 + (_ctrl.value * 0.45);
        final goldCompact = widget.compact && widget.goldFrame;
        return Container(
          padding: EdgeInsets.symmetric(
            horizontal: goldCompact ? 10 : (widget.compact ? 8 : 12),
            vertical: goldCompact ? 5 : (widget.compact ? 3 : 8),
          ),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(goldCompact ? 12 : (widget.compact ? 10 : 16)),
            gradient: LinearGradient(
              colors: blocked
                  ? [const Color(0xFF1E293B), const Color(0xFF334155)]
                  : [
                      Color.lerp(const Color(0xFF431407), const Color(0xFF7C2D12), pulse)!,
                      Color.lerp(const Color(0xFF7C2D12), const Color(0xFFEA580C), pulse)!,
                    ],
            ),
            boxShadow: [
              BoxShadow(
                color: accent.withOpacity(0.35 * pulse),
                blurRadius: 14,
                spreadRadius: 1,
                offset: const Offset(0, 4),
              ),
            ],
            border: Border.all(color: accent.withOpacity(0.55 + (pulse * 0.2))),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(
                blocked ? Icons.event_busy_rounded : Icons.alarm_rounded,
                color: Colors.white.withOpacity(0.95),
                size: goldCompact ? 11 : (widget.compact ? 10 : 14),
              ),
              SizedBox(width: goldCompact ? 5 : (widget.compact ? 4 : 7)),
              Text(
                widget.message,
                textAlign: TextAlign.center,
                style: TextStyle(
                  color: Colors.white,
                  fontSize: goldCompact ? 10 : (widget.compact ? 9 : 11),
                  fontWeight: FontWeight.w700,
                  letterSpacing: 0.2,
                ),
              ),
              if (!blocked && penalty > 0) ...[
                const SizedBox(width: 6),
                Container(
                  padding: EdgeInsets.symmetric(horizontal: goldCompact ? 6 : (widget.compact ? 5 : 7), vertical: goldCompact ? 3 : (widget.compact ? 2 : 3)),
                  decoration: BoxDecoration(
                    color: Colors.black.withOpacity(0.25),
                    borderRadius: BorderRadius.circular(999),
                    border: Border.all(color: Colors.white.withOpacity(0.35)),
                  ),
                  child: Text(
                    '-${penalty.toInt()}%',
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: goldCompact ? 9 : (widget.compact ? 8 : 10),
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
              ],
            ],
          ),
        );
      },
    );
  }
}

class _LateClockInDialog extends StatefulWidget {
  final double penaltyPercent;
  final DateTime clockTime;
  final double fullDaily;
  final double todayCap;

  const _LateClockInDialog({
    required this.penaltyPercent,
    required this.clockTime,
    required this.fullDaily,
    required this.todayCap,
  });

  @override
  State<_LateClockInDialog> createState() => _LateClockInDialogState();
}

class _LateClockInDialogState extends State<_LateClockInDialog> with SingleTickerProviderStateMixin {
  late final AnimationController _ctrl;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 1800))..repeat(reverse: true);
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  String _formatLate(DateTime clockTime) {
    if (!_ngmyShowLateClockUi(clockTime)) return 'Session started';
    final midnight = _ngmyDateOnly(clockTime);
    final diff = clockTime.difference(midnight);
    final hours = diff.inHours;
    final mins = diff.inMinutes % 60;
    if (hours <= 0 && mins <= 0) return 'Right on time';
    if (hours <= 0) return '$mins min late';
    return '$hours hr ${mins.toString().padLeft(2, '0')} min late';
  }

  @override
  Widget build(BuildContext context) {
    final penalty = widget.penaltyPercent;
    final showLate = _ngmyShowLateClockUi(widget.clockTime);
    final onTime = !showLate || penalty <= 0;
    final accent = onTime ? const Color(0xFF00B25A) : (penalty >= 20 ? const Color(0xFFEF4444) : const Color(0xFFF97316));
    return Dialog(
      backgroundColor: Colors.transparent,
      insetPadding: const EdgeInsets.symmetric(horizontal: 28),
      child: AnimatedBuilder(
        animation: _ctrl,
        builder: (context, _) {
          final glow = 0.35 + (_ctrl.value * 0.35);
          return Container(
            padding: const EdgeInsets.fromLTRB(22, 22, 22, 18),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(28),
              gradient: LinearGradient(
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
                colors: onTime
                    ? [const Color(0xFF052E16), const Color(0xFF14532D)]
                    : [const Color(0xFF431407), const Color(0xFF9A3412), const Color(0xFF7C2D12)],
              ),
              boxShadow: [
                BoxShadow(color: accent.withOpacity(glow), blurRadius: 28, spreadRadius: 2),
              ],
              border: Border.all(color: Colors.white.withOpacity(0.12)),
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  width: 64,
                  height: 64,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    gradient: RadialGradient(colors: [accent.withOpacity(0.35), Colors.transparent]),
                    border: Border.all(color: accent.withOpacity(0.8), width: 2),
                  ),
                  child: Icon(
                    onTime ? Icons.verified_rounded : Icons.schedule_rounded,
                    color: Colors.white,
                    size: 32,
                  ),
                ),
                const SizedBox(height: 14),
                Text(
                  showLate && !onTime ? 'Late Clock-In' : 'Clock-In Confirmed',
                  style: const TextStyle(color: Colors.white, fontSize: 20, fontWeight: FontWeight.w900),
                ),
                const SizedBox(height: 6),
                if (showLate)
                  Text(
                    _formatLate(widget.clockTime),
                    style: TextStyle(color: Colors.white.withOpacity(0.82), fontSize: 13, fontWeight: FontWeight.w600),
                  ),
                if (showLate) const SizedBox(height: 14),
                if (showLate && !onTime)
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
                    decoration: BoxDecoration(
                      color: Colors.black.withOpacity(0.22),
                      borderRadius: BorderRadius.circular(16),
                      border: Border.all(color: accent.withOpacity(0.45)),
                    ),
                    child: Column(
                      children: [
                        Text(
                          '${penalty.toInt()}% off today\'s daily income',
                          style: const TextStyle(color: Colors.white, fontSize: 16, fontWeight: FontWeight.w900),
                        ),
                        const SizedBox(height: 6),
                        Text(
                          'Plan daily: \$${formatCurrency(widget.fullDaily)} → You earn up to \$${formatCurrency(widget.todayCap)} today',
                          textAlign: TextAlign.center,
                          style: const TextStyle(color: Colors.white, fontSize: 13, fontWeight: FontWeight.w700),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          penalty >= 20
                              ? 'Checked in 30+ minutes after midnight.'
                              : 'Checked in 10+ minutes after midnight.',
                          textAlign: TextAlign.center,
                          style: TextStyle(color: Colors.white.withOpacity(0.78), fontSize: 12),
                        ),
                      ],
                    ),
                  )
                else if (showLate)
                  Text(
                    'You clocked in before the penalty window. Full daily earnings apply.',
