/// Builds bottom-nav tab content lazily so unvisited tabs do not block the home screen.
class _NgmyLazyTabSlot extends StatefulWidget {
  const _NgmyLazyTabSlot({
    super.key,
    required this.tabIndex,
    required this.activeIndex,
    required this.buildContent,
  });

  final int tabIndex;
  final int activeIndex;
  final Widget Function() buildContent;

  @override
  State<_NgmyLazyTabSlot> createState() => _NgmyLazyTabSlotState();
}

class _NgmyLazyTabSlotState extends State<_NgmyLazyTabSlot> {
  Widget? _content;

  @override
  void initState() {
    super.initState();
    ngmyBalanceTick.addListener(_refreshOnBalanceChange);
    if (widget.tabIndex == widget.activeIndex) {
      _content = widget.buildContent();
      return;
    }
    WidgetsBinding.instance.addPostFrameCallback((_) => _schedulePrefetch());
  }

  void _refreshOnBalanceChange() {
    if (!mounted || _content == null) return;
    // Only rebuild the Home tab for live balance — remounting Slides/Market
    // mid-session felt like the app was refreshing / kicking users out.
    if (widget.tabIndex != 0) return;
    setState(() => _content = widget.buildContent());
  }

  @override
  void dispose() {
    ngmyBalanceTick.removeListener(_refreshOnBalanceChange);
    super.dispose();
  }

  void _schedulePrefetch() {
    // Do not mount wallet/invest tabs in the background — breaks home on admin iOS PWA.
  }

  @override
  void didUpdateWidget(covariant _NgmyLazyTabSlot oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (_content == null && widget.tabIndex == widget.activeIndex) {
      _content = widget.buildContent();
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_content != null) return _content!;
    if (widget.tabIndex == widget.activeIndex) {
      _content = widget.buildContent();
      return _content!;
    }
    return ColoredBox(color: Theme.of(context).scaffoldBackgroundColor);
  }
}

