String _announcementsSig(List<Announcement> items) {
  if (items.isEmpty) return '0';
  final sorted = List<Announcement>.from(items)..sort((a, b) => b.timestamp.compareTo(a.timestamp));
  final latest = sorted.first;
  return '${items.length}:${latest.id}:${latest.timestamp.millisecondsSinceEpoch}';
}

String _investmentPlansSig(List<InvestmentPlan> plans) {
  if (plans.isEmpty) return '0';
  var h = 0;
  for (final p in plans) {
    h = Object.hash(h, p.name, p.price, p.roi);
  }
  return '${plans.length}:$h';
}

String _legalContentSig(AppConfig config) =>
    '${config.termsAndConditions.length}:${config.privacyPolicy.length}:'
    '${config.termsAndConditions.hashCode}:${config.privacyPolicy.hashCode}';

/// Admin dashboard is on a pushed route — notify it when shared config/transactions mutate.
class NgmyAdminLiveRefresh {
  NgmyAdminLiveRefresh._();
  static final Set<VoidCallback> _listeners = {};

  static void addListener(VoidCallback listener) => _listeners.add(listener);
  static void removeListener(VoidCallback listener) => _listeners.remove(listener);

  static void notify() {
    for (final listener in _listeners.toList()) {
      try {
        listener();
      } catch (_) {}
    }
  }
}

class _MainScreenState extends State<MainScreen> with WidgetsBindingObserver {
  int _idx = 0; Timer? _t; int _syncCounter = 0; int _missPolicyCounter = 0;
  Timer? _metricsDebounce;

  void _goToMainTab(int i, {bool refreshLegal = false}) {
    setState(() {
      _idx = i;
      _visitedTabs.add(i);
    });
    if (i == 0) {
      WidgetsBinding.instance.scheduleForcedFrame();
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) setState(() {});
      });
    }
    if (refreshLegal || i == 1 || i == 6) unawaited(widget.onRefreshLegalAndPlans?.call());
  }
  bool _offline = false;
  bool _investPurchaseInFlight = false;
  Timer? _onlineCheck;
  Timer? _adminTabRefreshDebounce;
  DateTime? _mainShellMountedAt;
  Map<int, Widget Function()>? _tabContentBuilders;
  String? _tabPagesKey;
  List<AppTransaction>? _sortedTxCache;
  int? _sortedTxCacheLen;
  List<AppTransaction>? _userClockInTxCache;
  int? _userClockInTxSourceLen;
  final GlobalKey _homeTabKey = GlobalKey(debugLabel: 'ngmy_home_tab');
  final Set<int> _visitedTabs = {0};
  bool _warmingTxCache = false;

  List<AppTransaction> _userClockInTransactions() {
    final len = widget.allTransactions.length;
    if (_userClockInTxCache != null && _userClockInTxSourceLen == len) {
      return _userClockInTxCache!;
    }
    final key = widget.user.email.toLowerCase().trim();
    _userClockInTxCache = widget.allTransactions
        .where((t) => t.userEmail.toLowerCase().trim() == key)
        .toList(growable: false);
    _userClockInTxSourceLen = len;
    return _userClockInTxCache!;
  }

  void _invalidateTransactionCaches() {
    _sortedTxCacheLen = null;
    _userClockInTxCache = null;
    _userClockInTxSourceLen = null;
  }

  List<AppTransaction> _sortedTransactions() {
    final len = widget.allTransactions.length;
    if (_sortedTxCache != null && _sortedTxCacheLen == len) return _sortedTxCache!;
    _sortedTxCacheLen = len;
    if (len == 0) {
      _sortedTxCache = const [];
      return _sortedTxCache!;
    }
    final raw = widget.allTransactions;
    if (len > 400) {
      _sortedTxCache = List<AppTransaction>.from(raw);
      final snapLen = len;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || widget.allTransactions.length != snapLen) return;
        final sorted = List<AppTransaction>.from(widget.allTransactions)
          ..sort((a, b) => b.timestamp.compareTo(a.timestamp));
        _sortedTxCache = sorted;
        _sortedTxCacheLen = snapLen;
        if (_idx != 0 && mounted) setState(() {});
      });
      return _sortedTxCache!;
    }
    _sortedTxCache = List<AppTransaction>.from(raw)
      ..sort((a, b) => b.timestamp.compareTo(a.timestamp));
    return _sortedTxCache!;
  }

  List<AppTransaction> _homeTransactionsForDisplay() {
    final len = widget.allTransactions.length;
    if (len == 0) return const [];
    if (_sortedTxCache != null && _sortedTxCacheLen == len) {
      final cache = _sortedTxCache!;
      return cache.length <= 120 ? cache : cache.sublist(0, 120);
    }
    return widget.allTransactions.take(120).toList(growable: false);
  }

  void _warmTransactionCacheAfterFrame() {
    if (_warmingTxCache) return;
    if (_sortedTxCache != null && _sortedTxCacheLen == widget.allTransactions.length) return;
    _warmingTxCache = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _warmingTxCache = false;
      if (!mounted) return;
      if (_sortedTxCache != null && _sortedTxCacheLen == widget.allTransactions.length) return;
      _sortedTransactions();
      if (_idx != 0 && mounted) setState(() {});
    });
  }

  void _runScheduledPopups() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      if (!ngmyShouldAllowGlobalInterrupt()) return;
      final mountedAt = _mainShellMountedAt;
      if (widget.user.isAdmin &&
          mountedAt != null &&
          DateTime.now().difference(mountedAt) < const Duration(seconds: 12)) {
        Future<void>.delayed(const Duration(seconds: 12), () {
      if (!mounted) return;
          NgmyPopupOrchestrator.handleAppOpen(
            context,
            popupsRaw: widget.config.ngmyPopups,
            videoPopupsRaw: widget.config.ngmyVideoPopups,
            userEmail: widget.user.email,
          );
        });
        return;
      }
      NgmyPopupOrchestrator.handleAppOpen(
        context,
        popupsRaw: widget.config.ngmyPopups,
        videoPopupsRaw: widget.config.ngmyVideoPopups,
        userEmail: widget.user.email,
      );
    });
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      // Avoid viewport resettle here — it was firing after gallery/photo pick
      // and made Menu Studio / Bio feel like a full app refresh.
      if (ngmyShouldAllowGlobalInterrupt()) {
      _runScheduledPopups();
      _promptPushNotificationsIfNeeded();
        unawaited(ngmyCheckItemRemindersNow(userEmail: widget.user.email));
        unawaited(ngmyCheckMedicineRemindersNow(userEmail: widget.user.email));
        unawaited(ngmyCheckCashierRemindersNow(userEmail: widget.user.email));
        unawaited(ngmyCheckSwahiliWordRemindersNow(userEmail: widget.user.email));
      }
      if (_idx == 0) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) setState(() {});
        });
      }
    }
  }

  @override
  void didChangeMetrics() {
    // iOS Safari fires metrics constantly for the keyboard / URL bar. Rebuilding
    // the whole MainScreen during Menu Studio / Bio made the app look like it
    // was crashing. Skip while another route covers the shell, and debounce.
    if (!mounted) return;
    final route = ModalRoute.of(context);
    if (route != null && !route.isCurrent) return;
    _metricsDebounce?.cancel();
    _metricsDebounce = Timer(const Duration(milliseconds: 180), () {
      if (!mounted) return;
      final r = ModalRoute.of(context);
      if (r != null && !r.isCurrent) return;
      setState(() {});
    });
  }

