  @override
  void didUpdateWidget(MainScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.user.email != widget.user.email) {
      NgmyIncomeSound.bindSession(widget.user.email);
      _tabPagesKey = null;
      _tabContentBuilders = null;
      _sortedTxCache = null;
      _sortedTxCacheLen = null;
      _userClockInTxCache = null;
      _userClockInTxSourceLen = null;
      _visitedTabs
        ..clear()
        ..add(0);
    } else if (oldWidget.allTransactions.length != widget.allTransactions.length) {
      _invalidateTransactionCaches();
      if (_idx != 0) {
      _warmTransactionCacheAfterFrame();
      }
    }
    if (oldWidget.user.username != widget.user.username ||
        oldWidget.user.crownBadge != widget.user.crownBadge ||
        (oldWidget.user.fullName ?? '') != (widget.user.fullName ?? '')) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) setState(() {});
      });
    }
    if (oldWidget.user.accountBalance != widget.user.accountBalance) {
      ngmySeedLiveBalance(
        widget.user.email,
        widget.user.accountBalance,
        allowIncrease: ngmyUserWalletLedgerSettled,
      );
    }
    if (oldWidget.currentThemeMode != widget.currentThemeMode) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) setState(() {});
      });
    }
    final oldSig = jsonEncode({'p': oldWidget.config.ngmyPopups, 'v': oldWidget.config.ngmyVideoPopups});
    final newSig = jsonEncode({'p': widget.config.ngmyPopups, 'v': widget.config.ngmyVideoPopups});
    if (oldSig != newSig) _runScheduledPopups();
  }

