  void _onAdminLiveRefresh() {
    if (!mounted) return;
    final mountedAt = _mainShellMountedAt;
    if (mountedAt != null && DateTime.now().difference(mountedAt) < const Duration(seconds: 10)) {
      return;
    }
    _adminTabRefreshDebounce?.cancel();
    _adminTabRefreshDebounce = Timer(const Duration(milliseconds: 400), () {
      if (!mounted) return;
      // Never wipe open tab content (Slides editor, etc.) — only refresh Home in place.
      if (_idx == 0) {
        setState(() {});
        return;
      }
      // Non-home tabs: leave mounted content alone so users stay where they are.
    });
  }

  void _scheduleMainShellRepaint() {
    // No-op: an extra setState here kept the home tab blank during startup sync.
  }

  void _onShellVisibleAgain() {
    if (!mounted || _idx == 0) return;
    final mountedAt = _mainShellMountedAt;
    if (mountedAt != null && DateTime.now().difference(mountedAt) < const Duration(seconds: 4)) {
      return;
    }
    // Request a frame only — do not setState (that remounted tabs and kicked users around).
    WidgetsBinding.instance.scheduleForcedFrame();
  }

  @override void initState() {
    super.initState();
    _mainShellMountedAt = DateTime.now();
    WidgetsBinding.instance.addObserver(this);
    // Always land on Home for a fresh shell. Never restore a previous tab — that
    // fought mid-session stability and is wrong for cold open (close → reopen).
    _idx = 0;
    try {
      SharedPreferences.getInstance().then((p) => p.remove('ngmy_main_tab_idx')).catchError((_) {});
    } catch (_) {}
    ngmyRegisterPageVisibleHandler(_onShellVisibleAgain);
    _warmTransactionCacheAfterFrame();
    NgmyAdminLiveRefresh.addListener(_onAdminLiveRefresh);
    _scheduleMainShellRepaint();
    NgmyIncomeSound.bindSession(widget.user.email);
    ngmySeedLiveBalance(
      widget.user.email,
      widget.user.accountBalance,
      allowIncrease: ngmyUserWalletLedgerSettled,
    );
    unawaited(NgmyIncomeSound.preload());
    NgmyPopupOrchestrator.resolveVideoUrl = _resolveSupabaseStorageUrlResilient;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final userTx = _userClockInTransactions();
      _ngmyReconcileClockInSession(widget.user, userTx);
      _evaluateClockInMissPolicy();
      unawaited(_autoAttemptClockIn());
    });
    _refreshOnlineStatus();
    _runScheduledPopups();
    WidgetsBinding.instance.addPostFrameCallback((_) => _promptPushNotificationsIfNeeded());
    WidgetsBinding.instance.addPostFrameCallback((_) => _maybeOpenCivicEnrollDeepLink());
    WidgetsBinding.instance.addPostFrameCallback((_) => _maybeOpenMediaPostDeepLink());
    ngmyStartItemReminderWatcher(widget.user.email);
    ngmyStartMedicineReminderWatcher(widget.user.email);
    ngmyStartCashierReminderWatcher(widget.user.email);
    WidgetsBinding.instance.addPostFrameCallback((_) => unawaited(ngmyCheckSwahiliWordRemindersNow(userEmail: widget.user.email)));
    WidgetsBinding.instance.addPostFrameCallback((_) => unawaited(ngmyCheckCashierRemindersNow(userEmail: widget.user.email)));
    ngmyRegisterAiAppTools(
      context: () => context,
      userEmail: widget.user.email,
      user: widget.user,
      config: widget.config,
      onDataChanged: widget.onDataChanged,
    );
    _onlineCheck = Timer.periodic(const Duration(seconds: 30), (_) => _refreshOnlineStatus());
    _t = Timer.periodic(const Duration(seconds: 1), (t) {
      if (widget.user.forceLogout) {
        // Ignore leftover forceLogout on cold open / remount. Only honor a live
        // admin kick after the shell has been open for a few seconds.
        final mountedAt = _mainShellMountedAt;
        final liveKick = mountedAt != null &&
            DateTime.now().difference(mountedAt) > const Duration(seconds: 4);
        widget.user.forceLogout = false;
        if (liveKick) {
          widget.onDataChanged();
          widget.onLogout();
          return;
        }
        widget.onDataChanged();
      }
      final userTx = _userClockInTransactions();
      // Overnight settle BEFORE midnight reset clears the session.
      final overnight = ngmyBuildOvernightClockInPayout(
        user: widget.user,
        transactions: userTx,
      );
      if (overnight != null) {
        final earned = overnight.amount;
        setState(() {
          widget.user.totalProfit += earned;
          if (widget.user.activeInvestment != null) {
            widget.user.activeInvestment!.totalEarned += earned;
            widget.user.activeInvestment!.daysClockedIn++;
          }
          widget.user.lastClockInEarningsDate = widget.user.clockInStartTime;
          widget.user.todayClockInEarned = earned;
          widget.user.isClockedIn = false;
          widget.user.clockInStartTime = null;
          widget.user.clockInPenaltyPercent = 0;
        });
        widget.onAddTransaction(overnight);
        widget.onDataChanged();
        return;
      }
      _ngmyApplyMidnightClockReset(widget.user);
      final wasClockedIn = widget.user.isClockedIn;
      _ngmyReconcileClockInSession(widget.user, userTx);
      if (!wasClockedIn && widget.user.isClockedIn) setState(() {});
      final now = DateTime.now();
      if (widget.user.isClockedIn) {
        if (_ngmyHasClockInPayoutForDay(widget.user.email, userTx, now) ||
            _ngmySameCalendarDay(widget.user.lastClockInEarningsDate, now)) {
          widget.user.isClockedIn = false;
          widget.user.clockInStartTime = null;
          widget.user.clockInPenaltyPercent = 0;
          widget.onDataChanged();
          return;
        }
        double earned = 0;
        bool completed = false;
        final goal = widget.user.todayDailyGoal;
        if (goal > 0 && widget.user.currentTodayEarnings >= goal - 0.0001) {
          earned = goal;
          setState(() {
            widget.user.totalProfit += earned;
            if (widget.user.activeInvestment != null) {
              widget.user.activeInvestment!.totalEarned += earned;
              widget.user.activeInvestment!.daysClockedIn++;
            }
            widget.user.isClockedIn = false;
            widget.user.clockInStartTime = null;
            widget.user.clockInPenaltyPercent = 0;
            widget.user.lastClockInDate = now;
            widget.user.lastClockInEarningsDate = now;
            widget.user.todayClockInEarned = earned;
            completed = true;
          });
        }

        if (completed) {
          final payoutId = _ngmyClockInTransactionId(widget.user.email, now);
          final alreadyPaid = _ngmyHasClockInPayoutForDay(widget.user.email, userTx, now);
          if (earned > 0 && !alreadyPaid) {
            ngmyPlayIncomeSoundForAmount(
              beneficiaryEmail: widget.user.email,
              amount: earned,
              dedupeKey: payoutId,
            );
            widget.onAddTransaction(AppTransaction(
              id: payoutId,
              userEmail: widget.user.email,
              amount: earned,
              type: TransactionType.reimbursement,
              method: PaymentMethod.system,
              sourceDetails: 'Clock-in daily earnings${widget.user.clockInPenaltyPercent > 0 ? ' (${widget.user.clockInPenaltyPercent.toInt()}% late deduction — cap \$${formatCurrency(earned)} of \$${formatCurrency(widget.user.fullDailyEarningsBeforePenalty)})' : ''}',
              status: TransactionStatus.approved,
              timestamp: now,
            ));
          }
          widget.onDataChanged(); // Immediate sync on completion
        } else {
          // Sync clock-in across devices — user row only; never push full config from background.
          _syncCounter++;
          if (_syncCounter >= 120) {
            _syncCounter = 0;
            unawaited(widget.onPushUserToCloud?.call(widget.user) ?? Future.value());
          }
        }
      } else {
        // No clock-in button on Home anymore — start the day's earning
        // session automatically the moment the user becomes eligible.
        unawaited(_autoAttemptClockIn());
      }
      _missPolicyCounter++;
      if (_missPolicyCounter >= 60) {
        _missPolicyCounter = 0;
        _evaluateClockInMissPolicy();
      }
      if (_ngmyIsPastNoon(now)) {
        final crown = widget.user.crownBadge.trim().toLowerCase();
        if ((crown == 'king' || crown == 'queen') &&
            !_ngmyHasCrownPayForDay(widget.user.email, userTx, now)) {
          _ngmyTryCrownDailyPayAtNoon(widget.user, userTx, widget.onAddTransaction);
          widget.onDataChanged();
        }
      }
    });
  }

  void _evaluateClockInMissPolicy() {
    final user = widget.user;
    final now = DateTime.now();
    NgmyClockInMissPolicy.rolloverMonthIfNeeded(user);
    if (!NgmyClockInMissPolicy.shouldEvaluateMiss(user, now)) return;
    final action = NgmyClockInMissPolicy.recordMissIfNeeded(user, now);
    if (action == null) return;
    widget.onDataChanged();
    unawaited(widget.onPushUserToCloud?.call(user) ?? Future.value());
    if (action == 'warn2') {
      unawaited(NgmyClockInMissPolicy.notifySecondMiss(user.email));
    } else if (action == 'reset') {
      unawaited(NgmyClockInMissPolicy.notifyPlanReset(user.email));
      if (mounted) {
        unawaited(NgmyClockInMissResetDialog.show(
          context,
          onGoToInvest: () => _goToMainTab(1, refreshLegal: true),
        ));
      }
    }
  }
  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    ngmyUnregisterPageVisibleHandler(_onShellVisibleAgain);
    NgmyAdminLiveRefresh.removeListener(_onAdminLiveRefresh);
    _adminTabRefreshDebounce?.cancel();
    _metricsDebounce?.cancel();
    _t?.cancel();
    _onlineCheck?.cancel();
    ngmyStopItemReminderWatcher();
    ngmyStopMedicineReminderWatcher();
    ngmyStopCashierReminderWatcher();
    NgmyAiAppBridge.clear();
    NgmyIncomeSound.bindSession(null);
    super.dispose();
  }

  List<UserData> _homeUsersForDisplay() {
    if (!widget.user.isAdmin || widget.allUsers.length <= 100) return widget.allUsers;
    final keys = <String>{widget.user.email.toLowerCase().trim()};
    for (final t in _homeTransactionsForDisplay()) {
      keys.add(t.userEmail.toLowerCase().trim());
    }
    return widget.allUsers
        .where((u) => keys.contains(u.email.toLowerCase().trim()))
        .toList(growable: false);
  }

