  void _ensureTabContentBuilders(List<AppTransaction> sorted) {
    final inv = widget.user.activeInvestment;
    final invSig = inv == null
        ? 'none'
        : '${inv.name}|${inv.amount.toStringAsFixed(2)}|${inv.daysLeft}|${inv.purchaseDate.millisecondsSinceEpoch}';
    final cacheKey =
        '${widget.user.email}|$invSig|'
        '${widget.user.pendingInvestmentName}|${widget.allMedia.length}|'
        '${_announcementsSig(widget.allAnnouncements)}|${widget.config.logoUrl}|$_investPurchaseInFlight|'
        '${_investmentPlansSig(widget.globalPlans)}|${_legalContentSig(widget.config)}|'
        '${widget.user.isEnrolledInRegistry}|${widget.user.isAuthorizedRegistrar}|'
        '${widget.user.state}|${widget.user.isCivicRegistryKing}|${widget.user.isCivicRegistryAdmin}';
    if (_tabContentBuilders != null && _tabPagesKey == cacheKey) return;
    _tabPagesKey = cacheKey;
    final civicEnrolled = widget.user.isEnrolledInRegistry ||
        NgmyCivicRegistryMembers.isEnrolled(widget.config, widget.user.email);
    final registrarServing = NgmyCivicRegistryStats.registrarStateForUser(
      email: widget.user.email,
      userState: widget.user.state,
      applications: widget.config.civicRegistrarApplications,
    );
    _tabContentBuilders = {
      1: () => NgmyMarketHubScreen(
                userEmail: widget.user.email,
        username: widget.user.username,
        isAdmin: widget.user.isAdmin,
      ),
      2: () => NgmySlidesStudioScreen(
        userEmail: widget.user.email,
        isAdmin: widget.user.isAdmin,
        bottomScrollPadding: _ngmyBottomNavScrollPadding(context),
        isCivicEnrolled: civicEnrolled,
        isAuthorizedRegistrar: widget.user.isAuthorizedRegistrar,
        isCivicRegistryKing: widget.user.isCivicRegistryKing,
        isCivicRegistryAdmin: widget.user.isCivicRegistryAdmin,
        memberState: widget.user.state,
        registrarServingState: registrarServing,
      ),
      3: () => NgmyHubScreen(
        user: widget.user,
        allUsers: widget.allUsers,
        allTransactions: sorted,
        allMedia: widget.allMedia,
        onAddTransaction: widget.onAddTransaction,
        onPostMedia: widget.onPostMedia,
        onDataChanged: widget.onDataChanged,
        config: widget.config,
        onRefreshMediaFromCloud: widget.onRefreshMediaFromCloud,
        onDeleteMedia: widget.onDeleteMedia,
        onPruneMedia: widget.onPruneMedia,
        onPurgeBrokenMedia: widget.onPurgeBrokenMedia,
        onSyncMediaPost: widget.onSyncAdminMediaPost,
        onSyncUserMedia: widget.onSyncAdminUserMedia,
      ),
      4: () => MediaHubScreen(
        user: widget.user,
        allUsers: widget.allUsers,
        allMedia: widget.allMedia,
        config: widget.config,
        onPost: widget.onPostMedia,
        onDataChanged: widget.onDataChanged,
        onAddTransaction: widget.onAddTransaction,
        onRefreshFromCloud: widget.onRefreshMediaFromCloud,
        onDeleteMedia: widget.onDeleteMedia,
        onPruneMedia: widget.onPruneMedia,
        onPurgeBrokenMedia: widget.onPurgeBrokenMedia,
        onSyncMediaPost: widget.onSyncAdminMediaPost,
        onSyncUserMedia: widget.onSyncAdminUserMedia,
      ),
      5: () => NgmyCreatorHubTab(
        userEmail: widget.user.email,
        bottomScrollPadding: _ngmyBottomNavScrollPadding(context),
        user: widget.user,
        config: widget.config,
        onCharge: (amount, description) async => ngmyChargeUserWallet(
          user: widget.user,
          allUsers: widget.allUsers,
          amount: amount,
          description: description,
          onAddTransaction: widget.onAddTransaction,
        ),
        onDataChanged: widget.onDataChanged,
        onPersistConfig: () => widget.onPersistManagementConfig?.call() ?? ngmyAdminPersistManagementConfig(widget.config),
      ),
      6: () => ProfileScreen(
        user: widget.user,
        allUsers: widget.allUsers,
        config: widget.config,
        onThemeChanged: widget.onThemeChanged,
        currentThemeMode: widget.currentThemeMode,
        onLogout: widget.onLogout,
        onDataChanged: widget.onDataChanged,
        onAddTransaction: widget.onAddTransaction,
        onRefreshLegalContent: widget.onRefreshLegalAndPlans,
        onReferralLinked: widget.onReferralLinked,
        onPersistUserToCloud: widget.onPersistUserToCloud,
      ),
    };
  }

  /// Non-home tabs only — home renders directly from [MainScreen.build].
  Widget _buildMainTabBody(List<AppTransaction> sorted) {
    assert(_idx != 0);
    _ensureTabContentBuilders(sorted);
    final builder = _tabContentBuilders![_idx];
    return _NgmyLazyTabSlot(
      key: ValueKey<String>(
        _idx == 2
            ? 'ngmy_tab_active_${_idx}_${widget.user.state.trim().toLowerCase()}'
            : 'ngmy_tab_active_$_idx',
      ),
      tabIndex: _idx,
      activeIndex: _idx,
      buildContent: builder!,
    );
  }

  Future<String?> _resolveUserPhoneFromCloud() async {
    if (!await ngmyCanReachCloud()) return null;
    final email = widget.user.email.trim();
    if (email.isEmpty) return null;
    try {
      final row = await Supabase.instance.client
          .from('users')
          .select('phone')
          .eq('email', email)
          .maybeSingle()
          .timeout(kNgmyCloudLoadTimeout);
      if (row == null) return null;
      final phone = (row['phone'] ?? '').toString().trim();
      if (!ngmyUserPhoneOnFile(phone)) return null;
      final key = email.toLowerCase().trim();
      widget.user.phone = phone;
      final idx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
      if (idx >= 0) widget.allUsers[idx].phone = phone;
      widget.onDataChanged();
      if (mounted) setState(() {});
      return phone;
    } catch (e) {
      debugPrint('[phone] resolve from cloud: $e');
      return null;
    }
  }

  Future<bool> _saveUserPhone(String phone) async {
    final trimmed = phone.trim();
    if (!ngmyUserPhoneOnFile(trimmed)) return false;
    final myEmail = widget.user.email.toLowerCase().trim();
    final taken = widget.allUsers.any(
      (u) => u.email.toLowerCase().trim() != myEmail && u.phone.trim() == trimmed,
    );
    if (taken) return false;
    widget.user.phone = trimmed;
    final idx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == myEmail);
    if (idx >= 0) widget.allUsers[idx].phone = trimmed;
    _syncCivicMemberRecordFromUser(widget.config, widget.user);
    widget.onDataChanged();
    await _pushUserPhoneToCloud(widget.user);
    await widget.onPushUserToCloud?.call(widget.user);
    if (mounted) setState(() {});
    return true;
  }

  @override Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final shellBg = Theme.of(context).scaffoldBackgroundColor;
    final viewportH = MediaQuery.sizeOf(context).height;
    final bottomInset = MediaQuery.paddingOf(context).bottom;
    return AnnotatedRegion<SystemUiOverlayStyle>(
      value: isDark
          ? const SystemUiOverlayStyle(
              statusBarColor: Color(0xFF121212),
              statusBarIconBrightness: Brightness.light,
              statusBarBrightness: Brightness.dark,
              systemNavigationBarColor: Colors.transparent,
              systemNavigationBarIconBrightness: Brightness.light,
            )
          : const SystemUiOverlayStyle(
              statusBarColor: Colors.white,
              statusBarIconBrightness: Brightness.dark,
              statusBarBrightness: Brightness.light,
              systemNavigationBarColor: Colors.transparent,
              systemNavigationBarIconBrightness: Brightness.dark,
            ),
      child: Listener(
        onPointerDown: (_) => unawaited(NgmyIncomeSound.unlockForWebUserGesture()),
        child: NgmyPhoneRequiredGate(
          phone: widget.user.phone,
          email: widget.user.email,
          onSavePhone: _saveUserPhone,
          onResolvePhoneFromCloud: _resolveUserPhoneFromCloud,
          child: Scaffold(
        extendBody: true,
        // Keep the shell height stable; keyboard overlays content instead of
        // removing the bottom nav (stale viewInsets used to leave a blank band).
        resizeToAvoidBottomInset: false,
        backgroundColor: shellBg,
        body: SizedBox(
          width: double.infinity,
          height: viewportH,
          child: Stack(
            clipBehavior: Clip.none,
            children: [
              Positioned.fill(
                child: _idx == 0
                    ? _buildHomeTabWidget()
                    : Builder(
                        builder: (context) {
                          final sorted = _sortedTransactions();
                          return Stack(
                            children: [
                              if (!isDark)
                                Positioned(
                                  top: 0,
                                  left: 0,
                                  right: 0,
                                  height: MediaQuery.of(context).padding.top,
                                  child: ColoredBox(color: shellBg),
                                ),
                              Positioned.fill(
                                child: ColoredBox(
                                  color: shellBg,
                                  child: _buildMainTabBody(sorted),
                                ),
                              ),
                            ],
                          );
                        },
                      ),
              ),
              Positioned(
                left: 15,
                right: 15,
                bottom: 20 + bottomInset,
                height: NgmyBottomNavMetrics.barHeight,
                child: _buildBottomNavBar(),
              ),
            ],
          ),
        ),
        ),
        ),
      ),
    );
  }

  Widget _buildBottomNavBar() {
    const orb = NgmyBottomNavMetrics.selectionOrb;
    const barH = NgmyBottomNavMetrics.barHeight;
    return Material(
      type: MaterialType.transparency,
      elevation: 0,
      color: Colors.transparent,
      child: NgmySculptedBottomNavFrame(
        child: LayoutBuilder(
          builder: (context, constraints) {
            final tabW = constraints.maxWidth / 7;
            final ballLeft = _idx * tabW + (tabW - orb) / 2;
            final ballTop = (barH - orb) / 2;
            final accent = switch (_idx) {
              3 => const Color(0xFFBB86FC),
              4 => kNgmyAdvisorsHubAccent,
              5 => const Color(0xFF8B5CF6),
              _ => const Color(0xFF67E8F9),
            };
            return Stack(
              clipBehavior: Clip.none,
              children: [
                AnimatedPositioned(
                  duration: const Duration(milliseconds: 320),
                  curve: Curves.easeOutCubic,
                  left: ballLeft,
                  top: ballTop,
                  width: orb,
                  height: orb,
                  child: IgnorePointer(child: NgmyNavSelectionOrb(size: orb, accent: accent)),
                ),
                Row(
                  crossAxisAlignment: CrossAxisAlignment.center,
                  children: [
                    _nav(0, Icons.home_rounded),
                    _navToolHub(),
                    _nav(2, Icons.auto_stories_rounded),
                    _navC(3),
                    _nav(4, kNgmyAdvisorsHubNavIcon, selectedColor: kNgmyAdvisorsHubAccent),
                    _navStudio(),
                    _nav(6, Icons.person_rounded),
                  ],
                ),
              ],
            );
          },
        ),
      ),
    );
  }

