class _HomeScreenState extends State<HomeScreen> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late AnimationController _smokeCtrl;
  int _unreadNewsCount = 0;
  DateTime? _homeMountedAt;
  final TextEditingController _assistantInputCtrl = TextEditingController();
  final ScrollController _assistantScrollCtrl = ScrollController();
  final List<Map<String, dynamic>> _assistantMessages = [];
  bool _assistantTyping = false;
  bool _assistantMemoryLoaded = false;

  Future<void> _openNewsHub({String? initialQuery, int initialTab = 0}) async {
    await NgmyNavigator.push(
      context,
      AnnouncementScreen(
        user: widget.user,
        allUsers: widget.allUsers,
        announcements: const [],
        config: widget.config,
        onPostToNews: (_) {},
        onAddTransaction: widget.onAddTransaction,
        onDataChanged: widget.onDataChanged,
        initialQuery: initialQuery,
        initialTab: initialTab,
        liveAppKnowledge: () => NgmyAppKnowledge.build(
          viewer: {
            'email': widget.user.email,
            'username': widget.user.username,
            'isAdmin': widget.user.isAdmin,
            'accountBalance': widget.user.accountBalance,
          },
          config: widget.config.toJson(),
          transactions: widget.allTransactions.take(100).map((e) => e.toJson()).toList(),
          investmentPlans: widget.globalPlans.map((e) => e.toJson()).toList(),
          announcements: const [],
          mediaPostCount: 0,
          userCount: widget.allUsers.length,
        ),
      ),
    );
  }

  @override void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _homeMountedAt = DateTime.now();
    _smokeCtrl = AnimationController(vsync: this, duration: const Duration(seconds: 10));
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      if (!ngmyPreferLightGraphics) _smokeCtrl.repeat();
    });
    unawaited(_loadAssistantMemory());
  }

  Future<void> _loadAssistantMemory() async {
    final mem = await NgmyAiMemoryStore.load(widget.user.email);
    if (!mounted) return;
    setState(() {
      _assistantMessages
        ..clear()
        ..addAll(mem);
      _assistantMemoryLoaded = true;
    });
    _scrollAssistantToBottom(jump: true);
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && mounted && !ngmyPreferLightGraphics) {
      if (!_smokeCtrl.isAnimating) _smokeCtrl.repeat();
    }
  }

  @override
  void didUpdateWidget(covariant HomeScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.user.isClockedIn != widget.user.isClockedIn ||
        oldWidget.user.accountBalance != widget.user.accountBalance ||
        oldWidget.user.displayedTodayEarnings != widget.user.displayedTodayEarnings ||
        oldWidget.user.todayDailyGoal != widget.user.todayDailyGoal ||
        oldWidget.user.email != widget.user.email ||
        oldWidget.user.username != widget.user.username ||
        oldWidget.user.crownBadge != widget.user.crownBadge ||
        oldWidget.allTransactions.length != widget.allTransactions.length) {
      if (mounted) setState(() {});
    }
  }

  @override void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    if (_smokeCtrl.isAnimating) _smokeCtrl.stop();
    _smokeCtrl.dispose();
    _assistantInputCtrl.dispose();
    _assistantScrollCtrl.dispose();
    super.dispose();
  }

  void _scrollAssistantToBottom({bool jump = false}) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!_assistantScrollCtrl.hasClients) return;
      final target = _assistantScrollCtrl.position.maxScrollExtent;
      if (jump) {
        _assistantScrollCtrl.jumpTo(target);
      } else {
        _assistantScrollCtrl.animateTo(target, duration: const Duration(milliseconds: 240), curve: Curves.easeOut);
      }
    });
  }

  /// Inline chat right on the Home card — answers in place instead of
  /// navigating to the full NGMY Helper screen. Uses the same Gemini
  /// credentials + shared local memory as NGMY Helper so context carries over.
  Future<void> _askAssistant() async {
    final text = _assistantInputCtrl.text.trim();
    if (text.isEmpty || _assistantTyping) return;
    _assistantInputCtrl.clear();

    if (!widget.user.isAdmin) {
      final limit = widget.config.ngmyHelperDailyMessageLimit;
      if (limit > 0) {
        final allowed = await NgmyHelperAiLimit.tryConsume(widget.user.email, limit);
        if (!allowed) {
          if (!mounted) return;
          setState(() {
            _assistantMessages.add({
              'role': 'ai',
              'text': "You've used today's free questions. Open NGMY Helper to browse the knowledge base, or come back tomorrow for more free questions.",
              'at': DateTime.now().toUtc().toIso8601String(),
            });
          });
          _scrollAssistantToBottom();
          return;
        }
      }
    }

    setState(() {
      _assistantMessages.add({'role': 'user', 'text': text, 'at': DateTime.now().toUtc().toIso8601String()});
      _assistantTyping = true;
    });
    unawaited(NgmyAiMemoryStore.append(widget.user.email, role: 'user', text: text));
    _scrollAssistantToBottom();

    try {
      var apiKey = widget.config.geminiApiKey.trim();
      if (apiKey.isEmpty) {
        apiKey = await _fetchRemoteGeminiApiKey();
        if (apiKey.isNotEmpty && mounted) setState(() => widget.config.geminiApiKey = apiKey);
      }
      if (apiKey.isEmpty) {
        final err = ngmyAiHelperFailureMessage(apiKey: '');
        if (!mounted) return;
        setState(() {
          _assistantMessages.add({'role': 'ai', 'text': err, 'at': DateTime.now().toUtc().toIso8601String()});
          _assistantTyping = false;
        });
        unawaited(NgmyAiMemoryStore.append(widget.user.email, role: 'ai', text: err));
        _scrollAssistantToBottom();
        return;
      }

      if (ngmyUserGrantsHelperAccess(text)) {
        await NgmyHelperPermissionStore.grantAll(widget.user.email);
      }
      final ngmyUserMaps = ngmyUsersToContactMaps(widget.allUsers);
      final contacts = await NgmyPhoneContactsStore.ensureHydrated(widget.user.email, ngmyUsers: ngmyUserMaps);
      final phoneCtx = ngmyHelperPhoneIntegrationContext(
        contactsDirectory: NgmyPhoneContactsStore.directoryForAi(contacts),
      );
      final creds = ngmyParseAiCredentials(apiKey);
      final liveDb = NgmyAppKnowledge.build(
        viewer: {
          'email': widget.user.email,
          'username': widget.user.username,
          'isAdmin': widget.user.isAdmin,
          'accountBalance': widget.user.accountBalance,
        },
        config: widget.config.toJson(),
        transactions: widget.allTransactions.take(100).map((e) => e.toJson()).toList(),
        investmentPlans: widget.globalPlans.map((e) => e.toJson()).toList(),
        announcements: const [],
        mediaPostCount: 0,
        userCount: widget.allUsers.length,
      );
      final prompt = '${_ngmyHelperSystemContext(user: widget.user)}'
          '\n$phoneCtx\n'
          '${widget.user.isAdmin ? '\n${ngmyAdminEmailSendContext(ngmyUsers: ngmyUserMaps)}\n' : ''}'
          '\n$liveDb\n'
          '${NgmyAiMemoryStore.transcriptForPrompt(_assistantMessages)}\n'
          '\nUser: $text';
      final aiResult = await ngmyAiGenerateWithCredentials(creds, prompt);
      if (!mounted) return;
      final rawReply = (aiResult.text != null && aiResult.text!.isNotEmpty)
          ? aiResult.text!
          : ngmyAiHelperFailureMessage(apiKey: apiKey, lastError: aiResult.error);
      final parsed = ngmyParseHelperPhoneActions(rawReply);
      var phoneActions = parsed.actions;
      if (phoneActions.isEmpty) {
        phoneActions = [
          ...ngmyInferAlarmActionsFromUserMessage(text),
          ...ngmyInferCalendarActionsFromUserMessage(text),
          ...ngmyInferContactActionsFromUserMessage(text),
          ...ngmyInferOpenToolActionsFromUserMessage(text),
          ...ngmyInferSendEmailActionsFromUserMessage(text, isAdmin: widget.user.isAdmin),
        ];
      }
      phoneActions = ngmyFilterAdminOnlyPhoneActions(phoneActions, isAdmin: widget.user.isAdmin);
      phoneActions = await ngmyResolvePhoneActionsByName(
        context: context,
        userEmail: widget.user.email,
        actions: phoneActions,
        ngmyUsers: ngmyUserMaps,
      );
      final reply = NgmyAiMemoryStore.sanitizeHelperReply(parsed.text.isNotEmpty ? parsed.text : rawReply);
      setState(() {
        _assistantMessages.add({
          'role': 'ai',
          'text': reply,
          'at': DateTime.now().toUtc().toIso8601String(),
          if (phoneActions.isNotEmpty) 'phoneActions': phoneActions.map(_phoneActionToJson).toList(),
        });
        _assistantTyping = false;
      });
      unawaited(NgmyAiMemoryStore.append(widget.user.email, role: 'ai', text: reply));
      if (phoneActions.isNotEmpty && mounted) {
        unawaited(_runHomePhoneActions(phoneActions));
      }
      _scrollAssistantToBottom();
    } catch (e) {
      if (!mounted) return;
      final err = ngmyAiHelperFailureMessage(apiKey: widget.config.geminiApiKey, lastError: e.toString());
      setState(() {
        _assistantMessages.add({'role': 'ai', 'text': err, 'at': DateTime.now().toUtc().toIso8601String()});
        _assistantTyping = false;
      });
      unawaited(NgmyAiMemoryStore.append(widget.user.email, role: 'ai', text: err));
      _scrollAssistantToBottom();
    }
  }

  void _clearAssistantChat() {
    setState(() => _assistantMessages.clear());
    unawaited(NgmyAiMemoryStore.saveAll(widget.user.email, const []));
  }

  Map<String, dynamic> _phoneActionToJson(NgmyPhoneAction action) => {
        'type': action.type,
        ...action.fields,
      };

  List<NgmyPhoneAction> _phoneActionsFromAssistantMessage(Map<String, dynamic> m) {
    final raw = m['phoneActions'];
    if (raw is! List) return const [];
    final out = <NgmyPhoneAction>[];
    for (final item in raw) {
      if (item is Map) {
        final action = NgmyPhoneAction.fromJson(Map<String, dynamic>.from(item));
        if (action != null) out.add(action);
      }
    }
    return out;
  }

  Future<void> _runHomePhoneActions(List<NgmyPhoneAction> actions) async {
    for (final action in actions) {
      if (!mounted) return;
      final result = await ngmyRunPhoneAction(
        action,
        context: context,
        userEmail: widget.user.email,
        isAdmin: widget.user.isAdmin,
        config: widget.config,
        skipConfirmation: action.type == 'alarm' || action.type == 'open_tool',
      );
      if (!mounted || result == null) continue;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(result),
          backgroundColor: action.type == 'alarm' ? const Color(0xFFF97316) : const Color(0xFF16A34A),
          duration: Duration(seconds: action.type == 'alarm' ? 9 : 5),
        ),
      );
    }
  }

  Future<void> _tapHomePhoneAction(NgmyPhoneAction action) async {
    await _runHomePhoneActions([action]);
  }

  Future<void> _openLocalGrowthFromHome() async {
    if (!widget.user.isAdmin) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Growth Income is only available to admin.')),
      );
      return;
    }
    if (widget.disableLocalGrowthIncomeEntry) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('You are already in Local Growth — use the back arrow to return to the main app.')),
      );
      return;
    }
    await showNgmyLocalGrowthIncomePage(
      context,
      liveUser: widget.user,
      config: widget.config,
      plans: widget.globalPlans,
      onCloudAddTransaction: widget.onAddTransaction,
      onPersistBalanceToCloud: (balance, {required bool allowDecrease}) async {
        // Growth Income shares this same account balance with Store, fees, games, etc.
        if (!allowDecrease && balance + 0.01 < widget.user.accountBalance) {
          return;
        }
        widget.user.accountBalance = allowDecrease
            ? balance.clamp(0.0, double.infinity)
            : math.max(widget.user.accountBalance, balance);
        ngmyNotifyBalanceChanged(
          email: widget.user.email,
          balance: widget.user.accountBalance,
          allowIncrease: true,
        );
        await widget.onPushBalanceToCloud?.call(widget.user, allowDecrease: allowDecrease);
        widget.onDataChanged();
      },
    );
  }

  @override Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness == Brightness.light;
    final bg = isLight ? const Color(0xFFF3FBFF) : const Color(0xFF121212);
    return ColoredBox(
      color: bg,
      child: LayoutBuilder(
        builder: (context, constraints) {
          // Force a definite height for the Column below so the Expanded hero
          // card below can never hit "unbounded height" — that previously
          // caused the whole screen to render blank with the bottom nav
          // bar mis-positioned on some embedding contexts (Local Growth).
          final h = constraints.hasBoundedHeight && constraints.maxHeight.isFinite
              ? constraints.maxHeight
              : (MediaQuery.of(context).size.height - _ngmyBottomNavScrollPadding(context));
          return SizedBox(
            height: h,
            width: double.infinity,
            child: Stack(
              children: [
                Positioned.fill(
                  child: IgnorePointer(child: _homePastelBackdrop(isLight)),
                ),
                // Scroll only so a small Neural/Signal bump can push Core/Vault down
                // without shrinking the cards above. No ClipRect / hard cut edges.
                Padding(
                  padding: EdgeInsets.fromLTRB(20, 2, 20, _ngmyBottomNavScrollPadding(context)),
                  child: SingleChildScrollView(
                    physics: const BouncingScrollPhysics(),
                    clipBehavior: Clip.none,
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        // Slim icon row — Loan | animated NGMY | Local Growth.
                        Row(
                          children: [
                            widget.homeLeadingOverride ??
                                _roundGlassButton(
                                  icon: Icons.attach_money_rounded,
                                  tooltip: 'Loan Service',
                                  onTap: () => NgmyNavigator.push(
                                    context,
                                    LoanServiceScreen(user: widget.user, config: widget.config, onDataChanged: widget.onDataChanged),
                                    routeName: 'LoanServiceScreen',
                                  ),
                                ),
                            Expanded(child: Center(child: NgmyHomeBrandBadge(onTap: widget.onOpenAdminDashboard))),
                            widget.user.isAdmin
                                ? _roundGlassButton(icon: Icons.wifi_rounded, tooltip: 'Growth Income', onTap: _openLocalGrowthFromHome)
                                : const SizedBox(width: 42),
                          ],
                        ),
                        if (widget.user.isOnFreeTrial) ...[
                          const SizedBox(height: 6),
                          _buildFreeTrialGlassBanner(isLight),
                        ],
                        // Room above cards so top peeks can show without pushing the deck down.
                        const SizedBox(height: 32),
                        NgmyHomeGlassCardsPanel(
                          userEmail: widget.user.email,
                          displayName: widget.user.username,
                          profilePicturePath: widget.user.profilePicturePath,
                          config: widget.config,
                          onCivicIdPhotoSaved: () async {
                            final ok = await ngmyPersistCivicRegistryMembers(widget.config);
                            if (mounted) setState(() {});
                            if (!ok && mounted) {
                              ScaffoldMessenger.of(context).showSnackBar(
                                const SnackBar(
                                  content: Text('ID photo saved on this device — will sync when online.'),
                                  backgroundColor: Colors.orange,
                                ),
                              );
                            }
                          },
                          civicIdRecord: () {
                            final u = widget.user;
                            final fromRegistry = NgmyCivicRegistryMembers.findByEmail(widget.config, u.email) ??
                                NgmyCivicRegistryMembers.passportForAppUser(
                                  widget.config,
                                  email: u.email,
                                  phone: u.phone,
                                );
                            if (fromRegistry != null) {
                              final rid = (fromRegistry['registryId'] ?? '').toString().trim();
                              if (rid.isEmpty) return null;
                              return Map<String, dynamic>.from(fromRegistry);
                            }
                            // Deleted from registry — do not resurrect from leftover profile fields.
                            return null;
                          }(),
                        ),
                        // Extra air so tech frames sit a bit lower under the cards.
                        const SizedBox(height: 26),
                        // Neural/Signal a little taller; Core/Vault keep size and sit lower.
                        const NgmyHomeTechFramesPanel(),
                      ],
                    ),
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  Widget _homePastelBackdrop(bool isLight) {
    if (!isLight) {
      // Match NGMY Hub darkness — solid canvas, no bluish gradient wash.
      return const ColoredBox(color: Color(0xFF121212));
    }
    final baseColors = const [Color(0xFFF7FCFF), Color(0xFFEFF8FF), Color(0xFFF9F1FF)];
    return DecoratedBox(
            decoration: BoxDecoration(
        gradient: LinearGradient(
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
          colors: baseColors,
        ),
      ),
      child: ngmyCrispUi
          ? const SizedBox.shrink()
          : Stack(
        children: [
                _pastelOrb(top: 48, left: -26, size: 118, colors: const [Color(0xFF8EEBFF), Color(0xFFE3B3FF)]),
                _pastelOrb(top: 82, right: -18, size: 96, colors: const [Color(0xFFFFD7B8), Color(0xFFFFA7DD)]),
                _pastelOrb(top: 250, left: 18, size: 76, colors: const [Color(0xFFD8F8A9), Color(0xFF8FE7FF)]),
                _pastelOrb(top: 360, right: 22, size: 112, colors: const [Color(0xFFC4B5FD), Color(0xFF67E8F9)]),
              ],
            ),
    );
  }

  Widget _pastelOrb({
    double? top,
    double? left,
    double? right,
    required double size,
    required List<Color> colors,
  }) {
    return Positioned(
      top: top,
      left: left,
      right: right,
      child: IgnorePointer(
        child: Container(
          width: size,
          height: size,
          decoration: BoxDecoration(
            shape: BoxShape.circle,
            gradient: RadialGradient(colors: [colors.first.withOpacity(0.40), colors.last.withOpacity(0.18), Colors.transparent]),
          ),
        ),
      ),
    );
  }

  Widget _glassPanel({
    required Widget child,
    EdgeInsetsGeometry padding = const EdgeInsets.all(16),
    double radius = 28,
  }) {
    final isLight = Theme.of(context).brightness == Brightness.light;
    final panel = Container(
      padding: padding,
      decoration: BoxDecoration(
        color: ngmyCrispSurfaceColor(context, elevated: true),
        borderRadius: BorderRadius.circular(radius),
        border: Border.all(color: ngmyCrispBorderColor(context), width: 1.2),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF8B5CF6).withValues(alpha: isLight ? 0.06 : 0.12),
            blurRadius: ngmyCrispUi ? 6 : 24,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: child,
    );
    if (ngmyPreferLightGraphics) return panel;
    return ngmyClipBackdrop(borderRadius: BorderRadius.circular(radius), sigma: 16, child: panel);
  }

