            if (mp)
              IconButton(
                icon: const Icon(Icons.person_add_rounded, color: Color(0xFFFBBF24)),
                tooltip: 'Invite player',
                onPressed: () => showMultiplayerInviteDialog(
                  context: context,
                  gameTitle: g.title,
