class _NgmyDiceGameHost extends StatefulWidget {
  final UserData user;
  final AppConfig config;
  final Function(AppTransaction) onAddTransaction;
  final VoidCallback onDataChanged;
  final VoidCallback onGameStarted;
  final VoidCallback? onGoToInvest;
  final List<String> missedDays;
  const _NgmyDiceGameHost({
    required this.user,
    required this.config,
    required this.onAddTransaction,
    required this.onDataChanged,
    required this.onGameStarted,
    this.onGoToInvest,
    this.missedDays = const [],
  });

  @override
  State<_NgmyDiceGameHost> createState() => _NgmyDiceGameHostState();
}

class _NgmyDiceGameHostState extends State<_NgmyDiceGameHost> with NgmyBalanceListener {
  late NgmyDiceSettings _dice;

  @override
  void initState() {
    super.initState();
    _dice = NgmyDiceSettings.fromJson(widget.config.diceSettings);
    NgmyGameSession.enterBetScreen('dice', 'Dice Roll');
  }

  @override
  void dispose() {
    NgmyGameSession.leaveBetScreen();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return NgmyDiceGameScreen(
      balanceOf: () => widget.user.accountBalance,
      userEmail: widget.user.email,
      diceSettings: _dice,
      onDiceSettingsChanged: () {
        widget.config.diceSettings = _dice.toJson();
        widget.onDataChanged();
        setState(() {});
      },
      onChargeBet: (bet, note) {
        if (!NgmyGameAccess.hasActiveInvestment(widget.user)) {
          if (NgmyGameAccess.sessionFreePlayConsumed(widget.user.email)) {
            unawaited(NgmyGameInvestmentPaywall.show(
              context,
              onGoToInvest: widget.onGoToInvest,
              missedDays: widget.missedDays,
            ));
            return false;
          }
          unawaited(NgmyGameAccess.markFreePlayUsed(widget.user.email));
        }
        final balance = ngmyLiveBalanceFor(widget.user.email, fallback: () => widget.user.accountBalance);
        if (balance < bet) return false;
        widget.user.points += 20;
        widget.onGameStarted();
        widget.onAddTransaction(
          AppTransaction(
            id: DateTime.now().microsecondsSinceEpoch.toString(),
            userEmail: widget.user.email,
            amount: bet,
            type: TransactionType.adminRemove,
            method: PaymentMethod.system,
            sourceDetails: note,
            status: TransactionStatus.approved,
            timestamp: DateTime.now(),
          ),
        );
        widget.onDataChanged();
        return true;
      },
      onPayout: (payout, note, {double bonus = 0}) {
        final txnId = DateTime.now().microsecondsSinceEpoch.toString();
        widget.onAddTransaction(
          AppTransaction(
            id: txnId,
            userEmail: widget.user.email,
            amount: payout,
            type: TransactionType.reimbursement,
            method: PaymentMethod.system,
            sourceDetails: note,
            status: TransactionStatus.approved,
            timestamp: DateTime.now(),
          ),
        );
        widget.onDataChanged();
        final detail = bonus > 0
            ? '+\$${payout.toStringAsFixed(2)} total (includes \$3 bonus for +3!)'
            : '+\$${payout.toStringAsFixed(2)} added to your balance';
        unawaited(NgmyGameNotifications.record(
          email: widget.user.email,
          gameTitle: 'Dice Roll',
          won: true,
          amount: payout,
          detail: detail,
          txnId: txnId,
        ));
      },
    );
  }
}

