      isDark: isDark,
      onPersistNow: () => ngmyAdminPersistManagementConfig(widget.config),
      onRefreshLoans: () async {
        await widget.onRefreshManagementData?.call();
        await NgmyLoanPhotosStore.applyTo(widget.config.loanApplications);
        await NgmyLoanStatusCloud.fetchAndApply(widget.config.loanApplications);
        await NgmyLoanPaymentsCloud.fetchAndApply(widget.config.loanApplications);
      },
    );
  }

  Future<void> _openPopupsAdmin(bool isDark) async {
    _showPopupsAdmin(isDark);
    unawaited(_refreshManagementInBackground());
  }

  void _showPopupsAdmin(bool isDark) {
    showNgmyPopupsAdminSheet(
      context: context,
      isDark: isDark,
      popups: widget.config.ngmyPopups,
      videoPopups: widget.config.ngmyVideoPopups,
      onUploadVideo: widget.onUploadPopupVideo,
      onSave: (popups, videos) async {
        widget.config.ngmyPopups = popups;
        widget.config.ngmyVideoPopups = videos;
        if (widget.onSavePopups != null) {
          final ok = await widget.onSavePopups!(popups, videos);
          if (!context.mounted) return ok;
          ngmyAdminShowCloudSaveSnackBar(
            context,
            cloudOk: ok,
            success: 'Pop-ups saved to cloud for all users.',
          );
          return ok;
        }
        final ok = await _persistManagementConfig();
        if (!context.mounted) return ok;
        ngmyAdminShowCloudSaveSnackBar(context, cloudOk: ok);
        return ok;
      },
    );
  }


