  void _showCivicRegistryAdmin(bool isDark) {
    final pending = NgmyAdminMenuCounts.pendingRegistrarApplications(widget.config.civicRegistrarApplications);
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (ctx) {
        return StatefulBuilder(
          builder: (ctx, setST) => Container(
          constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(ctx).height * 0.72),
          margin: const EdgeInsets.fromLTRB(14, 14, 14, 18),
          padding: const EdgeInsets.fromLTRB(20, 18, 20, 22),
          decoration: BoxDecoration(
            color: isDark ? const Color(0xFF0F111A) : Colors.white,
            borderRadius: BorderRadius.circular(26),
            border: Border.all(color: isDark ? Colors.white10 : const Color(0xFFE2E8F0)),
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const Text('Civic Registry', style: TextStyle(fontWeight: FontWeight.w900, fontSize: 20)),
              const SizedBox(height: 8),
              Text(
                'PIN, registrar requests, state limits, and per-state capacity (max $kNgmyMaxRegistrarsPerState per state).',
                style: TextStyle(fontSize: 12, color: isDark ? Colors.white60 : Colors.black54, height: 1.35),
              ),
              const SizedBox(height: 12),
              ListTile(
                  leading: const Icon(Icons.link_rounded, color: Color(0xFF6200EE)),
                  title: const Text('Copy enrollment link', style: TextStyle(fontWeight: FontWeight.w700)),
                  subtitle: const Text('Your own link — members who self-enroll through it are attributed to you'),
                  trailing: const Icon(Icons.copy_rounded, color: Color(0xFF6200EE)),
                  onTap: () async {
                    final link = ngmyCivicSelfEnrollmentShareUrl(state: widget.user.state, registrarEmail: widget.user.email);
                    await Clipboard.setData(ClipboardData(text: link));
                    if (!context.mounted) return;
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text('Enrollment link copied:\n$link'),
                        backgroundColor: const Color(0xFF059669),
                      ),
                    );
                  },
                ),
              ListTile(
                leading: const Icon(Icons.pin_rounded, color: Color(0xFF6200EE)),
                title: const Text('Registry PIN', style: TextStyle(fontWeight: FontWeight.w700)),
                subtitle: const Text('Per-state PINs + optional global fallback'),
                trailing: const Icon(Icons.chevron_right_rounded),
                onTap: () {
                  Navigator.pop(ctx);
                  _openCivicRegistryPinSheet(
                    context,
                    config: widget.config,
                    reviewer: widget.user,
                    onDataChanged: widget.onDataChanged,
                  );
                },
              ),
              ListTile(
                leading: const Icon(Icons.verified_user_rounded, color: Color(0xFF6200EE)),
                title: const Text('Registrar Applications', style: TextStyle(fontWeight: FontWeight.w700)),
                subtitle: Text('$pending pending request${pending == 1 ? '' : 's'}'),
                trailing: pending > 0
                    ? Container(
                        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                        decoration: BoxDecoration(color: Colors.red, borderRadius: BorderRadius.circular(12)),
                        child: Text('$pending', style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w900, fontSize: 11)),
                      )
                    : const Icon(Icons.chevron_right_rounded),
                onTap: () {
                  Navigator.pop(ctx);
                  showNgmyCivicRegistrarApplicationsSheet(
                    context,
                    config: widget.config,
                    allUsers: widget.allUsers,
                    reviewer: widget.user,
                    onDataChanged: widget.onDataChanged,
                  );
                },
              ),
              ListTile(
                leading: const Icon(Icons.map_rounded, color: Color(0xFF6200EE)),
                title: const Text('Manage Registry by State', style: TextStyle(fontWeight: FontWeight.w700)),
                subtitle: Text('Stats, registrars, Civic Registry Admin (max $kNgmyMaxRegistrarsPerState slots)'),
                trailing: const Icon(Icons.chevron_right_rounded),
                onTap: () {
                  Navigator.pop(ctx);
                  showNgmyManageRegistryByStateSheet(
                    context,
                    isDark: isDark,
                    usStates: const [
                      'Alabama', 'Alaska', 'Arizona', 'Arkansas', 'California', 'Colorado', 'Connecticut', 'Delaware', 'Florida', 'Georgia',
                      'Hawaii', 'Idaho', 'Illinois', 'Indiana', 'Iowa', 'Kansas', 'Kentucky', 'Louisiana', 'Maine', 'Maryland',
                      'Massachusetts', 'Michigan', 'Minnesota', 'Mississippi', 'Missouri', 'Montana', 'Nebraska', 'Nevada', 'New Hampshire', 'New Jersey',
                      'New Mexico', 'New York', 'North Carolina', 'North Dakota', 'Ohio', 'Oklahoma', 'Oregon', 'Pennsylvania', 'Rhode Island', 'South Carolina',
                      'South Dakota', 'Tennessee', 'Texas', 'Utah', 'Vermont', 'Virginia', 'Washington', 'West Virginia', 'Wisconsin', 'Wyoming',
                    ],
                    applications: widget.config.civicRegistrarApplications,
                    users: widget.allUsers.map(_civicRegistryUserRow).toList(),
                    readUsers: () => widget.allUsers.map(_civicRegistryUserRow).toList(),
                    onToggleKing: (email, on) {
                      final i = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email.toLowerCase().trim());
                      if (i == -1) return;
                      widget.allUsers[i].isCivicRegistryKing = on;
                      if (on) widget.allUsers[i].isAuthorizedRegistrar = true;
                      unawaited(_pushUserAuthorizedRegistrar(widget.allUsers[i]));
                      widget.onDataChanged();
                    },
                    onToggleRegistryAdmin: (email, on) {
                      final i = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email.toLowerCase().trim());
                      if (i == -1) return;
                      widget.allUsers[i].isCivicRegistryAdmin = on;
                      if (on) widget.allUsers[i].isAuthorizedRegistrar = true;
                      unawaited(_pushUserAuthorizedRegistrar(widget.allUsers[i]));
                      widget.onDataChanged();
                    },
                  );
                },
              ),
              ListTile(
                leading: const Icon(Icons.swap_horiz_rounded, color: Color(0xFF6200EE)),
                title: const Text('Transfer Member to Another State', style: TextStyle(fontWeight: FontWeight.w700)),
                subtitle: const Text('Move full civic record — profile, helps, claims, passport'),
                trailing: const Icon(Icons.chevron_right_rounded),
                onTap: () {
                  Navigator.pop(ctx);
                  final candidates = NgmyCivicRegistryMembers.listFrom(widget.config)
                      .map(NgmyCivicTransferCandidate.fromMember)
                      .toList()
                    ..sort((a, b) => a.fullName.toLowerCase().compareTo(b.fullName.toLowerCase()));
                  showNgmyTransferCivicMemberStateSheet(
                    context,
                    isDark: isDark,
                    usStates: const [
                      'Alabama', 'Alaska', 'Arizona', 'Arkansas', 'California', 'Colorado', 'Connecticut', 'Delaware', 'Florida', 'Georgia',
                      'Hawaii', 'Idaho', 'Illinois', 'Indiana', 'Iowa', 'Kansas', 'Kentucky', 'Louisiana', 'Maine', 'Maryland',
                      'Massachusetts', 'Michigan', 'Minnesota', 'Mississippi', 'Missouri', 'Montana', 'Nebraska', 'Nevada', 'New Hampshire', 'New Jersey',
                      'New Mexico', 'New York', 'North Carolina', 'North Dakota', 'Ohio', 'Oklahoma', 'Oregon', 'Pennsylvania', 'Rhode Island', 'South Carolina',
                      'South Dakota', 'Tennessee', 'Texas', 'Utah', 'Vermont', 'Virginia', 'Washington', 'West Virginia', 'Wisconsin', 'Wyoming',
                    ],
                    members: candidates,
                    onTransfer: ({required member, required fromState, required toState}) async {
                      return _adminTransferCivicMemberState(
                        email: member.email,
                        registryId: member.registryId,
                        toState: toState,
                      );
                    },
                  );
                },
              ),
              ListTile(
                leading: const Icon(Icons.restart_alt_rounded, color: Color(0xFF6200EE)),
                title: const Text('Reset State Change Limit', style: TextStyle(fontWeight: FontWeight.w700)),
                subtitle: Text('Search users — reset their ${NgmyCivicStateSwitches.maxSwitches} state changes / 1-hour lock'),
                trailing: const Icon(Icons.chevron_right_rounded),
                onTap: () {
                  Navigator.pop(ctx);
                  showNgmyResetCivicStateSwitchesSheet(
                    context,
                    isDark: isDark,
                    users: widget.allUsers.map(_civicRegistryUserRow).toList(),
                    onReset: (row) {
                      final i = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == row.email.toLowerCase().trim());
                      if (i == -1) return;
                      widget.allUsers[i].civicRegistryStateSwitchesUsed = 0;
                      unawaited(_pushUserAuthorizedRegistrar(widget.allUsers[i]));
                      unawaited(NgmyCivicStateSwitches.saveLocal(
                        email: widget.allUsers[i].email,
                        switchesUsed: 0,
                        anchorState: widget.allUsers[i].civicRegistryAnchorState,
                        lockedUntil: null,
                      ));
                      widget.onDataChanged();
                      if (!context.mounted) return;
                      ScaffoldMessenger.of(context).showSnackBar(
                        SnackBar(content: Text('${widget.allUsers[i].username} can change state ${NgmyCivicStateSwitches.maxSwitches} more times.')),
                      );
                    },
                  );
                },
              ),
            ],
          ),
        ),
        );
      },
    );
  }

  /// Admin / Civic Registry Admin only — move enrolled member to another state.
  Future<bool> _adminTransferCivicMemberState({
    required String email,
    required String registryId,
    required String toState,
  }) async {
    if (!(widget.user.isAdmin || widget.user.isCivicRegistryAdmin)) return false;
    final target = toState.trim();
    if (target.isEmpty) return false;
    final updated = NgmyCivicRegistryMembers.transferToState(
      widget.config,
      toState: target,
      email: email,
      registryId: registryId,
    );
    if (updated == null) return false;

    final emailKey = NgmyCivicRegistryMembers.emailKey(email);
    final oldRid = registryId.trim().toUpperCase();
    final newRid = (updated['registryId'] ?? '').toString().trim();
    void applyLinked(UserData u) {
      u.state = target;
      u.city = '';
      u.room = '';
      if (newRid.isNotEmpty) u.registryId = newRid;
      if (u.civicRegistryAnchorState.trim().isNotEmpty) {
        u.civicRegistryAnchorState = target;
      }
    }

    for (final u in widget.allUsers) {
      final sameEmail = emailKey.isNotEmpty && NgmyCivicRegistryMembers.emailKey(u.email) == emailKey;
      final sameId = oldRid.isNotEmpty && (u.registryId ?? '').trim().toUpperCase() == oldRid;
      if (sameEmail || sameId) applyLinked(u);
    }
    final selfEmail = NgmyCivicRegistryMembers.emailKey(widget.user.email);
    final selfId = (widget.user.registryId ?? '').trim().toUpperCase();
    if ((emailKey.isNotEmpty && selfEmail == emailKey) || (oldRid.isNotEmpty && selfId == oldRid)) {
      applyLinked(widget.user);
    }

    await NgmyCivicRegistryMembers.saveLocalBackup(widget.config);
    final cloudOk = await ngmyPersistCivicRegistryMembers(widget.config);
    NgmyAdminLiveRefresh.notify();
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(widget.config.toJson()));
      await prefs.setString('all_users', jsonEncode(widget.allUsers.map((e) => e.toJson()).toList()));
      if (emailKey.isNotEmpty && selfEmail == emailKey) {
        await prefs.setString('current_user', jsonEncode(widget.user.toJson()));
      }
    } catch (_) {}

    if (await ngmyCanReachCloud() && emailKey.isNotEmpty) {
      final idx = widget.allUsers.indexWhere((u) => NgmyCivicRegistryMembers.emailKey(u.email) == emailKey);
      if (idx >= 0) {
        try {
          await Supabase.instance.client
              .from('users')
              .upsert(
                {
                  'email': widget.allUsers[idx].email.trim().toLowerCase(),
                  'state': target,
                  'city': '',
                  'room': '',
                  'registryId': widget.allUsers[idx].registryId,
                  'civicRegistryAnchorState': widget.allUsers[idx].civicRegistryAnchorState,
                },
                onConflict: 'email',
              )
              .timeout(kNgmyCloudWriteTimeout);
        } catch (_) {}
      }
    }

    widget.onDataChanged();
    return cloudOk;
  }

