  void _showEditUserDialog(UserData u, bool isDark) {
    final nameC = TextEditingController(text: u.username);
    final emailC = TextEditingController(text: u.email);
    final phoneC = TextEditingController(text: u.phone);
    final fullC = TextEditingController(text: u.fullName ?? '');
    showDialog(context: context, builder: (c) => AlertDialog(
      title: const Text('Edit User'),
      content: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(controller: nameC, decoration: const InputDecoration(labelText: 'Username')),
            TextField(controller: emailC, decoration: const InputDecoration(labelText: 'Email')),
            TextField(controller: phoneC, decoration: const InputDecoration(labelText: 'Phone')),
            TextField(controller: fullC, decoration: const InputDecoration(labelText: 'Full Name')),
          ],
        ),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(c), child: const Text('CANCEL')),
        ElevatedButton(
          onPressed: () async {
            u.username = nameC.text.trim().isEmpty ? u.username : nameC.text.trim();
            u.email = emailC.text.trim().isEmpty ? u.email : emailC.text.trim();
            u.phone = phoneC.text.trim();
            u.fullName = fullC.text.trim().isEmpty ? u.fullName : fullC.text.trim();
            await _applyAdminUserAccountChange(
              u,
              apply: () {},
              snack: '${u.username} updated.',
            );
            unawaited(_pushUserProfileBasicsToCloud(u));
            if (c.mounted) Navigator.pop(c);
          },
          child: const Text('SAVE'),
        ),
      ],
    ));
  }

  List<UserData> _adminUsersForCurrentMode() {
    if (_adminUserListMode == 'civic') {
      return _civicRegistryMembersForDisplay(widget.config, widget.allUsers);
    }
    return widget.allUsers.where((u) => ngmyShowInAdminLoginUsersList(u, widget.config)).toList();
  }

  Widget _adminUsers(bool isDark) {
    final q = _query.trim().toLowerCase();
    final modeUsers = _adminUsersForCurrentMode();
    final filtered = modeUsers
        .where((u) => _userMatchesQuery(u, q))
        .toList()
      ..sort((a, b) => a.username.toLowerCase().compareTo(b.username.toLowerCase()));
    if (_selectedUserEmail != null) {
      UserData? selected;
      for (final x in modeUsers) {
        if (x.email.toLowerCase() == _selectedUserEmail!.toLowerCase()) {
          selected = x;
          break;
        }
      }
      if (selected != null) return _adminUserDetail(selected, isDark);
      _selectedUserEmail = null;
    }
    final panelBg = isDark ? const Color(0xFF1C1F2E) : Colors.white;
    final subtitle = _adminUserListMode == 'civic'
        ? 'Civic Registry (${filtered.length})'
        : 'NGMY accounts (${filtered.length})';
    return Column(children: [
      Padding(
        padding: const EdgeInsets.fromLTRB(15, 12, 15, 0),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            Expanded(
              child: Text(
                subtitle,
                style: TextStyle(fontSize: 11, color: isDark ? Colors.white54 : Colors.black54),
              ),
            ),
            SizedBox(
              height: 28,
              child: DropdownButtonHideUnderline(
                child: DropdownButton<String>(
                  value: _adminUserListMode,
                  isDense: true,
                  iconSize: 16,
                  style: TextStyle(fontSize: 10, color: isDark ? Colors.white70 : Colors.black87),
                  dropdownColor: panelBg,
                  items: const [
                    DropdownMenuItem(value: 'login', child: Text('Accounts')),
                    DropdownMenuItem(value: 'civic', child: Text('Civic Registry')),
                  ],
                  onChanged: (v) {
                    if (v == null) return;
                    setState(() {
                      _adminUserListMode = v;
                      _selectedUserEmail = null;
                    });
                  },
                ),
              ),
            ),
          ],
        ),
      ),
      Padding(
        padding: const EdgeInsets.all(15),
        child: TextField(
          controller: _search,
          style: TextStyle(color: isDark ? Colors.white : Colors.black),
          decoration: InputDecoration(
            hintText: 'Search by name, email, or account ID...',
            hintStyle: TextStyle(color: isDark ? Colors.white38 : Colors.grey),
            prefixIcon: Icon(Icons.search, color: isDark ? Colors.white38 : Colors.grey),
            filled: true,
            fillColor: panelBg,
            border: OutlineInputBorder(borderRadius: BorderRadius.circular(15), borderSide: BorderSide.none),
          ),
          onChanged: (v) => setState(() => _query = v.toLowerCase()),
        ),
      ),
      Expanded(
        child: ListView.builder(
          padding: const EdgeInsets.symmetric(horizontal: 15),
          itemCount: filtered.length,
          itemBuilder: (_, i) {
            final u = filtered[i];
            final displayBalance = ngmyAdminDisplayBalance(u, widget.allTransactions);
            final statusColor = u.status == 'active' ? Colors.green : u.status == 'suspended' ? Colors.orange : Colors.red;
            return Card(
              elevation: 0,
              color: panelBg,
              margin: const EdgeInsets.only(bottom: 10),
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(15)),
              child: ListTile(
                onTap: () => setState(() => _selectedUserEmail = u.email),
                leading: _adminUserAvatar(u, fallback: statusColor),
                title: Text(u.username, style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14, color: isDark ? Colors.white : Colors.black)),
                subtitle: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(u.email, style: TextStyle(fontSize: 11, color: isDark ? Colors.white38 : Colors.black54)),
                    Text(ngmyUserDisplayAccountId(u), style: TextStyle(fontSize: 10, color: isDark ? Colors.white30 : Colors.black38)),
                  ],
                ),
                isThreeLine: true,
                trailing: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  crossAxisAlignment: CrossAxisAlignment.end,
                  children: [
                    Text(
                      '\$${formatCurrency(displayBalance)}',
                      style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 13, color: Color(0xFF00B25A)),
                    ),
                    Icon(Icons.chevron_right, color: isDark ? Colors.white38 : Colors.black38, size: 18),
                  ],
                ),
              ),
            );
          },
        ),
      ),
    ]);
  }

  void _prompt(BuildContext ctx, String title, Function(String) onSave) {
    final ctrl = TextEditingController();
    showDialog(context: ctx, builder: (c) => AlertDialog(title: Text(title), content: TextField(controller: ctrl, keyboardType: TextInputType.number), actions: [TextButton(onPressed:()=>Navigator.pop(c), child:const Text('CANCEL')), ElevatedButton(onPressed: (){ onSave(ctrl.text); Navigator.pop(c); }, child:const Text('SAVE'))]));
  }
  Widget _sBtn(String l, IconData i, Color c, VoidCallback onTap) => ElevatedButton.icon(onPressed: onTap, icon: Icon(i, size: 14), label: Text(l, style: const TextStyle(fontSize: 10)), style: ElevatedButton.styleFrom(backgroundColor: c, foregroundColor: Colors.white));
}

