class LoanServiceScreen extends StatelessWidget {
  final UserData user;
  final AppConfig config;
  final VoidCallback onDataChanged;
  const LoanServiceScreen({super.key, required this.user, required this.config, required this.onDataChanged});

  @override
  Widget build(BuildContext context) {
    return NgmyLoanServicesScreen(
      userEmail: user.email,
      username: user.username,
      config: ngmyLoanConfigBridge(config),
      onDataChanged: onDataChanged,
      onPersistNow: () => ngmyUserPersistLoanApplications(config),
      onRefreshLoans: () async {
        await ngmyRefreshUserLoanApplications(config);
        await NgmyLoanPaymentsCloud.fetchAndApply(config.loanApplications);
      },
    );
  }
}

/// Scroll padding so list content can pass behind the floating bottom nav (like Media).
double _ngmyBottomNavScrollPadding(BuildContext context) {
  // Clear floating pill + outer pad so Core/Vault sit above the nav hit box.
  return NgmyBottomNavMetrics.barHeight + 56 + MediaQuery.paddingOf(context).bottom;
}

