  void _openEssentialTool(BuildContext ctx, String kind) {
    final name = widget.user.username.trim().isEmpty ? 'NGMY Member' : widget.user.username.trim();
    final email = widget.user.email.trim().isEmpty ? 'your@email.com' : widget.user.email.trim();
    late final String title;
    late final IconData icon;
    late final List<Color> colors;
    late final List<String> items;
    if (kind == 'signature') {
      _showEmailComposer(ctx, senderName: name, senderEmail: email);
      return;
    } else if (kind == 'text') {
      _showAnimatedMessageComposer(ctx);
      return;
    } else {
      title = 'Music & Fun Prompts';
      icon = Icons.music_note_rounded;
      colors = const [Color(0xFF10B981), Color(0xFF84CC16)];
      items = [
        'Create a smooth motivational song about building your future every day.',
        'Make an upbeat Afro-futuristic hook for NGMY: Next Generation - Make Yours.',
        'Write a short daily vibe: calm beat, confident voice, money-growth energy.',
        'Fun challenge: send one positive message, make one idea, and play one song that keeps you moving.',
      ];
    }
    _showEssentialSheet(ctx, title: title, icon: icon, colors: colors, items: items);
  }

  Future<void> _showEmailComposer(BuildContext ctx, {required String senderName, required String senderEmail}) {
    final toCtrl = TextEditingController();
    final subjectCtrl = TextEditingController(text: 'Quick update from $senderName');
    final messageCtrl = TextEditingController(text: 'Hello,\n\nI wanted to send you this quick update.\n\nThank you.');
    final titleCtrl = TextEditingController(text: 'NGMY Member');
    final brandCtrl = TextEditingController(text: 'NGMY Essential');
    final emailCardKey = GlobalKey();
    Uint8List? logoBytes;
    const colors = [Color(0xFF06B6D4), Color(0xFF2563EB)];

    String emailText() {
      final brand = brandCtrl.text.trim().isEmpty ? 'NGMY Essential' : brandCtrl.text.trim();
      final title = titleCtrl.text.trim().isEmpty ? 'NGMY Member' : titleCtrl.text.trim();
      return [
        messageCtrl.text.trim(),
        '',
        '------------------------------',
        brand,
        senderName,
        title,
        senderEmail,
        'Created with NGMY Essential',
        '------------------------------',
      ].join('\n');
    }

    Future<void> pickLogo(void Function(void Function()) setSheet, BuildContext sheetCtx) async {
      try {
        final file = await ImagePicker().pickImage(source: ImageSource.gallery, imageQuality: 85, maxWidth: 900);
        if (file == null) return;
        final bytes = await _readMediaPickerBytes(file);
        setSheet(() => logoBytes = bytes);
      } catch (e) {
        if (sheetCtx.mounted) {
          ScaffoldMessenger.of(sheetCtx).showSnackBar(SnackBar(content: Text('Logo upload failed: $e')));
        }
      }
    }

    Future<void> shareEmailCard(BuildContext sheetCtx) async {
      try {
        final bytes = await _captureEssentialPng(emailCardKey);
        final msg = await shareNgmyPngBytes(
          bytes,
          'ngmy_email_card_${DateTime.now().millisecondsSinceEpoch}.png',
          title: 'NGMY email card',
        );
        if (sheetCtx.mounted) {
          ScaffoldMessenger.of(sheetCtx).showSnackBar(SnackBar(content: Text(msg)));
        }
      } catch (e) {
        if (sheetCtx.mounted) {
          ScaffoldMessenger.of(sheetCtx).showSnackBar(SnackBar(content: Text('Share failed: $e')));
        }
      }
    }

    return showModalBottomSheet<void>(
      context: ctx,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetCtx) {
        final isDark = Theme.of(sheetCtx).brightness == Brightness.dark;
        final fg = isDark ? Colors.white : const Color(0xFF0F172A);
        final muted = isDark ? Colors.white70 : const Color(0xFF475569);
        return StatefulBuilder(
          builder: (context, setSheet) {
            final brand = brandCtrl.text.trim().isEmpty ? 'NGMY Essential' : brandCtrl.text.trim();
            final brandInitials = brand.substring(0, math.min(2, brand.length)).toUpperCase();
            final title = titleCtrl.text.trim().isEmpty ? 'NGMY Member' : titleCtrl.text.trim();
            return SafeArea(
              child: Container(
                constraints: BoxConstraints(maxHeight: MediaQuery.of(sheetCtx).size.height * 0.92),
                margin: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: isDark ? const Color(0xFF07111F) : Colors.white,
                  borderRadius: BorderRadius.circular(30),
                  border: Border.all(color: colors.first.withValues(alpha: 0.36)),
                  boxShadow: [BoxShadow(color: colors.last.withValues(alpha: 0.30), blurRadius: 34, offset: const Offset(0, 16))],
                ),
                child: SingleChildScrollView(
                  padding: const EdgeInsets.fromLTRB(18, 18, 18, 16),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Container(
                            width: 46,
                            height: 46,
                            decoration: BoxDecoration(borderRadius: BorderRadius.circular(16), gradient: const LinearGradient(colors: colors)),
                            child: const Icon(Icons.alternate_email_rounded, color: Colors.white, size: 25),
                          ),
                          const SizedBox(width: 12),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text('Email Signature Kit', style: TextStyle(color: fg, fontWeight: FontWeight.w900, fontSize: 21)),
                                const SizedBox(height: 3),
                                Text('Create a framed email with logo, subject, message, and signature.', style: TextStyle(color: muted, fontWeight: FontWeight.w600, fontSize: 12)),
                              ],
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 16),
                      _emailComposerField(toCtrl, label: 'Send to', hint: 'client@email.com', onChanged: () => setSheet(() {})),
                      const SizedBox(height: 10),
                      _emailComposerField(subjectCtrl, label: 'Subject', hint: 'Email subject', onChanged: () => setSheet(() {})),
                      const SizedBox(height: 10),
                      _emailComposerField(messageCtrl, label: 'Email message', hint: 'Write your email...', maxLines: 5, onChanged: () => setSheet(() {})),
                      const SizedBox(height: 10),
                      Row(
                        children: [
                          Expanded(child: _emailComposerField(brandCtrl, label: 'Brand / logo name', hint: 'Your brand', onChanged: () => setSheet(() {}))),
                          const SizedBox(width: 10),
                          Expanded(child: _emailComposerField(titleCtrl, label: 'Your title', hint: 'Founder / Creator', onChanged: () => setSheet(() {}))),
                        ],
                      ),
                      const SizedBox(height: 10),
                      InkWell(
                        onTap: () => unawaited(pickLogo(setSheet, sheetCtx)),
                        borderRadius: BorderRadius.circular(18),
                        child: Container(
                          width: double.infinity,
                          padding: const EdgeInsets.all(14),
                          decoration: BoxDecoration(
                            color: isDark ? Colors.white.withValues(alpha: 0.07) : const Color(0xFFF8FAFC),
                            borderRadius: BorderRadius.circular(18),
                            border: Border.all(color: colors.first.withValues(alpha: 0.28)),
                          ),
                          child: Row(
                            children: [
                              Container(
                                width: 42,
                                height: 42,
                                decoration: BoxDecoration(borderRadius: BorderRadius.circular(14), gradient: const LinearGradient(colors: colors)),
                                child: logoBytes == null ? const Icon(Icons.add_photo_alternate_rounded, color: Colors.white) : ClipRRect(borderRadius: BorderRadius.circular(14), child: Image.memory(logoBytes!, fit: BoxFit.cover)),
                              ),
                              const SizedBox(width: 12),
                              Expanded(
                                child: Text(
                                  logoBytes == null ? 'Upload logo from your phone' : 'Logo uploaded. Tap to change it.',
                                  style: TextStyle(color: fg, fontWeight: FontWeight.w800, fontSize: 13),
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                      const SizedBox(height: 16),
                      Text('Live Email Frame', style: TextStyle(color: fg, fontWeight: FontWeight.w900, fontSize: 14)),
                      const SizedBox(height: 10),
                      RepaintBoundary(
                        key: emailCardKey,
                        child: Container(
                          width: double.infinity,
                          padding: const EdgeInsets.all(16),
                          decoration: BoxDecoration(
                            borderRadius: BorderRadius.circular(24),
                            gradient: LinearGradient(
                              begin: Alignment.topLeft,
                              end: Alignment.bottomRight,
                              colors: isDark
                                  ? const [Color(0xFF121212), Color(0xFF121212), Color(0xFF1A1A1A)]
                                  : const [Color(0xFFFFFFFF), Color(0xFFE0F2FE), Color(0xFFF8FAFC)],
                            ),
                            border: Border.all(color: colors.first.withValues(alpha: 0.32)),
                          ),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(
                                children: [
                                  ClipRRect(
                                    borderRadius: BorderRadius.circular(18),
                                    child: Container(
                                      width: 62,
                                      height: 62,
                                      decoration: BoxDecoration(gradient: const LinearGradient(colors: colors), borderRadius: BorderRadius.circular(18)),
                                      child: logoBytes != null
                                          ? Image.memory(logoBytes!, fit: BoxFit.cover)
                                          : Center(child: Text(brandInitials, style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w900, fontSize: 18))),
                                    ),
                                  ),
                                  const SizedBox(width: 12),
                                  Expanded(
                                    child: Column(
                                      crossAxisAlignment: CrossAxisAlignment.start,
