  Widget _emailComposerField(
    TextEditingController controller, {
    required String label,
    required String hint,
    int maxLines = 1,
    required VoidCallback onChanged,
  }) {
    return TextField(
      controller: controller,
      maxLines: maxLines,
      onChanged: (_) => onChanged(),
      decoration: InputDecoration(
        labelText: label,
        hintText: hint,
        filled: true,
        fillColor: Colors.white.withValues(alpha: 0.08),
        border: OutlineInputBorder(borderRadius: BorderRadius.circular(16)),
      ),
    );
  }

  Future<void> _showAnimatedMessageComposer(BuildContext ctx) {
    final messageCtrl = TextEditingController(text: 'I am locked in right now. Give me a few and I will send you the clean version.');
    final messageCardKey = GlobalKey();
    const styleNames = ['Neon 3D', 'Glass Wave', 'Gold Pulse', 'Cosmic Bubble', 'Lava Pop', 'Ocean Spin', 'Candy Glow', 'Matrix Beam'];
    const palettes = [
      [Color(0xFF8B5CF6), Color(0xFFEC4899), Color(0xFF06B6D4)],
      [Color(0xFF06B6D4), Color(0xFF2563EB), Color(0xFFE0F2FE)],
      [Color(0xFFFFD166), Color(0xFFF59E0B), Color(0xFF7C2D12)],
      [Color(0xFF111827), Color(0xFF7C3AED), Color(0xFF22D3EE)],
      [Color(0xFFFF3B30), Color(0xFFFF7A00), Color(0xFFFFD60A)],
      [Color(0xFF0EA5E9), Color(0xFF14B8A6), Color(0xFFECFEFF)],
      [Color(0xFFFF5DA2), Color(0xFF8B5CF6), Color(0xFFFFE4F2)],
      [Color(0xFF052E16), Color(0xFF22C55E), Color(0xFFBBF7D0)],
    ];
    var selectedStyle = 0;

    String shareText() {
      final text = messageCtrl.text.trim().isEmpty ? 'Your message' : messageCtrl.text.trim();
      return text;
    }

    Future<void> shareMessageCard(BuildContext sheetCtx) async {
      try {
        final bytes = await _captureEssentialGif(messageCardKey);
        final msg = await shareNgmyBytes(
          bytes,
          'ngmy_message_${DateTime.now().millisecondsSinceEpoch}.gif',
          mimeType: 'image/gif',
        );
        if (sheetCtx.mounted) {
          ScaffoldMessenger.of(sheetCtx).showSnackBar(SnackBar(content: Text(msg)));
        }
      } catch (e) {
        if (sheetCtx.mounted) {
          ScaffoldMessenger.of(sheetCtx).showSnackBar(SnackBar(content: Text('Animated share failed: $e')));
        }
      }
    }

    return showModalBottomSheet<void>(
      context: ctx,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetCtx) {
        final isDark = Theme.of(sheetCtx).brightness == Brightness.dark;
        final fg = isDark ? Colors.white : const Color(0xFF0F172A);
        final muted = isDark ? Colors.white70 : const Color(0xFF475569);
        return StatefulBuilder(
          builder: (context, setSheet) {
            final colors = palettes[selectedStyle];
            final text = messageCtrl.text.trim().isEmpty ? 'Type your message and watch the animation take shape.' : messageCtrl.text.trim();
            return SafeArea(
              child: Container(
                constraints: BoxConstraints(maxHeight: MediaQuery.of(sheetCtx).size.height * 0.92),
                margin: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: isDark ? const Color(0xFF070A16) : Colors.white,
                  borderRadius: BorderRadius.circular(30),
                  border: Border.all(color: colors[1].withValues(alpha: 0.36)),
                  boxShadow: [BoxShadow(color: colors[1].withValues(alpha: 0.28), blurRadius: 36, offset: const Offset(0, 16))],
                ),
                child: SingleChildScrollView(
                  padding: const EdgeInsets.fromLTRB(18, 18, 18, 16),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Container(
                            width: 46,
                            height: 46,
                            decoration: BoxDecoration(borderRadius: BorderRadius.circular(16), gradient: LinearGradient(colors: colors)),
                            child: const Icon(Icons.chat_bubble_rounded, color: Colors.white, size: 24),
                          ),
                          const SizedBox(width: 12),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text('Animated iMessage Text', style: TextStyle(color: fg, fontWeight: FontWeight.w900, fontSize: 21)),
                                const SizedBox(height: 3),
                                Text('Type a message, choose a motion style, then share it through iMessage.', style: TextStyle(color: muted, fontWeight: FontWeight.w600, fontSize: 12)),
                              ],
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 16),
                      TextField(
                        controller: messageCtrl,
                        minLines: 3,
                        maxLines: 5,
                        onChanged: (_) => setSheet(() {}),
                        decoration: InputDecoration(
                          labelText: 'Your animated message',
                          hintText: 'Type something cool...',
                          filled: true,
                          fillColor: isDark ? Colors.white.withValues(alpha: 0.07) : const Color(0xFFF8FAFC),
                          border: OutlineInputBorder(borderRadius: BorderRadius.circular(18)),
                        ),
                      ),
                      const SizedBox(height: 14),
                      Wrap(
                        spacing: 8,
                        runSpacing: 8,
                        children: List.generate(styleNames.length, (i) {
                          final selected = selectedStyle == i;
                          return ChoiceChip(
                            selected: selected,
                            label: Text(styleNames[i]),
                            onSelected: (_) => setSheet(() => selectedStyle = i),
                            selectedColor: palettes[i][1].withValues(alpha: 0.26),
                            labelStyle: TextStyle(color: selected ? fg : muted, fontWeight: FontWeight.w800),
                            side: BorderSide(color: palettes[i][1].withValues(alpha: selected ? 0.72 : 0.24)),
                          );
                        }),
                      ),
                      const SizedBox(height: 16),
                      Text('Animated Preview', style: TextStyle(color: fg, fontWeight: FontWeight.w900, fontSize: 14)),
                      const SizedBox(height: 10),
                      RepaintBoundary(
                        key: messageCardKey,
                        child: _animatedMessagePreview(text: text, colors: colors, styleIndex: selectedStyle, isDark: isDark),
                      ),
                      const SizedBox(height: 16),
                      Row(
                        children: [
                          Expanded(
                            child: OutlinedButton.icon(
                              onPressed: () {
                                Clipboard.setData(ClipboardData(text: shareText()));
                                ScaffoldMessenger.of(sheetCtx).showSnackBar(const SnackBar(content: Text('Animated text copied')));
                              },
                              icon: const Icon(Icons.copy_rounded),
                              label: const Text('Copy'),
                            ),
                          ),
                          const SizedBox(width: 10),
                          Expanded(
                            child: FilledButton.icon(
                              onPressed: () => unawaited(shareMessageCard(sheetCtx)),
                              style: FilledButton.styleFrom(backgroundColor: colors[1]),
                              icon: const Icon(Icons.ios_share_rounded),
                              label: const Text('Share GIF'),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        );
      },
    ).whenComplete(messageCtrl.dispose);
  }

  Widget _animatedMessagePreview({
    required String text,
    required List<Color> colors,
    required int styleIndex,
    required bool isDark,
  }) {
    return StreamBuilder<int>(
      stream: Stream.periodic(const Duration(milliseconds: 900), (tick) => tick),
      initialData: 0,
      builder: (context, snapshot) {
        final tick = snapshot.data ?? 0;
        final pulse = 0.5 + (0.5 * math.sin(tick * 0.85));
        final tilt = (pulse - 0.5) * 0.07;
        final radius = 26.0 + pulse * 4;
        final shadow = 16.0 + pulse * 12;
        final isGold = styleIndex == 2;
        return TweenAnimationBuilder<double>(
          tween: Tween<double>(begin: 0, end: pulse),
          duration: const Duration(milliseconds: 820),
          curve: Curves.easeInOutCubic,
          builder: (context, value, _) {
            return Transform(
              alignment: Alignment.center,
              transform: Matrix4.identity()
                ..setEntry(3, 2, 0.0012)
                ..rotateY(styleIndex == 0 ? tilt : 0)
                ..rotateZ(styleIndex == 1 ? tilt * 0.45 : 0),
              child: Container(
                width: double.infinity,
                padding: const EdgeInsets.all(18),
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(radius),
                  gradient: LinearGradient(
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                    colors: [
                      colors[0].withValues(alpha: 0.92),
                      colors[1].withValues(alpha: 0.86),
                      colors[2].withValues(alpha: isGold ? 0.72 : 0.82),
                    ],
                  ),
                  border: Border.all(color: Colors.white.withValues(alpha: 0.34 + value * 0.26), width: 1.2),
                  boxShadow: [
                    BoxShadow(color: colors[1].withValues(alpha: 0.26 + value * 0.24), blurRadius: shadow, offset: Offset(0, 10 + value * 5)),
                    BoxShadow(color: Colors.white.withValues(alpha: isDark ? 0.06 : 0.30), blurRadius: 10, offset: const Offset(-4, -4)),
                  ],
                ),
                child: Stack(
                  children: [
                    Positioned(right: -16, top: -18, child: _messageOrb(colors[2], 78 + value * 10)),
                    Positioned(left: -14, bottom: -20, child: _messageOrb(colors[0], 64 + value * 8)),
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          text,
                          style: TextStyle(
                            color: Colors.white,
                            fontWeight: FontWeight.w900,
                            fontSize: 23 + value * 0.6,
                            height: 1.08,
                            letterSpacing: styleIndex == 0 ? -0.4 : 0,
                            shadows: [
                              Shadow(color: Colors.black.withValues(alpha: 0.22), blurRadius: 6, offset: const Offset(0, 2)),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );
  }

  Widget _messageOrb(Color color, double size) {
    return IgnorePointer(
      child: Container(
        width: size,
        height: size,
        decoration: BoxDecoration(
          shape: BoxShape.circle,
          gradient: RadialGradient(colors: [Colors.white.withValues(alpha: 0.32), color.withValues(alpha: 0.12), Colors.transparent]),
        ),
      ),
    );
  }

  Future<Uint8List> _captureEssentialPng(GlobalKey key) async {
    await Future.delayed(const Duration(milliseconds: 120));
    await WidgetsBinding.instance.endOfFrame;
    final boundary = key.currentContext?.findRenderObject() as RenderRepaintBoundary?;
    if (boundary == null) throw Exception('Preview is not ready yet.');
    final image = await boundary.toImage(pixelRatio: 3.0);
    final bytes = (await image.toByteData(format: ui.ImageByteFormat.png))?.buffer.asUint8List();
    if (bytes == null || bytes.isEmpty) throw Exception('Could not create image.');
    return bytes;
  }

  Future<Uint8List> _captureEssentialGif(GlobalKey key) async {
    final frames = <({int width, int height, Uint8List rgba})>[];
    for (var i = 0; i < 12; i++) {
      await Future.delayed(const Duration(milliseconds: 100));
      await WidgetsBinding.instance.endOfFrame;
      final boundary = key.currentContext?.findRenderObject() as RenderRepaintBoundary?;
      if (boundary == null) throw Exception('Preview is not ready yet.');
      final image = await boundary.toImage(pixelRatio: 2.35);
      final data = await image.toByteData(format: ui.ImageByteFormat.rawRgba);
      if (data == null) throw Exception('Could not create animation frame.');
      frames.add((width: image.width, height: image.height, rgba: data.buffer.asUint8List()));
      image.dispose();
    }
    return _encodeEssentialGif(frames, delayCs: 10);
  }

  Uint8List _encodeEssentialGif(List<({int width, int height, Uint8List rgba})> frames, {required int delayCs}) {
    if (frames.isEmpty) throw Exception('No animation frames were created.');
    final width = frames.first.width;
    final height = frames.first.height;
    final out = <int>[];
    void byte(int v) => out.add(v & 0xFF);
    void word(int v) {
      byte(v);
      byte(v >> 8);
    }

    out.addAll('GIF89a'.codeUnits);
    word(width);
    word(height);
    byte(0xF7);
    byte(0);
    byte(0);
    out.addAll(_essentialGifPalette());
    out.addAll([0x21, 0xFF, 0x0B, ...'NETSCAPE2.0'.codeUnits, 0x03, 0x01, 0x00, 0x00, 0x00]);

    for (final frame in frames) {
      if (frame.width != width || frame.height != height) continue;
      final indexed = _essentialGifIndexedPixels(frame.rgba);
      out.addAll([0x21, 0xF9, 0x04, 0x00]);
      word(delayCs);
      out.addAll([0x00, 0x00, 0x2C]);
      word(0);
      word(0);
      word(width);
      word(height);
      byte(0x00);
      byte(8);
      final lzw = _essentialGifLzw(indexed);
      for (var i = 0; i < lzw.length; i += 255) {
        final end = math.min(i + 255, lzw.length);
        byte(end - i);
        out.addAll(lzw.sublist(i, end));
      }
      byte(0);
    }
    byte(0x3B);
    return Uint8List.fromList(out);
  }

  List<int> _essentialGifPalette() {
    final palette = <int>[];
    const levels = [0, 51, 102, 153, 204, 255];
    for (final r in levels) {
      for (final g in levels) {
        for (final b in levels) {
          palette.addAll([r, g, b]);
        }
      }
    }
    for (var i = 0; i < 40; i++) {
      final v = (i * 255 / 39).round();
      palette.addAll([v, v, v]);
    }
    while (palette.length < 256 * 3) {
      palette.addAll([0, 0, 0]);
    }
    return palette.take(256 * 3).toList();
  }

  Uint8List _essentialGifIndexedPixels(Uint8List rgba) {
    final out = Uint8List(rgba.length ~/ 4);
    for (var i = 0, p = 0; i < rgba.length; i += 4, p++) {
      final a = rgba[i + 3];
      final r = a < 20 ? 255 : rgba[i];
      final g = a < 20 ? 255 : rgba[i + 1];
      final b = a < 20 ? 255 : rgba[i + 2];
      final ri = (r * 5 / 255).round().clamp(0, 5);
      final gi = (g * 5 / 255).round().clamp(0, 5);
      final bi = (b * 5 / 255).round().clamp(0, 5);
      out[p] = (ri * 36 + gi * 6 + bi).toInt();
    }
    return out;
  }

  List<int> _essentialGifLzw(Uint8List pixels) {
    const clear = 256;
    const end = 257;
    final out = <int>[];
    var buffer = 0;
    var bits = 0;
    void code(int value) {
      buffer |= value << bits;
      bits += 9;
      while (bits >= 8) {
        out.add(buffer & 0xFF);
        buffer >>= 8;
        bits -= 8;
      }
    }

    code(clear);
    var sinceClear = 0;
    for (final px in pixels) {
      code(px);
      sinceClear++;
      if (sinceClear >= 240) {
        code(clear);
        sinceClear = 0;
      }
    }
    code(end);
    if (bits > 0) out.add(buffer & 0xFF);
    return out;
  }

