  Widget _planRow(BuildContext ctx, InvestmentPlan p) {
    final user = widget.user;
    final cur = user.totalInvestmentAmount;
    final price = p.price;
    final diff = price - cur;
    final daily = p.dailyIncome;
    final total = p.totalReturn;

    final active = user.activeInvestment;
    final isExpired = active != null && active.daysLeft <= 0;

    final hasActivePlan = active != null && !isExpired;
    bool isCurrent = hasActivePlan && active!.name == p.name && price == active.amount;
    bool isUpgrade = hasActivePlan && price > active.amount;
    bool isDowngrade = hasActivePlan && price < active.amount;
    final pendingSamePlan = user.pendingInvestmentName == p.name &&
        user.pendingInvestmentAmount != null &&
        (user.pendingInvestmentAmount! - price).abs() < 0.0001;

    String buttonText = "Invest Now";
    if (isCurrent) {
      buttonText = "Active";
    } else if (isUpgrade) {
      buttonText = "Upgrade Now";
    } else if (isExpired && price == (active?.amount ?? 0)) {
      buttonText = "Renew Plan";
    }
    if (!isCurrent && !isDowngrade && pendingSamePlan) {
      buttonText = "Waiting for Deposit";
    }

    final isRenewSamePlan = isExpired && active != null && (price - active.amount).abs() < 0.0001;
    final requiredPayment = isRenewSamePlan ? price : math.max(0.0, diff);
    final canBuyNow = !isCurrent && !isDowngrade && !pendingSamePlan && requiredPayment > 0 && user.accountBalance >= requiredPayment;

    if (isCurrent) {
      buttonText = "Active";
    } else if (isDowngrade) {
      buttonText = "Downgrade Locked";
    } else if (pendingSamePlan) {
      buttonText = "Waiting for Deposit";
    } else if (canBuyNow) {
      buttonText = "Buy";
    } else if (isUpgrade) {
      buttonText = "Upgrade Now";
    } else if (isRenewSamePlan) {
      buttonText = "Renew Plan";
    } else {
      buttonText = "Invest Now";
    }

    final disableButton = isCurrent || isDowngrade || pendingSamePlan || widget.purchaseInFlight;

    // Platinum metal for available plans — active asset card stays gold.
    const textColor = Color(0xFF0F172A);
    const subColor = Color(0xFF475569);
    const cardBorderColor = Color(0xFFF8FAFC);
    const labelColor = Color(0xFFE2E8F0);

    return Container(
      margin: const EdgeInsets.only(bottom: 14),
      width: double.infinity,
      padding: const EdgeInsets.fromLTRB(12, 11, 12, 10),
      decoration: BoxDecoration(
        gradient: const LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            Color(0xFF1E293B),
            Color(0xFF334155),
            Color(0xFF94A3B8),
            Color(0xFFE2E8F0),
            Color(0xFFF8FAFC),
            Color(0xFFCBD5E1),
            Color(0xFF64748B),
          ],
          stops: [0.0, 0.18, 0.38, 0.52, 0.62, 0.78, 1.0],
        ),
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: cardBorderColor, width: 2),
        boxShadow: [
          BoxShadow(color: Colors.white.withOpacity(0.35), blurRadius: 16, offset: const Offset(-2, -2)),
          BoxShadow(color: const Color(0xFF64748B).withOpacity(0.45), blurRadius: 14, offset: const Offset(0, 8)),
          BoxShadow(color: Colors.black.withOpacity(0.2), blurRadius: 8, offset: const Offset(0, 4)),
        ],
      ),
      child: Stack(
        clipBehavior: Clip.none,
        children: [
          Positioned(
            right: -28,
            top: -32,
            child: Container(
              width: 110,
              height: 110,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                gradient: RadialGradient(
                  colors: [Colors.white.withOpacity(0.35), Colors.white.withOpacity(0.0)],
                ),
              ),
            ),
          ),
          Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  _diamondCardChip(),
                  const Spacer(),
                  _tapPayBadge(ctx, forceLight: true),
                ],
              ),
              const SizedBox(height: 2),
              const Text('NGMY PLATINUM', style: TextStyle(color: labelColor, fontSize: 9, letterSpacing: 1.4, fontWeight: FontWeight.w900)),
              const SizedBox(height: 2),
              CopyOnHoldText(p.name, style: const TextStyle(color: textColor, fontWeight: FontWeight.w900, fontSize: 14), maxLines: 1, overflow: TextOverflow.ellipsis),
              const SizedBox(height: 3),
              CopyOnHoldText(
                _pseudoCardNumber(price),
                style: const TextStyle(color: textColor, fontWeight: FontWeight.w700, fontSize: 11, letterSpacing: 0.8),
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
              const SizedBox(height: 5),
              Row(
                children: [
                  _planTagPlatinum('${(InvestmentPlan.fixedRoi * 100).toStringAsFixed(2)}%'),
                  const SizedBox(width: 5),
                  _planTagPlatinum('261d'),
                ],
              ),
              const SizedBox(height: 5),
              Row(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text('PLAN VALUE', style: TextStyle(color: subColor, fontSize: 8, fontWeight: FontWeight.w700)),
                        CopyOnHoldText('\$${formatCurrency(price)}', style: const TextStyle(color: textColor, fontWeight: FontWeight.w900, fontSize: 16), maxLines: 1, overflow: TextOverflow.ellipsis),
                      ],
                    ),
                  ),
                  Text(
                    isCurrent ? 'ACTIVE' : (isUpgrade ? 'UPGRADE' : 'AVAILABLE'),
                    style: const TextStyle(color: textColor, fontWeight: FontWeight.w800, fontSize: 9),
                  ),
                ],
              ),
              const SizedBox(height: 5),
              Container(height: 1, color: subColor.withOpacity(0.35)),
              const SizedBox(height: 5),
              Row(
                children: [
                  Expanded(child: _planInfoBoxPlatinum('Daily', '\$${formatCurrency(daily)}')),
                  const SizedBox(width: 5),
                  Expanded(child: _planInfoBoxPlatinum('Total', '\$${formatCurrency(total)}')),
                  const SizedBox(width: 5),
                  Expanded(child: _planInfoBoxPlatinum('Days', '261')),
                ],
              ),
              const SizedBox(height: 8),
              SizedBox(
                width: double.infinity,
                height: 40,
                child: ElevatedButton(
                  onPressed: disableButton
                      ? null
                      : () => widget.onInvest(p.name, price, InvestmentPlan.fixedRoi, requiredPayment),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF1E293B),
                    foregroundColor: const Color(0xFFF8FAFC),
                    disabledBackgroundColor: const Color(0xFF64748B).withOpacity(0.5),
                    disabledForegroundColor: const Color(0xFFE2E8F0).withOpacity(0.5),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(10),
                      side: const BorderSide(color: Color(0xFFCBD5E1), width: 0.8),
                    ),
                    elevation: 3,
                  ),
                  child: FittedBox(
                    fit: BoxFit.scaleDown,
                    child: Text(
                      widget.purchaseInFlight ? 'PROCESSING...' : buttonText.toUpperCase(),
                      style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 11),
                    ),
                  ),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _planTagPlatinum(String text) => Container(
    padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
    decoration: BoxDecoration(
      color: Colors.white.withOpacity(0.45),
      borderRadius: BorderRadius.circular(5),
      border: Border.all(color: const Color(0xFFCBD5E1)),
    ),
    child: Text(text, style: const TextStyle(color: Color(0xFF1E293B), fontSize: 9, fontWeight: FontWeight.w800)),
  );

  Widget _planInfoBoxPlatinum(String label, String value) => Container(
    padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 5),
    decoration: BoxDecoration(
      color: Colors.white.withOpacity(0.38),
      borderRadius: BorderRadius.circular(7),
      border: Border.all(color: const Color(0xFFE2E8F0)),
    ),
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(label, style: const TextStyle(color: Color(0xFF475569), fontSize: 7, fontWeight: FontWeight.w700)),
        const SizedBox(height: 1),
        FittedBox(
          alignment: Alignment.centerLeft,
          child: Text(value, style: const TextStyle(color: Color(0xFF0F172A), fontWeight: FontWeight.w800, fontSize: 10)),
        ),
      ],
    ),
  );

  Widget _tag(BuildContext ctx, String text) {
    final isDark = Theme.of(ctx).brightness == Brightness.dark;
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: isDark ? Colors.white.withOpacity(0.10) : const Color(0xFF334155).withOpacity(0.08),
        borderRadius: BorderRadius.circular(5),
        border: Border.all(color: isDark ? Colors.white24 : const Color(0xFFCBD5E1)),
      ),
      child: Text(text, style: TextStyle(color: isDark ? Colors.white70 : const Color(0xFF334155), fontSize: 10, fontWeight: FontWeight.bold)),
    );
  }

  Widget _infoBox(BuildContext ctx, String label, String value, {bool compact = false}) {
    final isDark = Theme.of(ctx).brightness == Brightness.dark;
    return Container(
      padding: EdgeInsets.all(compact ? 6 : 10),
      decoration: BoxDecoration(
        color: isDark ? Colors.white.withOpacity(0.05) : Colors.white.withOpacity(0.72),
        borderRadius: BorderRadius.circular(compact ? 8 : 10),
        border: Border.all(color: isDark ? Colors.white10 : const Color(0xFFE2E8F0)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(label, style: TextStyle(color: isDark ? Colors.white60 : const Color(0xFF64748B), fontSize: compact ? 8 : 10)),
          SizedBox(height: compact ? 2 : 4),
          Text(
            value,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(color: isDark ? Colors.white : const Color(0xFF0F172A), fontWeight: FontWeight.bold, fontSize: compact ? 11 : 14),
          ),
        ],
      ),
    );
  }
}

class _NgmyAiAdminSheet extends StatefulWidget {
  final bool isDark;
  final AppConfig config;
  final VoidCallback onDataChanged;
  final Future<bool> Function(String apiKey) persistGeminiKey;
  final Future<bool> Function()? onPersistManagement;
  final InputDecoration Function({required String label, required bool isDark, String? hint}) adminInputDecoration;

  const _NgmyAiAdminSheet({
    required this.isDark,
    required this.config,
    required this.onDataChanged,
    required this.persistGeminiKey,
    this.onPersistManagement,
    required this.adminInputDecoration,
  });

  @override
  State<_NgmyAiAdminSheet> createState() => _NgmyAiAdminSheetState();
}

class _NgmyAiAdminSheetState extends State<_NgmyAiAdminSheet> {
  late final TextEditingController _apiC;
  late final TextEditingController _youtubeC;
  late final TextEditingController _elevenLabsC;
  late final TextEditingController _resendC;
  late final TextEditingController _resendFromC;
  late final TextEditingController _helperLimitC;
  late final TextEditingController _logoC;
  final ImagePicker _picker = ImagePicker();
  final ScrollController _scrollC = ScrollController();
  final FocusNode _elevenLabsFocus = FocusNode();
  final GlobalKey _elevenLabsFieldKey = GlobalKey();
  Uint8List? _pendingLogoBytes;
  bool _logoUploading = false;
  bool _apiKeyVisible = false;
  bool _youtubeKeyVisible = false;
  bool _elevenLabsKeyVisible = false;
  bool _resendKeyVisible = false;

  @override
  void initState() {
    super.initState();
    _apiC = TextEditingController(text: widget.config.geminiApiKey);
    _youtubeC = TextEditingController(text: widget.config.youtubeApiKey);
    _elevenLabsC = TextEditingController(text: widget.config.elevenLabsApiKey);
    _resendC = TextEditingController(text: widget.config.resendApiKey);
    _resendFromC = TextEditingController(text: widget.config.resendFromEmail);
    _helperLimitC = TextEditingController(text: widget.config.ngmyHelperDailyMessageLimit.toString());
    _logoC = TextEditingController(text: widget.config.logoUrl);
    _elevenLabsFocus.addListener(_onElevenLabsFocus);
  }

  void _onElevenLabsFocus() {
    if (!_elevenLabsFocus.hasFocus) return;
    Future<void>.delayed(const Duration(milliseconds: 320), () {
      if (!mounted) return;
      final ctx = _elevenLabsFieldKey.currentContext;
      if (ctx != null) {
        Scrollable.ensureVisible(
          ctx,
          duration: const Duration(milliseconds: 280),
          curve: Curves.easeOutCubic,
          alignment: 0.35,
        );
      }
    });
  }

  @override
  void dispose() {
    _elevenLabsFocus.removeListener(_onElevenLabsFocus);
    _elevenLabsFocus.dispose();
    _scrollC.dispose();
    _apiC.dispose();
    _youtubeC.dispose();
    _elevenLabsC.dispose();
    _resendC.dispose();
    _resendFromC.dispose();
    _helperLimitC.dispose();
    _logoC.dispose();
    super.dispose();
  }

  Future<void> _showAiApiKeyHelp() async {
    final key = _apiC.text.trim();
    final provider = key.isEmpty ? 'Not set' : ngmyAiProviderLabel(ngmyParseAiCredentials(key).provider);
    await showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Row(
          children: [
            Icon(Icons.info_outline, color: Color(0xFF3B82F6)),
            SizedBox(width: 8),
            Text('AI API Key'),
          ],
        ),
        content: SingleChildScrollView(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text('Detected provider: $provider', style: const TextStyle(fontWeight: FontWeight.w700)),
              const SizedBox(height: 10),
              if (key.isNotEmpty) ...[
                const Text('Current key:', style: TextStyle(fontWeight: FontWeight.w600, fontSize: 12)),
                const SizedBox(height: 4),
                SelectableText(key, style: const TextStyle(fontFamily: 'monospace', fontSize: 12)),
                const SizedBox(height: 12),
              ],
              const Text(
                'Supported keys:\n'
                '• Google Gemini — starts with AIza…\n'
                '• OpenAI — starts with sk-…\n'
                '• Claude — starts with sk-ant-…\n'
                '• Other APIs — compat:https://api.example.com/v1|your-key\n\n'
                'Tap the eye icon on the field to show or hide the key while editing.',
                style: TextStyle(fontSize: 13, height: 1.4),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Close')),
        ],
      ),
    );
  }

  Future<void> _pickAppLogoImage() async {
    final img = await _picker.pickImage(source: ImageSource.gallery, imageQuality: 82, maxWidth: 512);
    if (img == null) return;
    final bytes = await img.readAsBytes();
    setState(() {
      _pendingLogoBytes = bytes;
      _logoC.text = '';
    });
  }

  Future<String> _resolveLogoForSave() async {
    final urlText = _logoC.text.trim();
    if (_pendingLogoBytes != null) {
      setState(() => _logoUploading = true);
      try {
        final path = 'branding/app_logo_${DateTime.now().millisecondsSinceEpoch}.jpg';
        final upload = await _uploadNgmyMediaBytes(
          bytes: _pendingLogoBytes!,
          storagePath: path,
          contentType: 'image/jpeg',
        );
        if (upload.ref != null) return upload.ref!;
        return 'data:image/jpeg;base64,${base64Encode(_pendingLogoBytes!)}';
      } finally {
        if (mounted) setState(() => _logoUploading = false);
      }
    }
    return urlText.isNotEmpty ? urlText : widget.config.logoUrl;
  }

  Widget _appLogoPreview(bool isDark) {
    const size = 56.0;
    if (_pendingLogoBytes != null) {
      return ClipRRect(
        borderRadius: BorderRadius.circular(12),
        child: Image.memory(_pendingLogoBytes!, width: size, height: size, fit: BoxFit.cover),
      );
    }
    return ClipRRect(
      borderRadius: BorderRadius.circular(12),
      child: _ngmyLogoImage(
        _logoC.text.trim().isNotEmpty ? _logoC.text.trim() : widget.config.logoUrl,
        width: size,
        height: size,
      ),
    );
  }

  Future<void> _saveSettings() async {
    widget.config.logoUrl = await _resolveLogoForSave();
    widget.config.geminiApiKey = _apiC.text.trim();
    widget.config.youtubeApiKey = _youtubeC.text.trim();
    widget.config.elevenLabsApiKey = _elevenLabsC.text.trim();
    widget.config.resendApiKey = _resendC.text.trim();
    widget.config.resendFromEmail = _resendFromC.text.trim().isEmpty ? NgmyResendEmail.defaultFrom : _resendFromC.text.trim();
    await NgmyElevenLabsTts.persistLocalKey(widget.config.elevenLabsApiKey);
    await NgmyResendEmail.persistLocalKey(widget.config.resendApiKey);
    await NgmyResendEmail.persistLocalFrom(widget.config.resendFromEmail);
    final helperLimit = int.tryParse(_helperLimitC.text.trim());
    if (helperLimit == null || helperLimit < 0) {
      if (!context.mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Enter a valid daily message limit (0 or more).')),
      );
      return;
    }
    widget.config.ngmyHelperDailyMessageLimit = helperLimit;
    var geminiSynced = true;
    if (widget.config.geminiApiKey.isNotEmpty) {
      geminiSynced = await widget.persistGeminiKey(widget.config.geminiApiKey);
    }
    await ngmyFlushCriticalConfigLocalAndCloud(widget.config, cloud: false);
    final brandingOk = await ngmyPersistAppBrandingSettings(widget.config);
    final helperOk = await ngmyPersistHelperAiSettings(widget.config);
    if (mounted) {
      setState(() {
        _pendingLogoBytes = null;
        _logoC.text = widget.config.logoUrl;
      });
    }
    widget.onDataChanged();
    final mgmtOk = await widget.onPersistManagement?.call() ?? await ngmyAdminPersistManagementConfig(widget.config);
    if (!mounted) return;
    final detected = ngmyAiProviderLabel(ngmyParseAiCredentials(widget.config.geminiApiKey).provider);
    final allCloudOk = geminiSynced && mgmtOk && helperOk && brandingOk;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          allCloudOk
              ? 'AI settings saved to cloud ($detected). Helper, Advisors, Scanner, and translator voice will use these keys.'
              : 'Saved locally. Supabase sync failed — check connection.',
        ),
        backgroundColor: allCloudOk ? const Color(0xFF16A34A) : const Color(0xFFEF4444),
      ),
    );
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final isDark = widget.isDark;
    final panel = isDark ? const Color(0xFF0F111A) : Colors.white;
    final keyboardInset = MediaQuery.viewInsetsOf(context).bottom;
    final maxSheetHeight = (MediaQuery.sizeOf(context).height * 0.88 - keyboardInset).clamp(280.0, MediaQuery.sizeOf(context).height * 0.92);
    return Align(
      alignment: Alignment.bottomCenter,
      child: Padding(
        padding: EdgeInsets.only(bottom: keyboardInset),
        child: Container(
        constraints: BoxConstraints(maxHeight: maxSheetHeight),
        margin: const EdgeInsets.fromLTRB(14, 14, 14, 18),
        decoration: BoxDecoration(
          color: panel,
          borderRadius: BorderRadius.circular(28),
          border: Border.all(color: isDark ? Colors.white10 : const Color(0xFFE2E8F0)),
        ),
        padding: const EdgeInsets.fromLTRB(22, 10, 22, 18),
        child: Column(
          children: [
            Container(width: 40, height: 4, decoration: BoxDecoration(color: Colors.grey.withOpacity(0.3), borderRadius: BorderRadius.circular(10))),
            const SizedBox(height: 15),
            Row(
              children: [
                const Expanded(
                  child: Text('NGMY AI Settings', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
                ),
                IconButton(onPressed: () => Navigator.pop(context), icon: const Icon(Icons.close_rounded)),
              ],
            ),
            const SizedBox(height: 8),
            Text(
              'Powers NGMY Helper, NGMY Advisors, Document Scanner, App Builder AI, and more.',
              style: TextStyle(fontSize: 12, color: isDark ? Colors.white60 : Colors.black54, height: 1.35),
            ),
            const SizedBox(height: 14),
            Expanded(
              child: SingleChildScrollView(
                controller: _scrollC,
                keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
                padding: EdgeInsets.only(bottom: keyboardInset > 0 ? 12 : 0),
                child: Container(
                  padding: const EdgeInsets.all(15),
                  decoration: BoxDecoration(
                    color: Colors.blue.withOpacity(0.05),
                    borderRadius: BorderRadius.circular(15),
                    border: Border.all(color: Colors.blue.withOpacity(0.2)),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Row(
                        children: [
                          Icon(Icons.auto_awesome_rounded, color: Colors.blue, size: 20),
                          SizedBox(width: 10),
                          Text('AI & App Configuration', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14)),
                        ],
                      ),
                      const SizedBox(height: 15),
                      Row(
                        children: [
                          _appLogoPreview(isDark),
                          const SizedBox(width: 12),
                          Expanded(
                            child: OutlinedButton.icon(
                              onPressed: _logoUploading ? null : _pickAppLogoImage,
                              icon: const Icon(Icons.photo_library_rounded, size: 18),
                              label: Text(_pendingLogoBytes != null ? 'Change logo' : 'Upload logo image'),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 10),
                      TextField(
                        controller: _logoC,
                        decoration: widget.adminInputDecoration(
                          label: 'App logo URL (optional)',
                          hint: 'Or paste an image link',
                          isDark: isDark,
                        ),
