                    TextField(controller: _msgC, maxLines: 3, decoration: widget.adminInputDecoration(label: 'Message', isDark: isDark)),
                    const SizedBox(height: 10),
                    TextField(controller: _attachImgC, decoration: widget.adminInputDecoration(label: 'Attachment image URL (optional)', isDark: isDark)),
                    const SizedBox(height: 15),
                    ElevatedButton(
                      onPressed: _postAnnouncement,
                      style: ElevatedButton.styleFrom(minimumSize: const Size(double.infinity, 50), backgroundColor: Colors.orange),
                      child: const Text('POST ANNOUNCEMENT', style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold)),
                    ),
                    const SizedBox(height: 22),
                    Row(
                      children: [
                        const Expanded(
                          child: Text('ACTIVE ANNOUNCEMENTS', style: TextStyle(color: Colors.grey, fontSize: 10, fontWeight: FontWeight.bold)),
                        ),
                        TextButton.icon(
                          onPressed: _confirmClearAll,
                          icon: const Icon(Icons.delete_sweep_outlined, size: 18, color: Colors.redAccent),
                          label: const Text('Clear All', style: TextStyle(color: Colors.redAccent, fontWeight: FontWeight.w700)),
                        ),
                      ],
                    ),
                    const SizedBox(height: 8),
                    if (widget.allAnnouncements.isEmpty)
                      Padding(
                        padding: const EdgeInsets.symmetric(vertical: 12),
                        child: Text('No active announcements.', style: TextStyle(color: isDark ? Colors.white54 : Colors.black54)),
                      )
                    else
                      ...widget.allAnnouncements.map((a) => Card(
                            margin: const EdgeInsets.only(bottom: 8),
                            child: ListTile(
                              title: Text(a.title, style: const TextStyle(fontWeight: FontWeight.bold)),
                              subtitle: Text(a.message, maxLines: 2, overflow: TextOverflow.ellipsis),
                              trailing: IconButton(
                                icon: const Icon(Icons.delete, color: Colors.red),
                                onPressed: () {
                                  widget.onDeleteAnnouncement(a.id);
                                  setState(() {});
                                },
                              ),
                            ),
                          )),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class ProfileScreen extends StatefulWidget {
  final UserData user; final List<UserData> allUsers; final AppConfig config; final Function(ThemeMode) onThemeChanged; final ThemeMode currentThemeMode; final VoidCallback onLogout; final VoidCallback onDataChanged; final Function(AppTransaction) onAddTransaction;
  final Future<void> Function()? onRefreshLegalContent;
  final Future<void> Function(String code)? onReferralLinked;
  final Future<bool> Function(UserData user)? onPersistUserToCloud;
  const ProfileScreen({super.key, required this.user, required this.allUsers, required this.config, required this.onThemeChanged, required this.currentThemeMode, required this.onLogout, required this.onDataChanged, required this.onAddTransaction, this.onRefreshLegalContent, this.onReferralLinked, this.onPersistUserToCloud});

  @override State<ProfileScreen> createState() => _ProfileScreenState();
}

class _ProfileScreenState extends State<ProfileScreen> {
  final TextEditingController _referralInputC = TextEditingController();
  ImageProvider? _profileAvatar;
  String _profileAvatarPath = '';
  bool _profileAvatarUploading = false;
  String? _referralPreviewName;
  bool _referralPreviewInvalid = false;
  bool _referralSubmitting = false;
  Timer? _referralPreviewDebounce;
  String _referralPreviewCode = '';
  Map<String, dynamic>? _referralPreviewReferrerRow;
  String? _linkedReferrerName;
  String _savedReferredByCode = '';

  bool get _isReferralLinked =>
      widget.user.referredByCode.trim().isNotEmpty || _savedReferredByCode.trim().isNotEmpty;

  String get _linkedReferralCode =>
      widget.user.referredByCode.trim().isNotEmpty ? widget.user.referredByCode.trim() : _savedReferredByCode.trim();

  String get _referralCode => ngmyReferralCodeForEmail(widget.user.email);

  bool _canScanCivicRegistryIds() =>
      widget.user.isAdmin ||
      _hasEffectiveRegistrarAccess(widget.config, widget.user);

  void _openCivicIdScanner() {
    showNgmyCivicIdScannerSheet(
      context,
      config: widget.config,
      walletDepositEnabled: widget.user.isAdmin,
      onDeposit: ({
        required String memberEmail,
        required String registryId,
        required String memberName,
        required double amount,
        required bool walletDeposit,
      }) {
        final now = DateTime.now();
        if (walletDeposit) {
          widget.onAddTransaction(
            AppTransaction(
              id: 'civic_scan_${registryId}_${now.millisecondsSinceEpoch}',
              userEmail: memberEmail,
              amount: amount,
              type: TransactionType.adminAdd,
              method: PaymentMethod.system,
              sourceDetails: 'Admin deposit via Registry ID scan ($registryId)',
              status: TransactionStatus.approved,
              timestamp: now,
            ),
          );
        } else {
          final member = NgmyCivicRegistryMembers.findByEmail(widget.config, memberEmail) ??
              NgmyCivicRegistryMembers.findByRegistryId(widget.config, registryId);
          final receiptState = ((member?['state'] ?? '').toString().trim().isNotEmpty
                  ? (member?['state'] ?? '').toString().trim()
                  : widget.user.state.trim());
          final campaignId = widget.config.helpCampaignIdFor(receiptState).trim();
          final payload = <String, dynamic>{
            'kind': 'contribution',
            'note': 'Registrar deposit via ID scan',
            'registryId': registryId,
            // Always stamp the member's Civic state so this receipt cannot
            // appear in every state's Contribution Receipts after help mode ends.
            'state': receiptState,
            'purpose': widget.config.helpPurposeFor(receiptState),
            'scopeType': widget.config.helpScopeTypeFor(receiptState),
            'scopeValue': widget.config.helpScopeValueFor(receiptState),
          };
          if (campaignId.isNotEmpty) payload['campaignId'] = campaignId;
          widget.onAddTransaction(
            AppTransaction(
              id: 'civic_scan_${registryId}_${now.millisecondsSinceEpoch}',
              userEmail: memberEmail,
              amount: amount,
              type: TransactionType.contribution,
              method: PaymentMethod.system,
              sourceDetails: jsonEncode(payload),
              status: TransactionStatus.approved,
              timestamp: now,
            ),
          );
        }
        widget.onDataChanged();
      },
    );
  }

  void _syncProfileAvatarCache() {
    final path = (widget.user.profilePicturePath ?? '').trim();
    if (path == _profileAvatarPath) return;
    _profileAvatarPath = path;
    _profileAvatar = ngmyCachedProfileImage(path.isEmpty ? null : path);
  }

  @override
  void initState() {
    super.initState();
    _savedReferredByCode = widget.user.referredByCode.trim();
    _syncProfileAvatarCache();
    _referralInputC.addListener(_scheduleReferralPreview);
    unawaited(_loadLinkedReferrerDisplay());
    unawaited(ngmyRegisterReferralCodesForUser(widget.user));
    unawaited(_refreshProfilePhotoFromCloud());
  }

  Future<void> _refreshProfilePhotoFromCloud() async {
    if (!await ngmyCanReachCloud()) return;
    final email = widget.user.email.trim();
    if (email.isEmpty) return;
    try {
      final row = await Supabase.instance.client
          .from('users')
          .select('profilePicturePath')
          .eq('email', email)
          .maybeSingle()
          .timeout(kNgmyCloudLoadTimeout);
      if (row == null || !mounted) return;
      final remote = (row['profilePicturePath'] ?? '').toString().trim();
      if (!_ngmyIsCloudProfilePhoto(remote)) return;
      final local = (widget.user.profilePicturePath ?? '').trim();
      if (local == remote) return;
      if (local.startsWith('data:image')) return;
      if (_ngmyIsCloudProfilePhoto(local) && local == remote) return;
      final emailKey = email.toLowerCase().trim();
      setState(() {
        widget.user.profilePicturePath = remote;
        final uIdx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == emailKey);
        if (uIdx >= 0) widget.allUsers[uIdx].profilePicturePath = remote;
        _syncProfileAvatarCache();
      });
      widget.onDataChanged();
    } catch (e) {
      debugPrint('[profile] refresh photo from cloud: $e');
    }
  }

  Future<void> _loadLinkedReferrerDisplay() async {
    if (!_isReferralLinked) return;
    final cached = await ngmyCachedReferrerNameForUser(widget.user.email);
    if (cached != null && cached.isNotEmpty) {
      if (mounted) setState(() => _linkedReferrerName = cached);
      return;
    }
    final localRow = ngmyLookupReferrerUserRowLocal(
      _linkedReferralCode,
      localUsers: widget.allUsers,
    );
    if (localRow != null) {
      final localName = ngmyDisplayNameFromReferrerRow(localRow);
      if (localName != null && localName.isNotEmpty) {
        await ngmyCacheReferrerNameForUser(widget.user.email, localName);
        if (mounted) setState(() => _linkedReferrerName = localName);
        return;
      }
    }
    final name = await ngmyResolveReferrerNameForCode(
      _linkedReferralCode,
      localUsers: widget.allUsers,
    );
    if (name != null && name.isNotEmpty) {
      await ngmyCacheReferrerNameForUser(widget.user.email, name);
    }
    if (mounted) setState(() => _linkedReferrerName = name);
  }

  String _referrerDisplayName(Map<String, dynamic> referrerRow, String referrerEmail) {
    final fromRow = ngmyDisplayNameFromReferrerRow(referrerRow);
    if (fromRow != null && fromRow.isNotEmpty) return fromRow;
    final refKey = referrerEmail.toLowerCase().trim();
    for (final u in widget.allUsers) {
      if (u.email.toLowerCase().trim() != refKey) continue;
      final name = u.fullName?.trim();
      if (name != null && name.isNotEmpty) return name;
      final username = u.username.trim();
      if (username.isNotEmpty && username.toLowerCase() != 'user') return username;
      if (u.email.contains('@')) return u.email.split('@').first;
      break;
    }
    if (referrerEmail.contains('@')) return referrerEmail.split('@').first;
    return referrerEmail;
  }

  String? _applyReferralLink(String code, Map<String, dynamic> referrerRow) {
    final normalized = ngmyNormalizeReferralCode(code);
    if (normalized.isEmpty) return null;

    var referrerEmail = ngmyApplyReferralCodeToUser(
      code: code,
      user: widget.user,
      allUsers: widget.allUsers,
      referrerRow: referrerRow,
    );
    if (referrerEmail != null && referrerEmail.trim().isNotEmpty) {
      return referrerEmail.trim();
    }

    final refEmail = (ngmyReferrerEmailFromRow(referrerRow) ?? '').trim();
    if (refEmail.isEmpty) return null;
    final currentEmail = widget.user.email.toLowerCase().trim();
    if (refEmail.toLowerCase().trim() == currentEmail) return null;

    final already = ngmyNormalizeReferralCode(widget.user.referredByCode);
    if (already.isNotEmpty && already != normalized) return null;

    widget.user.referredByCode = normalized;
    final currentIdx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == currentEmail);
    if (currentIdx >= 0) {
      widget.allUsers[currentIdx].referredByCode = normalized;
    } else {
      widget.allUsers.add(widget.user);
    }

    final refKey = refEmail.toLowerCase().trim();
    var refIdx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == refKey);
    if (refIdx == -1) {
      final referrer = UserData.fromJson(referrerRow);
      if (referrer.email.trim().isEmpty) referrer.email = refEmail;
      widget.allUsers.add(referrer);
      refIdx = widget.allUsers.length - 1;
    }
    if (already.isEmpty) {
      widget.allUsers[refIdx].referralCount += 1;
      widget.allUsers[refIdx].points += 100;
    }
    return widget.allUsers[refIdx].email;
  }

  void _scheduleReferralPreview() {
    _referralPreviewDebounce?.cancel();
    _referralPreviewDebounce = Timer(const Duration(milliseconds: 350), () {
      unawaited(_refreshReferralPreview());
    });
  }

  Future<void> _refreshReferralPreview() async {
    if (_isReferralLinked) {
      if (!mounted) return;
      setState(() {
        _referralPreviewName = null;
        _referralPreviewInvalid = false;
        _referralPreviewCode = '';
        _referralPreviewReferrerRow = null;
      });
      return;
    }
    final raw = _referralInputC.text.trim();
    if (raw.isEmpty) {
      if (!mounted) return;
      setState(() {
        _referralPreviewName = null;
        _referralPreviewInvalid = false;
        _referralPreviewCode = '';
        _referralPreviewReferrerRow = null;
      });
      return;
    }
    final normalized = ngmyNormalizeReferralCode(raw);
    if (ngmyReferralCodeBelongsToEmail(widget.user.email, raw)) {
      if (!mounted) return;
      setState(() {
        _referralPreviewName = null;
        _referralPreviewInvalid = true;
        _referralPreviewCode = normalized;
        _referralPreviewReferrerRow = null;
      });
      return;
    }
    final row = await ngmyLookupReferrerUserRow(raw, localUsers: widget.allUsers);
    if (!mounted) return;
    setState(() {
      _referralPreviewCode = normalized;
      _referralPreviewReferrerRow = row;
      _referralPreviewName = row == null ? null : ngmyDisplayNameFromReferrerRow(row);
      _referralPreviewInvalid = row == null;
    });
  }

  @override
  void didUpdateWidget(covariant ProfileScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.user.profilePicturePath != widget.user.profilePicturePath) {
      _syncProfileAvatarCache();
    }
    if (oldWidget.user.username != widget.user.username ||
        oldWidget.user.status != widget.user.status ||
        oldWidget.user.crownBadge != widget.user.crownBadge ||
        oldWidget.user.phone != widget.user.phone ||
        oldWidget.user.email != widget.user.email) {
      if (mounted) setState(() {});
    }
    if (oldWidget.user.referredByCode != widget.user.referredByCode) {
      if (widget.user.referredByCode.trim().isNotEmpty) {
        _savedReferredByCode = widget.user.referredByCode.trim();
      }
      unawaited(_loadLinkedReferrerDisplay());
    }
  }

  Future<void> _confirmLogout() async {
    final ok = await showDialog<bool>(
      context: context,
      barrierDismissible: true,
      barrierColor: Colors.black.withOpacity(0.58),
      builder: (ctx) => const _NgmyLogoutConfirmDialog(),
    );
    if (ok == true && mounted) widget.onLogout();
  }

  @override
  void dispose() {
    _referralPreviewDebounce?.cancel();
    _referralInputC.removeListener(_scheduleReferralPreview);
    _referralInputC.dispose();
    super.dispose();
  }

  Future<void> _copyReferralCode() async {
    await Clipboard.setData(ClipboardData(text: _referralCode));
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Referral code copied.')));
  }

  Future<void> _copyReferralInviteLink() async {
    final link = ngmyReferralInviteUrl(_referralCode);
    await Clipboard.setData(ClipboardData(text: link));
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('Invite link copied — share it so friends join with your referral'),
        backgroundColor: Color(0xFF059669),
      ),
    );
  }

  List<UserData> _myInvitees() {
    return widget.allUsers.where((u) {
      if (u.email.toLowerCase().trim() == widget.user.email.toLowerCase().trim()) return false;
      return u.referredByCode.trim().toUpperCase() == _referralCode.toUpperCase();
    }).toList();
  }

  void _showReferralTree() {
    final invites = _myInvitees();
    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.transparent,
      isScrollControlled: true,
      builder: (ctx) {
        final isDark = Theme.of(ctx).brightness == Brightness.dark;
        return Container(
          height: MediaQuery.of(ctx).size.height * 0.72,
          decoration: BoxDecoration(
            color: isDark ? const Color(0xFF0F152D) : Colors.white,
            borderRadius: const BorderRadius.vertical(top: Radius.circular(24)),
          ),
          child: Column(
            children: [
              const SizedBox(height: 10),
              Container(width: 42, height: 4, decoration: BoxDecoration(color: Colors.grey.withOpacity(0.4), borderRadius: BorderRadius.circular(10))),
              const SizedBox(height: 12),
              const Text('Referral Tree', style: TextStyle(fontWeight: FontWeight.w900, fontSize: 18)),
              const SizedBox(height: 4),
              Text('${invites.length} invited user(s)', style: TextStyle(color: isDark ? Colors.white70 : Colors.black54)),
              const SizedBox(height: 12),
              Expanded(
                child: invites.isEmpty
                    ? const Center(child: Text('No invited users yet.'))
                    : ListView.separated(
                        itemCount: invites.length,
                        separatorBuilder: (_, __) => const Divider(height: 1),
                        itemBuilder: (c, i) {
                          final u = invites[i];
                          return ListTile(
                            leading: const CircleAvatar(child: Icon(Icons.person_outline)),
                            title: Text(u.username, style: const TextStyle(fontWeight: FontWeight.w700)),
                            subtitle: Text(u.email),
                            trailing: Text('ID ${u.email.hashCode.abs().toString().padLeft(6, '0').substring(0, 6)}'),
                          );
                        },
                      ),
              ),
            ],
          ),
        );
      },
    );
  }

  Future<void> _submitReferralCode() async {
    if (_referralSubmitting) return;
    final code = _referralInputC.text.trim();
    if (code.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Enter a referral code first.')));
      return;
    }
    if (_isReferralLinked) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Referral code already linked on this account.')));
      return;
    }
    if (ngmyReferralCodeBelongsToEmail(widget.user.email, code)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('You cannot use your own referral code.')));
      return;
    }
    setState(() => _referralSubmitting = true);
    try {
      final normalized = ngmyNormalizeReferralCode(code);
      Map<String, dynamic>? referrerRow;
      if (_referralPreviewReferrerRow != null &&
          _referralPreviewCode == normalized &&
          (_referralPreviewName?.trim().isNotEmpty ?? false)) {
        referrerRow = _referralPreviewReferrerRow;
      }
      referrerRow ??= ngmyLookupReferrerUserRowLocal(code, localUsers: widget.allUsers);
      referrerRow ??= await ngmyLookupReferrerUserRow(code, localUsers: widget.allUsers);
      if (!mounted) return;
      if (referrerRow == null) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Invalid referral code. Check the code and try again.')),
        );
        return;
      }
      final referrerEmail = _applyReferralLink(code, referrerRow);
      if (!mounted) return;
      if (referrerEmail == null || referrerEmail.trim().isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Could not link that referral code. Try again.')),
        );
        return;
      }
      final referrerName = _referrerDisplayName(referrerRow, referrerEmail);
      _savedReferredByCode = normalized;
      widget.user.referredByCode = normalized;
      if (referrerName.isNotEmpty) {
        await ngmyCacheReferrerNameForUser(widget.user.email, referrerName);
      }
      setState(() {
        _linkedReferrerName = referrerName.isNotEmpty ? referrerName : null;
        _referralPreviewName = null;
        _referralPreviewInvalid = false;
        _referralPreviewCode = '';
        _referralPreviewReferrerRow = null;
      });
      _referralInputC.clear();
      if (widget.onReferralLinked != null) {
        await widget.onReferralLinked!(normalized);
      }
      try {
        final currentEmail = widget.user.email.toLowerCase().trim();
        final refKey = referrerEmail.toLowerCase().trim();
        final currentIdx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == currentEmail);
        final refIdx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == refKey);
        final rows = <Map<String, dynamic>>[];
        if (currentIdx != -1) {
          rows.add(Map<String, dynamic>.from(widget.allUsers[currentIdx].toJson()));
        } else {
          rows.add(Map<String, dynamic>.from(widget.user.toJson()));
        }
        if (refIdx != -1) {
          rows.add(Map<String, dynamic>.from(widget.allUsers[refIdx].toJson()));
        }
        if (rows.isNotEmpty) {
          final canWriteTrial = widget.user.isAdmin;
          unawaited(
            Supabase.instance.client
                .from('users')
                .upsert(rows.map((r) {
                  final u = UserData.fromJson(r);
                  return _userRowForBulkSync(u, includeFreeTrial: canWriteTrial);
                }).toList(), onConflict: 'email')
                .timeout(kNgmyCloudWriteTimeout)
                .catchError((_) {}),
          );
        }
      } catch (_) {}
      widget.onDataChanged();
      if (!mounted) return;
      setState(() {});
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            referrerName.isNotEmpty
                ? 'You were referred by $referrerName'
                : 'Referral linked successfully.',
          ),
          backgroundColor: const Color(0xFF059669),
        ),
      );
    } finally {
      if (mounted) setState(() => _referralSubmitting = false);
    }
  }

  @override Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final primaryText = isDark ? Colors.white : const Color(0xFF0F172A);
    final softText = isDark ? Colors.white.withValues(alpha: 0.62) : const Color(0xFF64748B);
    final cardBg = isDark ? Colors.white.withValues(alpha: 0.06) : const Color(0xFFF1F5F9);
    final panelBg = isDark ? Colors.white.withValues(alpha: 0.08) : Colors.white;
    final panelBorder = isDark ? Colors.white.withValues(alpha: 0.16) : const Color(0xFFCBD5E1);
    final neutralAction = isDark ? Colors.white.withValues(alpha: 0.12) : const Color(0xFFE2E8F0);
    final neutralActionText = isDark ? Colors.white : const Color(0xFF0F172A);
    const profileColors = [Color(0xFF22D3EE), Color(0xFF8B5CF6)];
    const legalFrameColors = [Color(0xFF3B82F6), Color(0xFF8B5CF6)];
    return Scaffold(
      backgroundColor: isDark ? const Color(0xFF121212) : const Color(0xFFF1F5F9),
      body: SafeArea(
        bottom: false,
        child: NgmyHudMotion(
          builder: (context, pulse, scan, orbit) {
            return SingleChildScrollView(
              padding: EdgeInsets.fromLTRB(20, 10, 20, _ngmyBottomNavScrollPadding(context)),
              child: Column(children: [
      NgmyToolkitAliveSection(
        colors: profileColors,
        pulse: pulse,
        scan: scan,
        orbit: orbit,
        padding: const EdgeInsets.fromLTRB(8, 6, 8, 6),
        child: Row(
          children: [
            Expanded(
              child: NgmyToolkitAliveHeader(
                title: 'MY PROFILE',
                subtitle: 'Account · rewards · settings',
                colors: profileColors,
                pulse: pulse,
                orbit: orbit,
                icon: Icons.person_rounded,
                dense: true,
              ),
            ),
            if (widget.user.isAdmin)
              IconButton(
                onPressed: () => showNgmyAdminLocalDepositQrFlow(context, adminEmail: widget.user.email),
                tooltip: 'Local deposit',
                icon: NgmyHudMiniOrb(
                  colors: const [Color(0xFF22C55E), Color(0xFF16A34A)],
                  pulse: pulse,
                  orbit: orbit,
                  size: 36,
                  icon: Icons.qr_code_2_rounded,
                ),
              ),
          ],
        ),
      ),
      const SizedBox(height: 22),
      GestureDetector(
        onTap: _profileAvatarUploading
            ? null
            : () async {
          final img = await ImagePicker().pickImage(source: ImageSource.gallery, imageQuality: 78, maxWidth: 1000);
          if (img == null || !mounted) return;
          final bytes = await img.readAsBytes();
          final previousPhoto = (widget.user.profilePicturePath ?? '').trim();
          final localPreview = 'data:image/jpeg;base64,${base64Encode(bytes)}';
          setState(() {
            _profileAvatarUploading = true;
            widget.user.profilePicturePath = localPreview;
            _profileAvatarPath = localPreview;
            _profileAvatar = ngmyCachedProfileImage(localPreview);
          });
          final cloudRef = await _uploadUserProfileAvatar(email: widget.user.email, bytes: bytes);
          if (!mounted) return;
          if (cloudRef != null && cloudRef.isNotEmpty) {
            setState(() {
              widget.user.profilePicturePath = cloudRef;
              _profileAvatarPath = cloudRef;
              _profileAvatar = ngmyCachedProfileImage(cloudRef);
              _profileAvatarUploading = false;
            });
            final myEmail = widget.user.email.toLowerCase().trim();
            final uIdx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == myEmail);
            if (uIdx >= 0) widget.allUsers[uIdx].profilePicturePath = cloudRef;
            widget.onDataChanged();
            var dbOk = await _pushUserProfilePictureToCloud(widget.user);
            if (!dbOk) {
              dbOk = await widget.onPersistUserToCloud?.call(widget.user) ?? false;
            }
            if (!dbOk) {
              dbOk = await _pushUserProfilePictureToCloud(widget.user);
            }
            if (!mounted) return;
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  dbOk
                      ? 'Profile photo saved — visible on all your devices.'
                      : 'Photo uploaded but account sync failed. Stay online and try again.',
                ),
                behavior: SnackBarBehavior.floating,
                backgroundColor: dbOk ? const Color(0xFF16A34A) : Colors.orange.shade800,
              ),
            );
          } else {
            final revert = previousPhoto.isEmpty ? null : previousPhoto;
            setState(() {
              _profileAvatarUploading = false;
              widget.user.profilePicturePath = revert;
              _profileAvatarPath = previousPhoto;
              _profileAvatar = ngmyCachedProfileImage(revert);
            });
            widget.onDataChanged();
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('Could not upload photo to cloud. Check connection and try again.'),
                behavior: SnackBarBehavior.floating,
              ),
            );
          }
        },
        child: RepaintBoundary(
          child: Stack(alignment: Alignment.center, children: [
          Container(
            width: 124,
            height: 124,
            padding: const EdgeInsets.all(4),
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              gradient: SweepGradient(
                colors: [
                  Color.lerp(const Color(0xFF22D3EE), const Color(0xFF8B5CF6), pulse)!,
                  const Color(0xFF60A5FA),
                  Color.lerp(const Color(0xFFA78BFA), const Color(0xFF22D3EE), pulse)!,
                  Color.lerp(const Color(0xFF22D3EE), const Color(0xFF8B5CF6), pulse)!,
                ],
              ),
              boxShadow: [
                BoxShadow(
                  color: const Color(0xFF22D3EE).withValues(alpha: 0.28 + pulse * 0.22),
                  blurRadius: 18 + pulse * 10,
                  offset: const Offset(0, 6),
                ),
              ],
            ),
            child: Container(
              decoration: const BoxDecoration(
                shape: BoxShape.circle,
                color: Color(0xFF0F172A),
              ),
              child: CircleAvatar(
                key: ValueKey(_profileAvatarPath),
                radius: 54,
                backgroundColor: Colors.grey.shade800,
                backgroundImage: _profileAvatar,
                child: _profileAvatar == null ? const Icon(Icons.person, size: 40, color: Colors.white70) : null,
              ),
            ),
          ),
          if (widget.user.status == 'verified') Positioned(bottom: 0, right: 0, child: Container(padding: const EdgeInsets.all(2), decoration: const BoxDecoration(color: Colors.white, shape: BoxShape.circle), child: const Icon(Icons.verified, color: Colors.blue, size: 24))),
          if (widget.user.status != 'active' && widget.user.status != 'verified') Positioned(top: 0, right: 0, child: Container(padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4), decoration: BoxDecoration(color: Colors.red, borderRadius: BorderRadius.circular(10)), child: Text(widget.user.status.toUpperCase(), style: const TextStyle(color: Colors.white, fontSize: 8, fontWeight: FontWeight.bold)))),
          if (_profileAvatarUploading)
            Positioned.fill(
              child: Container(
                decoration: BoxDecoration(color: Colors.black45, shape: BoxShape.circle),
                child: const Center(child: SizedBox(width: 28, height: 28, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))),
              ),
            ),
        ]),
        ),
      ),
      const SizedBox(height: 10),
      Text(
        widget.user.username,
        style: TextStyle(
          color: primaryText,
          fontWeight: FontWeight.w900,
          fontSize: 22,
          letterSpacing: 0.4,
          shadows: [Shadow(color: const Color(0xFF22D3EE).withValues(alpha: 0.4 + pulse * 0.25), blurRadius: 12)],
        ),
      ),
      const SizedBox(height: 16),
      _profileContactSection(
        context,
        panelBg: panelBg,
        panelBorder: panelBorder,
        cardBg: cardBg,
        primaryText: primaryText,
        neutralActionText: neutralActionText,
        pulse: pulse,
