  void _editMe(BuildContext ctx) {
    final e = TextEditingController(text: widget.user.email);
    final p = TextEditingController(text: widget.user.phone);
    final n = TextEditingController(text: widget.user.username);
    final isDark = Theme.of(ctx).brightness == Brightness.dark;
    const brand = Color(0xFF00B25A);
    const accent = Color(0xFF6366F1);
    var saving = false;

    InputDecoration fieldDec(String label, {IconData? icon, String? helper}) {
      return InputDecoration(
        labelText: label,
        helperText: helper,
        prefixIcon: icon != null ? Icon(icon, size: 20) : null,
        filled: true,
        fillColor: isDark ? const Color(0xFF1A2233) : const Color(0xFFF8FAFC),
        border: OutlineInputBorder(borderRadius: BorderRadius.circular(14)),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(14),
          borderSide: BorderSide(color: isDark ? Colors.white12 : const Color(0xFFE2E8F0)),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(14),
          borderSide: BorderSide(color: isDark ? brand : accent, width: 1.6),
        ),
        labelStyle: TextStyle(color: isDark ? Colors.white60 : Colors.black54),
      );
    }

    showDialog<void>(
      context: ctx,
      barrierColor: Colors.black.withOpacity(0.5),
      builder: (dialogCtx) {
        return StatefulBuilder(
          builder: (dialogCtx, setDlg) {
            Future<void> save() async {
              if (saving) return;
              final username = n.text.trim();
              if (username.isEmpty) {
                ScaffoldMessenger.of(dialogCtx).showSnackBar(
                  const SnackBar(content: Text('Username is required.')),
                );
                return;
              }
              final phone = p.text.trim();
              if (!ngmyUserPhoneOnFile(phone)) {
                ScaffoldMessenger.of(dialogCtx).showSnackBar(
                  const SnackBar(content: Text('Phone number is required (at least 10 digits).')),
                );
                return;
              }
              final myEmail = widget.user.email.toLowerCase().trim();
              final taken = NgmyCivicRegistryMembers.isAppPhoneTaken(
                widget.allUsers,
                phone,
                excludeEmail: myEmail,
              );
              if (taken) {
                ScaffoldMessenger.of(dialogCtx).showSnackBar(
                  const SnackBar(content: Text('That phone number is already registered to another account.')),
                );
                return;
              }
              setDlg(() => saving = true);
              widget.user.username = username;
              widget.user.email = e.text.trim();
              widget.user.phone = phone;
              final uIdx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == myEmail);
              if (uIdx >= 0) {
                widget.allUsers[uIdx].username = username;
                widget.allUsers[uIdx].email = widget.user.email;
                widget.allUsers[uIdx].phone = phone;
              }
              widget.onDataChanged();
              await _pushUserProfileBasicsToCloud(widget.user);
              await widget.onPersistUserToCloud?.call(widget.user);
              if (dialogCtx.mounted) Navigator.pop(dialogCtx);
              if (mounted) setState(() {});
            }

            return Dialog(
              insetPadding: const EdgeInsets.symmetric(horizontal: 22, vertical: 28),
              backgroundColor: Colors.transparent,
              elevation: 0,
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 420),
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(24),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Container(
                        width: double.infinity,
                        padding: const EdgeInsets.fromLTRB(22, 20, 22, 18),
                        decoration: BoxDecoration(
                          gradient: LinearGradient(
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                            colors: isDark
                                ? [const Color(0xFF0F3D2E), const Color(0xFF1E3A5F)]
                                : [brand, accent],
                          ),
                        ),
                        child: Row(
                          children: [
                            Container(
                              padding: const EdgeInsets.all(10),
                              decoration: BoxDecoration(
                                color: Colors.white.withOpacity(0.18),
                                borderRadius: BorderRadius.circular(14),
                              ),
                              child: const Icon(Icons.person_rounded, color: Colors.white, size: 22),
                            ),
                            const SizedBox(width: 12),
                            const Expanded(
                              child: Text(
                                'Edit profile',
                                style: TextStyle(
                                  color: Colors.white,
                                  fontSize: 20,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                            IconButton(
                              onPressed: saving ? null : () => Navigator.pop(dialogCtx),
                              icon: const Icon(Icons.close_rounded, color: Colors.white70),
                            ),
                          ],
                        ),
                      ),
                      Container(
                        color: isDark ? const Color(0xFF121826) : Colors.white,
                        padding: const EdgeInsets.fromLTRB(20, 18, 20, 20),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: [
                            TextField(
                              controller: n,
                              style: TextStyle(color: isDark ? Colors.white : const Color(0xFF0F172A)),
                              decoration: fieldDec('Username', icon: Icons.alternate_email_rounded),
                            ),
                            const SizedBox(height: 12),
                            TextField(
                              controller: e,
                              keyboardType: TextInputType.emailAddress,
                              autocorrect: false,
                              style: TextStyle(color: isDark ? Colors.white : const Color(0xFF0F172A)),
                              decoration: fieldDec('Email', icon: Icons.email_outlined),
                            ),
                            const SizedBox(height: 12),
                            TextField(
                              controller: p,
                              keyboardType: TextInputType.phone,
                              style: TextStyle(color: isDark ? Colors.white : const Color(0xFF0F172A)),
                              decoration: fieldDec(
                                'Phone',
                                icon: Icons.phone_in_talk_rounded,
                                helper: 'Required — synced across your devices',
                              ),
                            ),
                            const SizedBox(height: 18),
                            Row(
                              children: [
                                Expanded(
                                  child: OutlinedButton(
                                    onPressed: saving ? null : () => Navigator.pop(dialogCtx),
                                    style: OutlinedButton.styleFrom(
                                      padding: const EdgeInsets.symmetric(vertical: 14),
                                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
                                      side: BorderSide(color: isDark ? Colors.white24 : const Color(0xFFE2E8F0)),
                                    ),
                                    child: Text('Cancel', style: TextStyle(color: isDark ? Colors.white70 : Colors.black54)),
                                  ),
                                ),
                                const SizedBox(width: 10),
                                Expanded(
                                  flex: 2,
                                  child: FilledButton(
                                    onPressed: saving ? null : save,
                                    style: FilledButton.styleFrom(
                                      backgroundColor: brand,
                                      foregroundColor: Colors.white,
                                      padding: const EdgeInsets.symmetric(vertical: 14),
                                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
                                    ),
                                    child: saving
                                        ? const SizedBox(
                                            width: 20,
                                            height: 20,
                                            child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white),
                                          )
                                        : const Text('Save changes', style: TextStyle(fontWeight: FontWeight.w800)),
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        );
      },
    ).whenComplete(() {
      e.dispose();
      p.dispose();
      n.dispose();
    });
  }

  void _showLegal(BuildContext ctx, String title, String content) {
    final isDark = Theme.of(ctx).brightness == Brightness.dark;
    showDialog<void>(
      context: ctx,
      barrierColor: Colors.black.withOpacity(0.45),
      builder: (dialogCtx) {
        final maxHeight = MediaQuery.sizeOf(dialogCtx).height * 0.72;
        return Dialog(
          insetPadding: EdgeInsets.fromLTRB(
            20,
            MediaQuery.paddingOf(dialogCtx).top + 28,
            20,
            MediaQuery.paddingOf(dialogCtx).bottom + 28,
          ),
          backgroundColor: Colors.transparent,
          elevation: 0,
          child: Container(
            constraints: BoxConstraints(maxHeight: maxHeight),
            decoration: BoxDecoration(
              color: isDark ? const Color(0xFF121726) : Colors.white,
              borderRadius: BorderRadius.circular(24),
              border: Border.all(color: isDark ? Colors.white24 : const Color(0xFFE2E8F0), width: 1.5),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withOpacity(isDark ? 0.35 : 0.12),
                  blurRadius: 28,
                  offset: const Offset(0, 10),
                ),
              ],
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(22, 18, 12, 12),
                  child: Row(
                    children: [
                      Container(
                        padding: const EdgeInsets.all(8),
                        decoration: BoxDecoration(
                          color: const Color(0xFF00B25A).withOpacity(0.14),
                          borderRadius: BorderRadius.circular(12),
                        ),
                        child: Icon(
                          title.toLowerCase().contains('privacy') ? Icons.privacy_tip_outlined : Icons.gavel_rounded,
                          color: const Color(0xFF00B25A),
                          size: 20,
                        ),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Text(
                          title,
                          style: TextStyle(
                            fontSize: 18,
                            fontWeight: FontWeight.w900,
                            letterSpacing: 0.4,
                            color: isDark ? Colors.white : Colors.black87,
                          ),
                        ),
                      ),
                      IconButton(
                        onPressed: () => Navigator.pop(dialogCtx),
                        icon: Container(
                          padding: const EdgeInsets.all(6),
                          decoration: BoxDecoration(
                            color: isDark ? Colors.white.withOpacity(0.08) : Colors.grey.withOpacity(0.12),
                            shape: BoxShape.circle,
                          ),
                          child: Icon(Icons.close_rounded, size: 18, color: isDark ? Colors.white70 : Colors.black54),
                        ),
                      ),
                    ],
                  ),
                ),
                Divider(height: 1, color: isDark ? Colors.white12 : Colors.black12),
                Flexible(
                  child: SingleChildScrollView(
                    padding: const EdgeInsets.fromLTRB(24, 18, 24, 24),
                    child: Text(
                      content.trim().isEmpty ? 'No content available yet.' : content,
                      style: TextStyle(
                        fontSize: 14,
                        height: 1.65,
                        letterSpacing: 0.2,
                        fontWeight: FontWeight.w400,
                        color: isDark ? Colors.white.withOpacity(0.88) : const Color(0xFF334155),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
  Future<void> _copyProfileField(String label, String value) async {
    if (value.trim().isEmpty) return;
    await Clipboard.setData(ClipboardData(text: value.trim()));
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('$label copied'), duration: const Duration(seconds: 2), behavior: SnackBarBehavior.floating),
    );
  }

  Widget _row(
    IconData i,
    String l,
    String v, {
    String? copyText,
    bool requiredField = false,
    bool missing = false,
    VoidCallback? onTap,
  }) =>
      Material(
        color: Colors.transparent,
        child: InkWell(
          onTap: onTap,
          borderRadius: BorderRadius.circular(12),
          child: Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(12),
              border: Border.all(
                color: missing
                    ? const Color(0xFFEF4444).withValues(alpha: 0.65)
                    : NgmyHudInk.panelBorder(context),
                width: missing ? 1.4 : 1,
              ),
              color: missing
                  ? const Color(0xFFEF4444).withValues(alpha: NgmyHudInk.isDark(context) ? 0.12 : 0.06)
                  : NgmyHudInk.panel(context),
            ),
            child: Row(
              children: [
                Icon(
                  i,
                  size: 18,
                  color: missing ? const Color(0xFFEF4444) : NgmyHudInk.muted(context),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Text(
                            requiredField ? '$l *' : l,
                            style: TextStyle(
                              fontSize: 10,
                              fontWeight: requiredField ? FontWeight.w800 : FontWeight.w500,
                              color: missing ? const Color(0xFFEF4444) : NgmyHudInk.muted(context),
                            ),
                          ),
                          if (requiredField && missing) ...[
                            const SizedBox(width: 8),
                            Container(
                              padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 2),
                              decoration: BoxDecoration(
                                color: const Color(0xFFEF4444).withValues(alpha: 0.15),
                                borderRadius: BorderRadius.circular(99),
                              ),
                              child: const Text(
                                'REQUIRED',
                                style: TextStyle(
                                  fontSize: 9,
                                  fontWeight: FontWeight.w900,
                                  letterSpacing: 0.4,
                                  color: Color(0xFFEF4444),
                                ),
                              ),
                            ),
                          ],
                        ],
                      ),
                      CopyOnHoldText(
                        v,
                        style: TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.w600,
                          color: missing
                              ? (NgmyHudInk.isDark(context) ? const Color(0xFFFCA5A5) : const Color(0xFFB91C1C))
                              : NgmyHudInk.title(context),
                        ),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                      if (missing)
                        Padding(
                          padding: const EdgeInsets.only(top: 4),
                          child: Text(
                            'Add your phone number — tap to edit',
                            style: TextStyle(
                              fontSize: 11,
                              height: 1.25,
                              color: NgmyHudInk.isDark(context) ? const Color(0xFFFECACA) : const Color(0xFF991B1B),
                            ),
                          ),
                        ),
                    ],
                  ),
                ),
                if (copyText != null && copyText.trim().isNotEmpty)
                  IconButton(
                    visualDensity: VisualDensity.compact,
                    padding: EdgeInsets.zero,
                    constraints: const BoxConstraints(minWidth: 36, minHeight: 36),
                    tooltip: 'Copy $l',
                    icon: Icon(Icons.copy_rounded, size: 18, color: NgmyHudInk.muted(context)),
                    onPressed: () => _copyProfileField(l, copyText),
                  )
                else if (missing)
                  Icon(Icons.edit_rounded, size: 16, color: const Color(0xFFEF4444).withValues(alpha: 0.85)),
              ],
            ),
          ),
        ),
      );

