  Widget _ngmyServicesHeroCard({required bool isDark, required List<Color> topColors}) {
    return AnimatedBuilder(
      animation: _animCtrl,
      builder: (context, child) {
        final t = _animCtrl.value;
        final pulse = 0.55 + 0.45 * (math.sin(t * 2 * math.pi) + 1) / 2;
        final tiltX = 0.035 * math.sin(t * 2 * math.pi);
        final tiltY = 0.05 * math.cos(t * 2 * math.pi);
        final borderShift = t * 2 * math.pi;

        return Container(
          width: double.infinity,
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(24),
            boxShadow: [
              BoxShadow(
                color: topColors[1].withOpacity(0.28 + pulse * 0.22),
                blurRadius: 22 + pulse * 10,
                spreadRadius: 1 + pulse * 2,
                offset: const Offset(0, 10),
              ),
              BoxShadow(
                color: const Color(0xFF38BDF8).withOpacity(isDark ? 0.16 + pulse * 0.18 : 0.22 + pulse * 0.2),
                blurRadius: 28,
                spreadRadius: -2,
              ),
              BoxShadow(
                color: const Color(0xFF7C3AED).withOpacity(0.12 + pulse * 0.14),
                blurRadius: 36,
                spreadRadius: -6,
              ),
            ],
          ),
          child: Container(
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(24),
              gradient: SweepGradient(
                startAngle: borderShift,
                endAngle: borderShift + math.pi * 2,
                colors: [
                  Colors.white.withOpacity(0.95),
                  const Color(0xFF67E8F9).withOpacity(0.85),
                  const Color(0xFFA78BFA).withOpacity(0.85),
                  Colors.white.withOpacity(0.35),
                  const Color(0xFF22D3EE).withOpacity(0.75),
                  Colors.white.withOpacity(0.95),
                ],
              ),
            ),
            padding: const EdgeInsets.all(2.6),
            child: Transform(
              transform: Matrix4.identity()
                ..setEntry(3, 2, 0.0012)
                ..rotateX(tiltX)
                ..rotateY(tiltY),
              alignment: Alignment.center,
              child: Container(
                width: double.infinity,
                padding: const EdgeInsets.symmetric(vertical: 22, horizontal: 18),
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    colors: [
                      Color.lerp(topColors[0], const Color(0xFF38BDF8), pulse * 0.12)!,
                      Color.lerp(topColors[1], const Color(0xFF7C3AED), pulse * 0.1)!,
                    ],
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                  ),
                  borderRadius: BorderRadius.circular(21),
                  border: Border.all(
                    color: Colors.white.withOpacity(isDark ? 0.24 + pulse * 0.12 : 0.38 + pulse * 0.14),
                    width: 1.2,
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.white.withOpacity(0.08 + pulse * 0.1),
                      blurRadius: 18,
                      spreadRadius: -4,
                      offset: const Offset(0, -2),
                    ),
                  ],
                ),
                child: Column(
                  children: [
                    Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        _animatedStar(20, spin: false),
                        const SizedBox(width: 10),
                        _animatedStar(34, spin: true, reactive: _canOpenAppBuilder, onTap: _canOpenAppBuilder ? _openAppBuilder : null),
                        const SizedBox(width: 10),
                        _animatedStar(20, spin: false),
                      ],
                    ),
                    const SizedBox(height: 10),
                    const Text(
                      'NGMY Services',
                      style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 28),
                    ),
                    const SizedBox(height: 6),
                    Text(
                      'Next Generation - Make Yours',
                      style: TextStyle(
                        color: Colors.white.withOpacity(0.95),
                        fontSize: 12,
                        fontWeight: FontWeight.w600,
                        letterSpacing: 0.2,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }

  Widget _animatedStar(double size, {bool spin = true, bool reactive = false, VoidCallback? onTap}) {
    Widget starCore = AnimatedBuilder(
      animation: _animCtrl,
      builder: (context, child) {
        final pulse = 0.82 + (math.sin(_animCtrl.value * 2 * math.pi) + 1) * 0.12;
        final smokeDrift = math.sin(_animCtrl.value * 2 * math.pi) * (size * 0.08);
        return SizedBox(
          width: size * 1.9,
          height: size * 1.9,
          child: Stack(
            alignment: Alignment.center,
            children: [
              Positioned(
                left: size * 0.25 + smokeDrift,
                top: size * 0.35,
                child: Container(
                  width: size * 0.95,
                  height: size * 0.95,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: Colors.white.withOpacity(spin ? 0.12 : 0.16 * pulse),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.white.withOpacity(spin ? 0.16 : 0.20 * pulse),
                        blurRadius: size * 0.8,
                        spreadRadius: 1,
                      ),
                    ],
                  ),
                ),
              ),
              Container(
                width: size * 1.25,
                height: size * 1.25,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  gradient: RadialGradient(
                    colors: [
                      Colors.white.withOpacity(spin ? 0.26 : 0.32 * pulse),
                      Colors.transparent,
                    ],
                  ),
                ),
              ),
              Transform(
                transform: spin
                    ? (Matrix4.identity()
                      ..setEntry(3, 2, 0.001)
                      ..rotateY(_animCtrl.value * 2 * math.pi))
                    : Matrix4.identity(),
                alignment: Alignment.center,
                child: Icon(Icons.star_rounded, color: Colors.white, size: size),
              ),
            ],
          ),
        );
      },
    );

    if (!reactive) return starCore;

    final scale = _centerStarPressed ? 1.12 : (_centerStarHover ? 1.06 : 1.0);
    return MouseRegion(
      onEnter: (_) => setState(() => _centerStarHover = true),
      onExit: (_) => setState(() {
        _centerStarHover = false;
        _centerStarPressed = false;
      }),
      child: GestureDetector(
        behavior: HitTestBehavior.translucent,
        onTapDown: (_) => setState(() => _centerStarPressed = true),
        onTapUp: (_) => setState(() => _centerStarPressed = false),
        onTapCancel: () => setState(() => _centerStarPressed = false),
        onTap: onTap,
        child: AnimatedScale(
          duration: const Duration(milliseconds: 160),
          curve: Curves.easeOutCubic,
          scale: scale,
          child: starCore,
        ),
      ),
    );
  }

