/// Per-state help mode campaigns. Each US state activates/deactivates its
/// own campaign independently — Georgia's Authorized Registrar turning
/// help mode on must never show Alabama's registrar a "Deactivate Help
/// Mode" button for Georgia's campaign, and vice versa. Storage lives in
/// `AppConfig.helpModeByState` (state name -> campaign map); the older
/// flat `helpModeActive`/`helpPurpose`/etc fields on AppConfig are legacy
/// (a single shared slot) and are only read here once, to migrate
/// whichever campaign was active under the old system into this map the
/// first time it's touched — see `migrateLegacyHelpModeIfNeeded`.
extension AppConfigHelpMode on AppConfig {
  /// Case-insensitive key — "Alabama" and "alabama" must be the same
  /// campaign. A raw .trim() (what every accessor used before) let a
  /// casing difference between wherever a state name was activated from
  /// and wherever it was later read/deactivated from silently miss the
  /// map entry: Map.remove() on a non-matching key is a silent no-op, so
  /// Deactivate could run to completion, appear to succeed, and the
  /// campaign would still show active because nothing was actually
  /// removed under the key the read side was looking up.
  String _stateKey(String state) => state.trim().toLowerCase();

  Map<String, dynamic> _campaignFor(String state) {
    migrateLegacyHelpModeIfNeeded(state);
    final key = _stateKey(state);
    final raw = helpModeByState[key];
    return raw is Map ? Map<String, dynamic>.from(raw) : const {};
  }

  bool helpActiveFor(String state) => _campaignFor(state)['active'] == true;
  String helpPurposeFor(String state) => (_campaignFor(state)['purpose'] ?? '').toString();
  String helpCashAppFor(String state) => (_campaignFor(state)['cashApp'] ?? '').toString();
  String helpZelleFor(String state) => (_campaignFor(state)['zelle'] ?? '').toString();
  String helpPhoneFor(String state) => (_campaignFor(state)['phone'] ?? '').toString();
  String helpScopeTypeFor(String state) {
    final v = (_campaignFor(state)['scopeType'] ?? 'all').toString();
    return v.isEmpty ? 'all' : v;
  }

  String helpScopeValueFor(String state) => (_campaignFor(state)['scopeValue'] ?? '').toString();
  String helpCampaignIdFor(String state) => (_campaignFor(state)['campaignId'] ?? '').toString();
  String helpCampaignStartedAtFor(String state) => (_campaignFor(state)['campaignStartedAt'] ?? '').toString();

  /// Activates (or edits, if already active) the given state's campaign.
  /// `startNewCampaignId` should be true when the purpose/scope actually
  /// changed (or this is a fresh activation) — matches the old
  /// shouldStartNewCampaign logic, just scoped to one state now.
  void setHelpCampaign(
    String state, {
    required String purpose,
    required String cashApp,
    required String zelle,
    required String phone,
    required String scopeType,
    required String scopeValue,
    required bool startNewCampaignId,
  }) {
    final key = _stateKey(state);
    if (key.isEmpty) return;
    // Read the raw existing entry directly (not via _campaignFor) — that
    // triggers migration, and this is called *from* the migration path
    // itself, which would otherwise recurse forever.
    final existingRaw = helpModeByState[key];
    final existing = existingRaw is Map ? Map<String, dynamic>.from(existingRaw) : const <String, dynamic>{};
    final next = Map<String, dynamic>.from(helpModeByState)
      ..[key] = {
        'active': true,
        'purpose': purpose,
        'cashApp': cashApp,
        'zelle': zelle,
        'phone': phone,
        'scopeType': scopeType,
        'scopeValue': scopeValue,
        'campaignId': startNewCampaignId ? 'help_${DateTime.now().microsecondsSinceEpoch}' : (existing['campaignId'] ?? ''),
        'campaignStartedAt': startNewCampaignId ? DateTime.now().toUtc().toIso8601String() : (existing['campaignStartedAt'] ?? ''),
      };
    helpModeByState = next;
  }

  /// Deactivates by flipping `active: false` in place — it must NOT
  /// remove the state's key from helpModeByState. `_campaignFor` calls
  /// `migrateLegacyHelpModeIfNeeded` on every read, and that migration's
  /// only guard against re-running is `helpModeByState.containsKey(key)`.
  /// If a state's key were removed here, the very next `helpActiveFor`
  /// call (e.g. the button rebuilding right after this runs) would see
  /// the key missing, find the legacy flat `helpModeActive`/`helpState`
  /// fields still pointing at this state (they're never cleared —
  /// nothing else reads them), and silently recreate the campaign as
  /// active again. That was the actual cause of "Deactivate does
  /// nothing" — not a network/race issue, a deterministic resurrection
  /// on the very next read, every single time.
  void deactivateHelpCampaign(String state) {
    final key = _stateKey(state);
    if (key.isEmpty) return;
    final existingRaw = helpModeByState[key];
    final existing = existingRaw is Map ? Map<String, dynamic>.from(existingRaw) : const <String, dynamic>{};
    final next = Map<String, dynamic>.from(helpModeByState)
      ..[key] = {
        ...existing,
        'active': false,
      };
    helpModeByState = next;
  }

  /// One-time migration: if this state has no entry in the new per-state
  /// map yet, but the legacy single-slot fields say IT was the active
  /// campaign, copy it in. No-op once migrated (the map entry then exists,
  /// so this never runs again for that state).
  void migrateLegacyHelpModeIfNeeded(String state) {
    final key = _stateKey(state);
    if (key.isEmpty || helpModeByState.containsKey(key)) return;
    if (!helpModeActive) return;
    if (helpState.trim().isNotEmpty && _stateKey(helpState) != key) return;
    setHelpCampaign(
      key,
      purpose: helpPurpose,
      cashApp: helpCashApp,
      zelle: helpZelle,
      phone: helpPhone,
      scopeType: helpScopeType,
      scopeValue: helpScopeValue,
      startNewCampaignId: false,
    );
    if (helpCampaignId.trim().isNotEmpty || helpCampaignStartedAt.trim().isNotEmpty) {
      final next = Map<String, dynamic>.from(helpModeByState);
      final campaign = Map<String, dynamic>.from(next[key] as Map);
      campaign['campaignId'] = helpCampaignId;
      campaign['campaignStartedAt'] = helpCampaignStartedAt;
      next[key] = campaign;
      helpModeByState = next;
    }
  }
}

class CivicRegistryScreen extends StatefulWidget {
  final UserData user;
  final List<UserData> allUsers;
  final List<AppTransaction> allTransactions;
  final Function(AppTransaction) onAddTransaction;
  final VoidCallback onDataChanged;
  final AppConfig config;
  final bool openSelfEnrollmentOnStart;
  const CivicRegistryScreen({
    super.key,
    required this.user,
    required this.allUsers,
    required this.allTransactions,
    required this.onAddTransaction,
    required this.onDataChanged,
    required this.config,
    this.openSelfEnrollmentOnStart = false,
  });

  @override
  State<CivicRegistryScreen> createState() => _CivicRegistryScreenState();
}

class _CivicRegistryScreenState extends State<CivicRegistryScreen> {
  int _activeTab = 0; // 0: Search, 1: Enroll, 2: Members, 3: Rankings
  String _searchQuery = '';
  late String _selectedState;
  bool _registryUnlocked = false;
  bool _unlockChecked = false;
  String _selectedCity = 'All Cities';
  String _selectedRoom = 'All Rooms';
  final TextEditingController _searchController = TextEditingController();
  final TextEditingController _enrollSearchC = TextEditingController();

  // Enrollment Form Controllers
  final _fullNameC = TextEditingController();
  final _dobC = TextEditingController();
  final _idTypeC = TextEditingController(text: 'National ID');
  final _addressC = TextEditingController();
  final _phoneC = TextEditingController();
  final _emailC = TextEditingController();
  final _cityC = TextEditingController();
  final _roomC = TextEditingController();
  final _familyMembersC = TextEditingController();
  final _familyMalesC = TextEditingController();
  final _familyFemalesC = TextEditingController();
  /// When set, Enroll tab is updating this member's registry email key.
  String? _editingMemberOriginalEmail;
  String? _editingMemberRegistryId;
  /// Quiet registrar notes: fieldKey → {status, notedAt, notedBy}.
  Map<String, Map<String, dynamic>> _enrollmentFlags = {};
  final Set<String> _dismissedReceiptKeys = {};
  final Set<String> _openedReceiptKeys = {};
  Map<String, dynamic>? _localRegistrarBackup;
  bool _maintenanceQueued = false;
  Timer? _helpModePoll;
  List<AppTransaction> _communityContributions = [];
  List<AppTransaction> _communityClaims = [];
  /// Member state-switch cooldown after [NgmyCivicStateSwitches.maxSwitches] changes.
  DateTime? _stateSwitchLockedUntil;

  final List<String> _usStates = [
    'Alabama', 'Alaska', 'Arizona', 'Arkansas', 'California', 'Colorado', 'Connecticut', 'Delaware', 'Florida', 'Georgia',
    'Hawaii', 'Idaho', 'Illinois', 'Indiana', 'Iowa', 'Kansas', 'Kentucky', 'Louisiana', 'Maine', 'Maryland',
    'Massachusetts', 'Michigan', 'Minnesota', 'Mississippi', 'Missouri', 'Montana', 'Nebraska', 'Nevada', 'New Hampshire', 'New Jersey',
    'New Mexico', 'New York', 'North Carolina', 'North Dakota', 'Ohio', 'Oklahoma', 'Oregon', 'Pennsylvania', 'Rhode Island', 'South Carolina',
    'South Dakota', 'Tennessee', 'Texas', 'Utah', 'Vermont', 'Virginia', 'Washington', 'West Virginia', 'Wisconsin', 'Wyoming'
  ];

  @override
  void initState() {
    super.initState();
    NgmyAdminLiveRefresh.addListener(_onCivicLiveRefresh);
    _selectedState = widget.user.state;
    unawaited(ngmyHydrateCivicRegistryMembersFromAllBackups(widget.config, widget.allUsers));
    _ensureUniqueRegistryIds();
    unawaited(_hydrateReceiptReadState());
    unawaited(_hydrateRegistrarApplication());
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _runHelpModeLifecycleMaintenance();
      final purged = NgmyCivicRegistryMembers.purgeExpiredSoftDeletes(widget.config);
      if (purged > 0) {
        unawaited(ngmyPersistCivicRegistryMembers(widget.config));
        widget.onDataChanged();
      }
      _checkRegistryUnlock();
      unawaited(_hydrateStateSwitchLock());
      unawaited(_maybePromptCivicIdPhoto());
    });
    unawaited(_refreshCivicHelpModeAndContributions());
    _helpModePoll = Timer.periodic(const Duration(seconds: 75), (_) {
      if (!mounted) return;
      unawaited(_refreshCivicHelpModeAndContributions());
    });
  }

  Future<void> _hydrateStateSwitchLock() async {
    final local = await NgmyCivicStateSwitches.loadLocal(widget.user.email);
    if (!mounted) return;
    var lock = local == null
        ? null
        : NgmyCivicStateSwitches.parseLockedUntil(local['lockedUntil']);
    var used = widget.user.civicRegistryStateSwitchesUsed;
    final cleared = NgmyCivicStateSwitches.refreshLockIfNeeded(
      switchesUsed: used,
      lockedUntil: lock,
      setSwitchesUsed: (n) {
        used = n;
        widget.user.civicRegistryStateSwitchesUsed = n;
      },
      setLockedUntil: (u) => lock = u,
    );
    if (!mounted) return;
    setState(() => _stateSwitchLockedUntil = lock);
    if (cleared) unawaited(_persistStateSwitchLocal());
  }

  Future<void> _persistStateSwitchLocal() async {
    await NgmyCivicStateSwitches.saveLocal(
      email: widget.user.email,
      switchesUsed: widget.user.civicRegistryStateSwitchesUsed,
      anchorState: widget.user.civicRegistryAnchorState,
      lockedUntil: _stateSwitchLockedUntil,
    );
  }

  Future<void> _refreshCivicHelpModeAndContributions() async {
    await ngmyHydrateCivicHelpModeFromAllBackups(widget.config);
    await ngmyHydrateCivicContributionReceiptRemoved(widget.config);
    await ngmyHydrateCivicDeletedContributions(widget.config);
    final results = await Future.wait([
      ngmyFetchApprovedContributionsFromCloud(),
      ngmyFetchCivicClaimsFromCloud(),
    ]);
    if (!mounted) return;
    final deleted = widget.config.civicDeletedContributionIds
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toSet();
    setState(() {
      _communityContributions = results[0].where((t) => !deleted.contains(t.id)).toList();
      _communityClaims = results[1];
    });
    // After a cloud hydrate, re-run lifecycle so a resurrected "active"
    // campaign that already has a closure stays off (and gets persisted).
    _queueHelpModeLifecycleMaintenance();
    unawaited(_pruneExpiredResolvedClaims());
    // Re-delete any tombstoned rows that somehow still exist in cloud.
    if (deleted.isNotEmpty && await ngmyCanReachCloud()) {
      unawaited(_purgeTombstonedContributionsFromCloud(deleted));
    }
  }

  void _onCivicLiveRefresh() {
    if (!mounted) return;
    unawaited(_refreshCivicMembersFromCloud());
    unawaited(_checkRegistryUnlock());
    unawaited(ngmyHydrateCivicContributionReceiptRemoved(widget.config).then((_) async {
      await ngmyHydrateCivicDeletedContributions(widget.config);
      if (mounted) setState(() {});
    }));
  }

  @override
  void dispose() {
    _helpModePoll?.cancel();
    NgmyAdminLiveRefresh.removeListener(_onCivicLiveRefresh);
    _searchController.dispose();
    _enrollSearchC.dispose();
    _fullNameC.dispose();
