  @override
  void didUpdateWidget(CivicRegistryScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.user.email != widget.user.email) {
      unawaited(_hydrateReceiptReadState());
      unawaited(_hydrateRegistrarApplication());
    }
    if (!_canBypassCivicGate()) {
      unawaited(_checkRegistryUnlock());
    }
  }

  Future<void> _hydrateReceiptReadState() async {
    final email = widget.user.email.toLowerCase().trim();
    if (email.isEmpty) return;
    final localOpened = await NgmyCivicReadState.loadOpened(email);
    final localDismissed = await NgmyCivicReadState.loadDismissed(email);
    if (!mounted) return;
    setState(() {
      _openedReceiptKeys
        ..clear()
        ..addAll(NgmyCivicReadState.hydrateOpened(
          email: email,
          local: localOpened,
          userRow: widget.user.openedContributionReceiptKeys,
          legacyConfig: widget.config.openedContributionReceiptKeys,
        ));
      _dismissedReceiptKeys
        ..clear()
        ..addAll(NgmyCivicReadState.hydrateDismissed(
          email: email,
          local: localDismissed,
          userRow: widget.user.dismissedContributionReceiptKeys,
          legacyConfig: widget.config.dismissedContributionReceiptKeys,
        ));
    });
  }

  bool _hasRegistrarAccess() {
    return _hasEffectiveRegistrarAccess(widget.config, widget.user);
  }

  /// AR tools (and PIN bypass) only in the registrar's home state, or for King/Admin.
  bool _canUseRegistrarToolsHere([String? state]) {
    if (_isGlobalCivicRegistryAdmin()) return true;
    if (!_hasRegistrarAccess()) return false;
    final st = (state ?? _selectedState).trim().toLowerCase();
    return st == _registrarHomeState().trim().toLowerCase();
  }

  bool _canBypassCivicGate() => _canUseRegistrarToolsHere();

  /// State case (wallet) never remembers PIN / name / DOB / ID except for
  /// this state's first Authorized Registrar. Other ARs and all members
  /// re-enter every visit. King / Admin still skip so they are not locked
  /// out of cases they may not have a member record for.
  bool _shouldSkipStateCaseUnlock([String? state]) {
    final st = (state ?? _selectedState).trim();
    if (!_stateRequiresMemberUnlock(st)) return true;
    if (_isGlobalCivicRegistryAdmin()) return true;
    return NgmyCivicRegistryStats.isFirstAuthorizedRegistrar(
      email: widget.user.email,
      state: st,
      applications: widget.config.civicRegistrarApplications,
      users: widget.allUsers,
    );
  }

  /// PIN / name / DOB / registry ID only after a state has an Authorized Registrar.
  bool _stateRequiresMemberUnlock([String? state]) {
    return NgmyCivicRegistryStats.stateHasAuthorizedRegistrar(
      state: (state ?? _selectedState).trim(),
      applications: widget.config.civicRegistrarApplications,
      users: widget.allUsers,
    );
  }

  Future<void> _checkRegistryUnlock() async {
    if (_canBypassCivicGate() || !_stateRequiresMemberUnlock()) {
      if (mounted) setState(() {
        _registryUnlocked = true;
        _unlockChecked = true;
      });
      return;
    }
    final ok = await civicRegistryIsUnlocked(
      widget.user.email,
      state: _selectedState,
      globalPin: widget.config.civicRegistryPin,
      pinsByState: widget.config.civicRegistryPinsByState,
    );
    if (mounted) {
      setState(() {
        _registryUnlocked = ok;
        _unlockChecked = true;
      });
    }
  }

  void _onRegistryUnlocked(String state) {
    NgmyCivicStateSwitches.onGateUnlock(
      state: state,
      currentAnchor: widget.user.civicRegistryAnchorState,
      setAnchorState: (s) => widget.user.civicRegistryAnchorState = s,
      setUserState: (s) => widget.user.state = s,
    );
    setState(() {
      _selectedState = state;
      _registryUnlocked = true;
    });
    unawaited(_persistStateSwitchLocal());
    unawaited(_pushUserAuthorizedRegistrar(widget.user));
    widget.onDataChanged();
  }

  // Members: 8 state changes, then a 1-hour lock. Authorized Registrars /
  // King / Admin are unlimited.
  bool _canChangeCivicState() {
    NgmyCivicStateSwitches.refreshLockIfNeeded(
      switchesUsed: widget.user.civicRegistryStateSwitchesUsed,
      lockedUntil: _stateSwitchLockedUntil,
      setSwitchesUsed: (n) => widget.user.civicRegistryStateSwitchesUsed = n,
      setLockedUntil: (u) => _stateSwitchLockedUntil = u,
    );
    return NgmyCivicStateSwitches.canChangeState(
      isAdmin: widget.user.isAdmin,
      isCivicRegistryAdmin: widget.user.isCivicRegistryAdmin,
      isCivicRegistryKing: widget.user.isCivicRegistryKing,
      isAuthorizedRegistrar: _hasRegistrarAccess(),
      switchesUsed: widget.user.civicRegistryStateSwitchesUsed,
      lockedUntil: _stateSwitchLockedUntil,
    );
  }

  Future<bool> _applyCivicStateChange(String newState) async {
    final from = _selectedState;
    if (from.trim().toLowerCase() == newState.trim().toLowerCase()) return true;
    final ok = NgmyCivicStateSwitches.tryConsumeSwitch(
      isAdmin: widget.user.isAdmin,
      isCivicRegistryAdmin: widget.user.isCivicRegistryAdmin,
      isCivicRegistryKing: widget.user.isCivicRegistryKing,
      isAuthorizedRegistrar: _hasRegistrarAccess(),
      fromState: from,
      toState: newState,
      anchorState: widget.user.civicRegistryAnchorState,
      setAnchorState: (s) => widget.user.civicRegistryAnchorState = s,
      switchesUsed: widget.user.civicRegistryStateSwitchesUsed,
      setSwitchesUsed: (n) => widget.user.civicRegistryStateSwitchesUsed = n,
      lockedUntil: _stateSwitchLockedUntil,
      setLockedUntil: (u) => _stateSwitchLockedUntil = u,
    );
    if (!ok) {
      if (mounted) {
        final lock = _stateSwitchLockedUntil;
        final locked = lock != null && DateTime.now().toUtc().isBefore(lock.toUtc());
        final mins = locked
            ? lock.toUtc().difference(DateTime.now().toUtc()).inMinutes.clamp(1, 60)
            : 60;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              locked
                  ? 'State changes locked. Try again in ${mins}m.'
                  : 'You have used all ${NgmyCivicStateSwitches.maxSwitches} state changes. Wait 1 hour, then you can change again.',
            ),
          ),
        );
      }
      return false;
    }
    unawaited(_persistStateSwitchLocal());
    unawaited(_pushUserAuthorizedRegistrar(widget.user));
    widget.onDataChanged();

    // Home-state AR (or King/Admin) never sits behind membership verify.
    if (_canUseRegistrarToolsHere(newState)) {
      if (!mounted) return false;
      setState(() {
        widget.user.state = newState;
        _selectedState = newState;
        _selectedCity = 'All Cities';
        _selectedRoom = 'All Rooms';
        _registryUnlocked = true;
      });
      unawaited(_persistStateSwitchLocal());
      unawaited(_pushUserAuthorizedRegistrar(widget.user));
      widget.onDataChanged();
      return true;
    }

    if (_stateRequiresMemberUnlock(newState)) {
      final unlocked = await civicRegistryIsUnlocked(
        widget.user.email,
        state: newState,
        globalPin: widget.config.civicRegistryPin,
        pinsByState: widget.config.civicRegistryPinsByState,
      );
      if (!unlocked) {
        if (!mounted) return false;
        setState(() {
          widget.user.state = newState;
          _selectedState = newState;
          _selectedCity = 'All Cities';
          _selectedRoom = 'All Rooms';
          _registryUnlocked = false;
          if (_activeTab > 1) _activeTab = 0;
        });
        return false;
      }
    }
    if (!mounted) return false;
    setState(() {
      // The chosen state is the member's active Civic Registry state. It is
      // persisted with the switch allowance and controls receipt visibility.
      widget.user.state = newState;
      _selectedState = newState;
      _selectedCity = 'All Cities';
      _selectedRoom = 'All Rooms';
      _registryUnlocked = true;
      // Away from home AR state → member UI (no Enroll / Members tools).
      if (!_canUseRegistrarToolsHere() && _activeTab > 1) {
        _activeTab = 0;
      }
    });
    unawaited(_persistStateSwitchLocal());
    unawaited(_pushUserAuthorizedRegistrar(widget.user));
    widget.onDataChanged();
    return true;
  }

