  List<UserData> _registryMembersMatchingSearch() {
    final q = _searchQuery.trim();
    final active = _civicRegistryMembersForDisplay(widget.config, widget.allUsers)
        .where((u) => u.state.trim().toLowerCase() == _selectedState.trim().toLowerCase())
        .toList();
    final deceased = _civicDeceasedMembersForDisplay(widget.config, widget.allUsers, state: _selectedState);
    final pool = [...active, ...deceased];
    if (q.isEmpty) return pool;

    final scored = <({UserData u, double score})>[];
    for (final u in pool) {
      final raw = _civicMemberOrDeceasedRaw(widget.config, u);
      final nicks = raw == null ? const <String>[] : NgmyCivicRegistryMembers.nicknamesOf(raw);
      final score = _ngmyCivicMemberSearchScore(q, u, nicks);
      // Keep close name matches only (exact / prefix / 1–2 letter typos).
      if (score >= 0.75) scored.add((u: u, score: score));
    }
    scored.sort((a, b) {
      final byScore = b.score.compareTo(a.score);
      if (byScore != 0) return byScore;
      final an = (a.u.fullName ?? a.u.username).toLowerCase();
      final bn = (b.u.fullName ?? b.u.username).toLowerCase();
      return an.compareTo(bn);
    });
    return scored.map((e) => e.u).toList();
  }

  Future<void> _persistReceiptReadState() async {
    final email = widget.user.email.toLowerCase().trim();
    if (email.isEmpty) return;
    widget.user.openedContributionReceiptKeys = _openedReceiptKeys.toList();
    widget.user.dismissedContributionReceiptKeys = _dismissedReceiptKeys.toList();
    await NgmyCivicReadState.saveOpened(email, _openedReceiptKeys);
    await NgmyCivicReadState.saveDismissed(email, _dismissedReceiptKeys);
    unawaited(_pushUserContributionReceiptReads(widget.user));
    widget.onDataChanged();
  }

  void _markCampaignClosed(String campaignId, DateTime closedAt, {String? state}) {
    if (campaignId.trim().isEmpty) return;
    final closures = List<Map<String, dynamic>>.from(widget.config.helpCampaignClosures.map((e) => Map<String, dynamic>.from(e)));
    final idx = closures.indexWhere((e) => (e['campaignId'] ?? '').toString() == campaignId);
    final record = <String, dynamic>{
      'campaignId': campaignId,
      'closedAt': closedAt.toUtc().toIso8601String(),
      if ((state ?? '').trim().isNotEmpty) 'state': state!.trim(),
    };
    if (idx >= 0) {
      closures[idx] = record;
    } else {
      closures.add(record);
    }
    widget.config.helpCampaignClosures = closures;
  }

  void _runHelpModeLifecycleMaintenance() {
    var changed = false;
    var helpModeNeedsPersist = false;
    final now = DateTime.now();
    // Always evaluate the state the user is currently viewing — registrars
    // can switch states, and auto-expiry must hit that campaign, not the
    // stale home-state stamp on widget.user.state.
    final state = _selectedState.trim().isNotEmpty ? _selectedState.trim() : _helpModeState();

    final startedAtRaw = widget.config.helpCampaignStartedAtFor(state).trim();
    if (widget.config.helpActiveFor(state) && startedAtRaw.isEmpty) {
      // Backfill only the missing timestamp — setHelpCampaign(startNewCampaignId:
      // false) would just preserve this same empty value, not stamp "now".
      // Keys in helpModeByState are always lowercased (_stateKey); writing
      // with the display casing creates an orphan entry the read side never
      // finds, so the campaign looks stuck / never expires.
      final key = state.trim().toLowerCase();
      final next = Map<String, dynamic>.from(widget.config.helpModeByState);
      final campaign = Map<String, dynamic>.from(next[key] as Map? ?? const {});
      campaign['campaignStartedAt'] = now.toUtc().toIso8601String();
      next[key] = campaign;
      widget.config.helpModeByState = next;
      changed = true;
      helpModeNeedsPersist = true;
    }
    if (widget.config.helpActiveFor(state) && startedAtRaw.isNotEmpty) {
      try {
        final startedAt = DateTime.parse(startedAtRaw).toLocal();
        // Hard cap: 2 months. Then auto-deactivate once, persist to cloud, and
        // never blink back on. Missed is recorded only at that close.
        if (ngmyHelpCampaignReachedMaxDuration(startedAt, now)) {
          final campaignId = _activeHelpCampaignId(state);
          final alreadyClosed = campaignId.trim().isNotEmpty &&
              widget.config.helpCampaignClosures.any(
                (c) => (c['campaignId'] ?? '').toString().trim() == campaignId.trim(),
              );
          // Snapshot members while help is still active so a second pass
          // (or another device) cannot re-increment missed.
          final membersInScope = alreadyClosed
              ? const <UserData>[]
              : _membersInCurrentHelpScope(forState: state);
          if (!alreadyClosed) {
            // Missed first, then close — markMissed treats an existing closure
            // as "already handled" and would skip if we closed first.
            _markMissedForNonContributorsInCampaign(
              campaignId,
              members: membersInScope,
              campaignStartedAt: startedAt,
              campaignState: state,
            );
            _markCampaignClosed(campaignId, now, state: state);
          }
          widget.config.deactivateHelpCampaign(state);
          changed = true;
          helpModeNeedsPersist = true;
        }
      } catch (_) {}
    }

    // Force any campaign that already has a closure record to stay inactive —
    // protects against a stale cloud "active" row resurrecting the banner.
    if (widget.config.helpCampaignClosures.isNotEmpty) {
      final closedIds = <String>{
        for (final c in widget.config.helpCampaignClosures)
          if ((c['campaignId'] ?? '').toString().trim().isNotEmpty)
            (c['campaignId'] ?? '').toString().trim(),
      };
      final next = Map<String, dynamic>.from(widget.config.helpModeByState);
      var forcedOff = false;
      next.forEach((key, raw) {
        if (raw is! Map) return;
        final campaign = Map<String, dynamic>.from(raw);
        final cid = (campaign['campaignId'] ?? '').toString().trim();
        if (cid.isEmpty || !closedIds.contains(cid)) return;
        if (campaign['active'] == true) {
          campaign['active'] = false;
          next[key] = campaign;
          forcedOff = true;
        }
      });
      if (forcedOff) {
        widget.config.helpModeByState = next;
        changed = true;
        helpModeNeedsPersist = true;
      }
    }

    if (widget.config.helpCampaignClosures.isNotEmpty) {
      // Closures stay forever — they are the missed-count idempotency key.
      // Only dismiss old receipts once a campaign has been closed long enough.
      for (final c in widget.config.helpCampaignClosures) {
        final campaignId = (c['campaignId'] ?? '').toString().trim();
        final closedAtRaw = (c['closedAt'] ?? '').toString().trim();
        if (campaignId.isEmpty || closedAtRaw.isEmpty) continue;
        DateTime? closedAt;
        try {
          closedAt = DateTime.parse(closedAtRaw).toLocal();
        } catch (_) {}
        if (closedAt == null) continue;
        if (now.difference(closedAt) < const Duration(days: kNgmyContributionReceiptAfterCloseDays)) {
          continue;
        }
        _dismissedReceiptKeys.add(campaignId);
        if (!widget.config.dismissedContributionReceiptKeys.contains(campaignId)) {
          widget.config.dismissedContributionReceiptKeys = [
            ...widget.config.dismissedContributionReceiptKeys,
            campaignId,
          ];
          changed = true;
        }
      }
    }

    if (changed) {
      unawaited(_persistReceiptReadState());
      widget.onDataChanged();
      if (mounted) setState(() {});
    }
    if (helpModeNeedsPersist) {
      // Critical: without this, cloud still says "active" and the 75s poll
      // resurrects the banner, re-runs expiry, and re-counts missed.
      unawaited(ngmyPersistCivicHelpModeSettings(widget.config));
    }
  }

  void _queueHelpModeLifecycleMaintenance() {
    if (_maintenanceQueued) return;
    _maintenanceQueued = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _maintenanceQueued = false;
      if (!mounted) return;
      _runHelpModeLifecycleMaintenance();
    });
  }

  void _ensureUniqueRegistryIds() {
    // Only rewrite prefixes / collapse accidental clones — never mint a second profile.
    final before = NgmyCivicRegistryMembers.listFrom(widget.config).length;
    final removed = NgmyCivicRegistryMembers.normalizeRegistryIdsInPlace(widget.config);
    final after = NgmyCivicRegistryMembers.listFrom(widget.config);

    // Keep app profile IDs in lockstep with the single civic row for that email.
    var syncedUsers = false;
    for (final m in after) {
      final email = NgmyCivicRegistryMembers.emailKey((m['email'] ?? '').toString());
      final id = (m['registryId'] ?? '').toString().trim();
      if (email.isEmpty || id.isEmpty) continue;
      for (final u in widget.allUsers) {
        if (NgmyCivicRegistryMembers.emailKey(u.email) != email) continue;
        if ((u.registryId ?? '').trim() != id) {
          u.registryId = id;
          syncedUsers = true;
        }
      }
      if (NgmyCivicRegistryMembers.emailKey(widget.user.email) == email &&
          (widget.user.registryId ?? '').trim() != id) {
        widget.user.registryId = id;
        syncedUsers = true;
      }
    }

    // Fill blank IDs only (still in place — no new rows).
    final seen = <String>{};
    var mintedBlank = false;
    final members = NgmyCivicRegistryMembers.listFrom(widget.config);
    for (var i = 0; i < members.length; i++) {
      var id = (members[i]['registryId'] ?? '').toString().trim();
      final state = (members[i]['state'] ?? _selectedState).toString();
      if (id.isEmpty) {
        id = _generateUniqueRegistryId(state);
        members[i] = Map<String, dynamic>.from(members[i])..['registryId'] = id;
        mintedBlank = true;
      }
      seen.add(id);
    }
    if (mintedBlank) NgmyCivicRegistryMembers.setList(widget.config, members);

    if (removed > 0 || syncedUsers || mintedBlank || before != after.length) {
      unawaited(NgmyCivicRegistryMembers.saveLocalBackup(widget.config));
      unawaited(ngmyPersistCivicRegistryMembers(widget.config));
      widget.onDataChanged();
      if (mounted) setState(() {});
    }
  }

  String _generateUniqueRegistryId(String state) {
    final prefix = NgmyCivicRegistryIdCard.stateCode(state);
    final existing = <String>{
      ...widget.allUsers.map((u) => (u.registryId ?? '').trim()).where((id) => id.isNotEmpty),
      ...NgmyCivicRegistryMembers.listFrom(widget.config)
          .map((m) => (m['registryId'] ?? '').toString().trim())
          .where((id) => id.isNotEmpty),
    };
    for (int i = 0; i < 5000; i++) {
      final candidate = '$prefix${math.Random().nextInt(8999999) + 1000000}';
      if (!existing.contains(candidate)) return candidate;
    }
    return '$prefix${DateTime.now().microsecondsSinceEpoch}';
  }

  void _clearEnrollmentForm({bool clearEditing = true}) {
    _fullNameC.clear();
    _dobC.clear();
    _idTypeC.text = 'National ID';
    _addressC.clear();
    _phoneC.clear();
    _emailC.clear();
    _cityC.clear();
    _roomC.clear();
    _familyMembersC.clear();
    _familyMalesC.clear();
    _familyFemalesC.clear();
    _enrollmentFlags = {};
    if (clearEditing) {
      _editingMemberOriginalEmail = null;
      _editingMemberRegistryId = null;
    }
  }

  void _openEnrollmentForMember(UserData u) {
    final raw = NgmyCivicRegistryMembers.findByEmail(widget.config, u.email) ??
        ((u.registryId ?? '').trim().isEmpty
            ? null
            : NgmyCivicRegistryMembers.findByRegistryId(widget.config, u.registryId!));
    const idTypes = ['National ID', 'Passport', 'Drivers License', 'Voters Card'];
    final idType = (raw?['idType'] ?? u.idType ?? '').toString().trim();
    final familyRaw = raw?['familyMembers'];
    final familyStr = familyRaw is num ? '${familyRaw.toInt()}' : (familyRaw?.toString() ?? '').trim();
    final malesRaw = raw?['familyMales'];
    final femalesRaw = raw?['familyFemales'];
    final malesStr = malesRaw is num ? '${malesRaw.toInt()}' : (malesRaw?.toString() ?? '').trim();
    final femalesStr = femalesRaw is num ? '${femalesRaw.toInt()}' : (femalesRaw?.toString() ?? '').trim();
    final state = (raw?['state'] ?? u.state).toString().trim();
    final phoneDigits = (raw?['phone'] ?? u.phone).toString().replaceAll(RegExp(r'\D'), '');
    final registryId = (raw?['registryId'] ?? u.registryId ?? '').toString().trim();

    setState(() {
      _editingMemberOriginalEmail = NgmyCivicRegistryMembers.emailKey(
        (raw?['email'] ?? u.email).toString(),
      );
      _editingMemberRegistryId = registryId;
      _enrollmentFlags = ngmyReadProfileFlags(raw);
      if (state.isNotEmpty) _selectedState = state;
      _fullNameC.text = (raw?['fullName'] ?? u.fullName ?? u.username).toString();
      _dobC.text = (raw?['dob'] ?? u.dob ?? '').toString();
      _idTypeC.text = idTypes.contains(idType) ? idType : (idType.isEmpty ? 'National ID' : idType);
      if (!idTypes.contains(_idTypeC.text)) _idTypeC.text = 'National ID';
      _addressC.text = (raw?['homeAddress'] ?? u.homeAddress ?? '').toString();
      _phoneC.text = ngmyFormatPhoneDisplay(phoneDigits);
      _emailC.text = (raw?['email'] ?? u.email).toString();
      _cityC.text = (raw?['city'] ?? u.city ?? '').toString();
      _roomC.text = (raw?['room'] ?? u.room ?? '').toString();
      _familyMembersC.text = familyStr;
      _familyMalesC.text = malesStr;
      _familyFemalesC.text = femalesStr;
      _activeTab = 1;
    });
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Editing enrollment for ${_fullNameC.text.trim()}. Change only what you need, then save.'),
        backgroundColor: const Color(0xFF2563EB),
      ),
    );
  }

  Future<void> _registerMember({UserData? targetUser, BuildContext? closeSelfSheet}) async {
    final editingEmail = (_editingMemberOriginalEmail ?? '').trim().toLowerCase();
    final editingRegistryId = (_editingMemberRegistryId ?? '').trim();
    final isEditing = targetUser == null && (editingEmail.isNotEmpty || editingRegistryId.isNotEmpty);

    if (isEditing) {
      await _updateExistingMemberEnrollment(
        editingEmail: editingEmail,
        editingRegistryId: editingRegistryId,
      );
      return;
    }

    final fullName = _fullNameC.text.trim();
    final dob = _dobC.text.trim();
    final idType = _idTypeC.text.trim();
    final address = _addressC.text.trim();
    final phoneDigits = _phoneC.text.replaceAll(RegExp(r'\D'), '');
    final phone = phoneDigits;
    final email = _emailC.text.trim().toLowerCase();
    final city = _cityC.text.trim();
    final room = _roomC.text.trim();
    final isRegistrarManual = targetUser == null;

    final hasTwoNames = RegExp(r'^\S+\s+\S+').hasMatch(fullName);
    if (fullName.isEmpty || !hasTwoNames) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Full name is required (first and last name).')));
      return;
    }
    if (dob.isNotEmpty && !RegExp(r'^\d{2}/\d{2}/\d{4}$').hasMatch(dob)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Date of Birth must be in MM/DD/YYYY format.')));
      return;
    }
    if (!isRegistrarManual && !RegExp(r'^\d{2}/\d{2}/\d{4}$').hasMatch(dob)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Date of Birth must be in MM/DD/YYYY format.')));
      return;
    }
    if (idType.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please select ID Type.')));
      return;
    }
    if (address.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Home address is required.')));
      return;
    }
    if (phone.isEmpty || !RegExp(r'^\d{7,15}$').hasMatch(phone)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Phone number is required (7–15 digits).')));
      return;
    }
    if (email.isNotEmpty && !RegExp(r'^[^\s@]+@[^\s@]+\.[^\s@]+$').hasMatch(email)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please enter a valid email address.')));
      return;
    }
    if (!isRegistrarManual && email.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please enter a valid email address.')));
      return;
    }
    if (!_citiesForSelectedState().contains(city)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please choose a city from Manage Cities & Rooms.')));
      return;
    }
    if (room.isNotEmpty && !widget.config.rooms.contains(room)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please choose a room from Manage Cities & Rooms.')));
      return;
    }
    if (!isRegistrarManual && (room.isEmpty || !widget.config.rooms.contains(room))) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please choose a room from Manage Cities & Rooms.')));
      return;
    }
    final familyMembers = int.tryParse(_familyMembersC.text.trim()) ?? 0;
    final malesRaw = _familyMalesC.text.trim();
    final femalesRaw = _familyFemalesC.text.trim();
    final familyMales = malesRaw.isEmpty ? 0 : (int.tryParse(malesRaw) ?? -1);
    final familyFemales = femalesRaw.isEmpty ? 0 : (int.tryParse(femalesRaw) ?? -1);
    if (familyMembers < 1 || familyMembers > 99) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Family size is required (1–99).')));
      return;
    }
    if (malesRaw.isNotEmpty && familyMales < 0) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Males must be a number (or leave blank).')));
      return;
    }
    if (femalesRaw.isNotEmpty && familyFemales < 0) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Females must be a number (or leave blank).')));
      return;
    }
    // Male/female split is optional. Only enforce the sum when both are provided.
    if (malesRaw.isNotEmpty && femalesRaw.isNotEmpty && familyMales + familyFemales != familyMembers) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Males + females must equal family size ($familyMembers), or leave male/female blank.')),
      );
      return;
    }

    if (targetUser != null && email.isNotEmpty && targetUser.email.toLowerCase().trim() != email) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Use your account email for self-enrollment.')));
      return;
    }

    // Use the email the controller typed — never invent @guest.ngmy addresses.
    // Same email is allowed for multiple registrar-enrolled members (forceNew),
    // but identity duplicates (phone / name+dob / name+address) are still blocked.
    // Do NOT exclude by email for registrar enroll — that hid prior members who share an email.
    final registryEmail = targetUser != null ? email : email;

    final duplicate = NgmyCivicRegistryMembers.findDuplicateRecord(
      config: widget.config,
      fullName: fullName,
      dob: dob,
      city: city,
      homeAddress: address,
      phone: phone,
      excludeEmail: targetUser?.email,
    );
    if (duplicate != null) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(NgmyCivicRegistryMembers.duplicateMessage(duplicate))),
      );
      return;
    }

    final accountIdx = email.isEmpty
        ? -1
        : widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
    var registryId = accountIdx >= 0 ? (widget.allUsers[accountIdx].registryId ?? '').trim() : '';
    if (registryId.isEmpty) registryId = _generateUniqueRegistryId(_selectedState);
    final existingIds = NgmyCivicRegistryMembers.listFrom(widget.config)
        .map((m) => (m['registryId'] ?? '').toString().trim())
        .where((id) => id.isNotEmpty)
        .toSet();
    if (existingIds.contains(registryId)) registryId = _generateUniqueRegistryId(_selectedState);

    final member = NgmyCivicRegistryMembers.buildRecord(
      email: registryEmail,
      fullName: fullName,
      dob: dob,
      idType: idType,
      homeAddress: address,
      phone: phone,
      city: city,
      room: room,
      state: _selectedState,
      registryId: registryId,
      familyMembers: familyMembers,
      familyMales: familyMales,
      familyFemales: familyFemales,
      enrollmentSource: 'registrar',
    );
    final flagsJson = ngmyProfileFlagsToJson(_enrollmentFlags);
    if (flagsJson.isNotEmpty) member['profileFlags'] = flagsJson;

    setState(() {
      NgmyCivicRegistryMembers.upsert(
        widget.config,
        member,
        forceNew: isRegistrarManual,
      );
      if (accountIdx >= 0) {
        widget.allUsers[accountIdx].isEnrolledInRegistry = true;
        widget.allUsers[accountIdx].registryId = registryId;
      }
      if (targetUser != null && NgmyCivicRegistryMembers.emailKey(targetUser.email) == NgmyCivicRegistryMembers.emailKey(email)) {
        widget.user.isEnrolledInRegistry = true;
      }
      if (targetUser == null) {
        _clearEnrollmentForm();
        _activeTab = 2;
      }
    });
    final displayUser = _civicMemberRecordToDisplayUser(member, widget.allUsers);
    final saved = await _persistRegistryMember(displayUser);
    widget.onDataChanged();
    if (closeSelfSheet != null && closeSelfSheet.mounted) Navigator.pop(closeSelfSheet);
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          saved
              ? 'Member enrolled and saved.'
              : 'Member enrolled on this device. Will sync when online — run supabase/users_civic_enrollment_columns.sql if members vanish.',
        ),
        backgroundColor: saved ? Colors.green : Colors.orange,
      ),
    );
    if (targetUser != null) {
      unawaited(showNgmyCivicIdPhotoSheet(
        context,
        config: widget.config,
        email: email,
        onSaved: _persistCivicIdPhotoChange,
      ));
    }
  }

  Future<void> _updateExistingMemberEnrollment({
    required String editingEmail,
    required String editingRegistryId,
  }) async {
    final existing = (editingEmail.isNotEmpty
            ? NgmyCivicRegistryMembers.findByEmail(widget.config, editingEmail)
            : null) ??
        (editingRegistryId.isNotEmpty
            ? NgmyCivicRegistryMembers.findByRegistryId(widget.config, editingRegistryId)
            : null);
    if (existing == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Could not find that member to update. Open Edit Information again.')),
      );
      return;
    }

    String keep(String formValue, String key) {
      final v = formValue.trim();
      if (v.isNotEmpty) return v;
      return (existing[key] ?? '').toString().trim();
    }

    final fullName = keep(_fullNameC.text, 'fullName');
    final dob = keep(_dobC.text, 'dob');
    final idTypeRaw = _idTypeC.text.trim();
    final idType = idTypeRaw.isNotEmpty ? idTypeRaw : (existing['idType'] ?? '').toString().trim();
    final address = keep(_addressC.text, 'homeAddress');
    final phoneRaw = _phoneC.text.trim();
    final phone = phoneRaw.isNotEmpty
        ? phoneRaw.replaceAll(RegExp(r'\D'), '')
        : (existing['phone'] ?? '').toString().replaceAll(RegExp(r'\D'), '');
    final emailRaw = _emailC.text.trim().toLowerCase();
    final email = emailRaw.isNotEmpty
        ? emailRaw
        : NgmyCivicRegistryMembers.emailKey((existing['email'] ?? '').toString());
    final city = _cityC.text.trim(); // may stay empty on update
    final room = _roomC.text.trim(); // may stay empty on update
    final cityFinal = city.isNotEmpty ? city : (existing['city'] ?? '').toString().trim();
    final roomFinal = room.isNotEmpty ? room : (existing['room'] ?? '').toString().trim();
    final familyRaw = _familyMembersC.text.trim();
    final existingFamily = existing['familyMembers'];
    final familyMembers = familyRaw.isNotEmpty
        ? (int.tryParse(familyRaw) ?? 0)
        : (existingFamily is num
            ? existingFamily.toInt()
            : int.tryParse('${existingFamily ?? ''}') ?? 1);
    final malesRawForm = _familyMalesC.text.trim();
    final femalesRawForm = _familyFemalesC.text.trim();
    final existingMales = existing['familyMales'];
    final existingFemales = existing['familyFemales'];
    final familyMales = malesRawForm.isNotEmpty
        ? (int.tryParse(malesRawForm) ?? -1)
        : (existingMales is num
            ? existingMales.toInt()
            : int.tryParse('${existingMales ?? ''}') ?? 0);
    final familyFemales = femalesRawForm.isNotEmpty
        ? (int.tryParse(femalesRawForm) ?? -1)
        : (existingFemales is num
            ? existingFemales.toInt()
            : int.tryParse('${existingFemales ?? ''}') ?? 0);
    final registryId = (existing['registryId'] ?? editingRegistryId).toString().trim();
    final originalEmail = NgmyCivicRegistryMembers.emailKey((existing['email'] ?? editingEmail).toString());

    if (fullName.isEmpty || !RegExp(r'^\S+\s+\S+').hasMatch(fullName)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Full name is required (first and last name).')));
      return;
    }
    if (address.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Home address is required.')));
      return;
    }
    if (phone.isEmpty || !RegExp(r'^\d{7,15}$').hasMatch(phone)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Phone number is required (7–15 digits).')));
      return;
    }
    if (dob.isNotEmpty && !RegExp(r'^\d{2}/\d{2}/\d{4}$').hasMatch(dob)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Date of Birth must be in MM/DD/YYYY format.')));
      return;
    }
    if (email.isNotEmpty && !RegExp(r'^[^\s@]+@[^\s@]+\.[^\s@]+$').hasMatch(email)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please enter a valid email address.')));
      return;
    }
    if (familyMembers < 1 || familyMembers > 99) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Family size is required (1–99).')));
      return;
    }
    if (malesRawForm.isNotEmpty && familyMales < 0) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Males must be a number (or leave blank).')));
      return;
    }
    if (femalesRawForm.isNotEmpty && familyFemales < 0) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Females must be a number (or leave blank).')));
      return;
    }
    if (malesRawForm.isNotEmpty && femalesRawForm.isNotEmpty && familyMales + familyFemales != familyMembers) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Males + females must equal family size ($familyMembers), or leave male/female blank.')),
      );
      return;
    }

    final duplicate = NgmyCivicRegistryMembers.findDuplicateRecord(
      config: widget.config,
      fullName: fullName,
      dob: dob,
      city: cityFinal,
      homeAddress: address,
      phone: phone,
      excludeEmail: originalEmail,
      excludeRegistryId: registryId,
    );
    if (duplicate != null) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(NgmyCivicRegistryMembers.duplicateMessage(duplicate))),
      );
      return;
    }

    final updated = NgmyCivicRegistryMembers.updateExisting(
      widget.config,
      originalEmail: originalEmail,
      registryId: registryId,
      fields: {
        'email': email,
        'fullName': fullName,
        'dob': dob,
        'idType': idType,
        'homeAddress': address,
        'phone': phone,
        'city': cityFinal,
        'room': roomFinal,
        'state': _selectedState,
        'familyMembers': familyMembers < 1 ? 1 : familyMembers,
        'familyMales': familyMales < 0 ? 0 : familyMales,
        'familyFemales': familyFemales < 0 ? 0 : familyFemales,
        'profileFlags': ngmyProfileFlagsToJson(_enrollmentFlags),
      },
    );
    if (updated == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Update failed — that email may already belong to another member.')),
      );
      return;
    }

    if (NgmyCivicRegistryMembers.emailKey(originalEmail) != NgmyCivicRegistryMembers.emailKey(email)) {
      _setCivicEnrollmentFlagForAccount(widget.allUsers, originalEmail, false);
    }
    final accountIdx = widget.allUsers.indexWhere(
      (u) => NgmyCivicRegistryMembers.emailKey(u.email) == NgmyCivicRegistryMembers.emailKey(email),
    );
    setState(() {
      if (accountIdx >= 0) {
        widget.allUsers[accountIdx].isEnrolledInRegistry = true;
        widget.allUsers[accountIdx].registryId = registryId;
        widget.allUsers[accountIdx].fullName = fullName;
        widget.allUsers[accountIdx].phone = phone;
        widget.allUsers[accountIdx].homeAddress = address;
        widget.allUsers[accountIdx].dob = dob;
        widget.allUsers[accountIdx].idType = idType;
        widget.allUsers[accountIdx].city = cityFinal;
        widget.allUsers[accountIdx].room = roomFinal;
        widget.allUsers[accountIdx].state = _selectedState;
      }
      _clearEnrollmentForm();
      _activeTab = 2;
    });

    // Persist the updated registry row directly — do not rebuild from UserData (that was dropping edits).
    await NgmyCivicRegistryMembers.saveLocalBackup(widget.config);
    final saved = await ngmyPersistCivicRegistryMembers(widget.config);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(widget.config.toJson()));
      await prefs.setString('all_users', jsonEncode(widget.allUsers.map((e) => e.toJson()).toList()));
      await NgmyCivicRegistryMembers.saveLocalBackup(widget.config);
    } catch (e) {
      debugPrint('Member update local save failed: $e');
    }
    if (await ngmyCanReachCloud() && accountIdx >= 0) {
      try {
        await Supabase.instance.client
            .from('users')
            .upsert(_userRowForRegistryEnrollmentFlag(widget.allUsers[accountIdx]), onConflict: 'email')
            .timeout(kNgmyCloudWriteTimeout);
      } catch (e) {
        debugPrint('Member update enrollment flag upsert failed: $e');
      }
    }
    widget.onDataChanged();
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(saved ? 'Member profile updated.' : 'Member updated on this device. Will sync when online.'),
        backgroundColor: saved ? Colors.green : Colors.orange,
      ),
    );
  }

  Future<bool> _persistRegistryMember(UserData member) async {
    _syncCivicMemberRecordFromUser(widget.config, member);
    _setCivicEnrollmentFlagForAccount(widget.allUsers, member.email, true);
    if (NgmyCivicRegistryMembers.emailKey(widget.user.email) == NgmyCivicRegistryMembers.emailKey(member.email)) {
      widget.user.isEnrolledInRegistry = true;
    }

    var membersCloudOk = await ngmyPersistCivicRegistryMembers(widget.config);
    var userCloudOk = true;
    final accountIdx = widget.allUsers.indexWhere(
      (u) => NgmyCivicRegistryMembers.emailKey(u.email) == NgmyCivicRegistryMembers.emailKey(member.email),
    );
    if (await ngmyCanReachCloud() && accountIdx >= 0) {
      try {
        await Supabase.instance.client
            .from('users')
            .upsert(_userRowForRegistryEnrollmentFlag(widget.allUsers[accountIdx]), onConflict: 'email')
            .timeout(kNgmyCloudWriteTimeout);
      } catch (e) {
        userCloudOk = false;
        debugPrint('Registry enrollment flag upsert failed: $e');
      }
    }

    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(widget.config.toJson()));
      await prefs.setString('all_users', jsonEncode(widget.allUsers.map((e) => e.toJson()).toList()));
      if (NgmyCivicRegistryMembers.emailKey(widget.user.email) == NgmyCivicRegistryMembers.emailKey(member.email)) {
        await prefs.setString('current_user', jsonEncode(widget.user.toJson()));
      }
    } catch (e) {
      debugPrint('Registry member local save failed: $e');
    }
    return membersCloudOk && userCloudOk;
  }

  Future<void> _transferCivicMemberFromProfile(UserData member) async {
    if (!_canAdminTransferCivicState()) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Only an admin can transfer members between states.')),
      );
      return;
    }
    final fromState = member.state.trim().isEmpty ? _selectedState : member.state.trim();
    final picked = await showNgmyStatePickerSheet(
      context,
      states: _usStates,
      selected: fromState,
      title: 'Transfer to state',
      searchHint: 'Search destination state…',
    );
    if (picked == null || !mounted) return;
    if (picked.trim().toLowerCase() == fromState.toLowerCase()) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('${member.fullName ?? member.username} is already in $picked.')),
      );
      return;
    }
    final ok = await showNgmyLightConfirm(
      context,
      title: 'Transfer to $picked?',
      message:
          'Move ${member.fullName ?? member.username} from $fromState to $picked with their full civic registry record '
          '(profile, helps, missed, passport, nicknames, photo, claims, and contributions). '
          'City and room will be cleared for reassignment in $picked.',
      cancelLabel: 'Cancel',
      confirmLabel: 'Transfer',
      icon: Icons.swap_horiz_rounded,
    );
    if (ok != true || !mounted) return;

    final updated = NgmyCivicRegistryMembers.transferToState(
      widget.config,
      toState: picked,
      email: member.email,
      registryId: member.registryId ?? '',
    );
    if (updated == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Transfer failed — member record not found.'), backgroundColor: Color(0xFFDC2626)),
      );
      return;
    }

    final emailKey = NgmyCivicRegistryMembers.emailKey(member.email);
    final oldRid = (member.registryId ?? '').trim().toUpperCase();
    final newRid = (updated['registryId'] ?? '').toString().trim();
    void applyLinked(UserData u) {
      u.state = picked;
      u.city = '';
      u.room = '';
      if (newRid.isNotEmpty) u.registryId = newRid;
      if (u.civicRegistryAnchorState.trim().isNotEmpty) {
        u.civicRegistryAnchorState = picked;
      }
    }
    for (final u in widget.allUsers) {
      final sameEmail = emailKey.isNotEmpty && NgmyCivicRegistryMembers.emailKey(u.email) == emailKey;
      final sameId = oldRid.isNotEmpty && (u.registryId ?? '').trim().toUpperCase() == oldRid;
      if (sameEmail || sameId) applyLinked(u);
    }
    member.state = picked;
    member.city = '';
    member.room = '';
    if (newRid.isNotEmpty) member.registryId = newRid;

    await NgmyCivicRegistryMembers.saveLocalBackup(widget.config);
    final cloudOk = await ngmyPersistCivicRegistryMembers(widget.config);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(widget.config.toJson()));
      await prefs.setString('all_users', jsonEncode(widget.allUsers.map((e) => e.toJson()).toList()));
    } catch (_) {}
    if (await ngmyCanReachCloud() && emailKey.isNotEmpty) {
      final idx = widget.allUsers.indexWhere((u) => NgmyCivicRegistryMembers.emailKey(u.email) == emailKey);
      if (idx >= 0) {
        try {
          await Supabase.instance.client
              .from('users')
              .upsert(
                {
                  'email': widget.allUsers[idx].email.trim().toLowerCase(),
                  'state': picked,
                  'city': '',
                  'room': '',
                  'registryId': widget.allUsers[idx].registryId,
                  'civicRegistryAnchorState': widget.allUsers[idx].civicRegistryAnchorState,
                },
                onConflict: 'email',
              )
              .timeout(kNgmyCloudWriteTimeout);
        } catch (_) {}
      }
    }

    if (!mounted) return;
    setState(() {});
    widget.onDataChanged();
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          cloudOk
              ? '${member.fullName ?? member.username} transferred to $picked.'
              : '${member.fullName ?? member.username} moved locally to $picked. Cloud sync may still be catching up.',
        ),
        backgroundColor: cloudOk ? const Color(0xFF059669) : const Color(0xFFD97706),
      ),
    );
  }

  Future<bool> _markRegistryMemberDeceased(UserData member) async {
    final confirm = await showNgmyLightConfirm(
      context,
      title: 'Mark member as deceased?',
      message:
          'This removes ${member.fullName ?? member.username} from active members and state counts. They stay searchable with limited public info. Their contributions will no longer count in nationwide totals.',
      cancelLabel: 'Cancel',
      confirmLabel: 'Mark deceased',
      icon: Icons.person_off_rounded,
      destructive: true,
    );
    if (confirm != true) return false;

    final ok = NgmyCivicRegistryMembers.markDeceased(
      widget.config,
      email: member.email,
      registryId: member.registryId ?? '',
      markedByEmail: widget.user.email,
      markedByName: (widget.user.fullName ?? widget.user.username).trim(),
    );
    if (!ok) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Could not mark member as deceased.')),
        );
      }
      return false;
    }

    final emailKey = NgmyCivicRegistryMembers.emailKey(member.email);
    final registryId = (member.registryId ?? '').trim();
    void clearActiveStanding(UserData u) {
      u.isEnrolledInRegistry = false;
      u.registryId = '';
      u.helps = 0;
      u.missed = 0;
    }

    _setCivicEnrollmentFlagForAccount(widget.allUsers, member.email, false);
    final accountIdx = widget.allUsers.indexWhere(
      (u) => NgmyCivicRegistryMembers.emailKey(u.email) == emailKey,
    );
    if (accountIdx >= 0) clearActiveStanding(widget.allUsers[accountIdx]);
    if (NgmyCivicRegistryMembers.emailKey(widget.user.email) == emailKey ||
        ((widget.user.registryId ?? '').trim().isNotEmpty && (widget.user.registryId ?? '').trim() == registryId)) {
      clearActiveStanding(widget.user);
    }

    final membersCloudOk = await ngmyPersistCivicRegistryMembers(widget.config);
    NgmyAdminLiveRefresh.notify();
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(widget.config.toJson()));
      await prefs.setString('all_users', jsonEncode(widget.allUsers.map((e) => e.toJson()).toList()));
      if (NgmyCivicRegistryMembers.emailKey(widget.user.email) == emailKey) {
        await prefs.setString('current_user', jsonEncode(widget.user.toJson()));
      }
    } catch (_) {}
    widget.onDataChanged();
    if (mounted) {
      setState(() {});
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            membersCloudOk
                ? '${member.fullName ?? member.username} marked deceased — moved to nationwide deceased count.'
                : 'Marked deceased locally — will sync when online.',
          ),
          backgroundColor: membersCloudOk ? Colors.green : Colors.orange,
        ),
      );
    }
    return membersCloudOk;
  }

  Future<bool> _removeRegistryMember(UserData member, {bool permanent = false}) async {
    final emailKey = NgmyCivicRegistryMembers.emailKey(member.email);
    final registryId = (member.registryId ?? '').trim();
    final hard = permanent || _isGlobalCivicRegistryAdmin();
    if (hard) {
      if (registryId.isNotEmpty) {
        NgmyCivicRegistryMembers.permanentDeleteByRegistryId(widget.config, registryId);
      } else if (emailKey.isNotEmpty) {
        NgmyCivicRegistryMembers.permanentDeleteByEmail(widget.config, member.email);
      }
    } else if (registryId.isNotEmpty) {
      NgmyCivicRegistryMembers.softDeleteByRegistryId(widget.config, registryId);
    } else if (emailKey.isNotEmpty) {
      NgmyCivicRegistryMembers.softDeleteByEmail(widget.config, member.email);
    }
    void clearCivicFields(UserData u) {
      u.isEnrolledInRegistry = false;
      u.registryId = '';
      // Keep personal contact fields on the app account; strip registry standing so
      // search/rankings/ID surfaces cannot resurrect them without a restore.
      u.helps = 0;
      u.missed = 0;
    }

    _setCivicEnrollmentFlagForAccount(widget.allUsers, member.email, false);
    final accountIdx = widget.allUsers.indexWhere(
      (u) => NgmyCivicRegistryMembers.emailKey(u.email) == emailKey,
    );
    if (accountIdx >= 0) clearCivicFields(widget.allUsers[accountIdx]);
    // Also clear any app user linked by the same registry phone / linked passport email.
    for (final u in widget.allUsers) {
      final linked = NgmyCivicRegistryMembers.findByEmail(widget.config, u.email);
      if (linked != null) continue;
      if (NgmyCivicRegistryMembers.emailKey(u.email) == emailKey ||
          ((u.registryId ?? '').trim().isNotEmpty && (u.registryId ?? '').trim() == registryId)) {
        clearCivicFields(u);
      }
    }
    if (NgmyCivicRegistryMembers.emailKey(widget.user.email) == emailKey ||
        ((widget.user.registryId ?? '').trim().isNotEmpty && (widget.user.registryId ?? '').trim() == registryId)) {
      clearCivicFields(widget.user);
    }

    final membersCloudOk = await ngmyPersistCivicRegistryMembers(widget.config);
    NgmyAdminLiveRefresh.notify();
    var userCloudOk = true;
    if (await ngmyCanReachCloud() && accountIdx >= 0) {
      try {
        await Supabase.instance.client
            .from('users')
            .upsert(_userRowForRegistryEnrollmentFlag(widget.allUsers[accountIdx]), onConflict: 'email')
            .timeout(kNgmyCloudWriteTimeout);
      } catch (e) {
        userCloudOk = false;
      }
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(widget.config.toJson()));
      await prefs.setString('all_users', jsonEncode(widget.allUsers.map((e) => e.toJson()).toList()));
      if (NgmyCivicRegistryMembers.emailKey(widget.user.email) == emailKey) {
        await prefs.setString('current_user', jsonEncode(widget.user.toJson()));
      }
    } catch (_) {}
    return membersCloudOk && userCloudOk;
  }

  Future<String?> _pickCivicBackupText() async {
    try {
      final result = await FilePicker.platform.pickFiles(
        type: FileType.custom,
        allowedExtensions: const ['json', 'ngmy'],
        withData: true,
      );
      final file = result?.files.first;
      if (file == null) return null;
      if (file.bytes != null && file.bytes!.isNotEmpty) {
        return utf8.decode(file.bytes!);
      }
    } catch (_) {}
    return ngmyPickBackupJsonViaBrowser();
  }

  Future<void> _downloadCivicRegistryBackup() async {
    final state = _selectedState.trim();
    if (state.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Select a state before downloading a backup.')),
      );
      return;
    }
    final envelope = NgmyCivicRegistryMembers.backupEnvelope(widget.config, state: state);
    final count = envelope['memberCount'] as int? ?? 0;
    if (count < 1) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('No members in $state to download yet.')),
      );
      return;
    }
    // Stable per-state name so re-downloads can Replace the previous backup
    // instead of piling up timestamped copies.
    final stateSlug = state.replaceAll(RegExp(r'\s+'), '_');
    final filename = 'ngmy-civic-registry-$stateSlug.json';
    final msg = await downloadNgmyAdvisorSyncJson(jsonEncode(envelope), filename, allowReplace: true);
    if (!mounted) return;
    final cancelled = msg.toLowerCase().contains('cancelled');
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          cancelled
              ? msg
              : 'Backup ready ($count $_selectedState member(s)). $msg',
        ),
        backgroundColor: cancelled ? Colors.blueGrey : Colors.green,
      ),
    );
  }

  Future<void> _uploadCivicRegistryBackup() async {
    final currentState = _selectedState.trim();
    if (currentState.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Select a state before uploading a backup.')),
      );
      return;
    }

    final raw = await _pickCivicBackupText();
    if (raw == null || raw.trim().isEmpty) return;

    String fileState;
    List<Map<String, dynamic>> incoming;
    try {
      fileState = NgmyCivicRegistryMembers.backupStateFromJson(raw);
      if (!NgmyCivicRegistryMembers.backupStateMatches(fileState, currentState)) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              fileState.isEmpty
                  ? 'This backup has no state lock. Only state-specific backups can be restored.'
                  : 'This backup belongs to $fileState. It cannot be uploaded while you are in $currentState.',
            ),
            backgroundColor: Colors.red.shade700,
          ),
        );
        return;
      }
      incoming = NgmyCivicRegistryMembers.membersFromBackupJson(raw, requireState: currentState);
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('That file is not a valid civic registry backup.')),
      );
      return;
    }
    if (incoming.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('No $currentState members found in that backup file.')),
      );
      return;
    }

    final result = NgmyCivicRegistryMembers.importMissingMembers(
      widget.config,
      incoming,
      requireState: currentState,
    );
    for (final m in result.restored) {
      final email = NgmyCivicRegistryMembers.emailKey((m['email'] ?? '').toString());
      if (email.isEmpty) continue;
      _setCivicEnrollmentFlagForAccount(widget.allUsers, email, true);
      final idx = widget.allUsers.indexWhere((u) => NgmyCivicRegistryMembers.emailKey(u.email) == email);
      if (idx >= 0) {
        final u = widget.allUsers[idx];
        u.isEnrolledInRegistry = true;
        u.registryId = (m['registryId'] ?? u.registryId ?? '').toString();
        u.fullName = (m['fullName'] ?? u.fullName)?.toString();
        u.helps = m['helps'] is num ? (m['helps'] as num).toInt() : u.helps;
        u.missed = m['missed'] is num ? (m['missed'] as num).toInt() : u.missed;
        u.state = currentState;
        u.city = (m['city'] ?? u.city)?.toString();
        u.room = (m['room'] ?? u.room)?.toString();
        u.homeAddress = (m['homeAddress'] ?? u.homeAddress)?.toString();
        u.phone = (m['phone'] ?? u.phone).toString();
        u.dob = (m['dob'] ?? u.dob)?.toString();
        u.idType = (m['idType'] ?? u.idType)?.toString();
      }
    }

    final ok = await ngmyPersistCivicRegistryMembers(widget.config);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(widget.config.toJson()));
      await prefs.setString('all_users', jsonEncode(widget.allUsers.map((e) => e.toJson()).toList()));
    } catch (_) {}
    widget.onDataChanged();
    if (!mounted) return;
    setState(() {});
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          result.added < 1
              ? 'No new $currentState members to restore — everyone in that file is already enrolled (${result.skipped} skipped).'
              : 'Restored ${result.added} $currentState member(s)${result.skipped > 0 ? ', skipped ${result.skipped} already enrolled' : ''}. '
                  'They are back in Members, Search, and Rankings.',
        ),
        backgroundColor: result.added > 0 ? (ok ? Colors.green : Colors.orange) : Colors.blueGrey,
      ),
    );
  }

  Future<void> _downloadCivicPrintRoster() async {
    final state = _selectedState.trim();
    if (state.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Select a state first.')));
      return;
    }
    final members = NgmyCivicRegistryMembers.listFrom(widget.config)
        .where((m) => (m['state'] ?? '').toString().trim().toLowerCase() == state.toLowerCase())
        .toList();
    NgmyCivicRegistryMembers.sortNewestEnrolledFirst(members);
    if (members.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('No members in $state to print.')));
      return;
    }

    // Build a real PDF (not HTML print). Safari/Chrome HTML tables fragment
    // mid-page and leave hanging lines + nearly-empty continuation pages.
    final rosterRows = <NgmyCivicRosterRow>[];
    for (final m in members) {
      final name = (m['fullName'] ?? '').toString().trim();
      final phoneDigits = (m['phone'] ?? '').toString().replaceAll(RegExp(r'\D'), '');
      final phone = phoneDigits.isEmpty
          ? ''
          : ngmyFormatPhoneDisplay(
              phoneDigits.length >= 10 ? phoneDigits.substring(phoneDigits.length - 10) : phoneDigits,
            );
      final address = (m['homeAddress'] ?? '').toString().trim();
      final familyRaw = m['familyMembers'];
      final family = familyRaw is num ? familyRaw.toInt() : int.tryParse('${familyRaw ?? ''}') ?? 1;
      final malesRaw = m['familyMales'];
      final femalesRaw = m['familyFemales'];
      final males = malesRaw is num ? malesRaw.toInt() : int.tryParse('${malesRaw ?? ''}') ?? 0;
      final females = femalesRaw is num ? femalesRaw.toInt() : int.tryParse('${femalesRaw ?? ''}') ?? 0;
      final familyLabel = (males > 0 || females > 0) ? '$family ($males M / $females F)' : '$family';
      rosterRows.add(
        NgmyCivicRosterRow(
          name: name,
          phone: phone,
          address: address,
          familyLabel: familyLabel,
        ),
      );
    }

    final now = DateTime.now().toLocal();
    final dateStr =
        '${now.year.toString().padLeft(4, '0')}-${now.month.toString().padLeft(2, '0')}-${now.day.toString().padLeft(2, '0')}';
    final hour12 = now.hour % 12 == 0 ? 12 : now.hour % 12;
    final timeStr = '$hour12:${now.minute.toString().padLeft(2, '0')} ${now.hour >= 12 ? 'PM' : 'AM'}';
    final stamp = DateTime.now().toUtc().toIso8601String().replaceAll(':', '-').split('.').first;
    final fileName = 'ngmy-civic-roster-${state.replaceAll(RegExp(r'\s+'), '_')}-$stamp.pdf';

    try {
      final pdfBytes = await ngmyBuildCivicRosterPdfBytes(
        state: state,
        titleLine1: "EMO'YA M'BEMBE",
        titleLine2: "M'MBONDO · $state",
        dateStr: dateStr,
        timeStr: timeStr,
        rows: rosterRows,
      );
      final opened = await ngmyInvoicePrintPdfDirect(pdfBytes, fileName);
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            opened
                ? 'Roster PDF ready for $state (${members.length} members). Each page is a full framed table.'
                : 'Could not open print sheet — try again.',
          ),
          backgroundColor: opened ? Colors.green : Colors.orange,
          duration: const Duration(seconds: 6),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Could not build roster PDF: $e'), backgroundColor: Colors.red),
      );
    }
  }

  String _escapeHtml(String s) => s
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;');

  String _helpScopeLabelForState(String state) {
    if (widget.config.helpScopeTypeFor(state) == 'city') {
      return 'City: ${widget.config.helpScopeValueFor(state)}';
    }
    if (widget.config.helpScopeTypeFor(state) == 'room') {
      return 'Room: ${widget.config.helpScopeValueFor(state)}';
    }
    return 'All members';
  }

  List<UserData> _membersForContributionReport(String state) {
    final stateLower = state.trim().toLowerCase();
    final allInState = _civicRegistryMembersForDisplay(widget.config, widget.allUsers)
        .where((m) => m.state.trim().toLowerCase() == stateLower)
        .toList();
    if (widget.config.helpActiveFor(state)) {
      return _membersInCurrentHelpScope(forState: state);
    }
    final scopeType = widget.config.helpScopeTypeFor(state);
    final scopeValue = widget.config.helpScopeValueFor(state).trim();
    if (scopeType != 'city' && scopeType != 'room') return allInState;
    if (scopeValue.isEmpty) return allInState;
    final wanted = scopeValue.toLowerCase();
    return allInState.where((m) {
      final registry = NgmyCivicRegistryMembers.findByEmail(widget.config, m.email) ??
          (((m.registryId ?? '').trim().isNotEmpty)
              ? NgmyCivicRegistryMembers.findByRegistryId(widget.config, m.registryId!)
              : null);
      final memberCity = ((registry?['city'] ?? m.city) ?? '').toString().trim().toLowerCase();
      final memberRoom = ((registry?['room'] ?? m.room) ?? '').toString().trim().toLowerCase();
      if (scopeType == 'city') return memberCity == wanted;
      return memberRoom == wanted;
    }).toList();
  }

  Map<String, double> _contributionTotalsForCampaign({
    required String state,
    required String campaignId,
    DateTime? campaignStartedAt,
  }) {
    final normalizedCampaignId = campaignId.trim();
    final stateKey = state.trim().toLowerCase();
    if (normalizedCampaignId.isEmpty && campaignStartedAt == null) return const {};

    final totals = <String, double>{};

    void addAmount(String key, double amount) {
      if (key.isEmpty || amount <= 0) return;
      totals[key] = (totals[key] ?? 0) + amount;
    }

    for (final t in _civicTransactionsForDisplay()) {
      if (t.type != TransactionType.contribution || t.status != TransactionStatus.approved) continue;
      final meta = _decodeContributionMeta(t);
      final cid = (meta['campaignId'] ?? '').toString().trim();
      final receiptState = _contributionReceiptState(t, meta).trim().toLowerCase();
      if (stateKey.isNotEmpty && receiptState.isNotEmpty && receiptState != stateKey) continue;

      // Only the current campaign — never match older campaigns by purpose/scope fallback.
      final matchesThisCampaign = cid.isNotEmpty
          ? cid == normalizedCampaignId
          : (normalizedCampaignId.isNotEmpty &&
              campaignStartedAt != null &&
              !t.timestamp.isBefore(campaignStartedAt));
      if (!matchesThisCampaign) continue;

      final emailKey = NgmyCivicRegistryMembers.emailKey(t.userEmail);
      if (emailKey.isNotEmpty) addAmount(emailKey, t.amount);
      final metaEmail = NgmyCivicRegistryMembers.emailKey((meta['memberEmail'] ?? '').toString());
      if (metaEmail.isNotEmpty) addAmount(metaEmail, t.amount);
      final rid = (meta['registryId'] ?? '').toString().trim().toUpperCase();
      if (rid.isNotEmpty) addAmount('rid:$rid', t.amount);
    }
    return totals;
  }

  NgmyCivicContributionReportData? _buildContributionReportData() {
    final state = _selectedState.trim();
    if (state.isEmpty) return null;

    final campaignActive = widget.config.helpActiveFor(state);
    final resolvedCampaignId = widget.config.helpCampaignIdFor(state).trim().isNotEmpty
        ? widget.config.helpCampaignIdFor(state).trim()
        : _activeHelpCampaignId(state).trim();
    DateTime? campaignStartedAt;
    try {
      final raw = widget.config.helpCampaignStartedAtFor(state).trim();
      if (raw.isNotEmpty) campaignStartedAt = DateTime.parse(raw).toLocal();
    } catch (_) {}

    if (resolvedCampaignId.isEmpty && campaignStartedAt == null) return null;

    final campaignTitle = widget.config.helpPurposeFor(state).trim().isNotEmpty
        ? widget.config.helpPurposeFor(state).trim()
        : 'Community Contribution';

    final members = _membersForContributionReport(state);
    Map<String, dynamic>? rawOf(UserData u) {
      final byEmail = NgmyCivicRegistryMembers.findByEmail(widget.config, u.email);
      if (byEmail != null) return byEmail;
      final rid = (u.registryId ?? '').trim();
      if (rid.isEmpty) return null;
      return NgmyCivicRegistryMembers.findByRegistryId(widget.config, rid);
    }
    members.sort((a, b) => NgmyCivicRegistryMembers.compareEnrolledAtDesc(rawOf(a) ?? const {}, rawOf(b) ?? const {}));
    if (members.isEmpty) return null;

    final totals = _contributionTotalsForCampaign(
      state: state,
      campaignId: resolvedCampaignId,
      campaignStartedAt: campaignStartedAt,
    );

    final now = DateTime.now().toLocal();
    final generatedAt =
        '${now.month}/${now.day}/${now.year} ${now.hour % 12 == 0 ? 12 : now.hour % 12}:${now.minute.toString().padLeft(2, '0')} ${now.hour >= 12 ? 'PM' : 'AM'}';

    final rows = members.map((m) {
      final emailKey = NgmyCivicRegistryMembers.emailKey(m.email);
      final ridKey = 'rid:${(m.registryId ?? '').trim().toUpperCase()}';
      final contributed = (emailKey.isNotEmpty && totals.containsKey(emailKey)) ||
          (ridKey != 'rid:' && totals.containsKey(ridKey));
      final amount = (emailKey.isNotEmpty ? totals[emailKey] : null) ??
          (ridKey != 'rid:' ? totals[ridKey] : null) ??
          0.0;
      final phoneDigits = m.phone.replaceAll(RegExp(r'\D'), '');
      final phone = phoneDigits.isEmpty
          ? ''
          : ngmyFormatPhoneDisplay(phoneDigits.length >= 10 ? phoneDigits.substring(phoneDigits.length - 10) : phoneDigits);
      return NgmyCivicContributionReportRow(
        name: (m.fullName ?? m.username).trim(),
        registryId: (m.registryId ?? '').trim(),
        city: (m.city ?? '').trim(),
        room: (m.room ?? '').trim(),
        phone: phone,
        contributed: contributed,
        amount: amount,
      );
    }).toList();

    return NgmyCivicContributionReportData(
      state: state,
      campaignTitle: campaignTitle,
      scopeLabel: _helpScopeLabelForState(state),
      generatedAt: generatedAt,
      campaignActive: campaignActive,
      campaignStartedAt: campaignStartedAt,
      rows: rows,
    );
  }

  Future<void> _openCivicContributionReportSheet() async {
    final data = _buildContributionReportData();
    if (data == null) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            widget.config.helpActiveFor(_selectedState)
                ? 'No members in $_selectedState for this report yet.'
                : 'Start a contribution in $_selectedState first — the report tracks only the current campaign.',
          ),
        ),
      );
      return;
    }
    await showNgmyCivicContributionReportSheet(context, data: data);
  }

  List<AppTransaction> _stateWalletContributionTx([String? forState]) {
    final viewerState = (forState ?? _selectedState).trim().toLowerCase();
    final deleted = widget.config.civicDeletedContributionIds
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toSet();
    return _civicTransactionsForDisplay().where((t) {
      if (t.type != TransactionType.contribution || t.status != TransactionStatus.approved) return false;
      if (deleted.contains(t.id.trim())) return false;
      final meta = _decodeContributionMeta(t);
      final targetState = _contributionReceiptState(t, meta);
      if (viewerState.isEmpty || targetState.isEmpty) return false;
      return targetState.toLowerCase() == viewerState;
    }).toList();
  }

  NgmyCivicWalletSnapshot _buildCivicStateWalletSnapshot([String? forState]) {
    final state = (forState ?? _selectedState).trim();
    final contribRows = _stateWalletContributionTx(state).map((t) {
      final meta = _decodeContributionMeta(t);
      return <String, dynamic>{
        'id': t.id,
        'amount': t.amount,
        'title': (meta['purpose'] ?? 'Contribution').toString(),
        'at': t.timestamp.toUtc().toIso8601String(),
      };
    }).toList();
    final want = state.toLowerCase();
    final spendingRows = widget.config.helpCampaignSpendings
        .map((e) => Map<String, dynamic>.from(e))
        .where((e) {
          final st = (e['state'] ?? '').toString().trim().toLowerCase();
          if (want.isEmpty) return true;
          if (st.isEmpty) return true;
          return st == want;
        })
        .toList();
    return buildNgmyCivicWalletSnapshot(
      state: state,
      contributionRows: contribRows,
      spendingRows: spendingRows,
    );
  }

  NgmyCivicNationwideStats _buildCivicNationwideStats() {
    final members = NgmyCivicRegistryMembers.listFrom(widget.config);
    final deceasedKeys = _civicDeceasedContributorKeys(widget.config);
    final globalResetAt = DateTime.tryParse(widget.config.civicNationwideContributionCountResetAt.trim())?.toUtc();
    final stateResets = widget.config.civicContributionCountResetAtByState;
    final allContribRows = <Map<String, dynamic>>[];
    final countedContribRows = <Map<String, dynamic>>[];
    for (final t in _civicTransactionsForDisplay()) {
      if (t.type != TransactionType.contribution || t.status != TransactionStatus.approved) continue;
      final meta = _decodeContributionMeta(t);
      if (_civicContributionFromDeceased(t, deceasedKeys, meta)) continue;
      final targetState = _contributionReceiptState(t, meta).trim();
      if (targetState.isEmpty) continue;
      final row = <String, dynamic>{
        'id': t.id,
        'amount': t.amount,
        'title': (meta['purpose'] ?? 'Contribution').toString(),
        'at': t.timestamp.toUtc().toIso8601String(),
        'state': targetState,
        'memberName': _contributionMemberDisplayName(t),
        'campaignId': (meta['campaignId'] ?? '').toString().trim(),
        'scopeType': (meta['scopeType'] ?? 'all').toString(),
        'scopeValue': (meta['scopeValue'] ?? '').toString(),
      };
      allContribRows.add(row);
      final txAt = t.timestamp.toUtc();
      final stateResetRaw = stateResets[targetState.toLowerCase()] ?? '';
      final stateResetAt = DateTime.tryParse(stateResetRaw.trim())?.toUtc();
      final afterGlobal = globalResetAt == null || !txAt.isBefore(globalResetAt);
      final afterState = stateResetAt == null || !txAt.isBefore(stateResetAt);
      if (afterGlobal && afterState) {
        countedContribRows.add(row);
      }
    }
    final spendingRows = widget.config.helpCampaignSpendings
        .map((e) => Map<String, dynamic>.from(e))
        .toList();
    return buildNgmyCivicNationwideStats(
      registeredMembers: members.length,
      countedContributionRows: countedContribRows,
      allContributionRows: allContribRows,
      allSpendingRows: spendingRows,
      deceasedMembers: NgmyCivicRegistryMembers.deceasedCount(widget.config),
    );
  }

  Future<bool> _confirmAdminDeleteAllContributionsTriple({String? state}) async {
    final st = (state ?? '').trim();
    final isState = st.isNotEmpty;
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final panel = isDark ? const Color(0xFF151C2C) : Colors.white;
    final ink = isDark ? Colors.white : const Color(0xFF0F172A);
    final mute = isDark ? Colors.white70 : Colors.black54;

    Future<bool?> step({
      required int stepNum,
      required String title,
      required String message,
      required String confirmLabel,
      bool requireTypeAllStates = false,
    }) {
      final typeC = TextEditingController();
      return showGeneralDialog<bool>(
        context: context,
        barrierDismissible: false,
        barrierLabel: 'Dismiss',
        barrierColor: Colors.black.withValues(alpha: 0.55),
        transitionDuration: const Duration(milliseconds: 280),
        pageBuilder: (ctx, a, b) => const SizedBox.shrink(),
        transitionBuilder: (ctx, anim, secondary, child) {
          final curved = CurvedAnimation(parent: anim, curve: Curves.easeOutCubic);
          return FadeTransition(
            opacity: curved,
            child: ScaleTransition(
              scale: Tween<double>(begin: 0.94, end: 1).animate(curved),
              child: StatefulBuilder(
                builder: (ctx, setLocal) {
                  final typedOk = !requireTypeAllStates ||
                      typeC.text.trim().toUpperCase() == 'ALL STATES';
                  return Center(
                    child: Material(
                      color: Colors.transparent,
                      child: Container(
                        width: math.min(400, MediaQuery.sizeOf(ctx).width - 36),
                        margin: const EdgeInsets.symmetric(horizontal: 18),
                        padding: const EdgeInsets.fromLTRB(20, 20, 20, 16),
                        decoration: BoxDecoration(
                          color: panel,
                          borderRadius: BorderRadius.circular(22),
                          border: Border.all(color: const Color(0xFFEF4444).withValues(alpha: 0.55), width: 1.4),
                          boxShadow: [
                            BoxShadow(
                              color: Colors.black.withValues(alpha: isDark ? 0.45 : 0.14),
                              blurRadius: 28,
                              offset: const Offset(0, 12),
                            ),
                          ],
                        ),
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: [
                            Row(
                              children: [
                                Container(
                                  padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                                  decoration: BoxDecoration(
                                    color: const Color(0xFFDC2626),
                                    borderRadius: BorderRadius.circular(999),
                                  ),
                                  child: Text(
                                    'STEP $stepNum OF 3',
                                    style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w900, fontSize: 11, letterSpacing: 0.6),
                                  ),
                                ),
                                const Spacer(),
                                Icon(Icons.warning_amber_rounded, color: Colors.orange.shade700, size: 22),
                              ],
                            ),
                            const SizedBox(height: 14),
                            if (!isState) ...[
                              Container(
                                width: double.infinity,
                                padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 12),
                                decoration: BoxDecoration(
                                  color: const Color(0xFFFEF2F2),
                                  borderRadius: BorderRadius.circular(14),
                                  border: Border.all(color: const Color(0xFFEF4444), width: 1.5),
                                ),
                                child: const Text(
                                  'ALL STATES',
                                  textAlign: TextAlign.center,
                                  style: TextStyle(
                                    color: Color(0xFFB91C1C),
                                    fontWeight: FontWeight.w900,
                                    fontSize: 22,
                                    letterSpacing: 1.2,
                                  ),
                                ),
                              ),
                              const SizedBox(height: 12),
                            ],
                            Text(title, style: TextStyle(color: ink, fontWeight: FontWeight.w900, fontSize: 18)),
                            const SizedBox(height: 8),
                            Text(message, style: TextStyle(color: mute, fontSize: 13, height: 1.4)),
                            if (requireTypeAllStates) ...[
                              const SizedBox(height: 14),
                              Text(
                                'Type ALL STATES to continue',
                                style: TextStyle(color: ink, fontWeight: FontWeight.w800, fontSize: 12),
                              ),
                              const SizedBox(height: 6),
                              TextField(
                                controller: typeC,
                                autofocus: true,
                                textCapitalization: TextCapitalization.characters,
                                onChanged: (_) => setLocal(() {}),
                                style: TextStyle(color: ink, fontWeight: FontWeight.w800, letterSpacing: 0.8),
                                decoration: InputDecoration(
                                  hintText: 'ALL STATES',
                                  filled: true,
                                  fillColor: isDark ? const Color(0xFF0F172A) : const Color(0xFFF8FAFC),
                                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
                                  focusedBorder: const OutlineInputBorder(
                                    borderRadius: BorderRadius.all(Radius.circular(12)),
                                    borderSide: BorderSide(color: Color(0xFFDC2626), width: 1.6),
                                  ),
                                ),
                              ),
                            ],
                            const SizedBox(height: 16),
                            Row(
                              children: [
                                Expanded(
                                  child: OutlinedButton(
                                    onPressed: () => Navigator.pop(ctx, false),
                                    style: OutlinedButton.styleFrom(
                                      padding: const EdgeInsets.symmetric(vertical: 12),
                                      foregroundColor: mute,
                                      side: BorderSide(color: isDark ? const Color(0xFF475569) : const Color(0xFFCBD5E1)),
                                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                                    ),
                                    child: const Text('Cancel', style: TextStyle(fontWeight: FontWeight.w800)),
                                  ),
                                ),
                                const SizedBox(width: 10),
                                Expanded(
                                  child: ElevatedButton(
                                    onPressed: typedOk ? () => Navigator.pop(ctx, true) : null,
                                    style: ElevatedButton.styleFrom(
                                      backgroundColor: const Color(0xFFDC2626),
                                      disabledBackgroundColor: const Color(0xFFFECACA),
                                      foregroundColor: Colors.white,
                                      padding: const EdgeInsets.symmetric(vertical: 12),
                                      elevation: 0,
                                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                                    ),
                                    child: Text(confirmLabel, style: const TextStyle(fontWeight: FontWeight.w900)),
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    ),
                  );
                },
              ),
            ),
          );
        },
      ).whenComplete(typeC.dispose);
    }

    if (isState) {
      final a = await step(
        stepNum: 1,
        title: 'Delete all $st contributions?',
        message: 'This will permanently delete every contribution recorded for $st only. State Trust money is not touched.',
        confirmLabel: 'Continue',
      );
      if (a != true) return false;
      final b = await step(
        stepNum: 2,
        title: 'Confirm $st wipe',
        message: 'Contribution case / available for $st will drop by these amounts. This cannot be undone.',
        confirmLabel: 'Yes, continue',
      );
      if (b != true) return false;
      final c = await step(
        stepNum: 3,
        title: 'Final confirmation',
        message: 'Last step: permanently delete all $st contributions now?',
        confirmLabel: 'Delete $st',
      );
      return c == true;
    }

    final a = await step(
      stepNum: 1,
      title: 'Delete contributions for ALL STATES?',
      message:
          'This is not one state. This removes every civic contribution across the entire United States Civic Registry. State Trust is not touched.',
      confirmLabel: 'I understand',
    );
    if (a != true) return false;
    final b = await step(
      stepNum: 2,
      title: 'Type ALL STATES',
      message:
          'To prove this is intentional, type ALL STATES below. Contribution case available amounts from these contributions will also be cleared.',
      confirmLabel: 'Continue',
      requireTypeAllStates: true,
    );
    if (b != true) return false;
    final c = await step(
      stepNum: 3,
      title: 'Final confirmation — ALL STATES',
      message:
          'Last chance. This permanently deletes all contributions for ALL STATES and clears their contribution-case available totals. This cannot be undone.',
      confirmLabel: 'Delete ALL STATES',
    );
    return c == true;
  }

  Future<void> _zeroContributionCaseAvailableAfterDeletes(Iterable<String> states) async {
    final unique = <String>{};
    for (final s in states) {
      final st = s.trim();
      if (st.isNotEmpty) unique.add(st);
    }
    for (final st in unique) {
      // Rebuild after contribution txs were removed. Only cut leftover contribution-case
      // available tied to collected — never reverse State Trust deposits/balances.
      final snap = _buildCivicStateWalletSnapshot(st);
      final leftover = math.min(snap.available, snap.collected);
      if (leftover > 0.009) {
        await _silentAdminRemoveAvailable(state: st, amount: leftover);
      }
    }
  }

  Future<void> _adminResetNationwideContributionCount({String? state}) async {
    final st = (state ?? '').trim();
    final isState = st.isNotEmpty;
    final confirmed = await _confirmAdminDeleteAllContributionsTriple(state: isState ? st : null);
    if (!confirmed) return;

    final targets = <AppTransaction>[];
    final affectedStates = <String>{};
    for (final t in _civicTransactionsForDisplay()) {
      if (t.type != TransactionType.contribution || t.status != TransactionStatus.approved) continue;
      if (t.id.trim().isEmpty) continue;
      final meta = _decodeContributionMeta(t);
      final receiptState = _contributionReceiptState(t, meta).trim();
      if (isState) {
        if (receiptState.toLowerCase() != st.toLowerCase()) continue;
      }
      targets.add(t);
      if (receiptState.isNotEmpty) affectedStates.add(receiptState);
    }
    if (isState) affectedStates.add(st);
    if (targets.isEmpty) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(isState ? 'No $st contributions to delete.' : 'No contributions to delete.')),
        );
      }
      return;
    }

    final touchedMembers = <String, UserData>{};
    setState(() {
      for (final t in targets) {
        final member = _memberForContributionTx(t);
        _applyLocalContributionDeletion(t, member: member);
        if (member != null) {
          touchedMembers[NgmyCivicRegistryMembers.emailKey(member.email)] = member;
        }
      }
    });

    final ids = targets.map((t) => t.id.trim()).where((e) => e.isNotEmpty).toSet();
    await ngmyPersistCivicDeletedContributions(widget.config, addedIds: ids);
    await _purgeTombstonedContributionsFromCloud(ids);
    for (final member in touchedMembers.values) {
      await _persistMemberAfterContributionDelete(member);
    }
    // Drop contribution-case / available for affected states (same money as deleted contributions).
    // State Trust ledgers are not modified.
    await _zeroContributionCaseAvailableAfterDeletes(affectedStates);
    widget.onDataChanged();
    if (mounted) {
      setState(() {});
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            isState
                ? 'Deleted ${ids.length} contribution(s) for $st. Contribution case available updated. State Trust unchanged.'
                : 'Deleted ${ids.length} contribution(s) for ALL STATES. Contribution case available updated. State Trust unchanged.',
          ),
        ),
      );
    }
  }

  Future<bool> _adminDeleteNationwideContribution(String contributionId) async {
    final id = contributionId.trim();
    if (id.isEmpty) return false;
    AppTransaction? target;
    for (final t in _civicTransactionsForDisplay()) {
      if (t.id == id && t.type == TransactionType.contribution && t.status == TransactionStatus.approved) {
        target = t;
        break;
      }
    }
    if (target == null) {
      // Already gone locally — still tombstone + cloud purge so it cannot return.
      await ngmyPersistCivicDeletedContributions(widget.config, addedIds: [id]);
      await _purgeTombstonedContributionsFromCloud({id});
      return true;
    }

    final member = _memberForContributionTx(target);
    setState(() {
      _applyLocalContributionDeletion(target!, member: member);
    });
    await ngmyPersistCivicDeletedContributions(widget.config, addedIds: [id]);
    await _purgeTombstonedContributionsFromCloud({id});
    if (member != null) {
      await _persistMemberAfterContributionDelete(member);
    }
    widget.onDataChanged();
    return true;
  }

  Future<void> _addCivicWalletSpending({
    required String state,
    required double amount,
    required String description,
    String fund = 'contribution',
  }) async {
    final st = state.trim();
    if (st.isEmpty || amount <= 0) return;
    final ledger = fund == 'trust' ? 'trust' : 'contribution';
    final record = {
      'id': 'spend_${DateTime.now().microsecondsSinceEpoch}',
      'campaignId': _activeHelpCampaignId().trim().isEmpty
          ? 'wallet_${st.toLowerCase()}'
          : _activeHelpCampaignId().trim(),
      'amount': amount,
      'description': description,
      'recordedAt': DateTime.now().toUtc().toIso8601String(),
      'recordedByEmail': widget.user.email.toLowerCase().trim(),
      'recordedByName': (widget.user.fullName ?? widget.user.username).trim(),
      'state': st,
      'fund': ledger,
    };
    setState(() {
      widget.config.helpCampaignSpendings = [
        ...widget.config.helpCampaignSpendings.map((e) => Map<String, dynamic>.from(e)),
        record,
      ];
    });
    widget.onDataChanged();
    await ngmyPersistCivicHelpModeSettings(widget.config);
  }

  Future<void> _addCivicWalletTrustDeposit({
    required String state,
    required double amount,
    required String description,
  }) async {
    final st = state.trim();
    if (st.isEmpty || amount <= 0) return;
    final record = {
      'id': 'trust_deposit_${DateTime.now().microsecondsSinceEpoch}',
      'campaignId': 'wallet_${st.toLowerCase()}',
      'amount': amount,
      'description': description.trim().isEmpty ? 'State Trust deposit' : description.trim(),
      'recordedAt': DateTime.now().toUtc().toIso8601String(),
      'recordedByEmail': widget.user.email.toLowerCase().trim(),
      'recordedByName': (widget.user.fullName ?? widget.user.username).trim(),
      'state': st,
      'fund': 'trust',
      'walletTrustDeposit': true,
      'kind': 'state_trust_deposit',
    };
    setState(() {
      widget.config.helpCampaignSpendings = [
        ...widget.config.helpCampaignSpendings.map((e) => Map<String, dynamic>.from(e)),
        record,
      ];
    });
    widget.onDataChanged();
    await ngmyPersistCivicHelpModeSettings(widget.config);
  }

  int _stateRegistrarCountExcludingAdmins(String state) {
    final scopedUsers = widget.allUsers.where((u) {
      if (u.isAdmin || u.isCivicRegistryAdmin || u.isCivicRegistryKing) return false;
      return true;
    });
    return NgmyCivicRegistryStats.activeRegistrarsInState(
      state: state,
      applications: widget.config.civicRegistrarApplications,
      users: scopedUsers,
      excludeRegistryAdmins: true,
    );
  }

  bool _trustOutRequiresDualApproval(String state) =>
      _stateRegistrarCountExcludingAdmins(state) > 2;

  List<Map<String, dynamic>> _completedTransferRows({
    required String state,
    required double amount,
    required String description,
    required String direction,
    required String linkId,
  }) {
    final st = state.trim();
    final now = DateTime.now().toUtc().toIso8601String();
    final byEmail = widget.user.email.toLowerCase().trim();
    final byName = (widget.user.fullName ?? widget.user.username).trim();
    final campaignId = 'wallet_${st.toLowerCase()}';
    if (direction == 'to_trust') {
      return [
        {
          'id': 'xfer_out_contrib_$linkId',
          'campaignId': campaignId,
          'amount': amount,
          'description': description,
          'recordedAt': now,
          'recordedByEmail': byEmail,
          'recordedByName': byName,
          'state': st,
          'fund': 'contribution',
          'kind': 'transfer_to_trust',
          'transferLinkId': linkId,
        },
        {
          'id': 'xfer_in_trust_$linkId',
          'campaignId': campaignId,
          'amount': amount,
          'description': description,
          'recordedAt': now,
          'recordedByEmail': byEmail,
          'recordedByName': byName,
          'state': st,
          'fund': 'trust',
          'walletTrustDeposit': true,
          'kind': 'transfer_from_contribution',
          'transferLinkId': linkId,
        },
      ];
    }
    return [
      {
        'id': 'xfer_out_trust_$linkId',
        'campaignId': campaignId,
        'amount': amount,
        'description': description,
        'recordedAt': now,
        'recordedByEmail': byEmail,
        'recordedByName': byName,
        'state': st,
        'fund': 'trust',
        'kind': 'transfer_to_contribution',
        'transferLinkId': linkId,
      },
      {
        'id': 'xfer_in_contrib_$linkId',
        'campaignId': campaignId,
        'amount': amount,
        'description': description,
        'recordedAt': now,
        'recordedByEmail': byEmail,
        'recordedByName': byName,
        'state': st,
        'fund': 'contribution',
        'kind': 'transfer_from_trust',
        'contributionTransferCredit': true,
        'transferLinkId': linkId,
      },
    ];
  }

  Future<void> _civicWalletTransferFunds({
    required String state,
    required double amount,
    required String description,
    required String direction,
  }) async {
    final st = state.trim();
    if (st.isEmpty || amount <= 0) return;
    final dir = direction == 'to_contribution' ? 'to_contribution' : 'to_trust';
    final snap = _buildCivicStateWalletSnapshot(st);
    final bal = dir == 'to_trust' ? snap.available : snap.trustBalance;
    if (amount > bal + 0.001) return;

    final needsDual = dir == 'to_contribution' &&
        _trustOutRequiresDualApproval(st) &&
        !_isGlobalCivicRegistryAdmin();

    if (needsDual) {
      final now = DateTime.now().toUtc().toIso8601String();
      final byEmail = widget.user.email.toLowerCase().trim();
      final byName = (widget.user.fullName ?? widget.user.username).trim();
      final pending = {
        'id': 'xfer_pending_${DateTime.now().microsecondsSinceEpoch}',
        'campaignId': 'wallet_${st.toLowerCase()}',
        'amount': amount,
        'description': description.trim().isEmpty ? 'Transfer to Contribution Case' : description.trim(),
        'recordedAt': now,
        'requestedAt': now,
        'requestedByEmail': byEmail,
        'requestedByName': byName,
        'state': st,
        'kind': 'fund_transfer_pending',
        'direction': dir,
        'status': 'pending',
        'requiredApprovals': 2,
        'approvals': [
          {'email': byEmail, 'name': byName, 'at': now},
        ],
      };
      setState(() {
        widget.config.helpCampaignSpendings = [
          ...widget.config.helpCampaignSpendings.map((e) => Map<String, dynamic>.from(e)),
          pending,
        ];
      });
      widget.onDataChanged();
      await ngmyPersistCivicHelpModeSettings(widget.config);
      return;
    }

    final linkId = DateTime.now().microsecondsSinceEpoch.toString();
    final rows = _completedTransferRows(
      state: st,
      amount: amount,
      description: description.trim().isEmpty
          ? (dir == 'to_trust' ? 'Transfer to State Trust' : 'Transfer to Contribution Case')
          : description.trim(),
      direction: dir,
      linkId: linkId,
    );
    setState(() {
      widget.config.helpCampaignSpendings = [
        ...widget.config.helpCampaignSpendings.map((e) => Map<String, dynamic>.from(e)),
        ...rows,
      ];
    });
    widget.onDataChanged();
    await ngmyPersistCivicHelpModeSettings(widget.config);
  }

  Future<void> _approveCivicWalletTransfer(String transferId) async {
    final id = transferId.trim();
    if (id.isEmpty) return;
    final me = widget.user.email.toLowerCase().trim();
    final myName = (widget.user.fullName ?? widget.user.username).trim();
    final now = DateTime.now().toUtc().toIso8601String();
    Map<String, dynamic>? pending;
    for (final e in widget.config.helpCampaignSpendings) {
      if ((e['id'] ?? '').toString().trim() == id && ngmyIsFundTransferPending(e)) {
        pending = Map<String, dynamic>.from(e);
        break;
      }
    }
    if (pending == null) return;
    if ((pending['status'] ?? 'pending').toString().toLowerCase() != 'pending') return;

    final approvals = <Map<String, dynamic>>[
      ...((pending['approvals'] is List)
          ? (pending['approvals'] as List).map((e) => Map<String, dynamic>.from(e as Map))
          : const <Map<String, dynamic>>[]),
    ];
    if (approvals.any((a) => (a['email'] ?? '').toString().toLowerCase().trim() == me)) {
      return; // already approved by this user
    }
    final requester = (pending['requestedByEmail'] ?? '').toString().toLowerCase().trim();
    if (!_isGlobalCivicRegistryAdmin() && requester == me) return;

    approvals.add({'email': me, 'name': myName, 'at': now});
    final required = (pending['requiredApprovals'] as num?)?.toInt() ?? 2;
    final st = (pending['state'] ?? '').toString().trim();
    final amount = (pending['amount'] as num?)?.toDouble() ?? 0;
    final desc = (pending['description'] ?? 'Transfer to Contribution Case').toString();
    final direction = (pending['direction'] ?? 'to_contribution').toString();

    if (_isGlobalCivicRegistryAdmin() || approvals.length >= required) {
      final linkId = id.replaceFirst('xfer_pending_', '');
      final rows = _completedTransferRows(
        state: st,
        amount: amount,
        description: desc,
        direction: direction,
        linkId: linkId.isEmpty ? DateTime.now().microsecondsSinceEpoch.toString() : linkId,
      );
      setState(() {
        widget.config.helpCampaignSpendings = [
          ...widget.config.helpCampaignSpendings
              .where((e) => (e['id'] ?? '').toString().trim() != id)
              .map((e) => Map<String, dynamic>.from(e)),
          ...rows,
        ];
      });
    } else {
      pending['approvals'] = approvals;
      setState(() {
        widget.config.helpCampaignSpendings = widget.config.helpCampaignSpendings.map((e) {
          if ((e['id'] ?? '').toString().trim() != id) return Map<String, dynamic>.from(e);
          return pending!;
        }).toList();
      });
    }
    widget.onDataChanged();
    await ngmyPersistCivicHelpModeSettings(widget.config);
  }

  Future<void> _rejectCivicWalletTransfer(String transferId) async {
    final id = transferId.trim();
    if (id.isEmpty) return;
    setState(() {
      widget.config.helpCampaignSpendings = widget.config.helpCampaignSpendings
          .where((e) => (e['id'] ?? '').toString().trim() != id)
          .map((e) => Map<String, dynamic>.from(e))
          .toList();
    });
    widget.onDataChanged();
    await ngmyPersistCivicHelpModeSettings(widget.config);
  }

  Future<void> _openAdminCivicStateCase(String state) async {
    final st = state.trim();
    if (st.isEmpty || !mounted) return;
    if (!_shouldSkipStateCaseUnlock(st)) {
      final unlocked = await NgmyNavigator.push<bool>(
        context,
        NgmyCivicStateWalletVerifyScreen(
          state: st,
          globalPin: widget.config.civicRegistryPin,
          pinsByState: widget.config.civicRegistryPinsByState,
          members: ngmyCivicMembersForState(widget.config, st),
        ),
        routeName: 'NgmyCivicStateWalletVerifyScreen',
      );
      if (unlocked != true || !mounted) return;
    }
    final canEdit = _canUseRegistrarToolsHere(st);
    await NgmyNavigator.push<void>(
      context,
      NgmyCivicStateWalletScreen(
        state: st,
        canEdit: canEdit,
        snapshotBuilder: () => _buildCivicStateWalletSnapshot(st),
        onAddSpending: ({required double amount, required String description, String fund = 'contribution'}) =>
            _addCivicWalletSpending(state: st, amount: amount, description: description, fund: fund),
        onAddTrustDeposit: ({required double amount, required String description}) =>
            _addCivicWalletTrustDeposit(state: st, amount: amount, description: description),
        onTransferFunds: ({
          required double amount,
          required String description,
          required String direction,
        }) =>
            _civicWalletTransferFunds(
              state: st,
              amount: amount,
              description: description,
              direction: direction,
            ),
        onApproveTransfer: _approveCivicWalletTransfer,
        onRejectTransfer: _rejectCivicWalletTransfer,
        currentUserEmail: widget.user.email,
        isGlobalAdmin: _isGlobalCivicRegistryAdmin(),
        trustOutRequiresDualApproval: _trustOutRequiresDualApproval(st),
        onUpdateSpending: ({
          required String spendingId,
          required double amount,
          required String description,
        }) async {
          final id = spendingId.trim();
          if (id.isEmpty) return;
          setState(() {
            widget.config.helpCampaignSpendings = widget.config.helpCampaignSpendings.map((e) {
              final row = Map<String, dynamic>.from(e);
              if ((row['id'] ?? '').toString().trim() != id) return row;
              row['amount'] = amount;
              row['description'] = description;
              row['recordedAt'] = DateTime.now().toUtc().toIso8601String();
              row['recordedByEmail'] = widget.user.email.toLowerCase().trim();
              row['recordedByName'] = (widget.user.fullName ?? widget.user.username).trim();
              row['state'] = st;
              return row;
            }).toList();
          });
          widget.onDataChanged();
          await ngmyPersistCivicHelpModeSettings(widget.config);
        },
        onDeleteSpending: (spendingId) async {
          final id = spendingId.trim();
          if (id.isEmpty) return;
          final deleteAt = DateTime.now().toUtc().add(const Duration(hours: 24)).toIso8601String();
          setState(() {
            widget.config.helpCampaignSpendings = widget.config.helpCampaignSpendings.map((e) {
              final row = Map<String, dynamic>.from(e);
              if ((row['id'] ?? '').toString().trim() != id) return row;
              row['pendingDeleteAt'] = deleteAt;
              return row;
            }).toList();
          });
          widget.onDataChanged();
          await ngmyPersistCivicHelpModeSettings(widget.config);
        },
        onPurgeExpired: _purgeExpiredWalletSpendings,
        canAdminBrowseStates: _isGlobalCivicRegistryAdmin(),
        allStates: _usStates,
        snapshotForState: _buildCivicStateWalletSnapshot,
        onOpenStateCase: _openAdminCivicStateCase,
        onAdminRemoveAvailable: _silentAdminRemoveAvailable,
        onAdminResetStateCase: _adminResetStateCase,
        onAdminRestoreStateCase: _adminRestoreStateCase,
        softResetForState: _softResetForState,
        nationwideStatsBuilder: _buildCivicNationwideStats,
        onAdminResetContributionCount: _isGlobalCivicRegistryAdmin() ? _adminResetNationwideContributionCount : null,
        onAdminDeleteContribution: _isGlobalCivicRegistryAdmin() ? _adminDeleteNationwideContribution : null,
      ),
      routeName: 'NgmyCivicStateWalletScreen',
    );
  }

  /// Removes wallet spendings whose 24h delete window has ended,
  /// and permanently applies expired admin soft-resets.
  Future<void> _purgeExpiredWalletSpendings() async {
    final now = DateTime.now().toUtc();
    final kept = <Map<String, dynamic>>[];
    var changed = false;
    final statesToWipeSpendings = <String>{};
    final permanentSoftResets = <Map<String, dynamic>>[];

    for (final e in widget.config.helpCampaignSpendings) {
      final row = Map<String, dynamic>.from(e);
      if (ngmyIsWalletSoftResetRecord(row) && row['permanent'] != true) {
        final purgeRaw = (row['purgeAt'] ?? '').toString().trim();
        final purgeAt = purgeRaw.isEmpty ? null : DateTime.tryParse(purgeRaw)?.toUtc();
        if (purgeAt != null && !purgeAt.isAfter(now)) {
          changed = true;
          final st = (row['state'] ?? '').toString().trim();
          if (st.isNotEmpty && row['hideSpendings'] == true) {
            statesToWipeSpendings.add(st.toLowerCase());
          }
          row['permanent'] = true;
          row['purgeAt'] = '';
          permanentSoftResets.add(row);
          continue;
        }
      }
      final raw = (row['pendingDeleteAt'] ?? '').toString().trim();
      if (raw.isNotEmpty) {
        final at = DateTime.tryParse(raw)?.toUtc();
        if (at != null && !at.isAfter(now)) {
          changed = true;
          continue;
        }
      }
      kept.add(row);
    }

    if (statesToWipeSpendings.isNotEmpty) {
      changed = true;
      kept.removeWhere((row) {
        if (ngmyIsWalletSoftResetRecord(row)) return false;
        final st = (row['state'] ?? '').toString().trim().toLowerCase();
        return statesToWipeSpendings.contains(st);
      });
    }
    if (permanentSoftResets.isNotEmpty) {
      kept.addAll(permanentSoftResets);
    }

    if (!changed) return;
    setState(() => widget.config.helpCampaignSpendings = kept);
    widget.onDataChanged();
    await ngmyPersistCivicHelpModeSettings(widget.config);
  }

  Future<void> _openCivicStateWalletFlow() async {
    await _purgeExpiredWalletSpendings();
    final toolsHere = _canUseRegistrarToolsHere();
    await openNgmyCivicStateWalletFlow(
      context: context,
      state: _selectedState,
      globalPin: widget.config.civicRegistryPin,
      pinsByState: widget.config.civicRegistryPinsByState,
      members: ngmyCivicMembersForState(widget.config, _selectedState),
      snapshotBuilder: () => _buildCivicStateWalletSnapshot(),
      canEdit: toolsHere,
      // Only this state's first AR (and King/Admin) skip codes. Other ARs
      // and members must enter PIN / name / DOB / ID every visit.
      skipUnlockCodes: _shouldSkipStateCaseUnlock(),
      onAddSpending: ({required double amount, required String description, String fund = 'contribution'}) =>
          _addCivicWalletSpending(
            state: _selectedState,
            amount: amount,
            description: description,
            fund: fund,
          ),
      onAddTrustDeposit: ({required double amount, required String description}) =>
          _addCivicWalletTrustDeposit(
            state: _selectedState,
            amount: amount,
            description: description,
          ),
      onTransferFunds: ({
        required double amount,
        required String description,
        required String direction,
      }) =>
          _civicWalletTransferFunds(
            state: _selectedState,
            amount: amount,
            description: description,
            direction: direction,
          ),
      onApproveTransfer: _approveCivicWalletTransfer,
      onRejectTransfer: _rejectCivicWalletTransfer,
      currentUserEmail: widget.user.email,
      isGlobalAdmin: _isGlobalCivicRegistryAdmin(),
      trustOutRequiresDualApproval: _trustOutRequiresDualApproval(_selectedState),
      onUpdateSpending: ({
        required String spendingId,
        required double amount,
        required String description,
      }) async {
        final id = spendingId.trim();
        if (id.isEmpty) return;
        setState(() {
          widget.config.helpCampaignSpendings = widget.config.helpCampaignSpendings.map((e) {
            final row = Map<String, dynamic>.from(e);
            if ((row['id'] ?? '').toString().trim() != id) return row;
            row['amount'] = amount;
            row['description'] = description;
            row['recordedAt'] = DateTime.now().toUtc().toIso8601String();
            row['recordedByEmail'] = widget.user.email.toLowerCase().trim();
            row['recordedByName'] = (widget.user.fullName ?? widget.user.username).trim();
            row['state'] = _selectedState.trim();
            return row;
          }).toList();
        });
        widget.onDataChanged();
        await ngmyPersistCivicHelpModeSettings(widget.config);
      },
      onDeleteSpending: (spendingId) async {
        // Schedule complete removal after 24 hours (not instant).
        final id = spendingId.trim();
        if (id.isEmpty) return;
        final deleteAt = DateTime.now().toUtc().add(const Duration(hours: 24)).toIso8601String();
        setState(() {
          widget.config.helpCampaignSpendings = widget.config.helpCampaignSpendings.map((e) {
            final row = Map<String, dynamic>.from(e);
            if ((row['id'] ?? '').toString().trim() != id) return row;
            row['pendingDeleteAt'] = deleteAt;
            return row;
          }).toList();
        });
        widget.onDataChanged();
        await ngmyPersistCivicHelpModeSettings(widget.config);
      },
      onPurgeExpired: _purgeExpiredWalletSpendings,
      canAdminBrowseStates: _isGlobalCivicRegistryAdmin(),
      allStates: _usStates,
      snapshotForState: _buildCivicStateWalletSnapshot,
      onOpenStateCase: _openAdminCivicStateCase,
      onAdminRemoveAvailable: _silentAdminRemoveAvailable,
      onAdminResetStateCase: _adminResetStateCase,
      onAdminRestoreStateCase: _adminRestoreStateCase,
      softResetForState: _softResetForState,
      nationwideStatsBuilder: _buildCivicNationwideStats,
      onAdminResetContributionCount: _isGlobalCivicRegistryAdmin() ? _adminResetNationwideContributionCount : null,
      onAdminDeleteContribution: _isGlobalCivicRegistryAdmin() ? _adminDeleteNationwideContribution : null,
    );
  }

