  /// The state whose help mode this viewer sees/controls — King/Admin
  /// follow whatever state they've switched `_selectedState` to (they can
  /// operate across states); everyone else is locked to their own home
  /// state (`widget.user.state`) regardless of `_selectedState`, so a
  /// registrar merely browsing another state (their 3 free switches)
  /// still can't see or touch that state's help mode campaign.
  String _helpModeState() => _isGlobalCivicRegistryAdmin() ? _selectedState : widget.user.state;

  bool _memberMatchesHelpScope(UserData u, {String? forState}) {
    final state = forState ?? _helpModeState();
    if (!widget.config.helpActiveFor(state)) return false;
    final scopeType = widget.config.helpScopeTypeFor(state);
    final scopeValue = widget.config.helpScopeValueFor(state).trim();
    if (scopeType != 'city' && scopeType != 'room') return true;
    if (scopeValue.isEmpty) return false;
    // Prefer registry enrollment city/room — account UserData often leaves
    // those empty even when the member is enrolled with a city/room.
    final registry = NgmyCivicRegistryMembers.findByEmail(widget.config, u.email) ??
        (((u.registryId ?? '').trim().isNotEmpty)
            ? NgmyCivicRegistryMembers.findByRegistryId(widget.config, u.registryId!)
            : null);
    final memberCity = ((registry?['city'] ?? u.city) ?? '').toString().trim();
    final memberRoom = ((registry?['room'] ?? u.room) ?? '').toString().trim();
    if (scopeType == 'city') {
      return memberCity.toLowerCase() == scopeValue.toLowerCase();
    }
    return memberRoom.toLowerCase() == scopeValue.toLowerCase();
  }

  String _activeHelpCampaignId([String? forState]) {
    final state = forState ?? _helpModeState();
    final stored = widget.config.helpCampaignIdFor(state);
    if (stored.isNotEmpty) return stored;
    return '${widget.config.helpPurposeFor(state)}|${widget.config.helpScopeTypeFor(state)}|${widget.config.helpScopeValueFor(state)}|$state';
  }

  List<UserData> _membersInCurrentHelpScope({String? forState}) {
    // Must filter by the campaign's own state, not widget.user.state. For
    // a King/Admin managing a state that isn't their personal home state
    // (e.g. deactivating Alabama's campaign while their own account state
    // is something else), comparing against widget.user.state matched
    // zero members — so nobody was ever marked missed, even though the
    // campaign closed normally.
    //
    // Defaulting to _helpModeState() (which itself falls back to
    // widget.user.state for non-King/Admin) still isn't enough on its
    // own: widget.user.state is only ever set at initial PIN unlock or
    // registrar approval and is never resynced when a registrar spends
    // one of their 3 free state switches (_applyCivicStateChange updates
    // _selectedState, not widget.user.state). A registrar deactivating
    // *their own currently-selected state's* campaign needs that exact
    // state, not whatever widget.user.state happens to still say — this
    // is why the Deactivate button (which always operates on
    // _selectedState) passes forState explicitly instead of relying on
    // this default.
    final campaignState = (forState ?? _helpModeState()).trim().toLowerCase();
    return _civicRegistryMembersForDisplay(widget.config, widget.allUsers).where((m) {
      if (!_memberMatchesHelpScope(m, forState: forState)) return false;
      return m.state.trim().isEmpty || m.state.trim().toLowerCase() == campaignState;
    }).toList();
  }

  // [members] lets a caller snapshot the campaign's scope membership
  // *before* deactivating: _membersInCurrentHelpScope() filters through
  // _memberMatchesHelpScope(), whose first check is
  // `widget.config.helpActiveFor(state)` — once the campaign has already
  // been deactivated that's false for everyone, so calling this after
  // deactivateHelpCampaign() with no snapshot silently checks zero
  // members and nobody is ever marked missed. Defaults to a live lookup
  // for callers (like the 2-month auto-expiry) that still run this before
  // deactivating.
  void _markMissedForNonContributorsInCampaign(
    String campaignId, {
    List<UserData>? members,
    DateTime? campaignStartedAt,
    String? campaignState,
  }) {
    final normalizedCampaignId = campaignId.trim();
    if (normalizedCampaignId.isEmpty && campaignStartedAt == null) return;
    // Idempotency guard: a campaign can only ever be closed out once. Two
    // devices/sessions racing to deactivate the same campaign (or a
    // manual Deactivate overlapping the 2-month auto-expiry sweep) would
    // otherwise each independently decide "these members haven't
    // contributed yet" and both increment missed for them — double
    // counting. helpCampaignClosures already records every campaign this
    // device knows has been closed (and syncs across devices via
    // ngmyPersistCivicHelpModeSettings/ngmyHydrateCivicHelpModeFromAllBackups),
    // so it doubles as the "already handled, don't do it again" record.
    if (normalizedCampaignId.isNotEmpty &&
        widget.config.helpCampaignClosures.any((c) => (c['campaignId'] ?? '').toString().trim() == normalizedCampaignId)) {
      debugPrint('[help mode] campaign $normalizedCampaignId already closed — skipping duplicate missed marking');
      return;
    }
    final stateKey = (campaignState ?? _selectedState).trim().toLowerCase();
    // Anyone who put money / was recorded for THIS campaign must never be
    // marked missed. Match by campaignId, fallback purpose key, OR time
    // window in the same state — never require all three. Identity is
    // email OR registryId (Money stamps both).
    final contributorKeys = <String>{};
    for (final t in _civicTransactionsForDisplay()) {
      if (t.type != TransactionType.contribution || t.status != TransactionStatus.approved) continue;
      final meta = _decodeContributionMeta(t);
      final cid = (meta['campaignId'] ?? '').toString().trim();
      final receiptState = _contributionReceiptState(t, meta).trim().toLowerCase();
      final fallbackId =
          '${meta['purpose'] ?? 'Campaign'}|${meta['scopeType'] ?? 'all'}|${meta['scopeValue'] ?? ''}|${_contributionReceiptState(t, meta)}';
      final matchesCampaignId =
          normalizedCampaignId.isNotEmpty && (cid == normalizedCampaignId || fallbackId == normalizedCampaignId);
      final matchesTimeWindow =
          campaignStartedAt != null && !t.timestamp.isBefore(campaignStartedAt);
      final matchesState = stateKey.isEmpty ||
          receiptState.isEmpty ||
          receiptState == stateKey;
      // campaignId OR (time window in this state). Do not drop a paid
      // member because a campaignId string drifted slightly.
      final isForThisCampaign =
          matchesCampaignId || (matchesTimeWindow && matchesState);
      if (!isForThisCampaign) continue;
      final emailKey = NgmyCivicRegistryMembers.emailKey(t.userEmail);
      if (emailKey.isNotEmpty) contributorKeys.add(emailKey);
      final metaEmail = NgmyCivicRegistryMembers.emailKey((meta['memberEmail'] ?? '').toString());
      if (metaEmail.isNotEmpty) contributorKeys.add(metaEmail);
      final rid = (meta['registryId'] ?? '').toString().trim().toUpperCase();
      if (rid.isNotEmpty) contributorKeys.add('rid:$rid');
    }
    final alreadyMarked = <String>{};
    for (final m in members ?? _membersInCurrentHelpScope()) {
      final emailKey = NgmyCivicRegistryMembers.emailKey(m.email);
      final ridKey = 'rid:${(m.registryId ?? '').trim().toUpperCase()}';
      final key = emailKey.isNotEmpty ? emailKey : ridKey;
      if (key == 'rid:' || !alreadyMarked.add(key)) continue;
      final contributed = (emailKey.isNotEmpty && contributorKeys.contains(emailKey)) ||
          (ridKey != 'rid:' && contributorKeys.contains(ridKey));
      if (contributed) continue; // recorded money → never missed for this campaign
      m.missed += 1;
      unawaited(_persistCivicMemberActivity(m));
    }
  }

  /// True only for the global Civic Registry King/Admin roles — the ones
  /// meant to see and manage every state's data. A regular Authorized
  /// Registrar (`_canManageCivicRegistry()`) is only authorized for their
  /// own state and must stay state-gated like an ordinary member; see
  /// `_canCurrentUserSeeHelpMode` below, which used to let *any* registrar
  /// bypass the state check and see another state's active help mode.
  ///
  /// Must include the full app `isAdmin` flag, not just
  /// `isCivicRegistryAdmin`/`isCivicRegistryKing` — an app-wide Admin whose
  /// own `user.state` happened not to match the state they were trying to
  /// manage (e.g. Alabama) was otherwise blocked by the own-state check
  /// below and their Deactivate press silently did nothing.
  bool _isGlobalCivicRegistryAdmin() =>
      widget.user.isAdmin || widget.user.isCivicRegistryKing || widget.user.isCivicRegistryAdmin;

  bool _canCurrentUserSeeHelpMode() {
    final st = _selectedState;
    if (!widget.config.helpActiveFor(st)) return false;
    // Home-state AR / King / Admin manage help; elsewhere behave like a member.
    if (_canUseRegistrarToolsHere()) return true;
    return _memberMatchesHelpScope(widget.user, forState: st);
  }

  Map<String, dynamic> _decodeContributionMeta(AppTransaction t) {
    final raw = t.sourceDetails?.trim() ?? '';
    if (raw.isEmpty) return {};
    try {
      final decoded = jsonDecode(raw);
      if (decoded is Map<String, dynamic>) return decoded;
      if (decoded is Map) return Map<String, dynamic>.from(decoded);
    } catch (_) {}
    return {'note': raw};
  }

  bool _audienceMatchForViewer(String scopeType, String scopeValue) {
    if (_canUseRegistrarToolsHere()) return true;
    final wanted = scopeValue.trim().toLowerCase();
    if (scopeType != 'city' && scopeType != 'room') return true;
    if (wanted.isEmpty) return false;
    final registry = NgmyCivicRegistryMembers.findByEmail(widget.config, widget.user.email) ??
        (((widget.user.registryId ?? '').trim().isNotEmpty)
            ? NgmyCivicRegistryMembers.findByRegistryId(widget.config, widget.user.registryId!)
            : null);
    final memberCity = ((registry?['city'] ?? widget.user.city) ?? '').toString().trim().toLowerCase();
    final memberRoom = ((registry?['room'] ?? widget.user.room) ?? '').toString().trim().toLowerCase();
    if (scopeType == 'city') return memberCity == wanted;
    return memberRoom == wanted;
  }

  /// A resolved (rejected/deleted) claim stays visible as history for
  /// kNgmyCivicClaimRetentionDays, then must vanish everywhere — no view
  /// should still be able to show "Resolved claim" past that point.
  /// Open (pending) claims are never touched by this, no matter how old.
  bool _isExpiredResolvedClaim(AppTransaction t) {
    if (t.type != TransactionType.claim || t.status == TransactionStatus.pending) return false;
    return DateTime.now().difference(t.timestamp) > const Duration(days: kNgmyCivicClaimRetentionDays);
  }

  List<AppTransaction> _civicTransactionsForDisplay() {
    final deleted = widget.config.civicDeletedContributionIds
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toSet();
    final byId = <String, AppTransaction>{};
    for (final t in widget.allTransactions) {
      if (t.id.isEmpty) continue;
      if (t.type == TransactionType.contribution && deleted.contains(t.id)) continue;
      byId[t.id] = t;
    }
    for (final t in _communityContributions) {
      if (t.id.isEmpty) continue;
      if (deleted.contains(t.id)) continue;
      final existing = byId[t.id];
      // Never let a cloud-approved community row resurrect a local reject.
      if (existing != null &&
          existing.type == TransactionType.contribution &&
          existing.status == TransactionStatus.rejected) {
        continue;
      }
      byId[t.id] = existing == null ? t : _pickPreferredTransaction(existing, t);
    }
    for (final t in _communityClaims) {
      if (t.id.isEmpty) continue;
      final existing = byId[t.id];
      if (existing != null &&
          existing.type == TransactionType.claim &&
          existing.status == TransactionStatus.rejected) {
        continue;
      }
      byId[t.id] = existing == null ? t : _pickPreferredTransaction(existing, t);
    }
    byId.removeWhere((_, t) => _isExpiredResolvedClaim(t));
    return byId.values.toList();
  }

  Future<void> _purgeTombstonedContributionsFromCloud(Set<String> ids) async {
    if (ids.isEmpty) return;
    try {
      const chunkSize = 50;
      final list = ids.toList();
      for (var i = 0; i < list.length; i += chunkSize) {
        final chunk = list.sublist(i, math.min(i + chunkSize, list.length));
        await Supabase.instance.client
            .from('transactions')
            .delete()
            .inFilter('id', chunk)
            .timeout(kNgmyCloudWriteTimeout);
      }
    } catch (e) {
      debugPrint('[civic] purge tombstoned contributions: $e');
    }
  }

  void _applyLocalContributionDeletion(AppTransaction target, {UserData? member}) {
    final id = target.id.trim();
    if (id.isEmpty) return;
    if (!widget.config.civicDeletedContributionIds.contains(id)) {
      widget.config.civicDeletedContributionIds = [...widget.config.civicDeletedContributionIds, id];
    }
    widget.allTransactions.removeWhere((t) => t.id == id);
    _communityContributions.removeWhere((t) => t.id == id);
    if (member != null && member.helps > 0) {
      member.helps -= 1;
    }
  }

  UserData? _memberForContributionTx(AppTransaction target) {
    final meta = _decodeContributionMeta(target);
    final memberEmail = NgmyCivicRegistryMembers.emailKey(
      (meta['memberEmail'] ?? target.userEmail).toString(),
    );
    final registryId = (meta['registryId'] ?? '').toString().trim().toUpperCase();
    for (final u in _civicRegistryMembersForDisplay(widget.config, widget.allUsers)) {
      if (memberEmail.isNotEmpty && NgmyCivicRegistryMembers.emailKey(u.email) == memberEmail) {
        return u;
      }
      if (registryId.isNotEmpty && (u.registryId ?? '').trim().toUpperCase() == registryId) {
        return u;
      }
    }
    return null;
  }

  Future<void> _persistMemberAfterContributionDelete(UserData member) async {
    unawaited(_persistCivicMemberActivity(member));
    NgmyCivicRegistryMembers.syncFromFields(
      widget.config,
      email: member.email,
      fullName: member.fullName ?? member.username,
      dob: member.dob ?? '',
      idType: member.idType ?? '',
      homeAddress: member.homeAddress ?? '',
      phone: member.phone,
      city: member.city ?? '',
      room: member.room ?? '',
      state: member.state,
      registryId: member.registryId ?? '',
      helps: member.helps,
      missed: member.missed,
    );
    unawaited(ngmyPersistCivicRegistryMembers(widget.config));
  }

  /// Actually deletes expired resolved claims (not just hides them) — from
  /// the shared transaction list, the locally-cached community claims, and
  /// Supabase. Runs once per Civic Registry screen visit; claims are
  /// low-volume so this doesn't need its own background timer.
  Future<void> _pruneExpiredResolvedClaims() async {
    final expiredIds = <String>{};
    for (final t in widget.allTransactions) {
      if (_isExpiredResolvedClaim(t) && t.id.isNotEmpty) expiredIds.add(t.id);
    }
    for (final t in _communityClaims) {
      if (_isExpiredResolvedClaim(t) && t.id.isNotEmpty) expiredIds.add(t.id);
    }
    if (expiredIds.isEmpty) return;
    widget.allTransactions.removeWhere((t) => expiredIds.contains(t.id));
    _communityClaims.removeWhere((t) => expiredIds.contains(t.id));
    if (mounted) setState(() {});
    if (!await ngmyCanReachCloud()) return;
    try {
      const chunkSize = 50;
      final ids = expiredIds.toList();
      for (var i = 0; i < ids.length; i += chunkSize) {
        final chunk = ids.sublist(i, math.min(i + chunkSize, ids.length));
        await Supabase.instance.client.from('transactions').delete().inFilter('id', chunk).timeout(kNgmyCloudWriteTimeout);
      }
    } catch (e) {
      debugPrint('[civic claims] prune expired: $e');
    }
  }

  /// Resolves which Civic Registry state owns a contribution receipt.
  /// Prefer the stamped campaign state; fall back to the contributor's
  /// enrolled member record / account so older rows without a stamp still
  /// stay inside one state instead of leaking nationwide after deactivate.
  String _contributionReceiptState(AppTransaction t, [Map<String, dynamic>? meta]) {
    final decoded = meta ?? _decodeContributionMeta(t);
    final stamped = (decoded['state'] ?? '').toString().trim();
    if (stamped.isNotEmpty) return stamped;
    final email = t.userEmail.trim();
    if (email.isNotEmpty) {
      final member = NgmyCivicRegistryMembers.findByEmail(widget.config, email);
      final memberState = (member?['state'] ?? '').toString().trim();
      if (memberState.isNotEmpty) return memberState;
      for (final u in widget.allUsers) {
        if (u.email.toLowerCase().trim() != email.toLowerCase().trim()) continue;
        if (u.state.trim().isNotEmpty) return u.state.trim();
      }
    }
    return '';
  }

  List<AppTransaction> _visibleContributionTx() {
    final viewerState = _selectedState.trim().toLowerCase();
    return _civicTransactionsForDisplay().where((t) {
      if (t.type != TransactionType.contribution || t.status != TransactionStatus.approved) return false;
      final meta = _decodeContributionMeta(t);
      final scopeType = (meta['scopeType'] ?? 'all').toString();
      final scopeValue = (meta['scopeValue'] ?? '').toString();
      // Every viewer — member, registrar, King, or Admin — only sees the
      // receipts for the Civic state they are currently viewing. Help-mode
      // deactivate must not open Alabama receipts to Georgia (or vice
      // versa). Changing state is the only way to see another state's
      // contribution receipts.
      final targetState = _contributionReceiptState(t, meta);
      if (viewerState.isEmpty || targetState.isEmpty) return false;
      if (targetState.toLowerCase() != viewerState) return false;
      return _audienceMatchForViewer(scopeType, scopeValue);
    }).toList()
      ..sort((a, b) => b.timestamp.compareTo(a.timestamp));
  }

  DateTime? _contributionCampaignClosedAt(String receiptKey, Map<String, dynamic> meta) {
    final campaignId = (meta['campaignId'] ?? '').toString().trim();
    final lookup = campaignId.isNotEmpty ? campaignId : receiptKey;
    for (final c in widget.config.helpCampaignClosures) {
      if ((c['campaignId'] ?? '').toString().trim() != lookup) continue;
      final closedAtRaw = (c['closedAt'] ?? '').toString().trim();
      if (closedAtRaw.isEmpty) continue;
      try {
        return DateTime.parse(closedAtRaw).toLocal();
      } catch (_) {}
    }
    return null;
  }

  bool _contributionReceiptExpired(String receiptKey, Map<String, dynamic> meta) {
    final closedAt = _contributionCampaignClosedAt(receiptKey, meta);
    if (closedAt == null) return false;
    return DateTime.now().difference(closedAt) >=
        const Duration(days: kNgmyContributionReceiptAfterCloseDays);
  }

  bool _canDeleteReceiptForState(String receiptState) {
    final st = receiptState.trim().isEmpty ? _selectedState.trim() : receiptState.trim();
    if (st.isEmpty) return false;
    return _canUseRegistrarToolsHere(st);
  }

  Future<void> _deleteContributionReceipt(String key) async {
    final receiptKey = key.trim();
    if (receiptKey.isEmpty) return;
    _dismissedReceiptKeys.add(receiptKey);
    if (!widget.config.dismissedContributionReceiptKeys.contains(receiptKey)) {
      widget.config.dismissedContributionReceiptKeys = [
        ...widget.config.dismissedContributionReceiptKeys,
        receiptKey,
      ];
    }
    if (!widget.config.contributionReceiptRemovedKeys.contains(receiptKey)) {
      widget.config.contributionReceiptRemovedKeys = [
        ...widget.config.contributionReceiptRemovedKeys,
        receiptKey,
      ];
    }
    if (mounted) setState(() {});
    unawaited(_persistReceiptReadState());
    final cloudOk = await ngmyPersistCivicContributionReceiptRemoved(widget.config, addedKey: receiptKey);
    widget.onDataChanged();
    if (!mounted) return;
    setState(() {});
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          cloudOk
              ? 'Contribution receipt deleted for all users.'
              : 'Receipt deleted on this device. Will sync to everyone when online.',
        ),
        backgroundColor: cloudOk ? Colors.green : Colors.orange,
      ),
    );
  }

  List<Map<String, dynamic>> _spendingsForCampaign(String campaignId) {
    final id = campaignId.trim();
    if (id.isEmpty) return const [];
    return widget.config.helpCampaignSpendings
        .where((e) {
          final row = Map<String, dynamic>.from(e);
          if (ngmyIsSilentAdminWalletRemoval(row)) return false;
          if (ngmyIsWalletSoftResetRecord(row)) return false;
          return (row['campaignId'] ?? '').toString().trim() == id;
        })
        .map((e) => Map<String, dynamic>.from(e))
        .toList()
      ..sort((a, b) {
        final at = DateTime.tryParse((a['recordedAt'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
        final bt = DateTime.tryParse((b['recordedAt'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
        return bt.compareTo(at);
      });
  }

  double _totalCollectedForCampaign(String campaignId, List<AppTransaction> txs) {
    return txs.fold<double>(0.0, (s, t) => s + t.amount);
  }

  double _totalSpentForCampaign(String campaignId) {
    return _spendingsForCampaign(campaignId).fold<double>(0.0, (s, e) => s + ((e['amount'] as num?)?.toDouble() ?? 0.0));
  }

  Future<void> _silentAdminRemoveAvailable({
    required String state,
    required double amount,
  }) async {
    final st = state.trim();
    if (st.isEmpty || amount <= 0 || !_isGlobalCivicRegistryAdmin()) return;
    final record = {
      'id': 'admin_cut_${DateTime.now().microsecondsSinceEpoch}',
      'campaignId': 'wallet_${st.toLowerCase()}',
      'amount': amount,
      'description': '',
      'recordedAt': DateTime.now().toUtc().toIso8601String(),
      'recordedByEmail': widget.user.email.toLowerCase().trim(),
      'recordedByName': (widget.user.fullName ?? widget.user.username).trim(),
      'state': st,
      'silentAdminRemoval': true,
    };
    setState(() {
      widget.config.helpCampaignSpendings = [
        ...widget.config.helpCampaignSpendings.map((e) => Map<String, dynamic>.from(e)),
        record,
      ];
    });
    widget.onDataChanged();
    await ngmyPersistCivicHelpModeSettings(widget.config);
