                        const SizedBox(height: 12),
                        Container(
                          padding: const EdgeInsets.all(12),
                          decoration: BoxDecoration(
                            color: isDark ? const Color(0xFF0F172A) : Colors.white,
                            borderRadius: BorderRadius.circular(12),
                            border: Border.all(color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0)),
                          ),
                          child: Column(
                            children: [
                              _contactRow('Home Address', u.homeAddress ?? 'N/A', isDark),
                              _contactDivider(isDark),
                              _contactRow('Phone Number', u.phone.isEmpty ? 'N/A' : u.phone, isDark),
                              _contactDivider(isDark),
                              _contactRow('Email Address', u.email, isDark),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 16),
                  _nicknameAdminPanel(u, isDark),
                  const SizedBox(height: 18),
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(flex: 2, child: _statCard('Contributions', u.helps.toString(), Colors.green.shade50, Colors.green.shade800)),
                      const SizedBox(width: 8),
                      Expanded(
                        flex: 3,
                        child: _statCard(
                          'Money Given',
                          '\$${formatCurrency(contributionTotal)}',
                          Colors.blue.shade50,
