  void _copyMemberReport(
    UserData u, {
    List<AppTransaction>? contributions,
    List<AppTransaction>? claims,
    double? contributionTotal,
    int? openClaims,
  }) {
    final contrib = contributions ??
        widget.allTransactions
            .where((t) => t.userEmail == u.email && t.type == TransactionType.contribution && t.status == TransactionStatus.approved)
            .toList()
      ..sort((a, b) => b.timestamp.compareTo(a.timestamp));
    final claimList = claims ??
        widget.allTransactions.where((t) => t.userEmail == u.email && t.type == TransactionType.claim).toList()
      ..sort((a, b) => b.timestamp.compareTo(a.timestamp));
    final total = contributionTotal ?? contrib.fold<double>(0.0, (sum, t) => sum + t.amount);
    final open = openClaims ?? claimList.where((c) => c.status == TransactionStatus.pending).length;
    final raw = NgmyCivicRegistryMembers.findByEmail(widget.config, u.email) ??
        NgmyCivicRegistryMembers.findByRegistryId(widget.config, u.registryId ?? '');
    final passportGranted = raw != null && NgmyCivicRegistryMembers.passportGranted(raw);
    final familyRaw = raw?['familyMembers'];
    final familyTotal = familyRaw is num ? familyRaw.toInt() : int.tryParse('${familyRaw ?? ''}') ?? 1;
    final malesRaw = raw?['familyMales'];
    final femalesRaw = raw?['familyFemales'];
    final males = malesRaw is num ? malesRaw.toInt() : int.tryParse('${malesRaw ?? ''}') ?? 0;
    final females = femalesRaw is num ? femalesRaw.toInt() : int.tryParse('${femalesRaw ?? ''}') ?? 0;

    final report = StringBuffer()
      ..writeln('FULL MEMBER INFORMATION')
      ..writeln('Generated: ${DateTime.now().toLocal()}')
      ..writeln('')
      ..writeln('--- OFFICIAL RECORD ---')
      ..writeln('Name: ${u.fullName ?? u.username}')
      ..writeln('Registry ID: ${u.registryId ?? 'N/A'}')
      ..writeln('Date of Birth: ${u.dob ?? 'N/A'}')
      ..writeln('ID Type: ${u.idType ?? 'N/A'}')
      ..writeln('State: ${u.state}')
      ..writeln('City: ${u.city ?? 'N/A'}')
      ..writeln('Room: ${u.room ?? 'N/A'}')
      ..writeln('Status: ${_statusLabelForMissed(u.missed)}')
      ..writeln('Registry Passport: ${passportGranted ? 'Granted' : 'Not granted'}')
      ..writeln('Family size (Jumla): $familyTotal')
      ..writeln('Wanaume (M): $males')
      ..writeln('Wanawake (F): $females')
      ..writeln('')
      ..writeln('--- CONTACT ---')
      ..writeln('Home Address: ${u.homeAddress ?? 'N/A'}')
      ..writeln('Phone: ${u.phone.isEmpty ? 'N/A' : u.phone}')
      ..writeln('Email: ${u.email}')
      ..writeln('')
      ..writeln('--- ACTIVITY ---')
      ..writeln('Contributions (helps): ${u.helps}')
      ..writeln('Missed: ${u.missed}')
      ..writeln('Open Claims: $open')
      ..writeln('Total Money Given: \$${formatCurrency(total)}')
      ..writeln('')
      ..writeln('--- CONTRIBUTION RECORDS (${contrib.length}) ---');
    if (contrib.isEmpty) {
      report.writeln('No contribution records.');
    } else {
      for (final t in contrib) {
        report.writeln('- \$${formatCurrency(t.amount)} · ${_txReadableDetails(t)} · ${t.timestamp.month}/${t.timestamp.day}/${t.timestamp.year}');
      }
    }
    report
      ..writeln('')
      ..writeln('--- CLAIM RECORDS (${claimList.length}) ---');
    if (claimList.isEmpty) {
      report.writeln('No claim records.');
    } else {
      for (final t in claimList) {
        final label = t.sourceDetails?.trim().isNotEmpty == true ? t.sourceDetails!.trim() : 'Claim';
        final status = t.status == TransactionStatus.pending ? 'Open' : 'Resolved';
        report.writeln('- $label · $status · ${t.timestamp.month}/${t.timestamp.day}/${t.timestamp.year}');
      }
    }
    final text = report.toString();
    showNgmyCivicMemberReportSheet(
      context,
      memberName: u.fullName ?? u.username,
      plainText: text,
    );
  }

  String _txReadableDetails(AppTransaction t) {
    if (t.type != TransactionType.contribution) return t.sourceDetails?.trim().isNotEmpty == true ? t.sourceDetails!.trim() : 'No details';
    final meta = _decodeContributionMeta(t);
    final note = (meta['note'] ?? '').toString().trim();
    final purpose = (meta['purpose'] ?? '').toString().trim();
    if (note.isNotEmpty) return note;
    if (purpose.isNotEmpty) return purpose;
    return 'Contribution';
  }

  /// Never show a raw email on contribution receipts — prefer registry / account name.
  String _contributionMemberDisplayName(AppTransaction t) {
    final meta = _decodeContributionMeta(t);
    for (final key in ['memberName', 'fullName', 'name']) {
      final stored = (meta[key] ?? '').toString().trim();
      if (stored.isNotEmpty && !stored.contains('@') && stored.toLowerCase() != 'user' && stored.toLowerCase() != 'member') {
        return stored;
      }
    }

    final email = NgmyCivicRegistryMembers.emailKey(
      (meta['memberEmail'] ?? t.userEmail).toString(),
    );
    final rid = (meta['registryId'] ?? '').toString().trim();

    final registry = email.isNotEmpty
        ? NgmyCivicRegistryMembers.findByEmail(widget.config, email)
        : (rid.isNotEmpty ? NgmyCivicRegistryMembers.findByRegistryId(widget.config, rid) : null);
    final registryName = (registry?['fullName'] ?? '').toString().trim();
    if (registryName.isNotEmpty) return registryName;

    final deceased = email.isNotEmpty
        ? NgmyCivicRegistryMembers.findDeceasedByEmail(widget.config, email)
        : (rid.isNotEmpty ? NgmyCivicRegistryMembers.findDeceasedByRegistryId(widget.config, rid) : null);
    final deceasedSnap = deceased == null ? null : NgmyCivicRegistryMembers.deceasedMemberSnapshot(deceased);
    final deceasedName = (deceasedSnap?['fullName'] ?? deceased?['fullName'] ?? '').toString().trim();
    if (deceasedName.isNotEmpty) return deceasedName;

    if (email.isNotEmpty) {
      for (final u in widget.allUsers) {
        if (NgmyCivicRegistryMembers.emailKey(u.email) != email) continue;
        final full = (u.fullName ?? '').trim();
        if (full.isNotEmpty) return full;
        final un = u.username.trim();
        if (un.isNotEmpty && un != 'User' && !un.contains('@')) return un;
      }
      for (final u in _civicRegistryMembersForDisplay(widget.config, widget.allUsers)) {
        if (NgmyCivicRegistryMembers.emailKey(u.email) != email) continue;
        final full = (u.fullName ?? '').trim();
        if (full.isNotEmpty) return full;
        final un = u.username.trim();
        if (un.isNotEmpty && un != 'User' && !un.contains('@')) return un;
      }
    }

    if (rid.isNotEmpty) {
      for (final u in widget.allUsers) {
        if ((u.registryId ?? '').trim().toUpperCase() != rid.toUpperCase()) continue;
        final full = (u.fullName ?? '').trim();
        if (full.isNotEmpty) return full;
        final un = u.username.trim();
        if (un.isNotEmpty && un != 'User' && !un.contains('@')) return un;
      }
      for (final u in _civicRegistryMembersForDisplay(widget.config, widget.allUsers)) {
        if ((u.registryId ?? '').trim().toUpperCase() != rid.toUpperCase()) continue;
        final full = (u.fullName ?? '').trim();
        if (full.isNotEmpty) return full;
      }
    }

    if (email.contains('@')) {
      final local = email.split('@').first.trim();
      if (local.isNotEmpty && !local.startsWith('civic.')) return local;
    }
    return rid.isNotEmpty ? rid : 'Contributor';
  }

  List<UserData> _membersForReceiptMeta(Map<String, dynamic> meta) {
    final state = (meta['state'] ?? _selectedState).toString().trim();
    final stateLower = state.toLowerCase();
    if (stateLower.isEmpty) return const [];

    final allInState = _civicRegistryMembersForDisplay(widget.config, widget.allUsers)
        .where((m) => m.state.trim().toLowerCase() == stateLower)
        .toList();
    final scopeType = (meta['scopeType'] ?? 'all').toString().trim().toLowerCase();
    final scopeValue = (meta['scopeValue'] ?? '').toString().trim();
    if (scopeType != 'city' && scopeType != 'room') return allInState;
    if (scopeValue.isEmpty) return allInState;
    final wanted = scopeValue.toLowerCase();
    return allInState.where((m) {
      final registry = NgmyCivicRegistryMembers.findByEmail(widget.config, m.email) ??
          (((m.registryId ?? '').trim().isNotEmpty)
              ? NgmyCivicRegistryMembers.findByRegistryId(widget.config, m.registryId!)
              : null);
      final memberCity = ((registry?['city'] ?? m.city) ?? '').toString().trim().toLowerCase();
      final memberRoom = ((registry?['room'] ?? m.room) ?? '').toString().trim().toLowerCase();
      if (scopeType == 'city') return memberCity == wanted;
      return memberRoom == wanted;
    }).toList();
  }

  String _memberDisplayNameFromUser(UserData u) {
    final full = (u.fullName ?? '').trim();
    if (full.isNotEmpty) return full;
    final un = u.username.trim();
    if (un.isNotEmpty && un != 'User' && !un.contains('@')) return un;
    final registry = NgmyCivicRegistryMembers.findByEmail(widget.config, u.email);
    final registryName = (registry?['fullName'] ?? '').toString().trim();
    if (registryName.isNotEmpty) return registryName;
    final rid = (u.registryId ?? '').trim();
    if (rid.isNotEmpty) return rid;
    final email = u.email.trim();
    if (email.contains('@')) {
      final local = email.split('@').first.trim();
      if (local.isNotEmpty) return local;
    }
    return 'Mwanachama';
  }

  String _buildContributionReceiptWhatsAppSwahili({
    required Map<String, dynamic> meta,
    required List<AppTransaction> txs,
  }) {
    final purpose = (meta['purpose'] ?? 'Michango ya jamii').toString().trim();
    final state = (meta['state'] ?? _selectedState).toString().trim();
    final scopeType = (meta['scopeType'] ?? 'all').toString().trim().toLowerCase();
    final scopeValue = (meta['scopeValue'] ?? '').toString().trim();
    final scopeLabel = scopeType == 'city'
        ? 'Jiji: $scopeValue'
        : scopeType == 'room'
            ? 'Chumba: $scopeValue'
            : 'Wanachama wote';
    final when = txs.isNotEmpty
        ? '${txs.first.timestamp.month}/${txs.first.timestamp.day}/${txs.first.timestamp.year}'
        : '';

    final totalsByKey = <String, double>{};
    final namesByKey = <String, String>{};
    for (final t in txs) {
      final m = _decodeContributionMeta(t);
      final emailKey = NgmyCivicRegistryMembers.emailKey(
        (m['memberEmail'] ?? t.userEmail).toString(),
      );
      final rid = (m['registryId'] ?? '').toString().trim().toUpperCase();
      final key = emailKey.isNotEmpty ? emailKey : (rid.isNotEmpty ? 'rid:$rid' : t.id);
      if (key.isEmpty) continue;
      totalsByKey[key] = (totalsByKey[key] ?? 0) + t.amount;
      namesByKey.putIfAbsent(key, () => _contributionMemberDisplayName(t));
    }

    final contributedKeys = totalsByKey.keys.toSet();
    final contributedNames = totalsByKey.entries.toList()
      ..sort((a, b) => (namesByKey[a.key] ?? '').toLowerCase().compareTo((namesByKey[b.key] ?? '').toLowerCase()));

    final pendingNames = <String>[];
    for (final m in _membersForReceiptMeta(meta)) {
      final emailKey = NgmyCivicRegistryMembers.emailKey(m.email);
      final ridKey = 'rid:${(m.registryId ?? '').trim().toUpperCase()}';
      final contributed = (emailKey.isNotEmpty && contributedKeys.contains(emailKey)) ||
          (ridKey != 'rid:' && contributedKeys.contains(ridKey));
      if (contributed) continue;
      pendingNames.add(_memberDisplayNameFromUser(m));
    }
    pendingNames.sort((a, b) => a.toLowerCase().compareTo(b.toLowerCase()));

    final totalAmount = txs.fold<double>(0, (s, t) => s + t.amount);
    final buf = StringBuffer()
      ..writeln("*EMO 'YA M'MBONDO · $state*")
      ..writeln('📋 *RIPOTI YA MICHANGO*')
      ..writeln('')
      ..writeln('Kampeni: $purpose')
      ..writeln('Eneo: $scopeLabel');
    if (when.isNotEmpty) buf.writeln('Tarehe: $when');
    buf
      ..writeln('')
      ..writeln('✅ *WALIOCHANGIA (${contributedNames.length})*');
    if (contributedNames.isEmpty) {
      buf.writeln('Hakuna aliyetoa bado.');
    } else {
      for (var i = 0; i < contributedNames.length; i++) {
        final e = contributedNames[i];
        buf.writeln('${i + 1}. ${namesByKey[e.key]} — \$${formatCurrency(e.value)}');
      }
    }
    buf
      ..writeln('')
      ..writeln('❌ *HAWAJACHANGIA (${pendingNames.length})*');
    if (pendingNames.isEmpty) {
      buf.writeln('Wote walio kwenye orodha wamechangia. 🙌');
    } else {
      for (var i = 0; i < pendingNames.length; i++) {
        buf.writeln('${i + 1}. ${pendingNames[i]}');
      }
    }
    buf
      ..writeln('')
      ..writeln('────────')
      ..writeln('Jumla iliyokusanywa: *\$${formatCurrency(totalAmount)}*')
      ..writeln(
        'Waliochangia: *${contributedNames.length}* / Jumla: *${contributedNames.length + pendingNames.length}*',
      )
      ..writeln('')
      ..writeln('_Usajili wa Raia wa NGMY · ${state}_');
    return buf.toString().trim();
  }

  void _showContributionReceipts() {
    final initialGroups = _groupContributionReceipts(_visibleContributionTx());
    setState(() {
      _openedReceiptKeys.addAll(initialGroups.keys);
    });
    unawaited(_persistReceiptReadState());
    String? selectedKey;

    unawaited(NgmyNavigator.push<void>(
      context,
      StatefulBuilder(
        builder: (ctx, setPage) {
          final groups = _groupContributionReceipts(_visibleContributionTx());
          final keys = groups.keys.toList();
          final isDark = Theme.of(ctx).brightness == Brightness.dark;
          final pageBg = isDark ? const Color(0xFF121212) : const Color(0xFFF5F7FB);
          final panelBg = isDark ? const Color(0xFF121212) : const Color(0xFFE9F7EF);
          final tileBg = isDark ? const Color(0xFF161616) : Colors.white;
          final lineColor = isDark ? const Color(0xFF2A2A2A) : Colors.black12;
          final strongText = isDark ? Colors.white : Colors.black87;
          final softText = isDark ? Colors.white70 : Colors.black54;
          final hintGreen = isDark ? const Color(0xFF4ADE80) : Colors.green.shade800;
          final selected = selectedKey != null ? (groups[selectedKey] ?? <AppTransaction>[]) : <AppTransaction>[];
          final first = selected.isNotEmpty ? selected.first : null;
          final total = selected.fold<double>(0.0, (s, t) => s + t.amount);
          final contributors = selected.map((e) => e.userEmail).toSet().length;
          final meta = first != null ? _decodeContributionMeta(first) : <String, dynamic>{};

          void goBack() {
            if (selectedKey != null) {
              setPage(() => selectedKey = null);
            } else {
              NgmyNavigator.pop(ctx);
            }
          }

          Widget receiptStat(String label, String value, Color fg) {
            return Container(
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: tileBg,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: lineColor),
              ),
              child: Column(
                children: [
                  Text(label, style: TextStyle(fontSize: 12, color: softText)),
                  const SizedBox(height: 6),
                  Text(value, maxLines: 1, overflow: TextOverflow.ellipsis, style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold, color: fg)),
                ],
              ),
            );
          }

          return PopScope(
            canPop: selectedKey == null,
            onPopInvokedWithResult: (didPop, _) {
              if (!didPop && selectedKey != null) {
                setPage(() => selectedKey = null);
              }
            },
            child: Scaffold(
              backgroundColor: pageBg,
              appBar: AppBar(
                leading: IconButton(
                  icon: const Icon(Icons.arrow_back_ios_new_rounded),
                  onPressed: goBack,
                ),
                title: Text(
                  selectedKey == null ? 'Contribution Receipts' : 'Contribution Receipt',
                  style: const TextStyle(fontWeight: FontWeight.w900, letterSpacing: 0.5),
                ),
                centerTitle: true,
                backgroundColor: pageBg,
                foregroundColor: strongText,
                elevation: 0,
                actions: [
                  IconButton(
                    tooltip: 'State wallet',
                    onPressed: () {
                      NgmyNavigator.pop(ctx);
                      unawaited(_openCivicStateWalletFlow());
                    },
                    icon: const Icon(Icons.shield_outlined),
                  ),
                ],
              ),
              body: selectedKey == null
                  ? (keys.isEmpty
                      ? Center(child: Text('No contribution receipts yet.', style: TextStyle(color: softText)))
                      : ListView.builder(
                          padding: const EdgeInsets.fromLTRB(16, 8, 16, 24),
                          itemCount: keys.length + 1,
                          itemBuilder: (_, i) {
                            if (i == 0) {
                              return Padding(
                                padding: const EdgeInsets.only(bottom: 14),
                                child: Text("Past week's community contributions", style: TextStyle(color: softText, fontSize: 13)),
                              );
                            }
                            final k = keys[i - 1];
                            final txs = groups[k] ?? [];
                            if (txs.isEmpty) return const SizedBox.shrink();
                            final seed = txs.first;
                            final m = _decodeContributionMeta(seed);
                            final t = txs.fold<double>(0.0, (s, e) => s + e.amount);
                            final c = txs.map((e) => e.userEmail).toSet().length;
                            final receiptState = (m['state'] ?? widget.user.state).toString();
                            final canDelete = _canDeleteReceiptForState(receiptState);
                            final title = (m['purpose'] ?? 'Contribution Campaign').toString();
                            return Stack(
                              clipBehavior: Clip.none,
                              children: [
                                Container(
                                  width: double.infinity,
                                  margin: const EdgeInsets.only(bottom: 12),
                                  padding: const EdgeInsets.fromLTRB(12, 14, 12, 12),
                                  decoration: BoxDecoration(
                                    color: panelBg,
                                    borderRadius: BorderRadius.circular(12),
                                    border: Border.all(color: Colors.greenAccent.shade400),
                                  ),
                                  clipBehavior: Clip.hardEdge,
                                  child: Column(
                                    crossAxisAlignment: CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        title,
                                        maxLines: 2,
                                        overflow: TextOverflow.ellipsis,
                                        style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16, color: strongText),
                                      ),
                                      const SizedBox(height: 4),
                                      Text(
                                        '${m['state'] ?? widget.user.state} • ${m['scopeType'] == 'all' ? 'All members' : '${m['scopeType']}: ${m['scopeValue']}'}',
                                        maxLines: 1,
                                        overflow: TextOverflow.ellipsis,
                                        style: TextStyle(color: softText),
                                      ),
                                      const SizedBox(height: 4),
                                      Text('${seed.timestamp.month}/${seed.timestamp.day}/${seed.timestamp.year}', style: TextStyle(color: softText)),
                                      Divider(color: lineColor),
                                      FittedBox(
                                        fit: BoxFit.scaleDown,
                                        alignment: Alignment.centerLeft,
                                        child: Row(
                                          mainAxisSize: MainAxisSize.min,
                                          children: [
                                            Text(
                                              'Click to view full receipt →',
                                              style: TextStyle(color: hintGreen, fontWeight: FontWeight.w700, fontSize: 12),
                                            ),
                                            const SizedBox(width: 8),
                                            Text(
                                              '\$${formatCurrency(t)} • $c contributors',
                                              style: TextStyle(fontWeight: FontWeight.w800, fontSize: 12, color: strongText),
                                            ),
                                          ],
                                        ),
                                      ),
                                      const SizedBox(height: 8),
                                      SelectionContainer.disabled(
                                        child: GestureDetector(
                                          onTap: () {
                                            setPage(() {
                                              selectedKey = k;
                                              _openedReceiptKeys.add(k);
                                            });
                                            unawaited(_persistReceiptReadState());
                                            if (mounted) setState(() {});
                                          },
                                          child: Container(
                                            height: 38,
                                            width: double.infinity,
                                            decoration: BoxDecoration(color: Colors.indigo, borderRadius: BorderRadius.circular(10)),
                                            child: const Center(child: Text('Open Receipt', style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold))),
                                          ),
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                                _campaignReceiptCornerActions(
                                  campaignKey: k,
                                  receiptState: receiptState,
                                  campaignTitle: title,
                                  campaignTxs: txs,
                                  canDelete: canDelete,
                                  onDeleted: () {
                                    setPage(() => selectedKey = null);
                                    if (_groupContributionReceipts(_visibleContributionTx()).isEmpty) {
                                      NgmyNavigator.pop(ctx);
                                    }
                                  },
                                ),
                              ],
                            );
                          },
                        ))
                  : ListView(
                      padding: const EdgeInsets.fromLTRB(16, 8, 16, 24),
                      children: [
                        Stack(
                          clipBehavior: Clip.none,
                          children: [
                            Container(
                              width: double.infinity,
                              padding: const EdgeInsets.fromLTRB(14, 14, 40, 14),
                              decoration: BoxDecoration(
                                color: panelBg,
                                borderRadius: BorderRadius.circular(14),
                                border: Border.all(color: Colors.greenAccent.shade400),
                              ),
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    (meta['purpose'] ?? 'Contribution Campaign').toString(),
                                    style: TextStyle(fontWeight: FontWeight.bold, fontSize: 18, color: strongText),
                                  ),
                                  Text('State: ${meta['state'] ?? widget.user.state}', style: TextStyle(color: softText)),
                                  Text('${first?.timestamp.month}/${first?.timestamp.day}/${first?.timestamp.year}', style: TextStyle(color: softText)),
                                  const SizedBox(height: 12),
                                  Row(
                                    children: [
                                      Expanded(child: receiptStat('Total Collected', '\$${formatCurrency(total)}', isDark ? const Color(0xFF4ADE80) : Colors.green.shade800)),
                                      const SizedBox(width: 10),
                                      Expanded(child: receiptStat('Contributors', contributors.toString(), isDark ? const Color(0xFF93C5FD) : Colors.blue.shade800)),
                                    ],
                                  ),
                                  const SizedBox(height: 12),
                                  Container(
                                    width: double.infinity,
                                    decoration: BoxDecoration(
                                      color: tileBg,
                                      borderRadius: BorderRadius.circular(12),
                                      border: Border.all(color: lineColor),
                                    ),
                                    child: Column(
                                      crossAxisAlignment: CrossAxisAlignment.start,
                                      children: [
                                        Padding(
                                          padding: const EdgeInsets.all(10),
                                          child: Text('Contribution Details', style: TextStyle(fontWeight: FontWeight.bold, color: strongText)),
                                        ),
                                        Divider(height: 1, color: lineColor),
                                        if (selected.isEmpty)
                                          Padding(
                                            padding: const EdgeInsets.all(20),
                                            child: Center(child: Text('No contributions recorded yet', style: TextStyle(color: softText))),
                                          )
                                        else
                                          ...selected.map(
                                            (t) => ListTile(
                                              dense: true,
                                              leading: const Icon(Icons.volunteer_activism, color: Colors.green),
                                              title: Text(
