  void _showResolveClaimDialog(UserData u) {
    final pendingClaims = widget.allTransactions
        .where((t) => t.userEmail == u.email && t.type == TransactionType.claim && t.status == TransactionStatus.pending)
        .toList()
      ..sort((a, b) => b.timestamp.compareTo(a.timestamp));
    if (pendingClaims.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('No open claims to remove.')));
      return;
    }
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Resolve Claim'),
        content: SizedBox(
          width: 480,
          child: ListView.builder(
            shrinkWrap: true,
            itemCount: pendingClaims.length,
            itemBuilder: (_, i) {
              final c = pendingClaims[i];
              return ListTile(
                title: Text(c.sourceDetails?.isNotEmpty == true ? c.sourceDetails! : 'Claim'),
                subtitle: Text('${c.timestamp.month}/${c.timestamp.day}/${c.timestamp.year}'),
                trailing: TextButton(
                  onPressed: () {
                    setState(() {
                      c.status = TransactionStatus.rejected;
                    });
                    // onAddTransaction marks this dirty and pushes the
                    // rejected status to Supabase; onDataChanged alone does
                    // not, which is why removed claims kept reappearing for
                    // other users/devices.
                    widget.onAddTransaction(c);
                    Navigator.pop(ctx);
                  },
                  child: const Text('Remove'),
                ),
              );
            },
          ),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Close')),
        ],
      ),
    );
  }

  /// Money records for a member — same set as Contribution Records in View.
  List<AppTransaction> _contributionsForMember(UserData u) {
    return _civicTransactionsForDisplay().where((t) => _contributionBelongsToMember(t, u)).toList()
      ..sort((a, b) => b.timestamp.compareTo(a.timestamp));
  }

  /// The member's contribution for the *currently active* help campaign only.
  /// Returns null when help is off or they have not contributed this round yet.
  AppTransaction? _activeCampaignContributionForMember(UserData u, {String? forState}) {
    final state = (forState ?? _selectedState).trim();
    if (state.isEmpty || !widget.config.helpActiveFor(state)) return null;
    final campaignId = _activeHelpCampaignId(state).trim();
    final startedRaw = widget.config.helpCampaignStartedAtFor(state).trim();
    final startedAt = DateTime.tryParse(startedRaw);
    for (final t in _contributionsForMember(u)) {
      if (t.status != TransactionStatus.approved) continue;
      final meta = _decodeContributionMeta(t);
      final cid = (meta['campaignId'] ?? '').toString().trim();
      if (campaignId.isNotEmpty && cid.isNotEmpty) {
        if (cid == campaignId) return t;
        continue;
      }
      // Legacy rows without campaignId: treat as this campaign only if they
      // were recorded after the current campaign started.
      if (cid.isEmpty && startedAt != null && !t.timestamp.isBefore(startedAt)) {
        final receiptState = _contributionReceiptState(t, meta).trim().toLowerCase();
        if (receiptState.isEmpty || receiptState == state.toLowerCase()) return t;
      }
    }
    return null;
  }

  bool _contributionBelongsToMember(AppTransaction t, UserData u) {
    if (t.type != TransactionType.contribution || t.status != TransactionStatus.approved) return false;
    final emailKey = NgmyCivicRegistryMembers.emailKey(u.email);
    final rid = (u.registryId ?? '').trim().toUpperCase();
    final txEmail = NgmyCivicRegistryMembers.emailKey(t.userEmail);
    if (emailKey.isNotEmpty && txEmail == emailKey) return true;
    final raw = NgmyCivicRegistryMembers.findByEmail(widget.config, u.email) ??
        (rid.isNotEmpty ? NgmyCivicRegistryMembers.findByRegistryId(widget.config, rid) : null);
    if (raw != null) {
      final regEmail = NgmyCivicRegistryMembers.emailKey((raw['email'] ?? '').toString());
      if (regEmail.isNotEmpty && txEmail == regEmail) return true;
      final linked = NgmyCivicRegistryMembers.emailKey((raw['linkedAppEmail'] ?? '').toString());
      if (linked.isNotEmpty && txEmail == linked) return true;
    }
    final meta = _decodeContributionMeta(t);
    final metaEmail = NgmyCivicRegistryMembers.emailKey((meta['memberEmail'] ?? '').toString());
    if (emailKey.isNotEmpty && metaEmail == emailKey) return true;
    if (raw != null) {
      final linked = NgmyCivicRegistryMembers.emailKey((raw['linkedAppEmail'] ?? '').toString());
      if (linked.isNotEmpty && metaEmail == linked) return true;
    }
    final metaRid = (meta['registryId'] ?? '').toString().trim().toUpperCase();
    if (rid.isNotEmpty && metaRid == rid) return true;
    return false;
  }

  List<AppTransaction> _moneyRecordsForMember(UserData u) => _contributionsForMember(u);

  /// Lets a registrar remove a money/contribution record that was recorded
  /// by mistake — available while help mode is on or off. Mirrors the claim
  /// delete pattern: status flips to rejected and syncs via onAddTransaction.
  /// helps is decremented to undo the add; missed is never touched here.
  void _showMoneyRecordsManageDialog(UserData u) {
    final records = _moneyRecordsForMember(u);
    if (records.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('No money records to remove.')));
      return;
    }
    showDialog(
      context: context,
      builder: (ctx) {
        return StatefulBuilder(
          builder: (ctx, setDialogState) {
            final isDark = Theme.of(ctx).brightness == Brightness.dark;
            final panelBg = isDark ? const Color(0xFF111827) : Colors.white;
            final ink = isDark ? Colors.white : const Color(0xFF0F172A);
            final borderColor = isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0);

            Future<void> removeRecord(AppTransaction t) async {
              final isDarkConfirm = Theme.of(ctx).brightness == Brightness.dark;
              final confirmed = await showGeneralDialog<bool>(
                context: ctx,
                barrierDismissible: true,
                barrierLabel: 'Dismiss',
                barrierColor: Colors.black.withValues(alpha: 0.45),
                transitionDuration: const Duration(milliseconds: 320),
                pageBuilder: (dctx, anim, secondary) => const SizedBox.shrink(),
