  Widget _passportAdminPanel(UserData member, bool isDark) {
    final raw = NgmyCivicRegistryMembers.findByEmail(widget.config, member.email);
    if (raw == null) return const SizedBox.shrink();
    final granted = NgmyCivicRegistryMembers.passportGranted(raw);
    final linkEmail = NgmyCivicRegistryMembers.findLinkableAppEmail(widget.allUsers, raw);
    UserData? appUser;
    if (linkEmail != null) {
      for (final u in widget.allUsers) {
        if (NgmyCivicRegistryMembers.emailKey(u.email) == linkEmail) {
          appUser = u;
          break;
        }
      }
    }
    final alreadyHasCard = appUser != null &&
        NgmyCivicRegistryMembers.appUserHasGrantedPassport(widget.config, appUser);

    return Container(
      width: double.infinity,
      margin: const EdgeInsets.only(bottom: 18),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: isDark ? const Color(0xFF1A2233) : const Color(0xFFF0FDF4),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: isDark ? const Color(0xFF334155) : const Color(0xFF86EFAC)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(Icons.link_rounded, color: isDark ? const Color(0xFF86EFAC) : const Color(0xFF15803D), size: 20),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  'App account link',
                  style: TextStyle(fontWeight: FontWeight.w800, color: isDark ? Colors.white : const Color(0xFF14532D)),
                ),
              ),
              IconButton(
                tooltip: 'Search email or phone to link & grant ID',
                visualDensity: VisualDensity.compact,
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 36, minHeight: 36),
                onPressed: () => unawaited(_searchAndGrantPassport(member)),
                icon: Icon(
                  Icons.search_rounded,
                  size: 22,
                  color: isDark ? const Color(0xFF86EFAC) : const Color(0xFF15803D),
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          if (granted) ...[
            Text(
              'Passport granted${appUser != null ? ' to ${appUser.username}' : ''}.',
              style: TextStyle(fontSize: 13, color: isDark ? Colors.white70 : const Color(0xFF166534)),
            ),
            if ((raw['linkedAppEmail'] ?? '').toString().trim().isNotEmpty)
              Text(
                'Linked: ${raw['linkedAppEmail']}',
                style: TextStyle(fontSize: 11, color: isDark ? Colors.white54 : Colors.black54),
              ),
          ] else if (appUser != null && !alreadyHasCard) ...[
            Text(
              'App user "${appUser.username}" signed up with the same email or phone — grant passport to connect their account to this civic record.',
              style: TextStyle(fontSize: 13, color: isDark ? Colors.white70 : const Color(0xFF166534)),
            ),
            const SizedBox(height: 10),
            SizedBox(
              width: double.infinity,
              child: FilledButton.icon(
                onPressed: () => _grantRegistryPassport(member),
                icon: const Icon(Icons.verified_user_outlined, size: 18),
                label: const Text('Grant Registry Passport'),
                style: FilledButton.styleFrom(backgroundColor: const Color(0xFF059669)),
              ),
            ),
          ] else if (alreadyHasCard) ...[
            Text(
              'The matching app account already has a Civic Registry ID card, so it cannot be granted another one.',
              style: TextStyle(fontSize: 12, color: isDark ? Colors.white54 : Colors.black54, height: 1.35),
            ),
          ] else ...[
            Text(
              'No matching app sign-up detected yet. Tap search to find them by email or phone and grant their ID instantly — or wait until they sign up with this member\'s email/phone and the Grant button will appear automatically.',
              style: TextStyle(fontSize: 12, color: isDark ? Colors.white54 : Colors.black54, height: 1.35),
            ),
          ],
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    _queueHelpModeLifecycleMaintenance();
    bool isDark = Theme.of(context).brightness == Brightness.dark;
    final primaryColor = const Color(0xFF6200EE);
    final receiptGroups = _groupContributionReceipts(_visibleContributionTx(), unreadOnly: true);
    final receiptCount = receiptGroups.length;

    if (!_unlockChecked) {
      return const Scaffold(
        body: Center(child: CircularProgressIndicator()),
      );
    }
    if (!_registryUnlocked && !_canBypassCivicGate() && _stateRequiresMemberUnlock()) {
      return CivicRegistryGateScreen(
        usStates: _usStates,
        pinsByState: widget.config.civicRegistryPinsByState,
        globalPin: widget.config.civicRegistryPin,
        userEmail: widget.user.email,
        initialState: _selectedState,
        members: NgmyCivicRegistryMembers.listFrom(widget.config),
        onBack: () => NgmyNavigator.pop(context),
        onUnlocked: _onRegistryUnlocked,
        // AR home / King / Admin never need PIN — picking home while on the
        // gate must dismiss verify membership immediately.
        stateRequiresUnlock: (state) =>
            !_canUseRegistrarToolsHere(state) && _stateRequiresMemberUnlock(state),
      );
    }

    return NgmyTabBackScope(
      activeTab: _activeTab,
      onTabBack: () => setState(() => _activeTab = (_activeTab - 1).clamp(0, _maxCivicTabIndex)),
      child: Scaffold(
      backgroundColor: isDark ? const Color(0xFF121212) : const Color(0xFFF5F7FB),
      body: Stack(
        children: [
          SelectionContainer.disabled(
            child: SingleChildScrollView(
              padding: EdgeInsets.fromLTRB(
                20,
                MediaQuery.paddingOf(context).top + 8 + 64 + 14,
                20,
                20,
              ),
              child: Column(
            children: [
            // Top Header Card
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(25),
              decoration: BoxDecoration(
                gradient: LinearGradient(colors: [primaryColor, primaryColor.withOpacity(0.8)], begin: Alignment.topLeft, end: Alignment.bottomRight),
                borderRadius: BorderRadius.circular(30),
                boxShadow: [BoxShadow(color: primaryColor.withOpacity(0.3), blurRadius: 15, offset: const Offset(0, 8))],
              ),
              child: Row(
                children: [
                  SelectionContainer.disabled(
                    child: GestureDetector(
                      onTap: _showContributionReceipts,
