  Widget _civicVotingEntryCard() {
    final passport = NgmyCivicRegistryMembers.passportForAppUser(
      widget.config,
      email: widget.user.email,
      phone: widget.user.phone,
    );
    final memberState = (passport?['state'] ?? _selectedState).toString();
    final isVoteAdmin = widget.user.isAdmin ||
        widget.user.isCivicRegistryKing ||
        widget.user.isCivicRegistryAdmin;
    return NgmyCivicVotingEntryCard(
      config: widget.config,
      userEmail: widget.user.email,
      userPhone: widget.user.phone,
      memberState: memberState,
      isAdmin: isVoteAdmin,
    );
  }

  Future<void> _refreshCivicMembersFromCloud() async {
    await ngmyHydrateCivicRegistryMembersFromAllBackups(widget.config, widget.allUsers);
    if (!mounted) return;
    setState(() {});
  }

  Widget _tabItem(int index, String label, IconData icon) {
    bool isSelected = _activeTab == index;
    bool isDark = Theme.of(context).brightness == Brightness.dark;
    return SelectionContainer.disabled(
      child: InkWell(
        onTap: () {
          setState(() => _activeTab = index);
          if (index == 2) unawaited(_refreshCivicMembersFromCloud());
        },
        borderRadius: BorderRadius.circular(20),
        child: Container(
          height: 85,
          decoration: BoxDecoration(
            color: isSelected ? const Color(0xFF6200EE) : (isDark ? const Color(0xFF1E1E1E) : Colors.white),
            borderRadius: BorderRadius.circular(25),
            boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.05), blurRadius: 10, offset: const Offset(0, 5))],
          ),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(icon, color: isSelected ? Colors.white : Colors.grey, size: 28),
              const SizedBox(height: 8),
              Text(label, style: TextStyle(color: isSelected ? Colors.white : Colors.grey, fontWeight: FontWeight.bold, fontSize: 13)),
            ],
          ),
        ),
      ),
    );
  }

  Widget _searchSection(bool isDark) {
    return Container(
      padding: const EdgeInsets.all(25),
      decoration: BoxDecoration(color: isDark ? const Color(0xFF1E1E1E) : Colors.white, borderRadius: BorderRadius.circular(30), boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.05), blurRadius: 15)]),
      child: Column(
        children: [
          TextField(
            controller: _searchController,
            // Live — no more "Search Registry" button to click. Results
            // below update on every keystroke via onChanged.
            onChanged: (v) => setState(() => _searchQuery = v.toLowerCase()),
            decoration: InputDecoration(
              hintText: 'Search by name, ID, city...',
              hintStyle: const TextStyle(fontSize: 13, color: Colors.grey),
              prefixIcon: const Icon(Icons.search, size: 22),
              border: OutlineInputBorder(borderRadius: BorderRadius.circular(20), borderSide: BorderSide.none),
              filled: true,
              fillColor: isDark ? Colors.black.withOpacity(0.2) : Colors.grey.shade50,
            ),
          ),
          if (_searchQuery.isNotEmpty) ...[
            const SizedBox(height: 24),
            Align(
              alignment: Alignment.centerLeft,
              child: Text(
                '${_registryMembersMatchingSearch().length} result(s)',
                style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13, color: Colors.grey),
              ),
            ),
            const SizedBox(height: 12),
            ..._registryMembersMatchingSearch().map((m) => _publicSearchMemberCard(m, isDark)),
          ],
        ],
      ),
    );
  }

  Widget _publicSearchMemberCard(UserData u, bool isDark) {
    final raw = _civicMemberOrDeceasedRaw(widget.config, u);
    final isDeceased = _civicMemberIsDeceased(widget.config, u);
    final displayName = NgmyCivicRegistryMembers.publicDisplayName(
      raw,
      fullName: u.fullName ?? '',
      username: u.username,
    );
    final familyRaw = raw?['familyMembers'];
    final familyCount = familyRaw is num ? familyRaw.toInt() : int.tryParse('${familyRaw ?? ''}') ?? 1;
    final initials = displayName
        .trim()
        .split(RegExp(r'\s+'))
        .where((p) => p.isNotEmpty)
        .take(2)
        .map((p) => p[0].toUpperCase())
        .join();
    final statusLabel = isDeceased ? 'Deceased' : _statusLabelForMissed(u.missed);
    final statusColor = isDeceased ? const Color(0xFF64748B) : _statusColorForMissed(u.missed);
    final ink = isDark ? Colors.white : const Color(0xFF0F172A);
    final canManage = _canUseRegistrarToolsHere();

    return Material(
      color: Colors.transparent,
      child: InkWell(
        // _showMemberProfile dispatches to the full manager dialog
        // (money/claim/delete actions) for registrars/King/Admin, or the
        // read-only public profile otherwise — a manager searching live
        // now gets the same capabilities they'd have had from the
        // Members tab, without needing to switch to it first.
        onTap: () => _showMemberProfile(u),
        borderRadius: BorderRadius.circular(22),
        child: _AliveSearchFrame(
          isDark: isDark,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(12, 10, 12, 10),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Row(
                  children: [
                    Container(
                      width: 40,
                      height: 40,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        gradient: LinearGradient(
                          colors: isDark
                              ? const [Color(0xFF334155), Color(0xFF0F766E)]
                              : const [Color(0xFFCCFBF1), Color(0xFFE0E7FF)],
                        ),
                        border: Border.all(color: isDark ? const Color(0xFF5EEAD4) : const Color(0xFF14B8A6), width: 1.4),
                      ),
                      alignment: Alignment.center,
                      child: Text(
                        initials.isEmpty ? '?' : initials,
                        style: TextStyle(
                          fontWeight: FontWeight.w900,
                          fontSize: 13,
                          color: isDark ? Colors.white : const Color(0xFF0F766E),
                        ),
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            displayName,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(fontWeight: FontWeight.w900, fontSize: 14.5, color: ink, letterSpacing: -0.2),
                          ),
                          if (canManage)
                            Text(
                              u.registryId ?? 'PENDING ID',
                              style: TextStyle(color: isDark ? const Color(0xFF67E8F9) : const Color(0xFF0369A1), fontWeight: FontWeight.w800, fontSize: 11),
                            )
                          else if (u.username.trim().isNotEmpty)
                            Text(
                              u.username.trim(),
                              style: TextStyle(color: isDark ? Colors.white54 : Colors.black54, fontWeight: FontWeight.w600, fontSize: 11),
                            ),
                        ],
                      ),
                    ),
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      decoration: BoxDecoration(
                        color: statusColor.withValues(alpha: isDark ? 0.28 : 0.14),
                        borderRadius: BorderRadius.circular(999),
                        border: Border.all(color: statusColor.withValues(alpha: 0.55)),
                      ),
                      child: Text(statusLabel, style: TextStyle(color: statusColor, fontSize: 9, fontWeight: FontWeight.w900)),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Expanded(child: _publicMetaChip(Icons.location_on_rounded, u.city ?? 'City n/a', const Color(0xFFEF4444), isDark)),
                    const SizedBox(width: 6),
                    Expanded(child: _publicMetaChip(Icons.meeting_room_rounded, u.room ?? 'Room n/a', const Color(0xFFF59E0B), isDark)),
                    const SizedBox(width: 6),
                    Expanded(child: _publicMetaChip(Icons.phone_rounded, u.phone.isEmpty ? 'No phone' : u.phone, const Color(0xFF64748B), isDark)),
                    const SizedBox(width: 6),
                    Expanded(child: _publicMetaChip(Icons.family_restroom_rounded, '$familyCount', const Color(0xFF14B8A6), isDark)),
                  ],
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _publicMetaChip(IconData icon, String label, Color color, bool isDark) {
    return Container(
      height: 34,
      padding: const EdgeInsets.symmetric(horizontal: 6),
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: color.withValues(alpha: isDark ? 0.16 : 0.08),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: color.withValues(alpha: isDark ? 0.35 : 0.22)),
      ),
      child: Row(
        children: [
          Icon(icon, size: 12, color: color),
          const SizedBox(width: 4),
          Expanded(
            child: Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(fontSize: 10, fontWeight: FontWeight.w700, color: isDark ? Colors.white : const Color(0xFF334155)),
            ),
          ),
        ],
      ),
    );
  }

  Widget _enrollSection(bool isDark) {
    final availableAppUsers = widget.allUsers.where((u) =>
      ngmyLooksLikeAppLoginUser(u) &&
      !NgmyCivicRegistryMembers.isEnrolled(widget.config, u.email) &&
      (u.username.toLowerCase().contains(_enrollSearchC.text.toLowerCase()) ||
       u.email.toLowerCase().contains(_enrollSearchC.text.toLowerCase()))
    ).toList();
    final isEditing = (_editingMemberOriginalEmail ?? '').isNotEmpty ||
        (_editingMemberRegistryId ?? '').isNotEmpty;
    final cityOptions = [
      ..._citiesForSelectedState(),
      if (_cityC.text.trim().isNotEmpty && !_citiesForSelectedState().contains(_cityC.text.trim())) _cityC.text.trim(),
    ];
    final roomOptions = [
      ...widget.config.rooms,
      if (_roomC.text.trim().isNotEmpty && !widget.config.rooms.contains(_roomC.text.trim())) _roomC.text.trim(),
    ];

    return Column(
      children: [
        // MANUAL ENROLLMENT FORM
        Container(
          key: ValueKey('enroll-form-${_editingMemberOriginalEmail ?? 'new'}-${_cityC.text}-${_roomC.text}-${_idTypeC.text}'),
          padding: const EdgeInsets.all(25),
          decoration: BoxDecoration(color: isDark ? const Color(0xFF1E1E1E) : Colors.white, borderRadius: BorderRadius.circular(30), boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.05), blurRadius: 15)]),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(15),
                decoration: BoxDecoration(
                  color: (isEditing ? Colors.orange : Colors.blue).withOpacity(0.08),
                  borderRadius: BorderRadius.circular(15),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      isEditing ? 'Update Member Enrollment' : 'Manual Enrollment',
                      style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16, color: isEditing ? Colors.orange.shade800 : Colors.blue),
                    ),
                    Text(
                      isEditing
                          ? 'Same member profile — change only what you need. City and room are optional when updating.'
                          : 'Register a new member from scratch.',
                      style: TextStyle(fontSize: 11, color: isEditing ? Colors.orange.shade700 : Colors.blueGrey),
                    ),
                  ],
                ),
              ),
              if (isEditing) ...[
                const SizedBox(height: 12),
                Align(
                  alignment: Alignment.centerRight,
                  child: TextButton.icon(
                    onPressed: () => setState(_clearEnrollmentForm),
                    icon: const Icon(Icons.close, size: 16),
                    label: const Text('Cancel edit'),
                  ),
                ),
              ],
              const SizedBox(height: 25),

              _enrollFlagLabel('Full Name *', 'fullName'),
              const SizedBox(height: 8),
              TextField(
                controller: _fullNameC,
                decoration: InputDecoration(hintText: 'First name and last name', hintStyle: const TextStyle(fontSize: 13, color: Colors.grey), filled: true, fillColor: isDark ? Colors.black26 : Colors.grey.shade50, border: OutlineInputBorder(borderRadius: BorderRadius.circular(15), borderSide: BorderSide.none)),
              ),
              const SizedBox(height: 20),

              _enrollFlagLabel('Date of Birth (optional)', 'dob'),
              const SizedBox(height: 8),
              TextField(
                controller: _dobC,
                keyboardType: TextInputType.number,
                inputFormatters: [
                  const NgmyCivicDobInputFormatter(),
                  LengthLimitingTextInputFormatter(10),
                ],
                decoration: InputDecoration(hintText: 'MM/DD/YYYY', hintStyle: const TextStyle(fontSize: 13, color: Colors.grey), filled: true, fillColor: isDark ? Colors.black26 : Colors.grey.shade50, border: OutlineInputBorder(borderRadius: BorderRadius.circular(15), borderSide: BorderSide.none)),
              ),
              const SizedBox(height: 20),

              _enrollFlagLabel('ID Type', 'idType'),
