  Widget _enrollField(String label, TextEditingController c, String hint, {String? fieldKey}) {
    bool isDark = Theme.of(context).brightness == Brightness.dark;
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      if (label.isNotEmpty) ...[
        if (fieldKey != null) _enrollFlagLabel(label, fieldKey) else Text(label, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13)),
        const SizedBox(height: 8),
      ],
      TextField(controller: c, decoration: InputDecoration(hintText: hint, hintStyle: const TextStyle(fontSize: 13, color: Colors.grey), filled: true, fillColor: isDark ? Colors.black26 : Colors.grey.shade50, border: OutlineInputBorder(borderRadius: BorderRadius.circular(15), borderSide: BorderSide.none))),
      const SizedBox(height: 20),
    ]);
  }

  Widget _enrollFlagLabel(String label, String fieldKey) {
    final flag = _enrollmentFlags[fieldKey];
    final status = (flag?['status'] ?? '').toString().trim();
    final hasFlag = status.isNotEmpty;
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: () => _onEnrollLabelTap(fieldKey),
      child: Row(
        children: [
          Flexible(
            child: Text(label, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13)),
          ),
          if (hasFlag) ...[
            const SizedBox(width: 8),
            Container(
              width: 8,
              height: 8,
              decoration: const BoxDecoration(color: Color(0xFFE53935), shape: BoxShape.circle),
            ),
            const SizedBox(width: 6),
            Text(
              ngmyProfileFlagLabel(status),
              style: const TextStyle(color: Color(0xFFE53935), fontSize: 11, fontWeight: FontWeight.w700),
            ),
          ],
        ],
      ),
    );
  }

  DateTime? _enrollLabelLastTap;
  int _enrollLabelTapCount = 0;
  String? _enrollLabelTapKey;

  void _onEnrollLabelTap(String fieldKey) {
    if (!_canUseRegistrarToolsHere()) return;
    final now = DateTime.now();
    if (_enrollLabelTapKey != fieldKey ||
        _enrollLabelLastTap == null ||
        now.difference(_enrollLabelLastTap!) > const Duration(milliseconds: 450)) {
      _enrollLabelTapKey = fieldKey;
      _enrollLabelTapCount = 1;
      _enrollLabelLastTap = now;
      return;
    }
    _enrollLabelTapCount += 1;
    _enrollLabelLastTap = now;
    if (_enrollLabelTapCount < 3) return;
    _enrollLabelTapCount = 0;
    _enrollLabelTapKey = null;
    unawaited(_showProfileFlagPicker(fieldKey));
  }

  Future<void> _showProfileFlagPicker(String fieldKey) async {
    final current = (_enrollmentFlags[fieldKey]?['status'] ?? '').toString();
    final picked = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: Colors.transparent,
      builder: (ctx) {
        final isDark = Theme.of(ctx).brightness == Brightness.dark;
        final bg = isDark ? const Color(0xFF1E1E1E) : Colors.white;
        return SafeArea(
          child: Container(
            margin: const EdgeInsets.all(12),
            decoration: BoxDecoration(color: bg, borderRadius: BorderRadius.circular(18)),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
                  child: Text(
                    ngmyProfileFlagFieldLabel(fieldKey),
                    style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 16),
                  ),
                ),
                ...kNgmyProfileFlagStatuses.map((s) {
                  final on = current == s.$1;
                  return ListTile(
                    leading: Icon(on ? Icons.radio_button_checked : Icons.radio_button_off, color: const Color(0xFFE53935)),
                    title: Text(s.$2, style: const TextStyle(fontWeight: FontWeight.w700)),
                    onTap: () => Navigator.pop(ctx, s.$1),
                  );
                }),
                if (current.isNotEmpty)
                  ListTile(
                    leading: const Icon(Icons.check_circle_outline, color: Colors.green),
                    title: const Text('Clear note', style: TextStyle(fontWeight: FontWeight.w700)),
                    onTap: () => Navigator.pop(ctx, ''),
                  ),
                const SizedBox(height: 8),
              ],
            ),
          ),
        );
      },
    );
    if (!mounted || picked == null) return;
    setState(() {
      if (picked.isEmpty) {
        _enrollmentFlags.remove(fieldKey);
      } else {
        ngmySetProfileFlag(
          _enrollmentFlags,
          fieldKey: fieldKey,
          status: picked,
          notedBy: widget.user.email,
        );
      }
    });
  }

  /// The "Clear Missed" pill above the member list had no onTap at all —
  /// tapping it did nothing. Asks how many missed to subtract (not an
  /// unconditional reset to 0) from every member currently visible under
  /// the active city/room/search filters.
  Future<void> _confirmClearMissed(List<UserData> visibleMembers) async {
    final withMissed = visibleMembers.where((m) => m.missed > 0).toList();
    if (withMissed.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('No members here have a missed count to clear.')));
      return;
    }
    final maxMissed = withMissed.map((m) => m.missed).reduce((a, b) => a > b ? a : b);
    final amountC = TextEditingController();
    final searchC = TextEditingController();
    // Default target is everybody shown (matches the old behavior); the
    // registrar can switch to "One person" and search/pick a single member
    // instead of clearing the whole visible list.
    UserData? selectedMember;
    final result = await showDialog<Map<String, dynamic>>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialog) {
          final query = searchC.text.trim().toLowerCase();
          final searchResults = query.isEmpty
              ? withMissed
              : withMissed.where((m) {
                  final raw = NgmyCivicRegistryMembers.findByEmail(widget.config, m.email);
                  final nicks = raw == null ? const <String>[] : NgmyCivicRegistryMembers.nicknamesOf(raw);
                  return _ngmyCivicMemberSearchScore(query, m, nicks) >= 0.75 ||
                      m.email.toLowerCase().contains(query);
                }).toList();
          return AlertDialog(
            title: const Text('Clear Missed'),
            content: SizedBox(
              width: 420,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    selectedMember == null
                        ? '${withMissed.length} member(s) shown in $_selectedState have a missed count (highest: $maxMissed).'
                        : 'Clearing missed for ${selectedMember!.fullName ?? selectedMember!.username} only (currently ${selectedMember!.missed} missed).',
                  ),
                  const SizedBox(height: 12),
                  Row(
                    children: [
                      Expanded(
                        child: ChoiceChip(
                          label: const Text('Everybody'),
                          selected: selectedMember == null,
                          onSelected: (_) => setDialog(() => selectedMember = null),
                        ),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: ChoiceChip(
                          label: const Text('One person'),
                          selected: selectedMember != null,
                          onSelected: (_) => setDialog(() {
                            selectedMember ??= withMissed.first;
                          }),
                        ),
                      ),
                    ],
                  ),
                  if (selectedMember != null) ...[
                    const SizedBox(height: 12),
                    TextField(
                      controller: searchC,
                      autofocus: true,
                      decoration: const InputDecoration(
                        labelText: 'Search by name or email',
                        border: OutlineInputBorder(),
                      ),
                      onChanged: (_) => setDialog(() {}),
                    ),
                    const SizedBox(height: 8),
                    SizedBox(
                      height: 160,
                      child: searchResults.isEmpty
                          ? const Center(child: Text('No matches', style: TextStyle(color: Colors.grey)))
                          : ListView.builder(
                              itemCount: searchResults.length,
                              itemBuilder: (_, i) {
                                final m = searchResults[i];
                                final isSelected = m.email.toLowerCase().trim() == selectedMember?.email.toLowerCase().trim();
                                return ListTile(
                                  dense: true,
                                  selected: isSelected,
                                  title: Text(m.fullName ?? m.username),
                                  subtitle: Text('${m.missed} missed'),
                                  onTap: () => setDialog(() => selectedMember = m),
                                );
                              },
                            ),
                    ),
                  ],
                  const SizedBox(height: 12),
                  TextField(
                    controller: amountC,
                    autofocus: selectedMember == null,
                    keyboardType: TextInputType.number,
                    inputFormatters: [FilteringTextInputFormatter.digitsOnly],
                    decoration: const InputDecoration(
                      labelText: 'How many missed to clear',
                      hintText: 'e.g. 1',
                      border: OutlineInputBorder(),
                    ),
                  ),
                  const SizedBox(height: 6),
                  Text(
                    selectedMember == null
                        ? 'Subtracts this many from every shown member\'s missed count (never below 0).'
                        : 'Subtracts this many from just this member\'s missed count (never below 0).',
                    style: TextStyle(fontSize: 11, color: Colors.grey.shade600),
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
              FilledButton(
                onPressed: () {
                  final n = int.tryParse(amountC.text.trim()) ?? 0;
                  if (n <= 0) {
                    ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content: Text('Enter how many missed to clear.')));
                    return;
                  }
                  Navigator.pop(ctx, {'amount': n, 'member': selectedMember});
                },
                style: FilledButton.styleFrom(backgroundColor: Colors.red),
                child: const Text('Clear'),
              ),
            ],
          );
        },
      ),
    );
    if (result == null) return;
    final amount = result['amount'] as int;
    final UserData? target = result['member'] as UserData?;
    final targets = target == null ? withMissed : [target];
    setState(() {
      for (final m in targets) {
        m.missed = (m.missed - amount).clamp(0, 1 << 30);
      }
    });
    for (final m in targets) {
      unawaited(_persistCivicMemberActivity(m));
    }
    widget.onDataChanged();
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(
        target == null
            ? 'Cleared $amount missed from ${targets.length} member(s).'
            : 'Cleared $amount missed from ${target.fullName ?? target.username}.',
      ),
    ));
  }

  Widget _membersSection(bool isDark) {
    final q = _searchQuery.trim();
    final members = _civicRegistryMembersForDisplay(widget.config, widget.allUsers).where((u) {
      final stateMatch = (u.state).trim().toLowerCase() == _selectedState.trim().toLowerCase();
      final cityMatch = _selectedCity == 'All Cities' || (u.city ?? '').trim() == _selectedCity;
      final roomMatch = _selectedRoom == 'All Rooms' || (u.room ?? '').trim() == _selectedRoom;
      if (!stateMatch || !cityMatch || !roomMatch) return false;
      if (q.isEmpty) return true;
      final raw = NgmyCivicRegistryMembers.findByEmail(widget.config, u.email);
      final nicks = raw == null ? const <String>[] : NgmyCivicRegistryMembers.nicknamesOf(raw);
      return _ngmyCivicMemberSearchScore(q, u, nicks) >= 0.75;
    }).toList();
    if (q.isNotEmpty) {
      members.sort((a, b) {
        final rawA = NgmyCivicRegistryMembers.findByEmail(widget.config, a.email);
        final rawB = NgmyCivicRegistryMembers.findByEmail(widget.config, b.email);
        final nicksA = rawA == null ? const <String>[] : NgmyCivicRegistryMembers.nicknamesOf(rawA);
        final nicksB = rawB == null ? const <String>[] : NgmyCivicRegistryMembers.nicknamesOf(rawB);
        final byScore = _ngmyCivicMemberSearchScore(q, b, nicksB).compareTo(_ngmyCivicMemberSearchScore(q, a, nicksA));
        if (byScore != 0) return byScore;
        return (a.fullName ?? a.username).toLowerCase().compareTo((b.fullName ?? b.username).toLowerCase());
      });
    } else {
      // Newest-enrolled-first — use canonical compare with email + registryId lookup
      // so members without email (registrar manual enroll) still sort correctly.
      Map<String, dynamic>? rawOf(UserData u) {
        final byEmail = NgmyCivicRegistryMembers.findByEmail(widget.config, u.email);
        if (byEmail != null) return byEmail;
        final rid = (u.registryId ?? '').trim();
        if (rid.isEmpty) return null;
        return NgmyCivicRegistryMembers.findByRegistryId(widget.config, rid);
      }

      members.sort((a, b) =>
          NgmyCivicRegistryMembers.compareEnrolledAtDesc(rawOf(a) ?? const {}, rawOf(b) ?? const {}));
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Container(width: double.infinity, padding: const EdgeInsets.all(15), decoration: BoxDecoration(color: Colors.blue.withOpacity(0.05), borderRadius: BorderRadius.circular(15)), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('$_selectedState Community', style: const TextStyle(fontWeight: FontWeight.bold, color: Colors.blue)), Text('Only members registered in $_selectedState are shown', style: const TextStyle(fontSize: 10, color: Colors.blueGrey))])),
        const SizedBox(height: 20),

        TextField(
          onChanged: (v) => setState(() => _searchQuery = v.toLowerCase()),
          decoration: InputDecoration(hintText: 'Search by name, ID, city...', prefixIcon: const Icon(Icons.search), filled: true, fillColor: isDark ? Colors.white10 : Colors.white, border: OutlineInputBorder(borderRadius: BorderRadius.circular(20), borderSide: BorderSide.none)),
        ),
        const SizedBox(height: 20),

        Row(children: [
          const Text('Filter by City:', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 12)),
          const SizedBox(width: 10),
          Expanded(
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 2),
              decoration: BoxDecoration(
                color: isDark ? Colors.white10 : Colors.white,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: isDark ? Colors.white24 : const Color(0xFFD1D5DB)),
              ),
              child: DropdownButton<String>(
                isExpanded: true,
                value: _selectedCity,
                underline: const SizedBox.shrink(),
                items: ['All Cities', ..._citiesForSelectedState()].map((c) => DropdownMenuItem(value: c, child: Text(c, style: const TextStyle(fontSize: 12)))).toList(),
                onChanged: (v) => setState(() => _selectedCity = v!),
              ),
            ),
          ),
        ]),
        const SizedBox(height: 10),
        Row(children: [
          const Text('Filter by Room:', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 12)),
          const SizedBox(width: 10),
          Expanded(
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 2),
              decoration: BoxDecoration(
                color: isDark ? Colors.white10 : Colors.white,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: isDark ? Colors.white24 : const Color(0xFFD1D5DB)),
              ),
              child: DropdownButton<String>(
                isExpanded: true,
                value: _selectedRoom,
                underline: const SizedBox.shrink(),
                items: ['All Rooms', ...widget.config.rooms].map((r) => DropdownMenuItem(value: r, child: Text(r, style: const TextStyle(fontSize: 12)))).toList(),
                onChanged: (v) => setState(() => _selectedRoom = v!),
              ),
            ),
          ),
        ]),

        if (_canManageCitiesForSelectedState()) ...[
          const SizedBox(height: 15),
          ElevatedButton.icon(onPressed: _showManageCitiesRooms, icon: const Icon(Icons.settings, size: 16), label: const Text('Manage Cities & Rooms', style: TextStyle(fontSize: 12, fontWeight: FontWeight.bold)), style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFF6200EE), foregroundColor: Colors.white, minimumSize: const Size(double.infinity, 45), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(15)))),
        ],

        const SizedBox(height: 20),
        Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text('Showing ${members.length} member(s)', style: const TextStyle(color: Colors.grey, fontSize: 12, fontWeight: FontWeight.bold)), if (_canUseRegistrarToolsHere()) InkWell(borderRadius: BorderRadius.circular(10), onTap: () => _confirmClearMissed(members), child: Container(padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5), decoration: BoxDecoration(color: Colors.red.withOpacity(0.1), borderRadius: BorderRadius.circular(10)), child: Row(children: const [Icon(Icons.brush, size: 12, color: Colors.red), SizedBox(width: 5), Text('Clear Missed', style: TextStyle(color: Colors.red, fontSize: 10, fontWeight: FontWeight.bold))])))]),

        const SizedBox(height: 15),
        if (members.isEmpty) const Center(child: Padding(padding: EdgeInsets.all(40), child: Text('No members match your filters.', style: TextStyle(color: Colors.grey))))
        else ...members.map((m) => _memberCard(m, isDark, manageActions: _canUseRegistrarToolsHere())),
      ],
    );
  }

  Future<void> _openMoneyForMember(UserData u) async {
    await _refreshCivicHelpModeAndContributions();
    if (!mounted) return;
    final helpOn = widget.config.helpActiveFor(_selectedState);
    final records = _contributionsForMember(u);
    final active = _activeCampaignContributionForMember(u);
    if (helpOn && active == null) {
      _showContributionDialog(u);
      return;
    }
    if (helpOn && active != null) {
      showModalBottomSheet<void>(
        context: context,
        backgroundColor: Colors.transparent,
        builder: (ctx) {
          final isDark = Theme.of(ctx).brightness == Brightness.dark;
          return Container(
            margin: const EdgeInsets.all(12),
            padding: const EdgeInsets.all(16),
            decoration: BoxDecoration(
              color: isDark ? const Color(0xFF111827) : Colors.white,
              borderRadius: BorderRadius.circular(18),
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                ListTile(
                  leading: const Icon(Icons.add_circle_outline, color: Color(0xFF059669)),
                  title: const Text('Update contribution', style: TextStyle(fontWeight: FontWeight.w800)),
                  subtitle: Text(
                    'Adds to the current \$${formatCurrency(active.amount)} for this help campaign',
                    style: TextStyle(fontSize: 12, color: isDark ? Colors.white60 : Colors.black54),
                  ),
                  onTap: () {
                    Navigator.pop(ctx);
                    _showContributionDialog(u);
                  },
                ),
                ListTile(
                  leading: const Icon(Icons.delete_outline, color: Color(0xFFEF4444)),
                  title: const Text('Remove money record', style: TextStyle(fontWeight: FontWeight.w800)),
                  onTap: () {
                    Navigator.pop(ctx);
                    _showMoneyRecordsManageDialog(u);
                  },
                ),
              ],
            ),
          );
        },
      );
      return;
    }
    if (helpOn && records.isNotEmpty) {
      // Help is on but no row for *this* campaign — still allow add, plus
      // remove for older records.
      showModalBottomSheet<void>(
        context: context,
        backgroundColor: Colors.transparent,
        builder: (ctx) {
          final isDark = Theme.of(ctx).brightness == Brightness.dark;
          return Container(
            margin: const EdgeInsets.all(12),
            padding: const EdgeInsets.all(16),
            decoration: BoxDecoration(
              color: isDark ? const Color(0xFF111827) : Colors.white,
              borderRadius: BorderRadius.circular(18),
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                ListTile(
                  leading: const Icon(Icons.add_circle_outline, color: Color(0xFF059669)),
                  title: const Text('Add contribution', style: TextStyle(fontWeight: FontWeight.w800)),
                  onTap: () {
                    Navigator.pop(ctx);
                    _showContributionDialog(u);
                  },
                ),
                ListTile(
                  leading: const Icon(Icons.delete_outline, color: Color(0xFFEF4444)),
                  title: const Text('Remove money record', style: TextStyle(fontWeight: FontWeight.w800)),
                  onTap: () {
                    Navigator.pop(ctx);
                    _showMoneyRecordsManageDialog(u);
                  },
                ),
              ],
            ),
          );
        },
      );
      return;
    }
    _showMoneyRecordsManageDialog(u);
  }

  Widget _memberCard(UserData u, bool isDark, {bool manageActions = true}) {
    final raw = NgmyCivicRegistryMembers.findByEmail(widget.config, u.email) ??
        NgmyCivicRegistryMembers.findByRegistryId(widget.config, u.registryId ?? '');
    final familyRaw = raw?['familyMembers'];
    final familyCount = familyRaw is num ? familyRaw.toInt() : int.tryParse('${familyRaw ?? ''}') ?? 1;
    final malesRaw = raw?['familyMales'];
    final femalesRaw = raw?['familyFemales'];
    final males = malesRaw is num ? malesRaw.toInt() : int.tryParse('${malesRaw ?? ''}') ?? 0;
    final females = femalesRaw is num ? femalesRaw.toInt() : int.tryParse('${femalesRaw ?? ''}') ?? 0;
    final familyLabel = (males > 0 || females > 0)
        ? '$familyCount family · $males M / $females F'
        : '$familyCount family member${familyCount == 1 ? '' : 's'}';
    final showFixDot = manageActions && ngmyMemberHasProfileFlags(raw);
    return Stack(
      clipBehavior: Clip.none,
      children: [
        Container(
          margin: const EdgeInsets.only(bottom: 15),
          padding: const EdgeInsets.all(20),
          decoration: BoxDecoration(color: isDark ? const Color(0xFF1E1E1E) : Colors.white, borderRadius: BorderRadius.circular(25), boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.03), blurRadius: 10)]),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(children: [
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Row(children: [
                    Text(u.fullName ?? u.username, style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 16)),
                    const SizedBox(width: 8),
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                      decoration: BoxDecoration(color: _statusColorForMissed(u.missed), borderRadius: BorderRadius.circular(10)),
                      child: Text(_statusLabelForMissed(u.missed), style: const TextStyle(color: Colors.white, fontSize: 9, fontWeight: FontWeight.bold)),
                    ),
                  ]),
                  Text(u.registryId ?? 'PENDING ID', style: const TextStyle(color: Colors.blue, fontWeight: FontWeight.bold, fontSize: 13)),
                  Text('ID: ${u.registryId ?? "N/A"}', style: const TextStyle(color: Colors.grey, fontSize: 10)),
                ]),
                const Spacer(),
                Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
                  Text('${u.helps} helps', style: const TextStyle(color: Colors.green, fontWeight: FontWeight.bold, fontSize: 12)),
                  Text('${u.missed} missed', style: const TextStyle(color: Colors.red, fontSize: 10)),
                ]),
              ]),
              const SizedBox(height: 15),
              _memberInfo(Icons.location_on, u.city ?? 'Not specified', Colors.redAccent),
              _memberInfo(Icons.home_work_rounded, u.room ?? 'No room assigned', Colors.orange),
              _memberInfo(Icons.phone_android_rounded, u.phone, Colors.black54),
              _memberInfo(Icons.email_outlined, u.email, Colors.blueAccent),
              _memberInfo(
                Icons.family_restroom_rounded,
                familyLabel,
                Colors.teal,
              ),

              const SizedBox(height: 20),
              Row(
                mainAxisAlignment: manageActions ? MainAxisAlignment.spaceBetween : MainAxisAlignment.center,
                children: [
                  _mBtn(Icons.visibility_outlined, 'View', Colors.indigo, () => _showMemberProfile(u)),
                  if (manageActions) ...[
                    _mBtn(Icons.monetization_on_outlined, 'Money', Colors.green, () => unawaited(_openMoneyForMember(u))),
                    _mBtn(Icons.warning_amber_rounded, 'Claim', Colors.orange, () => _showClaimDialog(u)),
                    _mBtn(Icons.undo_rounded, 'Clean', Colors.grey.shade200, () => _showResolveClaimDialog(u), textColor: Colors.grey),
                    _mBtn(Icons.delete_outline_rounded, '', Colors.red, () async {
                      final adminHard = _isGlobalCivicRegistryAdmin();
                      final confirm = await showNgmyLightConfirm(
                        context,
                        title: adminHard ? 'Permanently delete member?' : 'Remove this member?',
                        message: adminHard
                            ? 'Admin delete is permanent. ${u.fullName ?? u.username} will be removed from the registry right away and cannot be recovered.'
                            : 'This hides ${u.fullName ?? u.username} from members, search, and rankings for 7 days. Recover them from the green verified icon next to Authorized Registrar before then.',
                        cancelLabel: 'Keep',
                        confirmLabel: adminHard ? 'Delete forever' : 'Remove',
                        icon: Icons.person_remove_rounded,
                        destructive: true,
                      );
                      if (confirm != true) return;
                      setState(() {});
                      await _removeRegistryMember(u, permanent: adminHard);
                      if (mounted) setState(() {});
                      widget.onDataChanged();
                    }),
                  ],
                ],
              ),
            ],
          ),
        ),
        if (showFixDot)
          Positioned(
            top: 6,
            right: 10,
            child: Container(
              width: 10,
              height: 10,
              decoration: BoxDecoration(
                color: const Color(0xFFE53935),
                shape: BoxShape.circle,
                border: Border.all(color: isDark ? const Color(0xFF1E1E1E) : Colors.white, width: 1.5),
                boxShadow: [
                  BoxShadow(color: const Color(0xFFE53935).withValues(alpha: 0.45), blurRadius: 6),
                ],
              ),
            ),
          ),
      ],
    );
  }

