      color: _storePurple,
      onRefresh: () async {
        await _refreshStoreOrdersFromConfig();
        if (mounted) setState(() {});
      },
      child: CustomScrollView(
        slivers: [
          if (awaitingReview > 0)
            SliverToBoxAdapter(
              child: Padding(
                padding: EdgeInsets.fromLTRB(14, topPad, 14, 4),
