  void _toggleListingLike(Map<String, dynamic> listing) {
    final id = (listing['id'] ?? '').toString();
    if (id.isEmpty) return;
    final idx = _listings.indexWhere((l) => (l['id'] ?? '').toString() == id);
    if (idx < 0) return;
    final liked = List<String>.from((_listings[idx]['likedBy'] as List?)?.map((e) => e.toString()) ?? []);
    final me = widget.user.email.toLowerCase().trim();
    if (liked.contains(me)) {
      liked.remove(me);
      _likedListingIds.remove(id);
    } else {
      liked.add(me);
      _likedListingIds.add(id);
    }
    _listings[idx]['likedBy'] = liked;
    unawaited(_upsertStoreListingRowSafe(_listings[idx]));
    final sig = _storeListingsSignature(_listings);
    if (sig != _listingsSig) {
      _listingsSig = sig;
      setState(() {});
    }
  }

  Future<String> _sellerPhoneForListing(Map<String, dynamic> listing) async {
    final email = (listing['sellerEmail'] ?? '').toString().toLowerCase().trim();
    if (email.isNotEmpty) {
      var idx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
      if (idx < 0) {
        await _resolveStoreUserIndex(email);
        idx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
      }
      if (idx >= 0) {
        final profilePhone = widget.allUsers[idx].phone.trim();
        if (profilePhone.isNotEmpty) return profilePhone;
      }
    }
    return (listing['sellerPhone'] ?? '').toString().trim();
  }

  String _sellerPhoneFromListing(Map<String, dynamic> listing) {
    final email = (listing['sellerEmail'] ?? '').toString().toLowerCase().trim();
    if (email.isNotEmpty) {
      final idx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
      if (idx >= 0) {
        final profilePhone = widget.allUsers[idx].phone.trim();
        if (profilePhone.isNotEmpty) return profilePhone;
      }
    }
    return (listing['sellerPhone'] ?? '').toString().trim();
  }

  Future<void> _callSellerPhone(String phone) async {
    final digits = phone.replaceAll(RegExp(r'[^\d+]'), '');
    if (digits.isEmpty) return;
    final uri = Uri.parse('tel:$digits');
    if (await canLaunchUrl(uri)) {
      await launchUrl(uri, mode: LaunchMode.externalApplication);
    } else if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Could not open the phone dialer.')));
    }
  }

  Future<void> _emailSeller(String email) async {
    final trimmed = email.trim();
    if (trimmed.isEmpty) return;
    final uri = Uri.parse('mailto:$trimmed');
    if (await canLaunchUrl(uri)) {
      await launchUrl(uri, mode: LaunchMode.externalApplication);
    } else {
      await Clipboard.setData(ClipboardData(text: trimmed));
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Seller email copied.')));
    }
  }

