  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final topInset = MediaQuery.paddingOf(context).top + 68;
    final searchPanelTop = MediaQuery.paddingOf(context).top + 8 + 64 + 6;
    final mediaFeed = _visibleMediaPosts(
      widget.allMedia,
      extraFilter: (m) => !_isExpired(m),
    )..sort((a, b) => b.timestamp.compareTo(a.timestamp));
    final savedPosts = _savedPostsForUser();
    final hasSavedPosts = savedPosts.isNotEmpty;
    return Scaffold(
      backgroundColor: isDark ? const Color(0xFF121212) : const Color(0xFFF3F7FF),
      body: Stack(
        clipBehavior: Clip.none,
        children: [
          Positioned.fill(
            child: mediaFeed.isEmpty
                ? _buildMediaEmptyState(isDark)
                : ListView.builder(
                    padding: EdgeInsets.fromLTRB(12, topInset, 12, 120),
                    cacheExtent: 400,
                    addAutomaticKeepAlives: false,
                    itemCount: mediaFeed.length,
                    itemBuilder: (context, index) {
                      final post = mediaFeed[index];
                      final highlight = widget.highlightPostId == post.id;
                      return VideoPostWidget(
                        key: highlight ? _postKey(post.id) : ValueKey(post.id),
                        post: post,
                      currentUser: widget.user,
                      allUsers: widget.allUsers,
                      onChanged: widget.onDataChanged,
                      onSyncPost: widget.onSyncMediaPost,
                      onDelete: () => _deletePost(mediaFeed[index]),
                      onMissingStorage: _removeBrokenPost,
                      onOpenProfile: _openMediaProfile,
                      onPayoutWatchReward: _payoutWatchReward,
                    );
                    },
                  ),
          ),
          Positioned(
            top: 0,
            left: 0,
            right: 0,
            child: SafeArea(
              bottom: false,
              child: Padding(
                padding: const EdgeInsets.fromLTRB(15, 8, 15, 0),
                child: ngmyClipBackdrop(
                  borderRadius: BorderRadius.circular(35),
                  child: Container(
                    height: 64,
                    padding: const EdgeInsets.symmetric(horizontal: 12),
                    decoration: BoxDecoration(
                      color: Theme.of(context).colorScheme.surface,
                      borderRadius: BorderRadius.circular(35),
                      border: Border.all(color: Colors.white.withOpacity(0.12)),
                      boxShadow: [
                        BoxShadow(
                          color: Colors.black.withOpacity(0.12),
                          blurRadius: 12,
                          offset: const Offset(0, 4),
                        ),
                      ],
                    ),
                    child: Row(
                        children: [
                          Padding(
                            padding: const EdgeInsets.only(left: 4),
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                if (widget.showBackButton)
                                  _mediaHubHeaderIcon(
                                    isDark: isDark,
                                    icon: Icons.arrow_back_ios_new_rounded,
                                    onTap: () => NgmyNavigator.pop(context),
                                  ),
                                if (!widget.showBackButton && widget.user.isAdmin)
                                  _mediaHubHeaderIcon(
                                    isDark: isDark,
                                    icon: Icons.add_circle_outline_rounded,
                                    onTap: _showPostDialog,
                                  ),
                                if (widget.showBackButton && widget.user.isAdmin) ...[
                                  const SizedBox(width: 6),
                                  _mediaHubHeaderIcon(
                                    isDark: isDark,
                                    icon: Icons.add_circle_outline_rounded,
                                    onTap: _showPostDialog,
                                  ),
                                ],
                                if (!widget.showBackButton && !widget.user.isAdmin)
                                  const SizedBox(width: 40),
                              ],
                            ),
                          ),
                          Expanded(
                            child: AnimatedSwitcher(
                              duration: const Duration(milliseconds: 260),
                              switchInCurve: Curves.easeOutCubic,
                              switchOutCurve: Curves.easeInCubic,
