  bool get _canOpenWorld => config.communicateEnabled || user.isAdmin;

  @override
  Widget build(BuildContext context) {
    if (!_canOpenWorld) {
      return Scaffold(
        backgroundColor: const Color(0xFF0A0612),
        body: SafeArea(
          child: Center(
            child: Padding(
              padding: const EdgeInsets.all(24),
              child: Column(
                mainAxisSize: MainAxisSize.min,
