class _NgmyFullscreenVideoPage extends StatefulWidget {
  final String url;
  final double aspectRatio;
  const _NgmyFullscreenVideoPage({required this.url, required this.aspectRatio});

  @override
  State<_NgmyFullscreenVideoPage> createState() => _NgmyFullscreenVideoPageState();
}

class _NgmyFullscreenVideoPageState extends State<_NgmyFullscreenVideoPage> {
  VideoPlayerController? _controller;
  bool _ready = false;
  static const _seekStep = Duration(seconds: 10);

  @override
  void initState() {
    super.initState();
    _init();
  }

  Future<void> _seekRelative(Duration delta) async {
    final c = _controller;
    if (c == null || !c.value.isInitialized) return;
    final dur = c.value.duration;
    var target = c.value.position + delta;
    if (target < Duration.zero) target = Duration.zero;
    if (dur.inMilliseconds > 0 && target > dur) target = dur;
    await c.seekTo(target);
    if (mounted) setState(() {});
  }

  Future<void> _init() async {
    try {
      final c = VideoPlayerController.networkUrl(
        Uri.parse(widget.url),
        videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
      );
      await c.initialize();
      c.setLooping(true);
      await c.play();
      if (!mounted) return;
      setState(() {
        _controller = c;
        _ready = true;
      });
    } catch (e) {
      debugPrint('[media] fullscreen video: $e');
    }
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      body: Stack(
        fit: StackFit.expand,
        children: [
          if (_ready && _controller != null)
            Center(
              child: AspectRatio(
                aspectRatio: _controller!.value.aspectRatio > 0 ? _controller!.value.aspectRatio : widget.aspectRatio,
                child: VideoPlayer(_controller!),
              ),
            )
          else
            const Center(child: CircularProgressIndicator(color: Colors.white)),
          SafeArea(
            child: Align(
              alignment: Alignment.topLeft,
              child: IconButton(
                icon: const Icon(Icons.close_rounded, color: Colors.white, size: 28),
                onPressed: () => Navigator.pop(context),
              ),
            ),
          ),
          if (_ready && _controller != null)
            Align(
              alignment: Alignment.bottomCenter,
              child: Padding(
                padding: const EdgeInsets.only(bottom: 28),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    IconButton(
                      iconSize: 44,
                      color: Colors.white,
                      icon: const Icon(Icons.replay_10_rounded),
                      onPressed: () => _seekRelative(-_seekStep),
                    ),
                    IconButton(
                      iconSize: 56,
                      color: Colors.white,
                      icon: Icon(_controller!.value.isPlaying ? Icons.pause_circle_filled : Icons.play_circle_filled),
                      onPressed: () {
                        setState(() {
                          _controller!.value.isPlaying ? _controller!.pause() : _controller!.play();
                        });
                      },
                    ),
                    IconButton(
                      iconSize: 44,
                      color: Colors.white,
                      icon: const Icon(Icons.forward_10_rounded),
                      onPressed: () => _seekRelative(_seekStep),
                    ),
                  ],
                ),
              ),
            ),
        ],
      ),
    );
  }
}

class _NgmyFullscreenImagePage extends StatelessWidget {
  final String url;
  const _NgmyFullscreenImagePage({required this.url});

  @override
  Widget build(BuildContext context) {
    Widget image;
    if (url.startsWith('data:image')) {
      try {
        image = Image.memory(base64Decode(url.split(',').last), fit: BoxFit.contain);
      } catch (_) {
        image = const Icon(Icons.broken_image_outlined, color: Colors.white54, size: 48);
      }
    } else if (url.startsWith('http')) {
      image = Image.network(url, fit: BoxFit.contain);
    } else if (!kIsWeb) {
      image = Image.file(File(url), fit: BoxFit.contain);
    } else {
      image = const Icon(Icons.image_not_supported_outlined, color: Colors.white54, size: 48);
    }
    return Scaffold(
      backgroundColor: Colors.black,
      body: Stack(
        children: [
          InteractiveViewer(minScale: 0.5, maxScale: 4, child: Center(child: image)),
          SafeArea(
            child: IconButton(
              icon: const Icon(Icons.close_rounded, color: Colors.white, size: 28),
              onPressed: () => Navigator.pop(context),
            ),
          ),
        ],
      ),
    );
  }
}

class _NgmyInstagramCommentBubbleIcon extends StatelessWidget {
  final double size;
  final Color color;

  const _NgmyInstagramCommentBubbleIcon({this.size = 24, required this.color});

  @override
  Widget build(BuildContext context) {
    return CustomPaint(
      size: Size(size, size),
      painter: _NgmyInstagramCommentBubblePainter(color: color),
    );
  }
}

class _NgmyInstagramCommentBubblePainter extends CustomPainter {
  final Color color;

  _NgmyInstagramCommentBubblePainter({required this.color});

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = size.width * 0.075
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;

    final body = RRect.fromRectAndRadius(
      Rect.fromLTWH(size.width * 0.05, size.height * 0.06, size.width * 0.9, size.height * 0.68),
      Radius.circular(size.width * 0.38),
    );
    canvas.drawRRect(body, paint);

    final tail = Path()
      ..moveTo(size.width * 0.20, size.height * 0.72)
      ..lineTo(size.width * 0.15, size.height * 0.80)
      ..lineTo(size.width * 0.27, size.height * 0.72);
    canvas.drawPath(tail, paint);
  }

  @override
  bool shouldRepaint(covariant _NgmyInstagramCommentBubblePainter oldDelegate) =>
      oldDelegate.color != color;
}

