class VideoPostWidget extends StatefulWidget {
  final MediaPost post;
  final UserData currentUser;
  final List<UserData> allUsers;
  final VoidCallback onChanged;
  final VoidCallback onDelete;
  final void Function(String userEmail)? onOpenProfile;
  final Future<bool> Function(MediaPost post)? onPayoutWatchReward;
  final Future<bool> Function(MediaPost post)? onSyncPost;
  final Future<void> Function(MediaPost post)? onMissingStorage;
  final void Function(AppTransaction)? onAddTransaction;
  const VideoPostWidget({
    super.key,
    required this.post,
    required this.currentUser,
    required this.allUsers,
    required this.onChanged,
    required this.onDelete,
    this.onOpenProfile,
    this.onPayoutWatchReward,
    this.onSyncPost,
    this.onMissingStorage,
    this.onAddTransaction,
  });

  @override
  State<VideoPostWidget> createState() => _VideoPostWidgetState();
}

class _VideoPostWidgetState extends State<VideoPostWidget> with WidgetsBindingObserver {
  VideoPlayerController? _controller;
  bool _isInitialized = false;
  bool _hasError = false;
  String _errorText = 'Unable to load media.';
  String? _resolvedMediaUrl;
  ImageProvider? _authorImage;
  bool _loadingMedia = false;
  bool _showHeartBurst = false;
  bool _previewEnded = false;
  bool _unlockedFullVideo = false;

  bool get _isImagePost => _mediaPostIsImage(widget.post);
  NgmyMediaMonetization get _mon => widget.post.monetization;

  Future<void> _initializePlayer(String resolvedUrl) async {
    if (_controller != null) {
      try {
        await _controller!.dispose();
      } catch (_) {}
      _controller = null;
    }
    try {
      if (resolvedUrl.startsWith('http')) {
        _controller = VideoPlayerController.networkUrl(
          Uri.parse(resolvedUrl),
          videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
        );
      } else if (!kIsWeb) {
        final file = File(resolvedUrl);
        if (!await file.exists()) throw Exception('File not found at $resolvedUrl');
        _controller = VideoPlayerController.file(file);
      } else {
        throw Exception('Invalid path for web.');
      }

      await _controller!.initialize().timeout(const Duration(seconds: 30));
      if (!mounted) return;
      if (_mon.hasPreviewLimit && !_unlockedFullVideo) {
        _controller!.setLooping(false);
        _controller!.addListener(_onVideoTick);
      } else {
        _controller!.setLooping(true);
      }
      await _controller!.pause();
      final ar = _controller!.value.aspectRatio;
      if (ar > 0) {
        widget.post.mediaAspectRatio = _clampMediaAspectRatio(ar);
        unawaited(_upsertMediaRowSafe(Map<String, dynamic>.from(widget.post.toJson())));
      }
      setState(() {
        _isInitialized = true;
        _hasError = false;
        _loadingMedia = false;
      });
    } catch (e) {
      debugPrint('Media init error ($resolvedUrl): $e');
      if (!mounted) return;
      setState(() {
        _hasError = true;
        _loadingMedia = false;
        _errorText = 'Media loading failed. Check your internet.';
      });
    }
  }

  Future<void> _prepareMedia({bool loadVideo = false}) async {
    if (!mounted) return;
    if (!_isImagePost && !loadVideo) return;

    setState(() {
      _loadingMedia = true;
      _hasError = false;
    });

    try {
      final avatar = await _profileImageProviderForEmail(widget.post.userEmail);
      if (mounted) setState(() => _authorImage = avatar);

      final resolved = await _resolveSupabaseStorageUrlResilient(widget.post.videoUrl);
      if (!mounted) return;
      if (resolved.isEmpty && widget.post.videoUrl.startsWith('supabase://')) {
        unawaited(widget.onMissingStorage?.call(widget.post));
        setState(() {
          _hasError = true;
          _loadingMedia = false;
          _errorText = 'This post was removed.';
        });
        return;
      }
      _resolvedMediaUrl = resolved;

      if (_isImagePost) {
        setState(() => _loadingMedia = false);
        return;
      }
      
      // 2. Initialize video player
      await _initializePlayer(resolved);
    } catch (e) {
      debugPrint('Media preparation failed: $e');
      if (mounted) {
        setState(() {
          _hasError = true;
          _loadingMedia = false;
        });
      }
    }
  }

  void _onVideoTick() {
    if (_controller == null || !_isInitialized || _unlockedFullVideo || !_mon.hasPreviewLimit) return;
    final pos = _controller!.value.position;
    if (pos.inSeconds >= _mon.previewSeconds) {
      _controller!.removeListener(_onVideoTick);
      _controller!.pause();
      if (mounted) setState(() => _previewEnded = true);
    }
  }

  static const _videoSeekStep = Duration(seconds: 10);

  Future<void> _seekVideoRelative(Duration delta) async {
    final c = _controller;
    if (c == null || !_isInitialized) return;
    final dur = c.value.duration;
    var target = c.value.position + delta;
    if (target < Duration.zero) target = Duration.zero;
    if (dur.inMilliseconds > 0 && target > dur) target = dur;
    if (_mon.hasPreviewLimit && !_unlockedFullVideo && target.inSeconds > _mon.previewSeconds) {
      target = Duration(seconds: _mon.previewSeconds);
    }
    await c.seekTo(target);
    if (mounted) setState(() {});
  }

  Widget _videoSeekButton({required IconData icon, required VoidCallback onPressed}) {
    return Material(
      color: Colors.black.withValues(alpha: 0.5),
      shape: const CircleBorder(),
      child: InkWell(
        customBorder: const CircleBorder(),
        onTap: onPressed,
        child: Padding(
          padding: const EdgeInsets.all(8),
          child: Icon(icon, color: Colors.white, size: 30),
        ),
      ),
    );
  }

  Widget _inlineVideoSeekControls() {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        _videoSeekButton(
          icon: Icons.replay_10_rounded,
          onPressed: () => _seekVideoRelative(-_videoSeekStep),
        ),
        const SizedBox(width: 16),
        _videoSeekButton(
          icon: Icons.forward_10_rounded,
          onPressed: () => _seekVideoRelative(_videoSeekStep),
        ),
      ],
    );
  }

  Future<void> _openExternalLink({bool startWatchSession = false}) async {
    final url = _mon.externalLink.trim();
    if (url.isEmpty) return;
    var uri = Uri.tryParse(url);
    if (uri == null) return;
    if (!uri.hasScheme) uri = Uri.parse('https://$url');

    if (startWatchSession && _mon.hasWatchReward && !_isOwner && !_mon.hasClaimed(widget.currentUser.email)) {
      await NgmyMediaRewardTracker.startSession(widget.post.id, widget.currentUser.email);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Stay on the link for ${_mon.watchRequiredSeconds}s, then return here to earn \$${formatCurrency(_mon.watchReward)}.'),
            duration: const Duration(seconds: 5),
          ),
        );
      }
    }

    if (await canLaunchUrl(uri)) {
      await launchUrl(uri, mode: LaunchMode.externalApplication);
    }
  }

  Future<void> _payToContinueVideo() async {
    final price = _mon.continuePrice;
    if (price <= 0) return;
    if (widget.currentUser.accountBalance + 0.001 < price) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Need \$${formatCurrency(price)} NGMY balance to continue.')),
        );
      }
      return;
    }
    final idx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == widget.currentUser.email.toLowerCase().trim());
    if (idx < 0) return;
    final ownerIdx = widget.allUsers.indexWhere(
      (u) => u.email.toLowerCase().trim() == widget.post.userEmail.toLowerCase().trim(),
    );
    final ts = DateTime.now().microsecondsSinceEpoch.toString();
    final ownerEmail = widget.post.userEmail.toLowerCase().trim();
    widget.onAddTransaction?.call(
      AppTransaction(
        id: 'video_unlock_buy_$ts',
        userEmail: widget.currentUser.email,
        amount: price,
        type: TransactionType.adminRemove,
        method: PaymentMethod.system,
        sourceDetails: 'Video unlock: ${widget.post.caption.isNotEmpty ? widget.post.caption : widget.post.id}',
        status: TransactionStatus.approved,
        timestamp: DateTime.now(),
      ),
    );
    if (ownerIdx >= 0 && ownerEmail != widget.currentUser.email.toLowerCase().trim()) {
      widget.onAddTransaction?.call(
        AppTransaction(
          id: 'video_unlock_sale_$ts',
          userEmail: widget.allUsers[ownerIdx].email,
          amount: price,
          type: TransactionType.reimbursement,
          method: PaymentMethod.system,
          sourceDetails: 'Video unlock sale: ${widget.post.caption.isNotEmpty ? widget.post.caption : widget.post.id}',
          status: TransactionStatus.approved,
          timestamp: DateTime.now(),
        ),
      );
    }
    setState(() {
      _unlockedFullVideo = true;
      _previewEnded = false;
    });
    _controller?.removeListener(_onVideoTick);
    _controller?.setLooping(true);
    await _controller?.play();
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Unlocked full video for \$${formatCurrency(price)}.')),
      );
    }
    widget.onChanged();
  }

  Future<void> _tryClaimWatchReward() async {
    if (!_mon.hasWatchReward || _isOwner || _mon.hasClaimed(widget.currentUser.email)) return;
    final elapsed = await NgmyMediaRewardTracker.elapsedSeconds(widget.post.id, widget.currentUser.email);
    if (elapsed == null || elapsed < _mon.watchRequiredSeconds) return;
    await widget.onPayoutWatchReward?.call(widget.post);
  }

  Future<void> _handleLinkAction() async {
    final mon = _mon;
    if (!mon.hasLink) return;
    if (mon.hasWatchReward && !_isOwner && !mon.hasClaimed(widget.currentUser.email)) {
      final ok = await showDialog<bool>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Text('Earn by watching'),
          content: Text(
            'Open the link and stay for ${mon.watchRequiredSeconds} seconds. When you return to NGMY you earn \$${formatCurrency(mon.watchReward)}.',
          ),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
            FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Open link')),
          ],
        ),
      );
      if (ok != true) return;
      await _openExternalLink(startWatchSession: true);
      return;
    }
    await _openExternalLink();
  }

  Widget _previewPaywallOverlay() {
    final mon = _mon;
    return Container(
      color: Colors.black.withValues(alpha: 0.82),
      padding: const EdgeInsets.all(16),
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          const Icon(Icons.lock_clock_rounded, color: Colors.white, size: 40),
          const SizedBox(height: 10),
          Text(
            mon.hasPreviewLimit ? 'Preview ended (${mon.previewSeconds}s)' : 'Continue watching',
            textAlign: TextAlign.center,
            style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w900, fontSize: 16),
          ),
          const SizedBox(height: 8),
          const Text(
            'Open the link or pay to keep watching.',
            textAlign: TextAlign.center,
            style: TextStyle(color: Colors.white70, fontSize: 12),
          ),
          const SizedBox(height: 14),
          if (mon.hasLink)
            SizedBox(
              width: double.infinity,
              child: FilledButton.icon(
                onPressed: () => _handleLinkAction(),
                icon: const Icon(Icons.open_in_new_rounded),
                label: const Text('Open link'),
                style: FilledButton.styleFrom(backgroundColor: const Color(0xFF8B5CF6)),
              ),
            ),
          if (mon.hasPayToContinue) ...[
            const SizedBox(height: 8),
            SizedBox(
              width: double.infinity,
              child: FilledButton.icon(
                onPressed: _payToContinueVideo,
                icon: const Icon(Icons.payments_rounded),
                label: Text('Pay \$${formatCurrency(mon.continuePrice)} to continue'),
                style: FilledButton.styleFrom(backgroundColor: const Color(0xFF00B25A)),
              ),
            ),
          ],
        ],
      ),
    );
  }

  double _effectiveAspectRatio(bool isVideo) {
    if (widget.post.mediaAspectRatio != null && widget.post.mediaAspectRatio! > 0) {
      return _clampMediaAspectRatio(widget.post.mediaAspectRatio!);
    }
    if (isVideo && _isInitialized && _controller != null && _controller!.value.aspectRatio > 0) {
      return _clampMediaAspectRatio(_controller!.value.aspectRatio);
    }
    return 1.0;
  }

  Widget _buildMediaFrame(bool isVideo, bool isImage) {
    final ratio = _effectiveAspectRatio(isVideo);
    final maxH = MediaQuery.of(context).size.height * 0.68;
    return LayoutBuilder(
      builder: (context, constraints) {
        final w = constraints.maxWidth;
        final naturalH = w / ratio;
        final h = naturalH > maxH ? maxH : naturalH;
        return SizedBox(
          width: w,
          height: h.clamp(72.0, maxH),
          child: Stack(
            alignment: Alignment.center,
            children: [
              ClipRRect(
                borderRadius: BorderRadius.circular(16),
                child: Container(
                  color: Colors.black,
                  width: double.infinity,
                  height: double.infinity,
                  child: _loadingMedia
                      ? const Center(child: CircularProgressIndicator())
                      : isVideo
                      ? (_hasError
                          ? Center(
                              child: Padding(
                                padding: const EdgeInsets.all(16),
                                child: Text(_errorText, style: const TextStyle(color: Colors.white70, fontSize: 12), textAlign: TextAlign.center),
                              ),
                            )
                          : (_isInitialized && _controller != null)
                              ? FittedBox(
                                  fit: BoxFit.cover,
                                  clipBehavior: Clip.hardEdge,
                                  child: SizedBox(
                                    width: _controller!.value.size.width,
                                    height: _controller!.value.size.height,
                                    child: VideoPlayer(_controller!),
                                  ),
                                )
                              : const Center(child: CircularProgressIndicator()))
                      : _buildImageContent(),
                ),
              ),
              if (isVideo && _previewEnded && !_unlockedFullVideo) _previewPaywallOverlay(),
              if (isVideo && _isInitialized && _controller != null && !_controller!.value.isPlaying && !_previewEnded)
                Container(
                  padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(color: Colors.black.withOpacity(0.4), shape: BoxShape.circle),
                  child: const Icon(Icons.play_arrow_rounded, color: Colors.white, size: 40),
                ),
              if (isImage && _mon.hasLink)
                Positioned(
                  right: 10,
                  bottom: 10,
                  child: Material(
                    color: const Color(0xFF8B5CF6),
                    borderRadius: BorderRadius.circular(20),
                    child: InkWell(
                      onTap: _handleLinkAction,
                      borderRadius: BorderRadius.circular(20),
                      child: const Padding(
                        padding: EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Icon(Icons.link_rounded, color: Colors.white, size: 18),
                            SizedBox(width: 6),
                            Text('Open link', style: TextStyle(color: Colors.white, fontWeight: FontWeight.w800, fontSize: 12)),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              if (_showHeartBurst)
                TweenAnimationBuilder<double>(
                  tween: Tween(begin: 0.4, end: 1.3),
                  duration: const Duration(milliseconds: 700),
                  curve: Curves.easeOutBack,
                  builder: (context, scale, child) => Opacity(
                    opacity: _showHeartBurst ? (1.0 - (scale - 0.4) / 1.1).clamp(0.0, 1.0) : 0,
                    child: Transform.scale(scale: scale, child: child),
                  ),
                  child: const Icon(Icons.favorite_rounded, color: Color(0xFFFF3B8A), size: 96),
                ),
            ],
          ),
        );
      },
    );
  }

  Widget _buildImageContent() {
    final resolved = _resolvedMediaUrl ?? widget.post.videoUrl;
    if (_hasError) {
      return Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(Icons.broken_image_outlined, color: Colors.white.withOpacity(0.7), size: 42),
            const SizedBox(height: 8),
            Text(_errorText, style: const TextStyle(color: Colors.white70, fontSize: 12), textAlign: TextAlign.center),
          ],
        ),
      );
    }
    if (resolved.startsWith('data:image')) {
      try {
        return Image.memory(base64Decode(resolved.split(',').last), fit: BoxFit.cover, width: double.infinity, height: double.infinity);
      } catch (_) {
        return Center(child: Icon(Icons.broken_image_outlined, color: Colors.white.withOpacity(0.7), size: 42));
      }
    }
    if (resolved.startsWith('http')) {
      return Image.network(
        resolved,
        fit: BoxFit.cover,
        width: double.infinity,
        height: double.infinity,
        gaplessPlayback: true,
        loadingBuilder: (_, child, progress) {
          if (progress == null) return child;
          return const Center(child: CircularProgressIndicator());
        },
        errorBuilder: (_, __, ___) => Center(
          child: Icon(Icons.broken_image_outlined, color: Colors.white.withOpacity(0.7), size: 42),
        ),
      );
    }
    if (!kIsWeb) {
      return Image.file(
        File(resolved),
        fit: BoxFit.cover,
        width: double.infinity,
        height: double.infinity,
        errorBuilder: (_, __, ___) => Center(
          child: Icon(Icons.broken_image_outlined, color: Colors.white.withOpacity(0.7), size: 42),
        ),
      );
    }
    return Center(
      child: Icon(Icons.image_not_supported_outlined, color: Colors.white.withOpacity(0.7), size: 42),
    );
  }

  Future<ImageProvider?> _profileImageProviderForEmail(String email) async {
    final u = widget.allUsers.firstWhere(
      (x) => x.email.toLowerCase().trim() == email.toLowerCase().trim(),
      orElse: () => UserData(email: email),
    );
    final path = u.profilePicturePath;
    if (path == null || path.trim().isEmpty) return null;
    if (path.startsWith('data:image')) {
      try {
        return MemoryImage(base64Decode(path.split(',').last));
      } catch (_) {
        return null;
      }
    }
    if (path.startsWith('http://') || path.startsWith('https://')) {
      return NetworkImage(path);
    }
    if (!kIsWeb) {
      final f = File(path);
      if (await f.exists()) return FileImage(f);
    }
    return null;
  }

  bool get _liked => _ngmyMediaLikedByContains(widget.post.likedBy, widget.currentUser.email);
  bool get _saved => widget.post.savedBy.any(
        (e) => _ngmyMediaActorKey(e) == _ngmyMediaActorKey(widget.currentUser.email),
      );
  bool get _isOwner => widget.currentUser.email.toLowerCase().trim() == widget.post.userEmail.toLowerCase().trim();

  String get _displayUsername => _mediaPostDisplayName(widget.post, widget.allUsers);

  Future<void> _persistPostChange() async {
    widget.post.likes = widget.post.likedBy.length;
    final ok = widget.onSyncPost != null
        ? await widget.onSyncPost!(widget.post)
        : await _upsertMediaSocialFields(widget.post);
    widget.onChanged();
    if (!mounted) return;
    if (!ok) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Could not sync like or comment. Check your connection and try again.')),
      );
    }
  }

  Future<void> _toggleLike() async {
    setState(() {
      if (_liked) {
        _ngmyMediaRemoveLike(widget.post.likedBy, widget.currentUser.email);
      } else {
        _ngmyMediaAddLike(widget.post.likedBy, widget.currentUser.email);
      }
      widget.post.likes = widget.post.likedBy.length;
    });
    await _persistPostChange();
  }

  Future<void> _toggleSave() async {
    final key = _ngmyMediaActorKey(widget.currentUser.email);
    setState(() {
      if (_saved) {
        widget.post.savedBy.removeWhere((e) => _ngmyMediaActorKey(e) == key);
      } else {
        widget.post.savedBy.removeWhere((e) => _ngmyMediaActorKey(e) == key);
        widget.post.savedBy.add(key);
      }
    });
    await _persistPostChange();
  }

  Future<void> _launchMediaShareUrl(Uri uri) async {
    if (await canLaunchUrl(uri)) {
      await launchUrl(uri, mode: LaunchMode.externalApplication);
    }
  }

  Future<void> _recordShare() async {
    final email = _ngmyMediaActorKey(widget.currentUser.email);
    var changed = false;
    setState(() {
      if (widget.currentUser.isAdmin) {
        widget.post.shareCount += 1;
        changed = true;
      } else if (!_ngmyMediaSharedByContains(widget.post.sharedBy, email)) {
        widget.post.sharedBy.add(email);
        widget.post.shareCount += 1;
        changed = true;
      }
    });
    if (changed) await _persistPostChange();
  }

  Future<void> _sharePost() async {
    if (!mounted) return;
    final link = ngmyMediaPostShareUrl(widget.post.id);
    final caption = widget.post.caption.trim();
    final shareText = caption.isEmpty ? 'Check out this post on NGMY Media' : caption;
    final fullText = '$shareText\n$link';

    await showModalBottomSheet<void>(
      context: context,
      useRootNavigator: true,
      backgroundColor: Theme.of(context).colorScheme.surface,
      shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(20))),
      builder: (ctx) {
        // Run share/launch while the tap gesture is still active (required on web).
        Future<void> runThenClose(Future<void> Function() action) async {
          await action();
          if (ctx.mounted) Navigator.pop(ctx);
          await _recordShare();
        }

        return SafeArea(
          child: Padding(
            padding: const EdgeInsets.fromLTRB(8, 12, 8, 8),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  width: 42,
                  height: 4,
                  margin: const EdgeInsets.only(bottom: 12),
                  decoration: BoxDecoration(
                    color: Colors.grey.withOpacity(0.35),
                    borderRadius: BorderRadius.circular(8),
                  ),
                ),
                const Text('Share post', style: TextStyle(fontWeight: FontWeight.w800, fontSize: 16)),
                const SizedBox(height: 4),
                Text(
                  'Friends can open this link in NGMY to like and comment.',
                  textAlign: TextAlign.center,
                  style: TextStyle(fontSize: 12, color: Colors.grey.shade600, height: 1.35),
                ),
                const SizedBox(height: 8),
                ListTile(
                  leading: const Icon(Icons.ios_share_rounded),
                  title: const Text('Share…'),
                  subtitle: const Text('Messages, email, or other apps'),
                  onTap: () => runThenClose(() => Share.share(fullText, subject: 'NGMY Media')),
                ),
                ListTile(
                  leading: const Icon(Icons.facebook_rounded, color: Color(0xFF1877F2)),
                  title: const Text('Facebook'),
                  onTap: () => runThenClose(
                    () => _launchMediaShareUrl(
                      Uri.parse('https://www.facebook.com/sharer/sharer.php?u=${Uri.encodeComponent(link)}'),
                    ),
                  ),
                ),
                ListTile(
                  leading: const Icon(Icons.chat_rounded, color: Color(0xFF25D366)),
                  title: const Text('WhatsApp'),
                  onTap: () => runThenClose(
                    () => _launchMediaShareUrl(
                      Uri.parse('https://wa.me/?text=${Uri.encodeComponent(fullText)}'),
                    ),
                  ),
                ),
                ListTile(
                  leading: const Icon(Icons.alternate_email_rounded),
                  title: const Text('X (Twitter)'),
                  onTap: () => runThenClose(
                    () => _launchMediaShareUrl(
                      Uri.parse(
                        'https://twitter.com/intent/tweet?text=${Uri.encodeComponent(shareText)}&url=${Uri.encodeComponent(link)}',
                      ),
                    ),
                  ),
                ),
                ListTile(
                  leading: const Icon(Icons.content_copy_rounded),
                  title: const Text('Copy NGMY link'),
                  onTap: () => runThenClose(() async {
                    await Clipboard.setData(ClipboardData(text: link));
                    if (mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('NGMY Media link copied.')),
                      );
                    }
                  }),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

