  Future<void> _handlePostMenu(String action) async {
    if (action == 'save') {
      await _toggleSave();
      return;
    }
    if (action == 'delete') {
      widget.onDelete();
      return;
    }
  }

  Future<void> _quickLike() async {
    if (!_liked) {
      setState(() {
        _ngmyMediaAddLike(widget.post.likedBy, widget.currentUser.email);
        widget.post.likes = widget.post.likedBy.length;
      });
      await _persistPostChange();
    }
    _triggerHeartBurst();
  }

  void _triggerHeartBurst() {
    setState(() => _showHeartBurst = true);
    Future.delayed(const Duration(milliseconds: 900), () {
      if (mounted) setState(() => _showHeartBurst = false);
    });
  }

  Future<void> _openFullscreenMedia() async {
    var resolved = _resolvedMediaUrl ?? widget.post.videoUrl;
    if (resolved.startsWith('supabase://')) {
      resolved = await _resolveSupabaseStorageUrlResilient(resolved);
    }
    if (!mounted || resolved.trim().isEmpty) return;
    if (_isImagePost) {
      await Navigator.of(context).push(
        MaterialPageRoute<void>(
          fullscreenDialog: true,
          builder: (_) => _NgmyFullscreenImagePage(url: resolved),
        ),
      );
      return;
    }
    await Navigator.of(context).push(
      MaterialPageRoute<void>(
        fullscreenDialog: true,
        builder: (_) => _NgmyFullscreenVideoPage(
          url: resolved,
          aspectRatio: _effectiveAspectRatio(true),
        ),
      ),
    );
  }

  Widget _commentAvatar(String email, {double radius = 18, String? profilePictureUrl, bool isVirtual = false}) {
    if (isVirtual || email.startsWith('vp_')) {
      final path = (profilePictureUrl ?? '').trim();
      ImageProvider? img;
      if (path.startsWith('data:image')) {
        try {
          img = MemoryImage(base64Decode(path.split(',').last));
        } catch (_) {}
      } else if (path.startsWith('http')) {
        img = NetworkImage(path);
      } else if (path.startsWith('supabase://')) {
        return FutureBuilder<String>(
          future: _resolveSupabaseStorageUrlResilient(path),
          builder: (_, s) {
            final resolved = s.data ?? '';
            if (resolved.startsWith('http')) {
              return CircleAvatar(radius: radius, backgroundImage: NetworkImage(resolved));
            }
            return CircleAvatar(radius: radius, child: Icon(Icons.person, size: radius));
          },
        );
      } else if (!kIsWeb && path.isNotEmpty) {
        img = FileImage(File(path));
      }
      return CircleAvatar(
        radius: radius,
        backgroundImage: img,
        backgroundColor: const Color(0xFF7C3AED).withOpacity(0.25),
        child: img == null ? Icon(Icons.person, size: radius, color: Colors.white70) : null,
      );
    }
    final u = widget.allUsers.firstWhere(
      (x) => x.email.toLowerCase().trim() == email.toLowerCase().trim(),
      orElse: () => UserData(email: email),
    );
    final path = u.profilePicturePath;
    ImageProvider? img;
    if (path != null && path.trim().isNotEmpty) {
      if (path.startsWith('data:image')) {
        try {
          img = MemoryImage(base64Decode(path.split(',').last));
        } catch (_) {}
      } else if (path.startsWith('http')) {
        img = NetworkImage(path);
      } else if (!kIsWeb) {
        img = FileImage(File(path));
      }
    }
    return CircleAvatar(
      radius: radius,
      backgroundImage: img,
      backgroundColor: const Color(0xFF7C3AED).withOpacity(0.25),
      child: img == null ? Icon(Icons.person, size: radius, color: Colors.white70) : null,
    );
  }

  Widget _buildCommentTile(
    Map<String, dynamic> cm, {
    required bool isDark,
    required void Function(String commentId, String username) onReply,
    int depth = 0,
  }) {
    final email = (cm['userEmail'] ?? '').toString();
    final storedName = (cm['username'] ?? 'User').toString();
    final username = storedName.trim().isNotEmpty && storedName.trim() != 'User'
        ? storedName.trim()
        : (email.isNotEmpty
            ? _mediaAuthorName(
                widget.allUsers.firstWhere(
                  (x) => x.email.toLowerCase().trim() == email.toLowerCase().trim(),
                  orElse: () => UserData(email: email),
                ),
              )
            : storedName);
    final text = (cm['text'] ?? '').toString();
    final id = (cm['id'] ?? '').toString();
    final isVirtual = cm['isVirtual'] == true || email.startsWith('vp_');
    final profilePictureUrl = (cm['profilePictureUrl'] ?? '').toString();
    final replies = List<Map<String, dynamic>>.from(
      (cm['replies'] ?? []).map((e) => Map<String, dynamic>.from(e as Map)),
    );
    return Padding(
      padding: EdgeInsets.only(left: depth * 16.0, bottom: 10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _commentAvatar(email, radius: depth > 0 ? 14 : 18, profilePictureUrl: profilePictureUrl, isVirtual: isVirtual),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    RichText(
                      text: TextSpan(
                        style: TextStyle(color: isDark ? Colors.white : Colors.black87, fontSize: 13),
                        children: [
                          TextSpan(text: username, style: const TextStyle(fontWeight: FontWeight.w800)),
                          const TextSpan(text: '  '),
                          TextSpan(text: text),
                        ],
                      ),
                    ),
                    if (depth == 0 && id.isNotEmpty)
                      TextButton(
                        style: TextButton.styleFrom(padding: EdgeInsets.zero, minimumSize: Size.zero, tapTargetSize: MaterialTapTargetSize.shrinkWrap),
                        onPressed: () => onReply(id, username),
                        child: Text('Reply', style: TextStyle(color: Colors.grey.shade500, fontSize: 12, fontWeight: FontWeight.w600)),
                      ),
                  ],
                ),
              ),
            ],
          ),
          for (final r in replies)
            _buildCommentTile(r, isDark: isDark, onReply: onReply, depth: depth + 1),
        ],
      ),
    );
  }

  void _openComments() {
    final c = TextEditingController();
    String? replyToId;
    String? replyToName;
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (ctx) {
        final isDark = Theme.of(ctx).brightness == Brightness.dark;
        return StatefulBuilder(
          builder: (ctx, setModal) {
            Future<void> submitComment() async {
              final text = c.text.trim();
              if (text.isEmpty) return;
              final node = {
                'id': DateTime.now().microsecondsSinceEpoch.toString(),
                'userEmail': _ngmyMediaActorKey(widget.currentUser.email),
                'username': _mediaAuthorName(widget.currentUser),
                'text': text,
                'timestamp': DateTime.now().toUtc().toIso8601String(),
                'replies': <Map<String, dynamic>>[],
              };
              setState(() {
                if (replyToId != null) {
                  final idx = widget.post.comments.indexWhere((x) => (x['id'] ?? '').toString() == replyToId);
                  if (idx != -1) {
                    final parent = Map<String, dynamic>.from(widget.post.comments[idx]);
                    final replies = List<Map<String, dynamic>>.from(
                      (parent['replies'] ?? []).map((e) => Map<String, dynamic>.from(e as Map)),
                    );
                    replies.add(node);
                    parent['replies'] = replies;
                    widget.post.comments[idx] = parent;
                  } else {
                    widget.post.comments.add(node);
                  }
                } else {
                  widget.post.comments.add(node);
                }
              });
              setModal(() {
                replyToId = null;
                replyToName = null;
              });
              c.clear();
              await _persistPostChange();
            }

            return Container(
              height: MediaQuery.of(ctx).size.height * 0.72,
              padding: EdgeInsets.only(
                left: 16,
                right: 16,
                top: 16,
                bottom: MediaQuery.of(ctx).viewInsets.bottom + 16,
              ),
              decoration: BoxDecoration(
                color: isDark ? const Color(0xFF0F152D) : Colors.white,
                borderRadius: const BorderRadius.vertical(top: Radius.circular(24)),
              ),
              child: Column(
                children: [
                  Row(
                    children: [
                      const Expanded(
                        child: Text('Comments', style: TextStyle(fontWeight: FontWeight.w800, fontSize: 17)),
                      ),
                      IconButton(
                        icon: const Icon(Icons.close_rounded),
                        onPressed: () => Navigator.pop(ctx),
                      ),
                    ],
                  ),
                  const SizedBox(height: 6),
                  Expanded(
                    child: widget.post.comments.isEmpty
                        ? const Center(child: Text('No comments yet. Be the first!'))
                        : ListView.builder(
                            itemCount: widget.post.comments.length,
                            itemBuilder: (context, i) {
                              final cm = widget.post.comments[i];
                              return _buildCommentTile(
                                cm,
                                isDark: isDark,
                                onReply: (id, name) {
                                  setModal(() {
                                    replyToId = id;
                                    replyToName = name;
                                  });
                                },
                              );
                            },
                          ),
                  ),
                  if (replyToName != null)
                    Align(
                      alignment: Alignment.centerLeft,
                      child: Padding(
                        padding: const EdgeInsets.only(bottom: 6),
                        child: Text('Replying to $replyToName', style: TextStyle(color: Colors.grey.shade500, fontSize: 12)),
                      ),
                    ),
                  Row(
                    children: [
                      _commentAvatar(widget.currentUser.email, radius: 16),
                      const SizedBox(width: 8),
                      Expanded(
                        child: TextField(
                          controller: c,
                          decoration: InputDecoration(
                            hintText: replyToName != null ? 'Reply to $replyToName...' : 'Write a comment...',
                            filled: true,
                            fillColor: isDark ? Colors.white.withOpacity(0.06) : Colors.grey.shade100,
                            border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide.none),
                          ),
                          onSubmitted: (_) => submitComment(),
                        ),
                      ),
                      const SizedBox(width: 8),
                      IconButton(onPressed: submitComment, icon: const Icon(Icons.send_rounded)),
                    ],
                  ),
                ],
              ),
            );
          },
        );
      },
    ).whenComplete(c.dispose);
  }

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _prepareMedia(loadVideo: true);
    });
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _controller?.removeListener(_onVideoTick);
    _controller?.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      unawaited(_tryClaimWatchReward());
    }
  }

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;

    final isImage = _isImagePost;
    final isVideo = !isImage;

    return Container(
      margin: const EdgeInsets.only(bottom: 14),
      decoration: BoxDecoration(
        color: isDark ? const Color(0xFF111731) : Colors.white,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: Colors.white.withOpacity(isDark ? 0.1 : 0.82)),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF8B5CF6).withOpacity(isDark ? 0.12 : 0.08),
            blurRadius: 16,
            offset: const Offset(0, 8),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Padding(
            padding: const EdgeInsets.all(12),
            child: Row(
              children: [
                GestureDetector(
                  onTap: () => widget.onOpenProfile?.call(widget.post.userEmail),
                  child: CircleAvatar(
                    radius: 18,
                    backgroundImage: _authorImage,
                    child: _authorImage == null ? const Icon(Icons.person, size: 20) : null,
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: GestureDetector(
                    onTap: () => widget.onOpenProfile?.call(widget.post.userEmail),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(_displayUsername, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 14)),
                        if (widget.post.caption.trim().isNotEmpty)
                          Text(widget.post.caption, maxLines: 1, overflow: TextOverflow.ellipsis, style: const TextStyle(color: Colors.grey, fontSize: 11)),
                      ],
                    ),
                  ),
                ),
                const Spacer(),
                Container(
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(isDark ? 0.07 : 0.75),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: PopupMenuButton<String>(
                    onSelected: _handlePostMenu,
                    icon: const Icon(Icons.more_horiz_rounded, size: 20),
                    itemBuilder: (ctx) => [
                      PopupMenuItem(
                        value: 'save',
                        child: Text(_saved ? 'Unsave' : 'Save post'),
                      ),
                      if (_isOwner || widget.currentUser.isAdmin) const PopupMenuItem(value: 'delete', child: Text('Delete post')),
                    ],
                  ),
                ),
              ],
            ),
          ),
          GestureDetector(
            onTap: () async {
              if (isImage && _mon.hasLink) {
                await _handleLinkAction();
                return;
              }
              if (isVideo && _previewEnded && !_unlockedFullVideo) return;
              await _openFullscreenMedia();
            },
            onDoubleTap: _quickLike,
            child: _buildMediaFrame(isVideo, isImage),
          ),
          if (_mon.hasLink || _mon.hasWatchReward)
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 0, 12, 4),
              child: Wrap(
                spacing: 6,
                children: [
                  if (_mon.hasLink)
                    Chip(
                      avatar: const Icon(Icons.link, size: 16),
                      label: Text(_mon.hasWatchReward ? 'Link + earn \$${formatCurrency(_mon.watchReward)}' : 'Link on post'),
                      visualDensity: VisualDensity.compact,
                    ),
                  if (_mon.hasPreviewLimit)
                    Chip(
                      avatar: const Icon(Icons.timer, size: 16),
                      label: Text('${_mon.previewSeconds}s free preview'),
                      visualDensity: VisualDensity.compact,
                    ),
                ],
              ),
            ),
          Padding(
            padding: const EdgeInsets.fromLTRB(8, 4, 8, 12),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    _instagramMetric(
                      count: _ngmyMediaLikeCount(widget.post),
                      onTap: _toggleLike,
                      icon: Icon(
                        _liked ? Icons.favorite : Icons.favorite_border,
                        size: 26,
                        color: _liked ? const Color(0xFFFF3B8A) : Theme.of(context).iconTheme.color,
                      ),
                    ),
                    const SizedBox(width: 10),
                    _instagramMetric(
                      count: _mediaCommentCount(widget.post.comments),
                      onTap: _openComments,
                      icon: _NgmyInstagramCommentBubbleIcon(
                        size: 24,
                        color: Theme.of(context).iconTheme.color ?? Colors.black87,
                      ),
                    ),
                    const SizedBox(width: 10),
                    _instagramMetric(
                      count: widget.post.shareCount,
                      onTap: _sharePost,
                      icon: _NgmyInstagramSendIcon(
                        size: 26,
                        color: Theme.of(context).iconTheme.color ?? Colors.black87,
                      ),
                    ),
                    const Spacer(),
                    IconButton(
                      padding: EdgeInsets.zero,
                      constraints: const BoxConstraints(minWidth: 40, minHeight: 40),
                      onPressed: _toggleSave,
                      icon: Icon(
                        _saved ? Icons.bookmark : Icons.bookmark_border,
                        size: 26,
                        color: Theme.of(context).iconTheme.color,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                RichText(
                  text: TextSpan(
                    style: TextStyle(color: Theme.of(context).brightness == Brightness.dark ? Colors.white : Colors.black87, fontSize: 13),
                    children: [
                      TextSpan(text: _displayUsername, style: const TextStyle(fontWeight: FontWeight.bold)),
                      const TextSpan(text: ' '),
                      TextSpan(text: widget.post.caption),
                    ],
                  ),
                ),
                const SizedBox(height: 5),
                Text(_timeAgo(widget.post.timestamp), style: const TextStyle(color: Colors.grey, fontSize: 10)),
              ],
            ),
          ),
        ],
      ),
    );
  }

  String _timeAgo(DateTime t) {
    final diff = DateTime.now().difference(t);
    if (diff.inMinutes < 1) return 'just now';
    if (diff.inMinutes < 60) return '${diff.inMinutes}m ago';
    if (diff.inHours < 24) return '${diff.inHours}h ago';
    return '${diff.inDays}d ago';
  }
}

class AnnouncementScreen extends StatefulWidget {
  final UserData user;
  final List<UserData> allUsers;
  final List<Announcement> announcements;
  final AppConfig config;
  final Function(Announcement) onPostToNews;
  final VoidCallback? onNewsRead;
  final Future<void> Function(List<String> ids)? onMarkAnnouncementsRead;
  final String Function()? liveAppKnowledge;
  final Function(AppTransaction)? onAddTransaction;
  final VoidCallback? onDataChanged;
  final String? initialQuery;
  final int initialTab;
  const AnnouncementScreen({
    super.key,
    required this.user,
    required this.allUsers,
    required this.announcements,
    required this.config,
    required this.onPostToNews,
    this.onNewsRead,
    this.onMarkAnnouncementsRead,
    this.liveAppKnowledge,
    this.onAddTransaction,
    this.onDataChanged,
    this.initialQuery,
    this.initialTab = 0,
  });

  @override
  State<AnnouncementScreen> createState() => _AnnouncementScreenState();
}

class _AnnouncementScreenState extends State<AnnouncementScreen> {
  late int _activeTab; // 0: Chat, 1: Music
  late final PageController _hubPageController;
  final List<Map<String, dynamic>> _messages = [];
  final TextEditingController _chatController = TextEditingController();
  final TextEditingController _newsController = TextEditingController();
  final ScrollController _newsScrollController = ScrollController();
  final ImagePicker _newsPicker = ImagePicker();
  String? _pendingNewsImageUrl;
  String? _pendingNewsVideoUrl;
  bool _isPostingNews = false;
  bool _isTyping = false;
  bool _memoryLoaded = false;
  bool _newsClosedForUsers = false;
  int _helperRemaining = -1;
  DateTime? _helperUnlockAt;
  bool _kbMode = false;
  bool _kbVoluntaryBrowse = false;
  NgmyHelperPermissions _helperPerms = NgmyHelperPermissions.empty;
  int _contactCount = 0;
  int _callMemoryCount = 0;
  int _calendarCount = 0;
  List<NgmyHelperKbCategory> _kbCategories = ngmyHelperKbDefaultCategories();
  Timer? _chatGateTimer;
  Timer? _helperQuotaTimer;
  Timer? _helperCountdownTimer;
  Timer? _newsPollTimer;
  int _unreadNewsInternal = 0;
  List<Announcement> _newsItems = [];
  final Set<String> _seenNewsIds = {};

  Future<void> _refreshUnreadNewsInternal() async {
    final count = await NgmyAnnouncementReads.unreadCountForEmail(
      widget.user.email,
      widget.user.readAnnouncementIds,
      _newsItems.map((a) => a.id),
    );
    if (mounted) setState(() => _unreadNewsInternal = count);
  }

  final ScrollController _scrollController = ScrollController();

  bool get _isBoss => ngmyIsNgmyBoss(isAdmin: widget.user.isAdmin);

  List<String> get _quickPrompts => _isBoss
      ? const [
          'NGMY morning brief',
          'Who called me at 2 AM today?',
          'Brief me on NGMY today, Sir',
          'Add a CEO strategy session Friday at 10am to my calendar',
        ]
      : const [
          'Allow access to my phone',
          'What is on my calendar today?',
          'Who called me at 2 AM today?',
          'Call Mom',
        ];

  @override
  void initState() {
    super.initState();
    _activeTab = widget.initialTab;
    _hubPageController = PageController(initialPage: _activeTab);
    _newsClosedForUsers = widget.config.ngmyChatClosed;
    _newsItems = List<Announcement>.from(widget.announcements);
    for (final a in _newsItems) {
      if (a.id.isNotEmpty) _seenNewsIds.add(a.id);
    }
    _loadChatMemory();
    unawaited(_loadHelperKb());
    unawaited(_bootstrapHelperConnections());
    _startChatGateWatcher();
    _startHelperQuotaWatcher();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _refreshGeminiKeyFromCloud();
      _refreshHelperQuota();
    });
    final initialQuery = widget.initialQuery?.trim() ?? '';
    if (initialQuery.isNotEmpty) {
      Future.delayed(const Duration(milliseconds: 350), () {
        if (!mounted) return;
        setState(() => _activeTab = 0);
        _sendQuickPrompt(initialQuery);
      });
    }
  }

  Future<void> _loadHelperKb() async {
    final cats = await NgmyHelperKbStore.hydrate();
    if (!mounted) return;
    setState(() => _kbCategories = cats);
  }

  bool get _shouldShowKb {
    if (widget.user.isAdmin) return _kbMode;
    final limit = widget.config.ngmyHelperDailyMessageLimit;
    if (limit > 0 && _helperRemaining == 0) return true;
    if (_kbVoluntaryBrowse && !_kbLockedByDailyLimit) return true;
    return false;
  }

  bool get _kbLockedByDailyLimit {
    if (widget.user.isAdmin) return false;
    final limit = widget.config.ngmyHelperDailyMessageLimit;
    return limit > 0 && _helperRemaining == 0;
  }

  Duration get _helperUnlockRemaining {
    final unlockAt = _helperUnlockAt;
    if (unlockAt == null) return Duration.zero;
    final left = unlockAt.difference(DateTime.now());
    return left.isNegative ? Duration.zero : left;
  }

  void _applyKbAutoSwitch() {
    if (widget.user.isAdmin) return;
    if (_kbLockedByDailyLimit) {
      if (!_kbMode) setState(() => _kbMode = true);
    } else if (_kbMode) {
      setState(() => _kbMode = false);
    }
  }

  void _returnToAiChatFromKb() {
    setState(() {
      _kbVoluntaryBrowse = false;
      _kbMode = false;
    });
  }

  Future<void> _refreshHelperQuota() async {
    if (widget.user.isAdmin) {
      if (mounted) setState(() => _helperRemaining = -1);
      return;
    }
    final limit = widget.config.ngmyHelperDailyMessageLimit;
    if (limit <= 0) {
      if (mounted) setState(() => _helperRemaining = -1);
      return;
    }
    final remaining = await NgmyHelperAiLimit.remaining(widget.user.email, limit);
    final unlockAt = remaining == 0 ? await NgmyHelperAiLimit.unlockAt(widget.user.email, limit) : null;
    if (mounted) {
      setState(() {
        _helperRemaining = remaining;
        _helperUnlockAt = unlockAt;
      });
      _syncHelperCountdownTimer();
      _applyKbAutoSwitch();
      if (remaining == 3) {
        unawaited(_maybeShowThreeLeftPopup(remaining));
      }
    }
  }

  Future<void> _maybeShowThreeLeftPopup(int remaining) async {
    if (!mounted || widget.user.isAdmin) return;
    final limit = widget.config.ngmyHelperDailyMessageLimit;
    if (limit <= 0 || remaining != 3) return;
    await showNgmyHelperThreeLeftPopup(
      context,
      userEmail: widget.user.email,
      remaining: remaining,
      dailyLimit: limit,
      onBrowseHelpTopics: () {
        if (!mounted) return;
        setState(() => _kbVoluntaryBrowse = true);
      },
    );
  }

  Future<void> _bootstrapHelperConnections({bool forceSync = false}) async {
    final email = widget.user.email;
    final ngmyUserMaps = ngmyUsersToContactMaps(widget.allUsers);
    await NgmyPhoneContactsStore.ensureHydrated(email, ngmyUsers: ngmyUserMaps);
    var perms = await NgmyHelperPermissionStore.load(email);
    if (perms.contacts || forceSync || !kIsWeb) {
      if (!kIsWeb) {
        await NgmyPhoneContactsStore.syncFromDevice(email);
      }
    }
    var contacts = await NgmyPhoneContactsStore.load(email);
    if (!perms.contacts && contacts.isNotEmpty) {
      perms = perms.copyWith(contacts: true);
      await NgmyHelperPermissionStore.save(email, perms);
    }
    final calls = await NgmyCallMemoryStore.load(email);
    final cals = await NgmyHelperCalendarMemoryStore.load(email);
    if (!mounted) return;
    setState(() {
      _helperPerms = perms;
      _contactCount = contacts.length;
      _callMemoryCount = calls.length;
      _calendarCount = cals.length;
    });
  }

  Future<void> _openKbAdmin() async {
    await _loadHelperKb();
    if (!mounted) return;
    await Navigator.push<void>(
      context,
      MaterialPageRoute(
        builder: (_) => NgmyHelperKbAdminScreen(
          initialCategories: _kbCategories,
          apiKey: widget.config.geminiApiKey,
          onSave: (cats) async {
            final ok = await NgmyHelperKbStore.save(cats);
            if (mounted) setState(() => _kbCategories = cats);
            return ok;
          },
        ),
      ),
    );
    await _loadHelperKb();
  }

  void _toggleKbModeForAdmin() {
    setState(() => _kbMode = !_kbMode);
  }

  Future<void> _pollNewsFromCloud() async {
    if (!NgmyCloudPolicy.persistAnnouncementsToCloud) return;
    if (!mounted || !await ngmyCanReachCloud()) return;
    try {
      final rows = await Supabase.instance.client
          .from('announcements')
          .select('id,title,message,authorEmail,authorUsername,imageUrl,videoUrl,timestamp,expiresAt')
          .order('timestamp', ascending: false)
          .limit(40);
      if (rows == null || !mounted) return;
      final remote = (rows as List).map((e) => Announcement.fromJson(e)).toList();
      _mergeNewsItems(remote, notifyNew: true);
    } catch (e) {
      debugPrint('[news] poll: $e');
    }
  }

  void _mergeNewsItems(List<Announcement> incoming, {bool notifyNew = false}) {
    final byId = <String, Announcement>{for (final a in _newsItems) a.id: a};
    var added = false;
    for (final ann in incoming) {
      if (ann.id.isEmpty) continue;
      final isNew = !_seenNewsIds.contains(ann.id);
      byId[ann.id] = ann;
      if (isNew) {
        _seenNewsIds.add(ann.id);
        added = true;
        if (notifyNew) {
          final me = widget.user.email.toLowerCase().trim();
          if (ann.authorEmail.toLowerCase().trim() != me) {
            unawaited(_notifyNewsMessage(ann));
          }
        }
      }
    }
    final next = byId.values.toList();
    final oldSig = _newsItems.map((a) => '${a.id}:${a.message.length}:${a.timestamp.millisecondsSinceEpoch}').join('|');
    final newSig = next.map((a) => '${a.id}:${a.message.length}:${a.timestamp.millisecondsSinceEpoch}').join('|');
    if (oldSig == newSig) return;
    setState(() => _newsItems = next);
    if (_activeTab == 1) {
      _scrollNewsToBottom();
    } else if (added) {
      unawaited(_refreshUnreadNewsInternal());
    }
  }

  Future<void> _notifyNewsMessage(Announcement ann) async {
    if (kNgmySuppressInAppBannerPopups) return;
    if (!mounted) return;
    final preview = ann.message.trim().isNotEmpty
        ? ann.message.trim()
        : (ann.videoUrl != null ? 'New video in News' : 'New photo in News');
    final title = ann.authorUsername.trim().isNotEmpty ? ann.authorUsername.trim() : 'New in News';
    if (kIsWeb) {
      await ngmyPushShow(title: title, body: preview, tag: 'news_${ann.id}');
    }
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('$title: ${preview.length > 80 ? '${preview.substring(0, 80)}…' : preview}'),
        duration: const Duration(seconds: 4),
        action: SnackBarAction(
          label: 'View',
          onPressed: () {
            _selectNewsTab();
            _scrollNewsToBottom(jump: true);
          },
        ),
      ),
    );
  }

  Future<void> _markNewsAsRead() async {
    if (_newsItems.isEmpty) return;
    final ids = _newsItems.map((a) => a.id).where((id) => id.isNotEmpty).toList();
    if (widget.onMarkAnnouncementsRead != null) {
      await widget.onMarkAnnouncementsRead!(ids);
    }
    widget.onNewsRead?.call();
    await _refreshUnreadNewsInternal();
  }

  void _selectNewsTab({bool jumpPage = true}) {
    if (_activeTab != 1) setState(() => _activeTab = 1);
    unawaited(_markNewsAsRead());
    _scrollNewsToBottom();
    if (jumpPage && _hubPageController.hasClients) {
      _hubPageController.animateToPage(1, duration: const Duration(milliseconds: 280), curve: Curves.easeOutCubic);
    }
  }

  void _startHelperQuotaWatcher() {
    _helperQuotaTimer?.cancel();
    if (widget.user.isAdmin) return;
    _helperQuotaTimer = Timer.periodic(const Duration(seconds: 60), (_) => unawaited(_refreshHelperQuota()));
  }

  void _syncHelperCountdownTimer() {
    _helperCountdownTimer?.cancel();
    _helperCountdownTimer = null;
    if (!_kbLockedByDailyLimit || _helperUnlockAt == null) return;
    _helperCountdownTimer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted) return;
      if (_helperUnlockRemaining.inSeconds <= 0) {
        _helperCountdownTimer?.cancel();
        unawaited(_refreshHelperQuota());
        return;
      }
      setState(() {});
    });
  }

  void _startChatGateWatcher() {
    _chatGateTimer?.cancel();
    _chatGateTimer = Timer.periodic(const Duration(seconds: 45), (_) => unawaited(_syncChatClosedFromCloud()));
    unawaited(_syncChatClosedFromCloud());
  }

  Future<void> _syncChatClosedFromCloud() async {
    bool closed = widget.config.ngmyChatClosed;
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString('app_config');
      if (raw != null && raw.isNotEmpty) {
        final map = jsonDecode(raw);
        if (map is Map) {
          closed = AppConfig.fromJson(Map<String, dynamic>.from(map)).ngmyChatClosed;
          widget.config.ngmyChatClosed = closed;
        }
      }
      if (await ngmyDeviceIsOnline()) {
        final remote = await ngmyFetchRemoteNgmyChatClosed();
        if (remote != null) {
          closed = remote;
          widget.config.ngmyChatClosed = closed;
          await prefs.setString('app_config', jsonEncode(widget.config.toJson()));
        }
      }
    } catch (_) {}
    if (!mounted) return;
    if (closed != _newsClosedForUsers) {
      setState(() => _newsClosedForUsers = closed);
    }
  }

  void _sortMessagesChronological() {
    _messages.sort((a, b) {
      final ta = DateTime.tryParse((a['at'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
      final tb = DateTime.tryParse((b['at'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
      return ta.compareTo(tb);
    });
  }

  Future<void> _loadChatMemory() async {
    final stored = await NgmyAiMemoryStore.load(widget.user.email);
    if (!mounted) return;
    final next = <Map<String, dynamic>>[];
    if (stored.isNotEmpty) {
      next.addAll(stored);
      next.sort((a, b) {
        final ta = DateTime.tryParse((a['at'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
        final tb = DateTime.tryParse((b['at'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
        return ta.compareTo(tb);
      });
    } else {
      next.add({
        'role': 'ai',
        'text': _isBoss
            ? 'Good to see you, Sir. I am your NGMY personal assistant — ready to help with the platform, strategy, or anything personal including relationships. How may I serve you today, Boss?'
            : 'Hello! Ask me about investments, clock-in, withdrawals, the store, or anything about the platform.',
        'at': DateTime.now().toUtc().toIso8601String(),
      });
    }
    setState(() {
      _messages
        ..clear()
        ..addAll(next);
      _memoryLoaded = true;
    });
    _scrollToBottom(jump: true);
    Future<void>.delayed(const Duration(milliseconds: 120), () {
      if (mounted) _scrollToBottom(jump: true);
    });
  }

  Future<void> _persistChatMemory() async {
    await NgmyAiMemoryStore.saveAll(widget.user.email, _messages);
  }

  @override
  void didUpdateWidget(covariant AnnouncementScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
  }

  @override
  void dispose() {
    _chatGateTimer?.cancel();
    _helperQuotaTimer?.cancel();
    _helperCountdownTimer?.cancel();
    _newsPollTimer?.cancel();
    _chatController.dispose();
    _newsController.dispose();
    _scrollController.dispose();
    _newsScrollController.dispose();
    _hubPageController.dispose();
    super.dispose();
  }

  void _goToHubTab(int idx, {bool animate = true}) {
    setState(() => _activeTab = idx);
    if (_hubPageController.hasClients) {
      if (animate) {
        _hubPageController.animateToPage(
          idx,
          duration: const Duration(milliseconds: 280),
          curve: Curves.easeOutCubic,
        );
      } else {
        _hubPageController.jumpToPage(idx);
      }
    } else {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (_hubPageController.hasClients) _hubPageController.jumpToPage(idx);
      });
    }
    if (idx == 0) _scrollToBottom(jump: true);
    if (idx == 1) _scrollNewsToBottom(jump: true);
  }

  void _scrollToBottom({bool jump = false}) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!_scrollController.hasClients) return;
      final target = _scrollController.position.maxScrollExtent;
      if (jump) {
        _scrollController.jumpTo(target);
      } else {
        _scrollController.animateTo(target, duration: const Duration(milliseconds: 280), curve: Curves.easeOut);
      }
    });
  }

  bool get _newsPostingLocked => _newsClosedForUsers && !widget.user.isAdmin;

  Future<void> _refreshGeminiKeyFromCloud() async {
    final remote = await _fetchRemoteGeminiApiKey();
    if (!mounted) return;
    if (remote.isNotEmpty && remote != widget.config.geminiApiKey.trim()) {
      setState(() => widget.config.geminiApiKey = remote);
    }
  }

  Future<void> _sendMessage() async {
    final text = _chatController.text.trim();
    if (text.isEmpty) return;

    if (!widget.user.isAdmin) {
      final limit = widget.config.ngmyHelperDailyMessageLimit;
      if (limit > 0) {
        final allowed = await NgmyHelperAiLimit.tryConsume(widget.user.email, limit);
        if (!allowed) {
          if (!mounted) return;
          await _refreshHelperQuota();
          setState(() => _kbMode = true);
          return;
        }
        await _refreshHelperQuota();
        if (mounted && _helperRemaining == 3) {
          unawaited(_maybeShowThreeLeftPopup(3));
        }
      }
    }

    setState(() {
      _messages.add({
        'role': 'user',
        'text': text,
        'at': DateTime.now().toUtc().toIso8601String(),
      });
      _sortMessagesChronological();
      _chatController.clear();
      _isTyping = true;
    });
    unawaited(NgmyAiMemoryStore.append(widget.user.email, role: 'user', text: text));
    _scrollToBottom();

    try {
      await _refreshGeminiKeyFromCloud();
      var apiKey = widget.config.geminiApiKey.trim();
      if (apiKey.isEmpty) {
        apiKey = await _fetchRemoteGeminiApiKey();
        if (apiKey.isNotEmpty && mounted) setState(() => widget.config.geminiApiKey = apiKey);
      }
      if (apiKey.isEmpty) {
        final err = ngmyAiHelperFailureMessage(apiKey: '');
        setState(() {
          _messages.add({'role': 'ai', 'text': err, 'at': DateTime.now().toUtc().toIso8601String()});
          _isTyping = false;
        });
        unawaited(NgmyAiMemoryStore.append(widget.user.email, role: 'ai', text: err));
        _scrollToBottom();
        return;
      }

      final creds = ngmyParseAiCredentials(apiKey);
      final liveDb = widget.liveAppKnowledge?.call() ?? '';
      final ngmyUserMaps = ngmyUsersToContactMaps(widget.allUsers);

      if (ngmyUserGrantsHelperAccess(text)) {
        _helperPerms = await NgmyHelperPermissionStore.grantAll(widget.user.email);
        await _bootstrapHelperConnections(forceSync: true);
      }

      final contacts = await NgmyPhoneContactsStore.ensureHydrated(
        widget.user.email,
        ngmyUsers: ngmyUserMaps,
      );
      if (_helperPerms.contacts && !kIsWeb) {
        await NgmyPhoneContactsStore.syncFromDevice(widget.user.email);
      }
      final contactsDir = NgmyPhoneContactsStore.directoryForAi(contacts);
      final phoneCtx = ngmyHelperPhoneIntegrationContext(contactsDirectory: contactsDir);
      final callMemory = await NgmyCallMemoryStore.load(widget.user.email);
      final callDir = NgmyCallMemoryStore.directoryForAi(callMemory);
      final calendarEvents = await NgmyHelperCalendarMemoryStore.load(widget.user.email);
      final calendarDir = NgmyHelperCalendarMemoryStore.directoryForAi(calendarEvents);
      final connectionsSummary = NgmyHelperPermissionStore.summaryForAi(
        _helperPerms,
        contactCount: _contactCount,
        callMemoryCount: _callMemoryCount,
        calendarCount: _calendarCount,
      );
      final superCtx = ngmyHelperSuperpowersContext(
        callMemoryDirectory: callDir,
        calendarDirectory: calendarDir,
        connectionsSummary: connectionsSummary,
      );
      final preflight = await ngmyHelperSuperpowerPreflight(
        userEmail: widget.user.email,
        userText: text,
        permissions: _helperPerms,
      );
      var grantNote = '';
      if (ngmyUserGrantsHelperAccess(text)) {
        grantNote = '\nACCESS GRANTED: User just said allow access — confirm contacts, calendar, and calls are now permanently connected on this device. Never ask again.\n';
      }
      final prompt = '${_ngmyHelperSystemContext(user: widget.user)}'
          '\n$superCtx\n'
          '\n$phoneCtx\n'
          '${widget.user.isAdmin ? '\n${ngmyAdminEmailSendContext(ngmyUsers: ngmyUserMaps)}\n' : ''}'
          '${liveDb.isNotEmpty ? '\n$liveDb\n' : ''}'
          '${preflight.isNotEmpty ? '\n$preflight\n' : ''}'
          '$grantNote'
          '${_messages.isNotEmpty ? '\n${NgmyAiMemoryStore.transcriptForPrompt(_messages)}\n' : ''}'
          '\nUser: $text';
      final aiResult = await ngmyAiGenerateWithCredentials(creds, prompt);
      if (!mounted) return;
      final rawReply = (aiResult.text != null && aiResult.text!.isNotEmpty)
          ? aiResult.text!
          : ngmyAiHelperFailureMessage(apiKey: apiKey, lastError: aiResult.error);
      final parsed = ngmyParseHelperPhoneActions(rawReply);
      var phoneActions = parsed.actions;
      if (phoneActions.isEmpty) {
        phoneActions = [
          ...ngmyInferAlarmActionsFromUserMessage(text),
          ...ngmyInferCalendarActionsFromUserMessage(text),
          ...ngmyInferContactActionsFromUserMessage(text),
          ...ngmyInferOpenToolActionsFromUserMessage(text),
          ...ngmyInferSendEmailActionsFromUserMessage(text, isAdmin: widget.user.isAdmin),
        ];
      }
      phoneActions = ngmyFilterAdminOnlyPhoneActions(phoneActions, isAdmin: widget.user.isAdmin);
      phoneActions = await ngmyResolvePhoneActionsByName(
        context: context,
        userEmail: widget.user.email,
        actions: phoneActions,
        ngmyUsers: ngmyUserMaps,
      );
      final reply = parsed.text.isNotEmpty ? parsed.text : rawReply;
      setState(() {
        _messages.add({
          'role': 'ai',
          'text': reply,
          'at': DateTime.now().toUtc().toIso8601String(),
          if (phoneActions.isNotEmpty) 'phoneActions': phoneActions.map(_phoneActionToJson).toList(),
        });
        _sortMessagesChronological();
      });
      unawaited(NgmyAiMemoryStore.append(widget.user.email, role: 'ai', text: reply));
      if (phoneActions.isNotEmpty && mounted) {
        unawaited(_runHelperPhoneActions(phoneActions));
      }
    } catch (e) {
      const err = 'Connection error. Please check your internet and try again.';
      setState(() {
        _messages.add({'role': 'ai', 'text': err, 'at': DateTime.now().toUtc().toIso8601String()});
      });
      unawaited(NgmyAiMemoryStore.append(widget.user.email, role: 'ai', text: err));
    } finally {
      setState(() => _isTyping = false);
      _scrollToBottom();
      unawaited(_persistChatMemory());
      if (!widget.user.isAdmin) {
        unawaited(_refreshHelperQuota());
      }
    }
  }

  void _sendQuickPrompt(String text) {
    _chatController.text = text;
    _sendMessage();
  }

  Map<String, dynamic> _phoneActionToJson(NgmyPhoneAction action) => {
        'type': action.type,
        ...action.fields,
      };

  List<NgmyPhoneAction> _phoneActionsFromMessage(Map<String, dynamic> m) {
    final raw = m['phoneActions'];
    if (raw is! List) return const [];
    final out = <NgmyPhoneAction>[];
    for (final item in raw) {
      if (item is Map) {
        final action = NgmyPhoneAction.fromJson(Map<String, dynamic>.from(item));
        if (action != null) out.add(action);
      }
    }
    return out;
  }

  Future<void> _runHelperPhoneActions(List<NgmyPhoneAction> actions) async {
    for (final action in actions) {
      if (!mounted) return;
      if (action.type == 'calendar') {
        await ngmyPresentPhoneCalendarSheet(
          context: context,
          action: action,
          onDone: (result) async {
            if (!mounted || result == null) return;
            final start = DateTime.tryParse(action.fields['start'] ?? '');
            final end = DateTime.tryParse(action.fields['end'] ?? '');
            if (start != null) {
              await NgmyHelperCalendarMemoryStore.add(
                widget.user.email,
                NgmyCalendarMemoryEntry(
                  id: 'cal_${DateTime.now().microsecondsSinceEpoch}',
                  title: (action.fields['title'] ?? 'Event').trim(),
                  start: start.toLocal(),
                  end: (end ?? start.add(const Duration(hours: 1))).toLocal(),
                  notes: action.fields['notes'],
                  location: action.fields['location'],
                ),
              );
              unawaited(_bootstrapHelperConnections());
            }
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(content: Text(result), backgroundColor: const Color(0xFF16A34A)),
            );
          },
        );
        continue;
      }
      if (action.type == 'alarm') {
        final result = await ngmyRunPhoneAction(
          action,
          context: context,
          userEmail: widget.user.email,
          skipConfirmation: true,
        );
        if (!mounted || result == null) continue;
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
            content: Text(result),
                backgroundColor: const Color(0xFFF97316),
            duration: const Duration(seconds: 9),
              ),
        );
        continue;
      }
      final result = await ngmyRunPhoneAction(
        action,
        context: context,
        userEmail: widget.user.email,
        skipConfirmation: action.type == 'call' || action.type == 'sms' || action.type == 'whatsapp',
        isAdmin: widget.user.isAdmin,
        config: widget.config,
      );
      if (!mounted || result == null) continue;
      if (action.type == 'call') {
        final name = (action.fields['name'] ?? '').trim();
        final phone = (action.fields['phone'] ?? '').trim();
        await NgmyCallMemoryStore.addAll(widget.user.email, [
          NgmyCallMemoryEntry(
            id: 'out_${DateTime.now().microsecondsSinceEpoch}',
            when: DateTime.now(),
            phone: phone.isNotEmpty ? phone : null,
            name: name.isNotEmpty ? name : null,
            note: 'Outgoing call via NGMY',
            source: 'ngmy',
          ),
        ]);
        unawaited(_bootstrapHelperConnections());
      }
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(result), backgroundColor: const Color(0xFF16A34A)),
      );
    }
  }

  Future<void> _tapHelperPhoneAction(NgmyPhoneAction action) async {
    if (action.type == 'calendar') {
      await ngmyPresentPhoneCalendarSheet(
        context: context,
        action: action,
        onDone: (result) async {
          if (!mounted || result == null) return;
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text(result), backgroundColor: const Color(0xFF16A34A)),
          );
        },
      );
      return;
    }
    if (action.type == 'alarm') {
      final result = await ngmyRunPhoneAction(
        action,
        context: context,
        userEmail: widget.user.email,
        skipConfirmation: true,
      );
          if (!mounted || result == null) return;
          ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(result),
          backgroundColor: const Color(0xFFF97316),
          duration: const Duration(seconds: 9),
        ),
      );
      return;
    }
    final result = await ngmyRunPhoneAction(
      action,
      context: context,
      userEmail: widget.user.email,
      skipConfirmation: action.type == 'call' || action.type == 'sms' || action.type == 'whatsapp' || action.type == 'send_email',
      isAdmin: widget.user.isAdmin,
      config: widget.config,
    );
    if (!mounted || result == null) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(result), backgroundColor: const Color(0xFF16A34A)),
    );
  }

  ImageProvider? _avatarForEmail(String email) {
    final key = email.toLowerCase().trim();
    for (final candidate in widget.allUsers) {
      if (candidate.email.toLowerCase().trim() == key) {
        return ngmyCachedProfileImage(candidate.profilePicturePath);
      }
    }
    return null;
  }

  Future<String> _uploadNewsMediaRef(String ref, {required bool isVideo}) async {
    final src = ref.trim();
    if (src.isEmpty || src.startsWith('supabase://') || src.startsWith('http')) return src;
    try {
      late List<int> bytes;
      var ext = isVideo ? 'mp4' : 'jpg';
      if (src.startsWith('data:')) {
        bytes = base64Decode(src.split(',').last);
      } else if (!kIsWeb) {
        bytes = await File(src).readAsBytes();
        if (src.contains('.')) ext = src.split('.').last.toLowerCase();
      } else {
        return src;
      }
      final storagePath = 'news/${DateTime.now().microsecondsSinceEpoch}_${widget.user.email.hashCode}.$ext';
      await Supabase.instance.client.storage.from('media').uploadBinary(
        storagePath,
        Uint8List.fromList(bytes),
        fileOptions: FileOptions(upsert: false, contentType: isVideo ? 'video/mp4' : 'image/jpeg'),
      );
      return 'supabase://media/$storagePath';
    } catch (e) {
      debugPrint('[news] media upload error: $e');
      return src;
    }
  }

  Future<void> _pickNewsMedia({required bool isVideo}) async {
    final picked = isVideo
        ? await _newsPicker.pickVideo(source: ImageSource.gallery)
        : await _newsPicker.pickImage(source: ImageSource.gallery, imageQuality: 80, maxWidth: 1400);
    if (picked == null) return;
    if (isVideo) {
      if (kIsWeb) {
        final bytes = await picked.readAsBytes();
        _pendingNewsVideoUrl = 'data:video/mp4;base64,${base64Encode(bytes)}';
      } else {
        _pendingNewsVideoUrl = picked.path;
      }
      _pendingNewsImageUrl = null;
    } else {
      if (kIsWeb) {
        final bytes = await picked.readAsBytes();
        _pendingNewsImageUrl = 'data:image/jpeg;base64,${base64Encode(bytes)}';
      } else {
        _pendingNewsImageUrl = picked.path;
      }
      _pendingNewsVideoUrl = null;
    }
    setState(() {});
  }

  Future<void> _postCommunityNews() async {
    if (_newsPostingLocked) return;
    final text = _newsController.text.trim();
    if (text.isEmpty && _pendingNewsImageUrl == null && _pendingNewsVideoUrl == null) return;
    setState(() => _isPostingNews = true);
    String? imageUrl;
    String? videoUrl;
    if (_pendingNewsImageUrl != null) {
      imageUrl = await _uploadNewsMediaRef(_pendingNewsImageUrl!, isVideo: false);
    }
    if (_pendingNewsVideoUrl != null) {
      videoUrl = await _uploadNewsMediaRef(_pendingNewsVideoUrl!, isVideo: true);
    }
    final ann = Announcement(
      id: DateTime.now().microsecondsSinceEpoch.toString(),
      title: widget.user.username,
      message: text.isEmpty ? (videoUrl != null ? 'Shared a video' : 'Shared a photo') : text,
      imageUrl: imageUrl,
      videoUrl: videoUrl,
      timestamp: DateTime.now(),
      authorEmail: widget.user.email,
      authorUsername: widget.user.username,
      postType: 'community',
    );
    widget.onPostToNews(ann);
    setState(() {
      _newsItems.removeWhere((a) => a.id == ann.id);
      _newsItems.add(ann);
      _seenNewsIds.add(ann.id);
    });
    _newsController.clear();
    _pendingNewsImageUrl = null;
    _pendingNewsVideoUrl = null;
    if (mounted) {
      setState(() => _isPostingNews = false);
      _scrollNewsToBottom();
    }
  }

  List<Announcement> get _sortedNews {
    final list = _newsItems
        .where((a) => !NgmyNewsRetention.isExpired(a.timestamp))
        .toList();
    list.sort((a, b) => a.timestamp.compareTo(b.timestamp));
    return list;
  }

  void _scrollNewsToBottom({bool jump = false}) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!_newsScrollController.hasClients) return;
      final target = _newsScrollController.position.maxScrollExtent;
      if (jump) {
        _newsScrollController.jumpTo(target);
      } else {
        _newsScrollController.animateTo(target, duration: const Duration(milliseconds: 280), curve: Curves.easeOut);
      }
    });
  }

